package com.slayercompanion;

import com.slayercompanion.data.Access;
import com.slayercompanion.data.SlayerLocation;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/**
 * Whether a place is open for an account. A place names the quests that must be finished or started and the real
 * levels it needs (/slayer_areas.json, from the OSRS Wiki). The checks are pure, so tests run them without a client. A
 * quest or skill the client does not know, a quest that was not read and a level that is not loaded lock nothing, so
 * data newer than the client never shuts a player out.
 */
@Slf4j
final class PlaceAccess
{
	/** The quest states and real levels the checks compare with. */
	@Value
	static class Account
	{
		/** Nothing read: every place is open. */
		static final Account UNKNOWN = new Account(Collections.emptyMap(), new int[0]);

		/** States of the quests read, by Quest constant name. */
		Map<String, QuestState> quests;
		/** Real levels by Skill ordinal, in the order of Client.getRealSkillLevels. */
		int[] levels;

		/**
		 * Reads the named quests with {@code state} and keeps a copy of the levels. A name the client does not know is
		 * skipped, and a quest whose state cannot be read stays unknown until the next read.
		 */
		static Account read(Collection<String> questNames, Function<Quest, QuestState> state, int[] levels)
		{
			final Map<String, QuestState> quests = new LinkedHashMap<>();
			for (String name : questNames)
			{
				final Quest quest = quest(name);
				if (quest == null) continue;
				try
				{
					final QuestState read = state.apply(quest);
					if (read != null) quests.put(name, read);
				}
				catch (RuntimeException ex)
				{
					log.debug("Slayer Sensei could not read the state of {}", name, ex);
				}
			}
			return new Account(Collections.unmodifiableMap(quests), levels == null ? new int[0] : levels.clone());
		}
	}

	/** Open, or locked with what the account lacks. A note can come with either. */
	@Value
	static class Verdict
	{
		static final Verdict OPEN = new Verdict(Collections.emptyList(), null);

		/** What the account lacks, such as "Priest in Peril", "Sins of the Father started" or "60 Sailing". */
		List<String> missing;
		/** A requirement the plugin cannot check, shown with the place and never locking it, or null. */
		String note;

		boolean isLocked()
		{
			return !missing.isEmpty();
		}

		/** "Needs Priest in Peril and 60 Sailing", or null when the place is open. */
		String needs()
		{
			if (missing.isEmpty()) return null;
			final StringBuilder sb = new StringBuilder("Needs ");
			for (int i = 0; i < missing.size(); i++)
			{
				if (i > 0) sb.append(i == missing.size() - 1 ? " and " : ", ");
				sb.append(missing.get(i));
			}
			return sb.toString();
		}

		/** The sentence for a tooltip or the sidebar: what the place needs, then the note. Null when there is neither. */
		String sentence()
		{
			final String needs = needs();
			if (needs == null) return note;
			return note == null ? needs + "." : needs + ". " + note;
		}
	}

	private PlaceAccess()
	{
	}

	/** What a place needs for one task: the place's own access, then the task's own access there. */
	static List<Access> of(SlayerLocation location, int taskId)
	{
		final List<Access> out = new ArrayList<>(2);
		if (location == null) return out;
		if (location.getAccess() != null) out.add(location.getAccess());
		final SlayerLocation.TaskEntry task = Destination.taskEntry(location, taskId);
		if (task != null && task.getAccess() != null) out.add(task.getAccess());
		return out;
	}

	/** Every quest the places name for the task, so a reader can read only those. */
	static Set<String> quests(Collection<SlayerLocation> places, int taskId)
	{
		final Set<String> quests = new LinkedHashSet<>();
		for (SlayerLocation location : places)
		{
			for (Access access : of(location, taskId))
			{
				if (access.getQuestsFinished() != null) quests.addAll(access.getQuestsFinished());
				if (access.getQuestsStarted() != null) quests.addAll(access.getQuestsStarted());
			}
		}
		return quests;
	}

	/**
	 * Whether the account can enter a place with these requirements. A quest that must be finished locks unless it is
	 * finished, a quest that must be started locks only while it is not started, and a level locks while the real
	 * level is below it.
	 */
	static Verdict check(List<Access> requirements, Account account)
	{
		final Set<String> finished = new LinkedHashSet<>();
		final Set<String> started = new LinkedHashSet<>();
		final Map<String, Integer> levels = new LinkedHashMap<>();
		final List<String> notes = new ArrayList<>();
		for (Access access : requirements)
		{
			if (access == null) continue;
			if (access.getQuestsFinished() != null) finished.addAll(access.getQuestsFinished());
			if (access.getQuestsStarted() != null) started.addAll(access.getQuestsStarted());
			if (access.getSkills() != null)
			{
				for (Map.Entry<String, Integer> skill : access.getSkills().entrySet())
				{
					levels.merge(skill.getKey(), skill.getValue() == null ? 0 : skill.getValue(), Math::max);
				}
			}
			if (access.getNote() != null && !access.getNote().trim().isEmpty()) notes.add(access.getNote().trim());
		}
		final List<String> missing = new ArrayList<>();
		for (String name : finished)
		{
			final Quest quest = quest(name);
			final QuestState state = account.getQuests().get(name);
			if (quest != null && state != null && state != QuestState.FINISHED) missing.add(quest.getName());
		}
		for (String name : started)
		{
			final Quest quest = quest(name);
			final QuestState state = account.getQuests().get(name);
			// A quest that must be finished already says it
			if (quest != null && state == QuestState.NOT_STARTED && !finished.contains(name)) missing.add(quest.getName() + " started");
		}
		for (Map.Entry<String, Integer> level : levels.entrySet())
		{
			final Skill skill = skill(level.getKey());
			final int have = skill == null || skill.ordinal() >= account.getLevels().length ? 0 : account.getLevels()[skill.ordinal()];
			// A level of 0 is not loaded yet
			if (have > 0 && have < level.getValue()) missing.add(level.getValue() + " " + skill.getName());
		}
		if (missing.isEmpty() && notes.isEmpty()) return Verdict.OPEN;
		return new Verdict(Collections.unmodifiableList(missing), notes.isEmpty() ? null : String.join(" ", notes));
	}

	/** The quest of a constant name, or null when this client does not know it. */
	static Quest quest(String name)
	{
		if (name == null) return null;
		try
		{
			return Quest.valueOf(name);
		}
		catch (IllegalArgumentException ex)
		{
			return null;
		}
	}

	/** The skill of a constant name, or null when this client does not know it. */
	static Skill skill(String name)
	{
		if (name == null) return null;
		try
		{
			return Skill.valueOf(name);
		}
		catch (IllegalArgumentException ex)
		{
			return null;
		}
	}
}

package com.slayercompanion;

import lombok.Value;

/**
 * What the sidebar says about Shortest Path, the optional plugin that draws the routes, chosen from its state and the
 * path mode. Pure, so which notice shows, its words and its button are tested without RuneLite.
 */
final class PluginNotices
{
	/** One notice in both layouts. */
	@Value
	static class Notice
	{
		/** The compact item. */
		String item;
		/** The notice in full: the compact item's tooltip and the detailed sidebar's line. */
		String text;
		/** The button's label, or null without a button. */
		String button;
		/** The last press of the button did not turn the plugin on, so the item reads as an error. */
		boolean failed;
	}

	static final String PATH_BUTTON = "Turn on Shortest Path";
	static final String FAILED_ITEM = "Could not turn it on";
	private static final String PATH_OPTIONAL = "Shortest Path is optional. It draws the route to your task and to your next master.";
	private static final String TRY_THE_LIST = " Turn it on in RuneLite's plugin list instead.";

	private PluginNotices()
	{
	}

	/**
	 * The line where the route buttons go when Shortest Path cannot draw a route, or null when it can, or when the
	 * routes are off, as nothing is said about Shortest Path then.
	 *
	 * @param failed whether the last press of the button left the plugin off
	 */
	static Notice shortestPath(ShortestPathBridge.Status status, PathMode mode, boolean failed)
	{
		if (!mode.showsButtons() || status == ShortestPathBridge.Status.ACTIVE)
		{
			return null;
		}
		if (status == ShortestPathBridge.Status.MISSING)
		{
			return new Notice("Optional: Shortest Path, Plugin Hub", PATH_OPTIONAL + " You can install it from the Plugin Hub.", null, false);
		}
		if (failed)
		{
			return new Notice(FAILED_ITEM, PATH_OPTIONAL + " The button could not turn it on." + TRY_THE_LIST, PATH_BUTTON, true);
		}
		return new Notice("Optional, draws the route", PATH_OPTIONAL + " It is installed but off.", PATH_BUTTON, false);
	}
}

package com.slayercompanion;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginInstantiationException;
import net.runelite.client.plugins.PluginManager;

/**
 * Turns another plugin on when the player presses a sidebar button, the way RuneLite's own plugin list does: enabled in
 * the config, then started. Nothing else switches a plugin on. The steps go through {@link Plugins}, so a failure can be
 * tested without a client.
 */
@Slf4j
final class PluginSwitch
{
	/** The plugin manager's three calls this needs. */
	interface Plugins
	{
		void setEnabled(Plugin plugin, boolean enabled);

		boolean start(Plugin plugin) throws PluginInstantiationException;

		boolean isActive(Plugin plugin);
	}

	private PluginSwitch()
	{
	}

	/** The plugin manager's own calls. Starting asserts the Swing thread, as the plugin list starts plugins there. */
	static Plugins of(PluginManager pluginManager)
	{
		return new Plugins()
		{
			@Override
			public void setEnabled(Plugin plugin, boolean enabled)
			{
				pluginManager.setPluginEnabled(plugin, enabled);
			}

			@Override
			public boolean start(Plugin plugin) throws PluginInstantiationException
			{
				return pluginManager.startPlugin(plugin);
			}

			@Override
			public boolean isActive(Plugin plugin)
			{
				return pluginManager.isPluginActive(plugin);
			}
		};
	}

	/**
	 * Swing thread. Whether the plugin runs afterwards. A plugin that fails to start stays enabled, as the plugin list
	 * leaves it, so it tries again at the next launch.
	 */
	static boolean turnOn(Plugins plugins, Plugin plugin)
	{
		if (plugin == null) return false;
		try
		{
			plugins.setEnabled(plugin, true);
			// Starting does nothing for a plugin that already runs, so the check below decides
			plugins.start(plugin);
		}
		catch (PluginInstantiationException | RuntimeException e)
		{
			log.warn("Could not turn on {}", plugin.getName(), e);
			return false;
		}
		return plugins.isActive(plugin);
	}
}

package com.slayercompanion;

/**
 * Holds back sidebar refreshes while one of its dropdowns is open. A refresh can come with every kill. Most
 * only change text in place, but a rebuild would close the open list under the cursor, so a refresh asked
 * for while a list is open runs once, after the list closes. Swing thread only.
 */
final class RefreshGate
{
	private boolean pending;

	/** Whether to rebuild now. A refresh while a list is open is remembered instead. */
	boolean shouldRebuild(boolean popupOpen)
	{
		if (popupOpen)
		{
			pending = true;
			return false;
		}
		pending = false;
		return true;
	}

	/** A list closed. Whether a refresh held back while it was open should run now. */
	boolean popupClosed()
	{
		final boolean run = pending;
		pending = false;
		return run;
	}
}

package com.slayercompanion;

import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.util.Text;

/**
 * Talks to the Shortest Path Plugin Hub plugin through RuneLite's PluginMessage events only, so there is
 * no build or runtime dependency on it. When it is missing or disabled nothing subscribes to the
 * messages and posting them does nothing.
 * <p>
 * Contract, read from the bytecode of Shortest Path 1.20.7 and again of 1.20.8 (ShortestPathPlugin#onPluginMessage):
 * namespace "shortestpath", name "path" with data key "target" holding a WorldPoint, a packed Integer
 * or a Set of either (it routes to the closest), and name "clear". Without a "start" key the handler
 * reads the local player's location, so messages must be posted on the client thread.
 */
@Singleton
class ShortestPathBridge
{
	static final String NAMESPACE = "shortestpath";
	static final String PATH = "path";
	static final String CLEAR = "clear";
	static final String TARGET = "target";
	static final String PLUGIN_CLASS = "shortestpath.ShortestPathPlugin";
	static final String PLUGIN_NAME = "Shortest Path";

	enum Status
	{
		/** Not installed. */
		MISSING,
		/** Installed but turned off. */
		DISABLED,
		ACTIVE
	}

	private final PluginManager pluginManager;
	private final EventBus eventBus;
	private PluginMessage lastPosted;

	@Inject
	ShortestPathBridge(PluginManager pluginManager, EventBus eventBus)
	{
		this.pluginManager = pluginManager;
		this.eventBus = eventBus;
	}

	Status status()
	{
		final Plugin plugin = find();
		if (plugin == null) return Status.MISSING;
		return pluginManager.isPluginActive(plugin) ? Status.ACTIVE : Status.DISABLED;
	}

	/** The installed Shortest Path plugin, or null. */
	Plugin find()
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (isShortestPath(plugin)) return plugin;
		}
		return null;
	}

	/** Client thread only. */
	void postPath(Collection<WorldPoint> targets)
	{
		post(new PluginMessage(NAMESPACE, PATH, pathData(targets)));
	}

	/** Client thread only. */
	void postClear()
	{
		post(new PluginMessage(NAMESPACE, CLEAR));
	}

	private void post(PluginMessage message)
	{
		lastPosted = message;
		eventBus.post(message);
	}

	/** True for the message this bridge is posting right now. Event bus delivery is synchronous. */
	boolean isOwnMessage(PluginMessage message)
	{
		return message == lastPosted;
	}

	static boolean isShortestPath(Plugin plugin)
	{
		if (plugin == null) return false;
		if (PLUGIN_CLASS.equals(plugin.getClass().getName())) return true;
		// Plugin.getName() is RuneLite's own way to a plugin's display name, so no reflection is needed here
		return PLUGIN_NAME.equals(plugin.getName());
	}

	/** A single target goes as a WorldPoint, several as a Set so Shortest Path picks the closest. */
	static Map<String, Object> pathData(Collection<WorldPoint> targets)
	{
		if (targets == null || targets.isEmpty())
		{
			throw new IllegalArgumentException("a route needs at least one target");
		}
		if (targets.size() == 1)
		{
			return Collections.singletonMap(TARGET, targets.iterator().next());
		}
		final Set<WorldPoint> set = new LinkedHashSet<>(targets);
		return Collections.singletonMap(TARGET, set.size() == 1 ? set.iterator().next() : set);
	}

	/** A "path" or "clear" request to Shortest Path, from any plugin. */
	static boolean isRouteRequest(PluginMessage message)
	{
		return message != null && NAMESPACE.equals(message.getNamespace())
				&& (PATH.equals(message.getName()) || CLEAR.equals(message.getName()));
	}

	/**
	 * Shortest Path's own menu entries that replace or clear the target: "Set Target" (also "Target 2"
	 * and so on for extra targets), "Clear Path" and "Find closest". "Set Start" keeps the target.
	 */
	static boolean changesTarget(String option, String target)
	{
		if (option == null) return false;
		final String what = target == null ? "" : Text.removeTags(target).trim();
		switch (option)
		{
			case "Set": return what.startsWith("Target");
			case "Clear": return what.equals("Path");
			case "Find closest": return true;
			default: return false;
		}
	}
}

