package com.slayercompanion;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.DBTableID;

/**
 * Reads area names from the game's SlayerArea table the same way the core Slayer plugin derives its
 * task location: the SLAYER_AREA varp value matches COL_AREA_ID, and COL_AREA_NAME_IN_HELPER is the
 * display name. Used only for areas the data file does not cover yet. Client thread only.
 */
@Slf4j
final class SlayerAreaTable
{
	private final Map<Integer, String> names = new HashMap<>();

	String areaName(Client client, int areaId)
	{
		if (areaId <= 0) return null;
		if (names.containsKey(areaId)) return names.get(areaId);
		String name = null;
		try
		{
			final List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, 0, areaId);
			if (rows != null && !rows.isEmpty())
			{
				final Object[] values = client.getDBTableField(rows.get(0), DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, 0);
				if (values != null && values.length > 0 && values[0] instanceof String)
				{
					name = (String) values[0];
				}
			}
		}
		catch (RuntimeException ex)
		{
			log.debug("Slayer Sensei could not read slayer area {} from the cache", areaId, ex);
		}
		names.put(areaId, name);
		return name;
	}
}

package com.slayercompanion;

import lombok.AllArgsConstructor;
import lombok.Getter;

/**
 * Every master spot that hands out tasks, keyed by the game's master id (SlayerMasterTask.COL_MASTER_ID
 * and the SLAYER_MASTER varbit). A replacement NPC takes over the spot and keeps its id, task list and
 * block list: Aya for Turael, Achtryn for Mazchna, Steve for Nieve, Kuradal for Duradel. See
 * {@link SlayerMasterAccess} for who stands where and {@link SlayerPayout} for the points.
 * {@link SlayerMaster} stays the list of block lists the planner can show.
 * <p>
 * Levels and quests are from the OSRS Wiki "Slayer Master" table and each master's page. Block and cancel
 * costs are the game's own (client scripts 823 and 9741, which match the same wiki table).
 */
@Getter
@AllArgsConstructor
enum SlayerAssigner
{
	TURAEL(1, "Turael", "Burthorpe", 0, 0, QuestNeed.NONE, Streak.MAIN, 40, 30),
	SPRIA(9, "Spria", "Draynor Village", 0, 0, QuestNeed.PORCINE_OF_INTEREST, Streak.MAIN, 40, 30),
	MAZCHNA(2, "Mazchna", "Canifis", 20, 0, QuestNeed.PRIEST_IN_PERIL, Streak.MAIN, 50, 30),
	VANNAKA(3, "Vannaka", "Edgeville Dungeon", 40, 0, QuestNeed.NONE, Streak.MAIN, 60, 30),
	CHAELDAR(4, "Chaeldar", "Zanaris", 70, 0, QuestNeed.LOST_CITY, Streak.MAIN, 70, 30),
	KONAR(8, "Konar", "Mount Karuulm", 75, 0, QuestNeed.NONE, Streak.MAIN, 80, 30),
	NIEVE(6, "Nieve", "the Tree Gnome Stronghold", 85, 0, QuestNeed.NONE, Streak.MAIN, 90, 30),
	DURADEL(5, "Duradel", "Shilo Village", 100, 50, QuestNeed.SHILO_VILLAGE, Streak.MAIN, 100, 30),
	/** Refuses players with level 1 Slayer, so her Slayer requirement is 2. */
	KRYSTILIA(7, "Krystilia", "Edgeville", 0, 2, QuestNeed.NONE, Streak.WILDERNESS, 100, 30),
	MORTIMER(10, "Mortimer", "Wyrmscraig Cavern", 100, 70, QuestNeed.FALLEN_FROM_GRACE_PART, Streak.MORTIMER, 120, 100);

	/** The quest a master needs before giving tasks. */
	enum QuestNeed
	{
		NONE,
		/** Canifis lies behind it. */
		PRIEST_IN_PERIL,
		/** Zanaris lies behind it. */
		LOST_CITY,
		/** Shilo Village lies behind it. */
		SHILO_VILLAGE,
		/** Spria takes assignments once A Porcine of Interest is done. */
		PORCINE_OF_INTEREST,
		/** Mortimer appears part way through Fallen From Grace. */
		FALLEN_FROM_GRACE_PART
	}

	/** Which task streak a master's tasks count toward. Each streak pays its own milestones. */
	enum Streak
	{
		/** SLAYER_TASKS_COMPLETED, shared by every master below. */
		MAIN,
		/** SLAYER_WILDERNESS_TASKS_COMPLETED, Krystilia only. */
		WILDERNESS,
		/** SLAYER_MORTIMER_TASKS_COMPLETED. His tasks pay no streak points at all. */
		MORTIMER
	}

	private final int id;
	/** The name of the NPC who first held the spot. */
	private final String displayName;
	private final String location;
	/** Combat level needed. 99 Slayer waives it, as the Slayer cape does in game. */
	private final int combatLevel;
	private final int slayerLevel;
	private final QuestNeed questNeed;
	private final Streak streak;
	/** Points to block a task at this master. */
	private final int blockCost;
	/** Points to cancel a task from this master. */
	private final int cancelCost;

	/** What client script 823 charges to block at a master it does not list. */
	static final int DEFAULT_BLOCK_COST = 100;

	/** The master for a game master id, or null for the leagues pool, no task and unknown ids. */
	static SlayerAssigner forId(int id)
	{
		for (SlayerAssigner a : values())
		{
			if (a.id == id) return a;
		}
		return null;
	}

	/** Points to block a task at the master with this game id. */
	static int blockCost(int masterId)
	{
		final SlayerAssigner master = forId(masterId);
		return master == null ? DEFAULT_BLOCK_COST : master.blockCost;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.slayercompanion;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.AllArgsConstructor;
import lombok.Value;

/**
 * Which tasks to block at one master for a goal, starting from the block list the player has. Pure.
 * <p>
 * A block is judged by how much it raises the goal's rate in {@link SlayerGoalModel}: tasks the player can
 * be assigned, weighed by how often they come up, how long they take and how poor they are for the goal (the
 * xp rating for XP, gp for profit, speed for Slayer points). The wiki gives the same rule: "The undesirable
 * tasks with the highest weighting ... should be blocked" (Slayer training).
 * <p>
 * Blocks cost points and unblocking refunds nothing (wiki Slayer Rewards), so a current block that helps the
 * goal stays even when another task would help a little more. For XP a task the wiki's Slayer guide says to do is
 * never blocked, and a block on one does not fit. Free slots are filled with the best blocks on
 * top of the kept ones. With every slot full, one swap is suggested when the best task left would help at
 * least {@link #SWAP_FACTOR} times as much as the weakest kept block.
 */
final class SlayerBlockAdvisor
{
	/** How much more a waiting block must help than the weakest current one before a swap is worth its points. */
	static final double SWAP_FACTOR = 2;
	private static final double EPSILON = 1e-9;

	/** A current block that does not fit the goal. */
	@Value
	static class Misfit
	{
		String name;
		/** Why, e.g. "good for XP". */
		String why;
	}

	@Value
	@AllArgsConstructor
	static class Advice
	{
		SlayerGoal goal;
		/** Points per block at this master. */
		int cost;
		/** Block slots the player can use at this master. */
		int slots;
		/** Current blocks that help the goal, in slot order. */
		List<String> keep;
		/** Tasks to block, best first: one per free slot, plus one per misfit to replace. */
		List<String> add;
		/** Current blocks that do not fit the goal, to unblock. */
		List<Misfit> misfits;
		/** The task rows of {@link #keep} and {@link #add}, so the points plan can value each block. */
		List<Integer> keepRows;
		List<Integer> addRows;

		/** Advice for the sidebar text alone, without task rows. */
		Advice(SlayerGoal goal, int cost, int slots, List<String> keep, List<String> add, List<Misfit> misfits)
		{
			this(goal, cost, slots, keep, add, misfits, Collections.<Integer>emptyList(), Collections.<Integer>emptyList());
		}
	}

	private SlayerBlockAdvisor()
	{
	}

	/**
	 * @param pool the master's pool with the player's current blocks
	 * @param slots block slots the player can use at the master
	 * @param blockedRows task rows on the master's block list, in slot order
	 */
	static Advice advise(SlayerMaster master, SlayerPool pool, SlayerGoal goal, int slots, List<Integer> blockedRows)
	{
		final List<Integer> kept = new ArrayList<>();
		final Map<Integer, Misfit> lifted = new HashMap<>();
		for (int row : blockedRows)
		{
			final SlayerPool.Entry e = pool.find(row);
			if (e == null || !e.isAssignable())
			{
				lifted.put(row, new Misfit(e == null ? "Task row " + row : e.getName(), "you cannot be given it anyway"));
			}
			else if (!e.isRated())
			{
				lifted.put(row, new Misfit(e.getName(), "not rated yet"));
			}
			else if (e.wikiSaysDo(goal))
			{
				lifted.put(row, new Misfit(e.getName(), "the wiki's Slayer guide says to do it for XP"));
			}
			else
			{
				kept.add(row);
			}
		}
		// A current block fits when lifting it, the others kept, would lower the rate. Blocks help each other, so each is
		// judged on top of the rest, and the one whose lifting raises the rate most goes first until every block left fits.
		while (!kept.isEmpty())
		{
			double best = SlayerGoalModel.rate(pool.withBlocks(kept), goal);
			Integer worst = null;
			for (Integer row : kept)
			{
				final List<Integer> without = new ArrayList<>(kept);
				without.remove(row);
				final double r = SlayerGoalModel.rate(pool.withBlocks(without), goal);
				if (r > best + EPSILON)
				{
					best = r;
					worst = row;
				}
			}
			if (worst == null) break;
			kept.remove(worst);
			lifted.put(worst, new Misfit(pool.find(worst).getName(), misfit(pool.find(worst), goal)));
		}
		final List<Misfit> misfits = new ArrayList<>();
		for (int row : blockedRows)
		{
			if (lifted.containsKey(row)) misfits.add(lifted.remove(row));
		}

		final int free = Math.max(0, slots - kept.size());
		List<SlayerPool.Entry> add = SlayerGoalModel.bestBlocks(pool, goal, kept, free);
		if (free == 0 && !kept.isEmpty())
		{
			// Every slot holds a useful block. Suggest one swap when a far better block is waiting.
			final List<SlayerPool.Entry> next = SlayerGoalModel.bestBlocks(pool, goal, kept, 1);
			final int weakest = weakest(pool, goal, kept);
			if (!next.isEmpty() && gain(pool, goal, kept, next.get(0).getTaskRow()) > SWAP_FACTOR * contribution(pool, goal, kept, weakest))
			{
				kept.remove(Integer.valueOf(weakest));
				misfits.add(new Misfit(pool.find(weakest).getName(), "a weaker block than " + next.get(0).getName()));
				add = next;
			}
		}

		final List<String> keep = new ArrayList<>();
		for (int row : kept)
		{
			keep.add(pool.find(row).getName());
		}
		final List<String> addNames = new ArrayList<>();
		final List<Integer> addRows = new ArrayList<>();
		for (SlayerPool.Entry e : add)
		{
			addNames.add(e.getName());
			addRows.add(e.getTaskRow());
		}
		return new Advice(goal, SlayerAssigner.blockCost(master.getId()), slots, Collections.unmodifiableList(keep),
				Collections.unmodifiableList(addNames), Collections.unmodifiableList(misfits),
				Collections.unmodifiableList(new ArrayList<>(kept)), Collections.unmodifiableList(addRows));
	}

	/** The kept block that helps least, given the others. */
	private static int weakest(SlayerPool pool, SlayerGoal goal, List<Integer> kept)
	{
		int weakest = kept.get(0);
		double least = Double.MAX_VALUE;
		for (int row : kept)
		{
			final double c = contribution(pool, goal, kept, row);
			if (c < least)
			{
				least = c;
				weakest = row;
			}
		}
		return weakest;
	}

	/** How much the rate drops when {@code row} is unblocked and the other kept blocks stay. */
	private static double contribution(SlayerPool pool, SlayerGoal goal, List<Integer> kept, int row)
	{
		final List<Integer> without = new ArrayList<>(kept);
		without.remove(Integer.valueOf(row));
		return SlayerGoalModel.rate(pool.withBlocks(kept), goal) - SlayerGoalModel.rate(pool.withBlocks(without), goal);
	}

	/** How much the rate rises when {@code row} is blocked on top of the kept blocks. */
	private static double gain(SlayerPool pool, SlayerGoal goal, List<Integer> kept, int row)
	{
		final List<Integer> with = new ArrayList<>(kept);
		with.add(row);
		return SlayerGoalModel.rate(pool.withBlocks(with), goal) - SlayerGoalModel.rate(pool.withBlocks(kept), goal);
	}

	/**
	 * Why a current block does not fit: the task is good for the goal, or, for a task rated lower, a block on it
	 * lowers the rate all the same. A task rated below good is never called good.
	 */
	private static String misfit(SlayerPool.Entry e, SlayerGoal goal)
	{
		switch (goal)
		{
			case XP:
				return e.rating(goal) >= SlayerSpend.GOOD ? "good for XP" : "a block on it lowers your XP rate";
			case PROFIT:
				return e.rating(goal) >= SlayerSpend.GOOD ? "good for profit" : "a block on it lowers your profit rate";
			default:
				return "quick enough";
		}
	}
}

package com.slayercompanion;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.ui.overlay.OverlayPosition;

@ConfigGroup("slayercompanion")
public interface SlayerCompanionConfig extends Config
{
	@ConfigItem(keyName = "showPanel", name = "Show panel", description = "Show a small panel over the game with the task, kills left, gear warnings, streak and points. It shows for a while after a new task and for three minutes after each kill on the task.", position = 0)
	default boolean showPanel()
	{
		return true;
	}

	@ConfigItem(keyName = "position", name = "Panel position", description = "Where the panel sits on the game screen", position = 1)
	default OverlayPosition panelPosition()
	{
		return OverlayPosition.TOP_RIGHT;
	}

	@ConfigItem(keyName = "showAwayFromTaskTargets", name = "Always show panel", description = "Keep the panel on screen the whole time you have a task, not only after a new task and while you kill", position = 2)
	default boolean showAwayFromTaskTargets()
	{
		return false;
	}

	@Range(min = 0, max = 300)
	@ConfigItem(keyName = "taskIntroSeconds", name = "New-task display (seconds)", description = "Show the panel for this long after you get a new task, so the gear warnings are there before you set off", position = 3)
	default int taskIntroSeconds()
	{
		return 120;
	}

	@ConfigItem(keyName = "showPanelGear", name = "Gear lines on panel", description = "Add a red line to the panel when you lack an item the task needs, and a yellow one when it is in your bank or when you lack an item the wiki recommends for it", position = 4)
	default boolean showPanelGear()
	{
		return true;
	}

	@ConfigItem(keyName = "showRecommendedGear", name = "Recommended gear", description = "Also check for items the wiki recommends for the task, such as a demonbane weapon against demons. Off, the sidebar and the panel only ask for items the task needs.", position = 5)
	default boolean showRecommendedGear()
	{
		return true;
	}

	@ConfigItem(keyName = "showUnlockAdvisor", name = "Unlock advisor", description = "Show a line in the sidebar on the task in progress: do it, skip it, block it or buy its extension. The advice follows your Slayer goal.", position = 6)
	default boolean showUnlockAdvisor()
	{
		return true;
	}

	@ConfigItem(keyName = "showMapMarker", name = "Task map marker", description = "Pin the task location on the world map. Konar's assigned area comes first, otherwise the place you picked in the sidebar or the recommended one. Off screen it becomes an arrow at the map edge. Click it to focus the map there.", position = 7)
	default boolean showMapMarker()
	{
		return true;
	}

	@ConfigItem(keyName = "showSidebar", name = "Full dossier sidebar", description = "Add a Slayer Sensei sidebar with the complete, wrapping task guide", position = 8)
	default boolean showSidebar()
	{
		return true;
	}

	String SIDEBAR_DETAIL_KEY = "sidebarDetail";

	@ConfigItem(keyName = SIDEBAR_DETAIL_KEY, name = "Sidebar detail", description = "Compact shows short lists. Hover an item to see why. Detailed shows every line as a sentence.", position = 9)
	default SidebarDetail sidebarDetail()
	{
		return SidebarDetail.COMPACT;
	}

	@ConfigItem(keyName = "showPointsPlanner", name = "Points planner", description = "Show a slayer points spend plan in the sidebar, based on what you already bought, your block list and your levels", position = 10)
	default boolean showPointsPlanner()
	{
		return true;
	}

	@ConfigItem(keyName = "plannerMaster", name = "Planner master", description = "Master whose task pool and block list the points plan uses when Pin planner master is on, or when your goal points to no master yet", position = 11)
	default SlayerMaster plannerMaster()
	{
		return SlayerMaster.KONAR;
	}

	@Range(min = 0, max = 1000)
	@ConfigItem(keyName = "pointsReserve", name = "Points to keep for skips", description = "The plan already keeps enough to skip the bad tasks its master ranking expects you to skip. Set this to keep at least this many.", position = 12)
	default int pointsReserve()
	{
		return 0;
	}

	@ConfigItem(keyName = "pathMode", name = "Route to task", description = "Draw the route to the task with the Shortest Path plugin. New task and button draws it once each time you get a new task. Every mode except Off adds route buttons to the sidebar: Path to task, Clear path, and a path to the master your goal says to visit next.", position = 13)
	default PathMode pathMode()
	{
		return PathMode.NEW_TASK;
	}

	String GOAL_KEY = "goal";

	@ConfigItem(keyName = GOAL_KEY, name = "Slayer goal", description = "What the points plan works toward. Slayer points adds a next task routine. You can also switch it at the top of the plan in the sidebar.", position = 20)
	default SlayerGoal goal()
	{
		return SlayerGoal.POINTS;
	}

	@ConfigItem(keyName = "boostInterval", name = "Points boost", description = "For the Slayer points goal. Which milestone tasks go to the master who pays most. Every 10th task earns more points. Every 50th task means fewer hard tasks.", position = 21)
	default BoostInterval boostInterval()
	{
		return BoostInterval.EVERY_10TH;
	}

	@ConfigItem(keyName = "pinPlannerMaster", name = "Pin planner master", description = "Off: the plan uses the master your goal points to, the best master for XP or profit, or the master who pays most for milestones for Slayer points. On: it always uses the Planner master.", position = 22)
	default boolean pinPlannerMaster()
	{
		return false;
	}
}

package com.slayercompanion;

import com.slayercompanion.data.SlayerTask;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import lombok.Value;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * The panel over the game for the task in progress: the task's name, the kills left, Konar's area, a line for each
 * item that is missing or worth bringing, the streak and the points. The gear lines have their own setting, and
 * {@link SlayerCompanionPlugin#shouldShowOverlay} decides when the panel shows.
 */
public class SlayerCompanionOverlay extends OverlayPanel
{
	private final SlayerCompanionPlugin plugin;
	private final SlayerCompanionConfig config;

	/** One gear line: the compact sidebar's words in the sidebar's colour. */
	@Value
	static class GearLine
	{
		String text;
		Color color;
	}

	@Inject
	private SlayerCompanionOverlay(SlayerCompanionPlugin plugin, SlayerCompanionConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPriority(PRIORITY_LOW);
		setPosition(config.panelPosition());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showPanel())
		{
			return null;
		}
		if (!plugin.shouldShowOverlay())
		{
			return null;
		}
		setPosition(config.panelPosition());

		final List<String> texts = new ArrayList<>();
		final SlayerTask t = plugin.getCurrentTask();
		if (t == null)
		{
			if (plugin.getTaskName() == null)
			{
				return null;
			}
			// Have a task the dataset doesn't cover yet.
			addTitle(plugin.getTaskName(), texts);
			addLine("No dossier for this task yet", Color.GRAY, texts);
			addGearLines(texts);
			return render(graphics, texts);
		}

		addTitle(t.getTask(), texts);
		addLine("Status", hasValue(plugin.getTaskAmount()) ? plugin.getTaskAmount() + " left" : "active", Color.WHITE, texts);
		final Destination destination = plugin.getDestination();
		if (destination != null && destination.getOrigin() == Destination.Origin.ASSIGNED)
		{
			addLine("Area", destination.getLabel(), new Color(120, 200, 255), texts);
		}
		addGearLines(texts);
		addLine("Streak", hasValue(plugin.getTaskStreak()) ? plugin.getTaskStreak() : "?", new Color(255, 215, 0), texts);
		addLine("Points", hasValue(plugin.getSlayerPoints()) ? plugin.getSlayerPoints() : "?", new Color(120, 200, 255), texts);

		return render(graphics, texts);
	}

	/** The panel's narrowest and widest size. */
	static final int MIN_WIDTH = 150;
	static final int MAX_WIDTH = 240;
	/** The panel's border on both sides of a line, plus a little room, so the widest line does not wrap. */
	private static final int SIDE_ROOM = 12;

	/** Sizes the panel to its widest line in the game's font, within the bounds, then draws it. */
	private Dimension render(Graphics2D graphics, List<String> texts)
	{
		int widest = 0;
		for (String text : texts)
		{
			widest = Math.max(widest, graphics.getFontMetrics().stringWidth(text));
		}
		panelComponent.setPreferredSize(new Dimension(panelWidth(widest), 0));
		return super.render(graphics);
	}

	/** The panel's width for its widest line: wide enough that the line does not wrap, within the bounds. */
	static int panelWidth(int widestLine)
	{
		return Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, widestLine + SIDE_ROOM));
	}

	private void addTitle(String text, List<String> texts)
	{
		panelComponent.getChildren().add(TitleComponent.builder().text(text).color(ColorScheme.BRAND_ORANGE).build());
		texts.add(text);
	}

	/** What is missing and what to bring, from the gear check the sidebar shows. Read once, as the client thread replaces it. */
	private void addGearLines(List<String> texts)
	{
		if (!config.showPanelGear())
		{
			return;
		}
		for (GearLine line : gearLines(plugin.getGearResult()))
		{
			addLine(line.getText(), line.getColor(), texts);
		}
	}

	/**
	 * A red line for each missing mandatory item and a yellow one for each item to bring, from the bank or recommended.
	 * Empty without either.
	 */
	static List<GearLine> gearLines(SlayerGearCheck.Result gear)
	{
		if (gear == null)
		{
			return Collections.emptyList();
		}
		final List<GearLine> lines = new ArrayList<>();
		for (String item : gear.getMissing())
		{
			lines.add(new GearLine(item, SlayerCompanionPanel.gearColor(SlayerGearCheck.Status.MISSING)));
		}
		for (String item : gear.getBring())
		{
			lines.add(new GearLine(item, SlayerCompanionPanel.gearColor(SlayerGearCheck.Status.BRING)));
		}
		return lines;
	}

	private void addLine(String label, String value, Color color, List<String> texts)
	{
		if (value == null || value.isEmpty())
		{
			return;
		}
		addLine(label + ": " + value, color, texts);
	}

	private void addLine(String text, Color color, List<String> texts)
	{
		panelComponent.getChildren().add(LineComponent.builder().left(text).leftColor(color).build());
		texts.add(text);
	}

	private static boolean hasValue(String value)
	{
		return value != null && !value.isEmpty();
	}

}

package com.slayercompanion;

import com.slayercompanion.data.SlayerTask;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.Rectangle;
import java.awt.event.ItemEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Objects;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.DefaultListCellRenderer;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
