		if (task != null)
		{
			task.setCannon(value);
		}
	}

	private static SlayerTask genericFallback(String taskName)
	{
		if (taskName == null || taskName.trim().isEmpty())
		{
			return null;
		}

		final SlayerTask task = new SlayerTask();
		task.setTask(taskName.trim());
		task.setAssignedBy("A task the dossier does not cover yet. Which masters give it depends on your levels, quests and unlocks.");
		task.setNote("This task is not in the dossier yet. Do not block it or spend points on it from this alone.");
		// The compact sidebar shows the words before the first full stop as the place
		task.setBestLocation("Not in the dossier yet. Go to the area Konar named, or into the Wilderness for Krystilia. For any other"
				+ " master, check the world map or the Slayer master's tip before you travel.");
		task.setMultiOrSingle("Unknown. Check the area before you bring a cannon or a multi-target setup.");
		task.setKillStyle("Check the gear and weapon the monster needs before you pick a setup.");
		task.setWeakness("Not known yet. Do not assume an elemental weakness.");
		task.setMonsterAttackStyle("Unknown. Watch its first attack from a safe spot and look the monster up on the wiki before"
				+ " you rely on a prayer.");
		task.setProtectionPrayer("No verified prayer recommendation yet.");
		task.setRequiredItems("Check the Slayer master's tip before you attack. Some Slayer monsters need protective gear or a"
				+ " special weapon.");
		task.setCannon("Unknown. Check that the area allows a cannon.");
		task.setHasSuperior(false);
		task.setNotableDrops("Not listed yet. The Loot Tracker plugin shows what you get.");
		return task;
	}

	private void alias(String alias, String canonical)
	{
		final SlayerTask task = byName.get(normalize(canonical));
		if (task != null)
		{
			aliases.put(normalize(alias), task);
		}
	}

	private static String singular(String value)
	{
		if (value.endsWith("ies"))
		{
			return value.substring(0, value.length() - 3) + "y";
		}
		return value.endsWith("s") ? value.substring(0, value.length() - 1) : value;
	}

	/** The sidebar's Data line: where the notes come from, or that they are general advice for a task without a dossier. */
	public String dataLabel(SlayerTask task)
	{
		return task != null && lookup(task.getTask()) == null ? FALLBACK_LABEL : DATA_LABEL;
	}
}

package com.slayercompanion;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;

/**
 * Reward shop and task-pool data read from the game cache's database tables, so costs, names and
 * master weights track game updates without a plugin release. Must be loaded on the client thread.
 * Every column read here was checked against a dump of the live cache and the game's own client
 * scripts (tools/cache-dump). That includes which reward lengthens which task and to what amount, and
 * the items and costs of the shop's Buy tab, which come from two enums rather than a table.
 */
@Slf4j
final class SlayerGameData
{
	/**
	 * SlayerUnlock.COL_BIT is a bit index across these three varps, 32 bits each, in this order. It is
	 * not a varbit id. The game's own ownership check (client script 8048) reads it the same way.
	 */
	static final int[] UNLOCK_VARPS = {
		VarPlayerID.SLAYER_REWARDS_UNLOCKS, VarPlayerID.SLAYER_REWARDS_UNLOCKS1, VarPlayerID.SLAYER_REWARDS_UNLOCKS2};

	/** Stat ids in the requirement columns follow {@link net.runelite.api.Skill} order. */
	private static final int STAT_SLAYER = 18;

	/** Shop tabs, the first value of SlayerUnlock.COL_LIST_POSITION. */
	static final int TAB_UNLOCK = 0;
	static final int TAB_EXTEND = 1;
	static final int TAB_COSMETIC = 2;

	/**
	 * The reward shop's Buy tab, as client script 322 draws it: enum 840 holds the item in each slot and enum 842
	 * each item's cost in points. RuneLite has no gameval names for these enums. Checked against the cache dump
	 * (tools/cache-dump, section shopBuyTab).
	 */
	static final int SHOP_ITEMS_ENUM = 840;
	static final int SHOP_COSTS_ENUM = 842;

	/** The client's DB table reads, behind an interface so parsing can be tested against a cache dump. */
	interface Db
	{
		List<Integer> rows(int table);

		/**
		 * Same contract as {@link Client#getDBTableField}: element {@code tupleIndex} of every tuple stored
		 * in the column, so a list column returns one value per entry. A row without a value returns the
		 * column default, else an empty array. A tuple index past the column's types throws.
		 */
		Object[] field(int row, int column, int tupleIndex);

		/** An enum's keys and int values as {@link Client#getEnum} holds them, {keys, values}. Empty when unknown. */
		default int[][] enumInts(int enumId)
		{
			return new int[][]{new int[0], new int[0]};
		}

		/**
		 * Same contract as {@link Client#getDBRowsByValue}: the rows of {@code table} whose column holds {@code value} at
		 * {@code tupleIndex}, in table order. The client looks it up in its index. This default scans the rows.
		 */
		default List<Integer> rowsByValue(int table, int column, int tupleIndex, Object value)
		{
			final List<Integer> found = new ArrayList<>();
			for (int row : rows(table))
			{
				if (Arrays.asList(field(row, column, tupleIndex)).contains(value)) found.add(row);
			}
			return found;
		}
	}

	@Value
	static class Unlock
	{
		int row;
		String name;
		int cost;
		/** Bit index into {@link #UNLOCK_VARPS}, or -1. */
		int bit;
		/** Every task the reward names. Pedal to the Metals lists all metal dragons, I Wildy More Slayer four tasks. */
		List<Integer> relatedTaskRows;
		/** False for rewards taken out of the shop. Their rows stay in the cache with list position (-1, -1). */
		boolean listed;
		/** The shop tab: {@link #TAB_UNLOCK}, {@link #TAB_EXTEND} or {@link #TAB_COSMETIC}. -1 when unlisted. */
		int tab;
	}

	/**
	 * How a reward changes the amount of one task (SlayerTask COL_EXTENSION_MIN_MAX and COL_EXTENSION_ADDITIVE).
	 * The wiki: extending "will increase the amount assigned across all slayer masters that can assign it
	 * regardless of the quantity they can originally assign" (Slayer Rewards).
	 */
	@Value
	static class Extension
	{
		int unlockRow;
		int taskRow;
		/** The new fewest and most kills, or the kills added to the master's own range when {@link #additive}. */
		int min;
		int max;
		boolean additive;

		int extendedMin(int masterMin)
		{
			return additive ? masterMin + min : min;
		}

		int extendedMax(int masterMax)
		{
			return additive ? masterMax + max : max;
		}
	}

	/** A reward that changes a task's weight, e.g. Chance of Heavy Frost (SlayerTask COL_UNLOCK_WEIGHTING). */
	@Value
	static class Weighting
	{
		int unlockRow;
		int taskRow;
		int weight;
	}

	@Value
	static class PoolEntry
	{
		int taskRow;
		int weight;
		/** Unlock the player must own before this master assigns the task, or -1. */
		int unlockRow;
		/** Fewest and most kills the master assigns. -1 for boss tasks, where the player picks the amount. */
		int minAmount;
		int maxAmount;
	}

	/** A stat level a master checks before assigning a task. Stat ids follow {@link net.runelite.api.Skill} order. */
	@Value
	static class StatLevel
	{
		int stat;
		int level;
	}

	private final Map<Integer, Unlock> unlocks = new HashMap<>();
	private final Map<Integer, String> taskNames = new HashMap<>();
	private final Map<String, List<Integer>> taskRowsByName = new HashMap<>();
	private final Map<Integer, Integer> taskRowById = new HashMap<>();
	private final Map<Integer, Integer> slayerLevels = new HashMap<>();
	private final Map<Integer, Integer> combatLevels = new HashMap<>();
	private final Map<Integer, List<StatLevel>> statsAll = new HashMap<>();
	private final Map<Integer, List<StatLevel>> statsAny = new HashMap<>();
	private final Map<Integer, List<PoolEntry>> pools = new HashMap<>();
	private final Map<Integer, Double> typicalAmounts = new HashMap<>();
	private final Set<Integer> poolUnlocks = new HashSet<>();
	private final Map<Integer, List<Extension>> extensions = new HashMap<>();
	private final Map<Integer, Extension> extensionOfTask = new HashMap<>();
	private final Map<Integer, List<Weighting>> weightings = new HashMap<>();
	private final Map<Integer, List<Integer>> blockedBy = new HashMap<>();
	private final Map<Integer, Integer> shopCosts = new LinkedHashMap<>();

	private SlayerGameData()
	{
	}

	static SlayerGameData load(Client client)
	{
		return load(db(client));
	}

	/** The client's own table reads. Client thread. */
	static Db db(Client client)
	{
		return new Db()
		{
			@Override
			public List<Integer> rows(int table)
			{
				return client.getDBTableRows(table);
			}

			@Override
			public Object[] field(int row, int column, int tupleIndex)
			{
				return client.getDBTableField(row, column, tupleIndex);
			}

			@Override
			public int[][] enumInts(int enumId)
			{
				final EnumComposition e = client.getEnum(enumId);
				if (e == null || e.getKeys() == null || e.getIntVals() == null) return new int[][]{new int[0], new int[0]};
				return new int[][]{e.getKeys(), e.getIntVals()};
			}

			@Override
			public List<Integer> rowsByValue(int table, int column, int tupleIndex, Object value)
			{
				return client.getDBRowsByValue(table, column, tupleIndex, value);
			}
		};
	}

	static SlayerGameData load(Db db)
	{
		final SlayerGameData data = new SlayerGameData();
		try
		{
			data.loadTasks(db);
			data.loadUnlocks(db);
			data.loadPools(db);
		}
		catch (RuntimeException ex)
		{
			log.warn("Slayer Sensei could not read the Slayer cache tables. The points planner uses its built-in fallback.", ex);
			return null;
		}
		// The rest only adds detail to the plan, so a failure leaves it out instead of losing the tables
		try
		{
			data.loadTaskRewards(db);
		}
		catch (RuntimeException ex)
		{
			log.warn("Slayer Sensei could not read the task extensions from the cache", ex);
			data.extensions.clear();
			data.extensionOfTask.clear();
			data.weightings.clear();
			data.blockedBy.clear();
		}
		try
		{
			data.loadShop(db);
		}
		catch (RuntimeException ex)
		{
			log.warn("Slayer Sensei could not read the reward shop's Buy tab from the cache", ex);
			data.shopCosts.clear();
		}
		log.debug("Slayer Sensei cache: {} tasks, {} unlocks, master pools {}, {} extensions, Buy tab {}",
				data.taskNames.size(), data.unlocks.size(), data.pools.keySet(), data.extensions.size(), data.shopCosts);
		return data;
	}

	private void loadTasks(Db db)
	{
		for (int row : db.rows(DBTableID.SlayerTask.ID))
		{
			final String name = stringField(db, row, DBTableID.SlayerTask.COL_NAME_UPPERCASE);
			if (name != null && !name.isEmpty())
			{
				taskNames.put(row, name);
				taskRowsByName.computeIfAbsent(name.toLowerCase(Locale.ROOT), k -> new ArrayList<>()).add(row);
			}
			// The id the block-list varbits and the SLAYER_TARGET varp store. Boss sub-tasks have -1.
			final int id = intField(db, row, DBTableID.SlayerTask.COL_ID, -1);
			if (id > 0) taskRowById.put(id, row);
			// (level, stat) tuples, all of which a master checks before assigning the task
			final List<StatLevel> all = statLevels(db, row, DBTableID.SlayerTask.COL_MIN_STAT_REQUIREMENT_ALL);
			for (StatLevel s : all)
			{
				if (s.getStat() == STAT_SLAYER) slayerLevels.put(row, s.getLevel());
			}
			if (!all.isEmpty()) statsAll.put(row, all);
			// At least one of these, e.g. 60 Strength or 60 Agility for the God Wars Dungeon
			final List<StatLevel> any = statLevels(db, row, DBTableID.SlayerTask.COL_MIN_STAT_REQUIREMENT_ANY);
			if (!any.isEmpty()) statsAny.put(row, any);
			final int combat = intField(db, row, DBTableID.SlayerTask.COL_MIN_COMLEVEL, 0);
			if (combat > 0) combatLevels.put(row, combat);
		}
	}

	private static List<StatLevel> statLevels(Db db, int row, int column)
	{
		final Object[] levels = db.field(row, column, 0);
		final Object[] stats = db.field(row, column, 1);
		final List<StatLevel> out = new ArrayList<>();
		for (int i = 0; i < Math.min(levels.length, stats.length); i++)
		{
			final int stat = asInt(stats[i], -1);
			if (stat >= 0) out.add(new StatLevel(stat, asInt(levels[i], 0)));
		}
		return out;
	}

	private void loadUnlocks(Db db)
	{
		for (int row : db.rows(DBTableID.SlayerUnlock.ID))
		{
			// (tab, position) in the shop
			final int tab = intField(db, row, DBTableID.SlayerUnlock.COL_LIST_POSITION, -1);
			unlocks.put(row, new Unlock(row,
					stringField(db, row, DBTableID.SlayerUnlock.COL_NAME),
					intField(db, row, DBTableID.SlayerUnlock.COL_COST, -1),
					intField(db, row, DBTableID.SlayerUnlock.COL_BIT, -1),
					intList(db, row, DBTableID.SlayerUnlock.COL_RELATED_TASK),
					tab >= 0, Math.max(-1, tab)));
		}
	}

	/** Extensions, weightings and blockers, which each task row names with the reward that changes it. */
	private void loadTaskRewards(Db db)
	{
		for (int row : db.rows(DBTableID.SlayerTask.ID))
		{
			addExtensions(db, row, DBTableID.SlayerTask.COL_EXTENSION_MIN_MAX, false);
			addExtensions(db, row, DBTableID.SlayerTask.COL_EXTENSION_ADDITIVE, true);
			// (unlock, weight)
			final Object[] weightUnlocks = db.field(row, DBTableID.SlayerTask.COL_UNLOCK_WEIGHTING, 0);
			final Object[] weights = db.field(row, DBTableID.SlayerTask.COL_UNLOCK_WEIGHTING, 1);
			for (int i = 0; i < Math.min(weightUnlocks.length, weights.length); i++)
			{
				final int unlock = asInt(weightUnlocks[i], -1);
				if (unlock >= 0) weightings.computeIfAbsent(unlock, k -> new ArrayList<>()).add(new Weighting(unlock, row, asInt(weights[i], 0)));
			}
			for (Object blocker : db.field(row, DBTableID.SlayerTask.COL_BLOCK_UNLOCK, 0))
			{
				final int unlock = asInt(blocker, -1);
				if (unlock >= 0) blockedBy.computeIfAbsent(unlock, k -> new ArrayList<>()).add(row);
			}
		}
	}

	/** (unlock, min, max) tuples. */
	private void addExtensions(Db db, int row, int column, boolean additive)
	{
		final Object[] rewards = db.field(row, column, 0);
		final Object[] mins = db.field(row, column, 1);
		final Object[] maxes = db.field(row, column, 2);
		for (int i = 0; i < Math.min(rewards.length, Math.min(mins.length, maxes.length)); i++)
		{
			final int unlock = asInt(rewards[i], -1);
			if (unlock < 0) continue;
			final Extension e = new Extension(unlock, row, asInt(mins[i], 0), asInt(maxes[i], 0), additive);
			extensions.computeIfAbsent(unlock, k -> new ArrayList<>()).add(e);
			extensionOfTask.putIfAbsent(row, e);
		}
	}

	private void loadShop(Db db)
	{
		final int[][] slots = db.enumInts(SHOP_ITEMS_ENUM);
		final int[][] costs = db.enumInts(SHOP_COSTS_ENUM);
		final Map<Integer, Integer> cost = new HashMap<>();
		for (int i = 0; i < Math.min(costs[0].length, costs[1].length); i++)
		{
			cost.put(costs[0][i], costs[1][i]);
		}
		// Slot order, as the tab lists them
		final int[] order = slots[0].clone();
		Arrays.sort(order);
		for (int slot : order)
		{
			for (int i = 0; i < Math.min(slots[0].length, slots[1].length); i++)
			{
				if (slots[0][i] == slot && cost.containsKey(slots[1][i])) shopCosts.put(slots[1][i], cost.get(slots[1][i]));
			}
		}
	}

	private void loadPools(Db db)
	{
		for (int row : db.rows(DBTableID.SlayerMasterTask.ID))
		{
			final int master = intField(db, row, DBTableID.SlayerMasterTask.COL_MASTER_ID, -1);
			if (master < 0) continue;
			// The column could hold a list, but every pool row has at most one unlock
			final int unlock = intField(db, row, DBTableID.SlayerMasterTask.COL_TASK_UNLOCK, -1);
			if (unlock >= 0) poolUnlocks.add(unlock);
			pools.computeIfAbsent(master, k -> new ArrayList<>()).add(new PoolEntry(
					intField(db, row, DBTableID.SlayerMasterTask.COL_TASK, -1),
					intField(db, row, DBTableID.SlayerMasterTask.COL_WEIGHT, 0),
					unlock,
					intField(db, row, DBTableID.SlayerMasterTask.COL_MIN_AMOUNT, -1),
					intField(db, row, DBTableID.SlayerMasterTask.COL_MAX_AMOUNT, -1)));
		}
		// The task ratings' speed is judged at the amounts the regular masters give most of. Mortimer's
		// amounts move with his modifiers, so his count only when no other master assigns the task.
		final Map<Integer, Double> regular = new HashMap<>();
		final Map<Integer, Double> mortimer = new HashMap<>();
		for (Map.Entry<Integer, List<PoolEntry>> pool : pools.entrySet())
		{
			final SlayerAssigner master = SlayerAssigner.forId(pool.getKey());
			if (master == null) continue;
			for (PoolEntry e : pool.getValue())
			{
				if (e.getMinAmount() <= 0) continue;
				final double average = (e.getMinAmount() + e.getMaxAmount()) / 2.0;
				(master == SlayerAssigner.MORTIMER ? mortimer : regular).merge(e.getTaskRow(), average, Math::max);
			}
		}
		typicalAmounts.putAll(mortimer);
		typicalAmounts.putAll(regular);
	}

	Unlock unlock(int row)
	{
		return unlocks.get(row);
	}

	Collection<Unlock> unlocks()
	{
		return Collections.unmodifiableCollection(unlocks.values());
	}

	String taskName(int taskRow)
	{
		return taskNames.get(taskRow);
	}

	/** Rows of the tasks with this display name, ignoring case. */
	List<Integer> taskRowsNamed(String name)
	{
		final List<Integer> rows = taskRowsByName.get(name.toLowerCase(Locale.ROOT));
		return rows == null ? Collections.emptyList() : rows;
	}

	/** Block-list varbits store the task's numeric id, not its database row. */
	int taskRowForId(int taskId)
	{
		final Integer row = taskRowById.get(taskId);
		return row == null ? -1 : row;
	}

	/** Slayer level a master needs before assigning the task, 0 when it needs none. */
	int slayerLevel(int taskRow)
	{
		final Integer level = slayerLevels.get(taskRow);
		return level == null ? 0 : level;
	}

	/** Combat level a master needs before assigning the task, 0 when it needs none. */
	int combatLevel(int taskRow)
	{
		final Integer level = combatLevels.get(taskRow);
		return level == null ? 0 : level;
	}

	/** Every stat level the task needs, Slayer included. */
	List<StatLevel> statsAll(int taskRow)
	{
		final List<StatLevel> stats = statsAll.get(taskRow);
		return stats == null ? Collections.emptyList() : Collections.unmodifiableList(stats);
	}

	/** Stat levels of which the task needs one, or an empty list. */
	List<StatLevel> statsAny(int taskRow)
	{
		final List<StatLevel> stats = statsAny.get(taskRow);
		return stats == null ? Collections.emptyList() : Collections.unmodifiableList(stats);
	}

	/**
	 * The largest average amount any regular master assigns of the task, or Mortimer's when only he does.
	 * The task ratings judge speed at this amount. 0 for boss tasks and unknown rows.
	 */
	double typicalAmount(int taskRow)
	{
		final Double amount = typicalAmounts.get(taskRow);
		return amount == null ? 0 : amount;
	}

	/** The master's whole pool, including tasks the player has not unlocked or has blocked. */
	List<PoolEntry> pool(SlayerMaster master)
	{
		return pool(master.getId());
	}

	/** The pool of a game master id. Spria and Mortimer have pools of their own. */
	List<PoolEntry> pool(int masterId)
	{
		final List<PoolEntry> pool = pools.get(masterId);
		return pool == null ? Collections.emptyList() : Collections.unmodifiableList(pool);
	}

	/** Whether some master needs this unlock before assigning a task, i.e. it adds tasks. */
	boolean gatesPool(int unlockRow)
	{
		return poolUnlocks.contains(unlockRow);
	}

	/** The tasks a reward lengthens, one entry per task. Empty for every other reward. */
	List<Extension> extensions(int unlockRow)
	{
		final List<Extension> list = extensions.get(unlockRow);
		return list == null ? Collections.emptyList() : Collections.unmodifiableList(list);
	}

	/** The reward that lengthens a task, or null when the task has none. */
	Extension extensionOf(int taskRow)
	{
		return extensionOfTask.get(taskRow);
	}

	/** The task weights a reward changes, e.g. Chance of Heavy Frost. */
	List<Weighting> weightings(int unlockRow)
	{
		final List<Weighting> list = weightings.get(unlockRow);
		return list == null ? Collections.emptyList() : Collections.unmodifiableList(list);
	}

	/** Task rows a reward keeps out of every master's list without a block slot, e.g. Stop the Wyvern. */
	List<Integer> blockedBy(int unlockRow)
	{
		final List<Integer> list = blockedBy.get(unlockRow);
		return list == null ? Collections.<Integer>emptyList() : Collections.unmodifiableList(list);
	}

	/** The Buy tab's items in slot order, each with its cost in points. Empty when the enums could not be read. */
	Map<Integer, Integer> shopItems()
	{
		return Collections.unmodifiableMap(shopCosts);
	}

	/** Whether the reward on this bit is owned. {@code varp} reads a varp, e.g. {@code client::getVarpValue}. */
	static boolean ownsBit(IntUnaryOperator varp, int bit)
	{
		if (bit < 0 || bit >= UNLOCK_VARPS.length * 32) return false;
		return (varp.applyAsInt(UNLOCK_VARPS[bit / 32]) >>> (bit % 32) & 1) != 0;
	}

	/** First entry of a column, or the fallback when the row has no value. */
	private static int intField(Db db, int row, int column, int fallback)
	{
		final Object[] values = db.field(row, column, 0);
		return values == null || values.length == 0 ? fallback : asInt(values[0], fallback);
	}

	/** Every entry of a list column. */
	private static List<Integer> intList(Db db, int row, int column)
	{
		final List<Integer> out = new ArrayList<>();
		final Object[] values = db.field(row, column, 0);
		if (values == null) return out;
		for (Object value : values)
		{
			if (value instanceof Number) out.add(((Number) value).intValue());
		}
		return out;
	}

	private static String stringField(Db db, int row, int column)
	{
		final Object[] values = db.field(row, column, 0);
		if (values == null || values.length == 0 || !(values[0] instanceof String)) return null;
		return (String) values[0];
	}

	private static int asInt(Object value, int fallback)
	{
		return value instanceof Number ? ((Number) value).intValue() : fallback;
	}
}

package com.slayercompanion;

import com.slayercompanion.SlayerRequirements.ItemGroup;
import com.slayercompanion.SlayerRequirements.Need;
import com.slayercompanion.SlayerRequirements.Recommendation;
import com.slayercompanion.SlayerRequirements.Requirement;
import com.slayercompanion.SlayerRequirements.Unlock;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;

/**
 * The sidebar's "Live gear check" line: what {@link SlayerRequirements} says the task needs and recommends, against
 * what the player carries and wears, and against what the bank held when it was last open. It is pure, so the plugin
 * only gathers the items, the bank it remembers, the kills left, Konar's area and a varbit reader for the unlocks, the
 * elite diary, the Fires of Eternal Light and Malevolent Masquerade. The compact sidebar's items and the scene overlay's
 * lines come from the same look ({@link #evaluate}).
 */
final class SlayerGearCheck
{
	/** A count at the end of a name, as in "Fungicide spray 7" or "Rod of Ivandis (7)". */
	private static final Pattern TRAILING_NUMBER = Pattern.compile("\\(?(\\d{1,6})\\)?\\s*$");
	/**
	 * The longest compact item, about what fits on a line of the compact sidebar. Longer ones leave out the counts or
	 * the place, which the line keeps.
	 */
	static final int MAX_ITEM = 34;
	/** The compact item of a mandatory item that only the bank holds. */
	private static final String IN_BANK = "In bank: ";
	/** The line's sentence for everything to bring from the bank. */
	private static final String FROM_BANK = "Bring from your bank: ";
	/** Shorter names for the item groups whose label is too long for a compact item. The line names every item. */
	private static final Map<ItemGroup, String> SHORT_LABELS = new IdentityHashMap<>();

	static
	{
		SHORT_LABELS.put(SlayerRequirements.EARMUFFS_OR_HELMET, "earmuffs or Slayer helmet");
		SHORT_LABELS.put(SlayerRequirements.SPINY_OR_HELMET, "spiny or Slayer helmet");
		SHORT_LABELS.put(SlayerRequirements.GOGGLES_OR_HELMET, "goggles or Slayer helmet");
		SHORT_LABELS.put(SlayerRequirements.MIRROR_SHIELDS, "mirror or V's shield");
		SHORT_LABELS.put(SlayerRequirements.WYVERN_SHIELDS, "wyvern shield or similar");
		SHORT_LABELS.put(SlayerRequirements.TUROTH_KURASK_WEAPONS, "leaf-bladed weapon");
		SHORT_LABELS.put(SlayerRequirements.KARUULM_BOOTS, "boots of stone or similar");
		SHORT_LABELS.put(SlayerRequirements.ROCK_HAMMERS, "rock or granite hammer");
		SHORT_LABELS.put(SlayerRequirements.ANY_ROCK_HAMMER, "rock or granite hammer");
		SHORT_LABELS.put(SlayerRequirements.VAMPYREBANE, "Ivandis flail or better");
		SHORT_LABELS.put(SlayerRequirements.SILVER_OR_EFARITAY, "silver or Efaritay's aid");
		SHORT_LABELS.put(SlayerRequirements.DRAGONFIRE_PROTECTION, "dragonfire protection");
		SHORT_LABELS.put(SlayerRequirements.HELMET_MASK_OR_SALVE, "Slayer helm, mask or salve");
		SHORT_LABELS.put(SlayerRequirements.HELMET_OR_SALVE, "Slayer helmet or salve");
	}

	/**
	 * How the gear stands: a mandatory item missing, something to bring from the bank or a recommended item to bring,
	 * or everything there.
	 */
	enum Status
	{
		MISSING,
		BRING,
		READY
	}

	/** The line, the compact sidebar's items and the overlay's lines from one look at the items. */
	@Value
	static class Result
	{
		/**
		 * READY or MISSING and the mandatory items when the task has any, then what to bring from the bank, then "Bring"
		 * and the recommended items that are not there with the reasons some carry, then "You have" and the ones that are,
		 * such as "READY: Rock hammer. Bring a Slayer helmet or black mask". When nothing is missing but a mandatory item
		 * is only in the bank there is no READY or MISSING, and the line starts with what to bring from the bank.
		 */
		String line;
		/** Every mandatory item is carried or worn. One that only the bank holds is not missing, and not ready either. */
		boolean ready;
		/** "Missing: 14 ice coolers (26 of 40)" for each missing need. */
		List<String> missing;
		/**
		 * "In bank: Rock hammer" for each mandatory item only the bank holds, "Bring from bank: Arclight" for each
		 * recommended item that is not there and the bank holds, then "Bring: demonbane weapon" for the others.
		 */
		List<String> bring;
		/** "Ready: Rock hammer", or "Ready" when the names do not fit, once nothing is missing or left to bring. Else null. */
		String readyItem;
		/** The bank has been seen, so what it holds counts. Before that only carried and worn items do. */
		boolean bankSeen;

		/** The compact sidebar's items: what is missing, then what to bring, or the one ready item. */
		List<String> getItems()
		{
			if (readyItem != null) return Collections.singletonList(readyItem);
			final List<String> items = new ArrayList<>(missing);
			items.addAll(bring);
			return Collections.unmodifiableList(items);
		}

		Status getStatus()
		{
			return !missing.isEmpty() ? Status.MISSING : !bring.isEmpty() ? Status.BRING : Status.READY;
		}
	}

	/**
	 * What one need lacks of what is carried: the line's words and the compact item's. When the bank holds it, it is
	 * brought from there rather than missing.
	 */
	private static final class Missed
	{
		final String text;
		final String item;
		final boolean inBank;
		/** The item the bank brings, or -1 for a count of used-up items or a need that is missing. */
		final int bankId;

		Missed(String text, String item)
		{
			this(text, item, false, -1);
		}

		private Missed(String text, String item, boolean inBank, int bankId)
		{
			this.text = text;
			this.item = item;
			this.inBank = inBank;
			this.bankId = bankId;
		}

		static Missed banked(String text, String item, int bankId)
		{
			return new Missed(text, item, true, bankId);
		}
	}

	private SlayerGearCheck()
	{
	}

	/** One stack in the inventory or the worn equipment. */
	static final class Held
	{
		final int id;
		final String name;
		final int quantity;

		Held(int id, String name, int quantity)
		{
			this.id = id;
			this.name = name;
			this.quantity = quantity;
		}
	}

	/** What is carried and worn, and what the bank holds once it has been seen. */
	private static final class Stock
	{
		final List<Held> held;
		/** Null before the bank is seen. */
		final BankGear bank;
		/**
		 * Items that bring a warning when carried, such as an open flame in the swamp caves. The bank's item is one of them
		 * only when the bank holds nothing else that does the job.
		 */
		final List<ItemGroup> warned;

		Stock(List<Held> held, BankGear bank, List<ItemGroup> warned)
		{
			this.held = held;
			this.bank = bank;
			this.warned = warned;
		}

		/** The first item of the group the bank holds, in the group's order, passing over a warned item when it holds another. -1 for none. */
		int bankItem(ItemGroup group)
		{
			if (bank == null) return -1;
			int warnedId = -1;
			for (int id : group.ids())
			{
				if (bank.quantity(id) <= 0) continue;
				if (!listedIn(id, warned)) return id;
				if (warnedId < 0) warnedId = id;
			}
			return warnedId;
		}

		int bankCount(ItemGroup group)
		{
			return bank == null ? 0 : bank.count(group);
		}

		/** The charges the bank holds for a need: those in the names of its sprays, and its refills. */
		int bankCharges(Need need)
		{
			if (bank == null) return 0;
			long charges = (long) need.getRefillCharges() * bank.count(need.getRefills());
			for (int id : need.getItems().ids())
			{
				charges += (long) chargesInName(need.getItems().name(id)) * bank.quantity(id);
			}
			return (int) Math.min(Integer.MAX_VALUE, charges);
		}
	}

	/**
	 * Whether the task, or the place Konar assigned, needs or recommends anything. Lets the plugin skip reading the
	 * items.
	 */
	static boolean hasNeeds(String taskName, int assignedAreaId, IntUnaryOperator varbits)
	{
		return hasNeeds(taskName, assignedAreaId, varbits, true);
	}

	/** @param recommend whether the recommended tier is on, as the config sets it. Off, only mandatory items count. */
	static boolean hasNeeds(String taskName, int assignedAreaId, IntUnaryOperator varbits, boolean recommend)
	{
		return taskName != null && (!needs(taskName, assignedAreaId).isEmpty() || !recommended(taskName, varbits, recommend).isEmpty());
	}

	/**
	 * @param killsLeft kills left on the task, 0 or less when unknown
	 * @param assignedAreaId Konar's SLAYER_AREA value, 0 when the master assigned no area
	 * @param held inventory and worn items
	 * @param varbits the current value of a varbit
	 * @return the line, or null when the task needs and recommends nothing
	 */
	static String check(String taskName, int killsLeft, int assignedAreaId, List<Held> held, IntUnaryOperator varbits)
	{
		final Result result = evaluate(taskName, killsLeft, assignedAreaId, held, varbits);
		return result == null ? null : result.getLine();
	}

	/** {@link #check} with the compact sidebar's items. Null when the task needs and recommends nothing. */
	static Result evaluate(String taskName, int killsLeft, int assignedAreaId, List<Held> held, IntUnaryOperator varbits)
	{
		return evaluate(taskName, killsLeft, assignedAreaId, held, varbits, true);
	}

	/**
	 * @param recommend whether the recommended tier is on, as the config sets it. Off, the result is the mandatory tier
	 * alone, with no recommended item to bring and no "You have", and null for a task that needs nothing.
	 */
	static Result evaluate(String taskName, int killsLeft, int assignedAreaId, List<Held> held, IntUnaryOperator varbits,
		boolean recommend)
	{
		return evaluate(taskName, killsLeft, assignedAreaId, held, null, varbits, recommend);
	}

	/**
	 * @param bank what the bank held when it was last open, or null before it is seen, which leaves the check to what is
	 * carried and worn. A mandatory item only the bank holds is to be brought from there rather than missing, and a
	 * recommended item it holds is named. The bank never makes the check READY.
	 */
	static Result evaluate(String taskName, int killsLeft, int assignedAreaId, List<Held> held, BankGear bank,
		IntUnaryOperator varbits, boolean recommend)
	{
		if (taskName == null) return null;
		final List<Need> needs = needs(taskName, assignedAreaId);
		final List<Recommendation> recommended = recommended(taskName, varbits, recommend);
		if (needs.isEmpty() && recommended.isEmpty()) return null;
		final int kills = killsLeft > 0 ? killsLeft : -1;
		final Stock stock = new Stock(held, bank, bank == null ? Collections.<ItemGroup>emptyList() : warned(recommended, varbits));
		final List<String> have = new ArrayList<>();
		final List<String> missing = new ArrayList<>();
		final List<String> missingItems = new ArrayList<>();
		final List<Missed> banked = new ArrayList<>();
		final List<String> notes = new ArrayList<>();
		// The item groups of the missing needs. A recommendation that shares items with one is already asked for.
		final List<ItemGroup> lacking = new ArrayList<>();
		for (Need need : needs)
		{
			// Konar's area is where the kills count, so the place needs no naming once it is known.
			String where = assignedAreaId > 0 ? null : need.getWhere();
			String exemptNote = null;
			if (need.getExemptVarbit() >= 0 && varbits.applyAsInt(need.getExemptVarbit()) > 0)
			{
				if (need.getExemptWhere() == null)
				{
					notes.add(need.getExemptNote());
					continue;
				}
				where = need.getExemptWhere();
				exemptNote = need.getExemptNote();
			}
			final Missed missed = evaluate(need, stock, kills, where, have, notes);
			if (missed == null) continue;
			if (missed.inBank)
			{
				banked.add(missed);
			}
			else
			{
				missing.add(missed.text);
				missingItems.add(missed.item);
				lacking.add(need.getItems());
				if (need.getAlternative() != null) lacking.add(need.getAlternative());
			}
			if (exemptNote != null) notes.add(exemptNote);
		}
		// The mandatory tier's sentence, READY only when every mandatory item is carried or worn
		String status = null;
		if (!missing.isEmpty())
		{
			status = "MISSING: " + sentences(list(missing, true), notes);
		}
		else if (banked.isEmpty() && !needs.isEmpty())
		{
			final Requirement requirement = SlayerRequirements.forTask(taskName);
			final Unlock unlock = requirement == null ? null : requirement.getUnlock();
			if (unlock != null && varbits.applyAsInt(unlock.getVarbit()) > 0 && find(held, unlock.getUses()) != null)
			{
				notes.add(unlock.getName() + " is unlocked, so the finishing blow is automatic");
			}
			status = "READY: " + sentences(have.isEmpty() ? null : list(have, false), notes);
		}

		// What the bank brings, the mandatory items first. Their compact items come before the other items to bring, as in the line.
		final List<String> fromBank = new ArrayList<>();
		final List<String> bringItems = new ArrayList<>();
		for (Missed item : banked)
		{
			fromBank.add(item.text);
			bringItems.add(item.item);
		}
		// The recommended tier, after the mandatory one. An item the mandatory part already names is not named twice, and
		// a conditional one is a warning, so it is not named once it is met.
		final List<String> bring = new ArrayList<>();
		final List<String> labelItems = new ArrayList<>();
		final List<String> reasons = new ArrayList<>();
		final List<String> extra = new ArrayList<>();
		for (Recommendation recommendation : recommended)
		{
			final ItemGroup group = recommendation.getItems();
			final Held item = find(held, group);
			final boolean conditional = recommendation.getOnlyWith() != null;
			if (item != null)
			{
				if (!conditional && !have.contains(item.name) && !extra.contains(item.name)) extra.add(item.name);
			}
			else if (applies(recommendation, held, banked, varbits) && !overlaps(group, lacking))
			{
				final int id = stock.bankItem(group);
				if (id >= 0 && bringsFromBank(banked, id)) continue;
				if (id >= 0)
				{
					fromBank.add(group.name(id));
					bringItems.add(bringFromBank(group, id));
				}
				else
				{
					bring.add(group.getLabel());
					labelItems.add("Bring: " + shortLabel(group));
				}
				if (recommendation.getReason() != null) reasons.add(recommendation.getReason());
			}
		}
		bringItems.addAll(labelItems);
		final List<String> parts = new ArrayList<>();
		if (status != null) parts.add(status);
		if (!fromBank.isEmpty()) parts.add(FROM_BANK + list(fromBank, false));
		// Without READY or MISSING in front, the notes follow what to bring from the bank
		if (status == null) parts.addAll(notes);
		if (!bring.isEmpty()) parts.add("Bring " + list(bring, true));
		parts.addAll(reasons);
		if (!extra.isEmpty()) parts.add("You have " + list(extra, false));

		String readyItem = null;
		if (missingItems.isEmpty() && bringItems.isEmpty())
		{
			final List<String> named = new ArrayList<>(have);
			named.addAll(extra);
			readyItem = readyItem(named, have);
		}
		return new Result(String.join(". ", parts), missing.isEmpty() && banked.isEmpty(), Collections.unmodifiableList(missingItems),
				Collections.unmodifiableList(bringItems), readyItem, bank != null);
	}

	/** "Ready: " and the names, those of the mandatory items alone when all do not fit, or "Ready". */
	private static String readyItem(List<String> all, List<String> mandatory)
	{
		for (List<String> names : Arrays.asList(all, mandatory))
		{
			final String item = "Ready: " + String.join(", ", names);
			if (!names.isEmpty() && item.length() <= MAX_ITEM) return item;
		}
		return "Ready";
	}

	/** The task's recommendations, then the Slayer helmet once Malevolent Masquerade is bought. None while the tier is off. */
	private static List<Recommendation> recommended(String taskName, IntUnaryOperator varbits, boolean recommend)
	{
		if (!recommend) return Collections.emptyList();
		final List<Recommendation> recommendations = new ArrayList<>(SlayerRequirements.recommendedFor(taskName));
		if (varbits.applyAsInt(SlayerRequirements.HELMET_UNLOCK_VARBIT) > 0)
		{
			recommendations.add(Recommendation.of(SlayerRequirements.slayerHeadgear(taskName)));
		}
		return recommendations;
	}

	/**
	 * A conditional recommendation applies while one of its other group is carried, or is to be brought from the bank,
	 * and its varbit is not set.
	 */
	private static boolean applies(Recommendation recommendation, List<Held> held, List<Missed> banked, IntUnaryOperator varbits)
	{
		if (exempt(recommendation, varbits)) return false;
		final ItemGroup onlyWith = recommendation.getOnlyWith();
		if (onlyWith == null || find(held, onlyWith) != null) return true;
		for (Missed item : banked)
		{
			if (onlyWith.ids().contains(item.bankId)) return true;
		}
		return false;
	}

	private static boolean exempt(Recommendation recommendation, IntUnaryOperator varbits)
	{
		return recommendation.getExemptVarbit() >= 0 && varbits.applyAsInt(recommendation.getExemptVarbit()) > 0;
	}

	/** The items the conditional recommendations warn about, such as an open flame in the swamp caves, unless a varbit lifts the warning. */
	private static List<ItemGroup> warned(List<Recommendation> recommended, IntUnaryOperator varbits)
	{
		final List<ItemGroup> warned = new ArrayList<>();
		for (Recommendation recommendation : recommended)
		{
			if (recommendation.getOnlyWith() != null && !exempt(recommendation, varbits)) warned.add(recommendation.getOnlyWith());
		}
		return warned;
	}

	private static boolean listedIn(int id, List<ItemGroup> groups)
	{
		for (ItemGroup group : groups)
		{
			if (group.ids().contains(id)) return true;
		}
		return false;
	}

	/** Whether a mandatory need already brings this item from the bank. */
	private static boolean bringsFromBank(List<Missed> banked, int id)
	{
		for (Missed item : banked)
		{
			if (item.bankId == id) return true;
		}
		return false;
	}

	/** Whether a recommended item class shares an item with a missing need, as the helmet does with a nose peg's need. */
	private static boolean overlaps(ItemGroup group, List<ItemGroup> lacking)
	{
		for (ItemGroup missing : lacking)
		{
			if (!Collections.disjoint(group.ids(), missing.ids())) return true;
		}
		return false;
	}

	/**
	 * "Missing: " and what is missing, with the place and the counts when they fit in {@link #MAX_ITEM}. The counts
	 * go first, so "14 ice coolers" with "for desert lizards" and "(26 of 40)" reads "Missing: 14 ice coolers (26 of 40)".
	 */
	static String missingItem(String what, String where, String counts)
	{
		return fit("Missing: ", what, where, counts);
	}

	/** {@link #missingItem} with another start, such as "In bank: 14 ice coolers (26 of 40)". */
	private static String fit(String start, String what, String where, String counts)
	{
		final String place = where == null ? "" : " " + where;
		final String count = counts == null ? "" : " (" + counts + ")";
		for (String item : new String[]{what + place + count, what + count, what + place})
		{
			if ((start + item).length() <= MAX_ITEM) return start + item;
		}
		return start + what;
	}

	/** A kept item only the bank holds: the line names it, and the compact item too unless the group's short name must stand in. */
	private static Missed keptItem(ItemGroup group, int id, String where)
	{
		final String name = group.name(id);
		final String item = fit(IN_BANK, name, where, null);
		return Missed.banked(name + place(where), item.length() <= MAX_ITEM ? item : fit(IN_BANK, shortLabel(group), where, null), id);
	}

	/**
	 * A recommended item the bank holds, such as "Bring from bank: Arclight". A long name keeps "From bank: " alone, and
	 * the group's short name stands in for a name that still does not fit.
	 */
	private static String bringFromBank(ItemGroup group, int id)
	{
		final String name = group.name(id);
		final String label = shortLabel(group);
		for (String item : new String[]{"Bring from bank: " + name, "From bank: " + name, "Bring from bank: " + label, "From bank: " + label})
		{
			if (item.length() <= MAX_ITEM) return item;
		}
		return "From bank: " + name;
	}

	/** An item group's name in a compact item: its short name, or its label without the leading article. */
	static String shortLabel(ItemGroup group)
	{
		final String label = SHORT_LABELS.get(group);
		if (label != null) return label;
		if (group.getLabel().startsWith("a ")) return group.getLabel().substring(2);
		return group.getLabel().startsWith("an ") ? group.getLabel().substring(3) : group.getLabel();
	}

	/** Charges carried in an item's name, as in "Fungicide spray 7". 0 when the name has none. */
	static int chargesInName(String name)
	{
		if (name == null) return 0;
		final Matcher matcher = TRAILING_NUMBER.matcher(name);
		return matcher.find() ? Integer.parseInt(matcher.group(1)) : 0;
	}

	/** The task's needs that apply where it is done, then those of Konar's area that the task does not have yet. */
	private static List<Need> needs(String taskName, int assignedAreaId)
	{
		final List<Need> needs = new ArrayList<>();
		final Requirement requirement = SlayerRequirements.forTask(taskName);
		if (requirement != null)
		{
			for (Need need : requirement.getNeeds())
			{
				if (need.appliesIn(assignedAreaId)) needs.add(need);
			}
		}
		for (Need need : SlayerRequirements.forArea(assignedAreaId))
		{
			if (need.appliesIn(assignedAreaId) && !hasGroup(needs, need.getItems())) needs.add(need);
		}
		return needs;
	}

	/** Adds what is carried to {@code have} and returns null, or returns what the bank brings or what is missing. */
	private static Missed evaluate(Need need, Stock stock, int kills, String where, List<String> have, List<String> notes)
	{
		switch (need.getKind())
		{
			case PER_KILL:
				return perKill(need, stock, kills, where, have);
			case CHARGES:
				return charges(need, stock, kills, where, have);
			case ADVICE:
			{
				final Held item = find(stock.held, need.getItems());
				if (item != null) have.add(item.name);
				else notes.add(need.getAdvice());
				return null;
			}
			default:
			{
				final Held item = find(stock.held, need.getItems());
				if (item != null)
				{
					have.add(item.name);
					return null;
				}
				final int id = stock.bankItem(need.getItems());
				if (id >= 0) return keptItem(need.getItems(), id, where);
				return new Missed(need.getItems().getLabel() + place(where), missingItem(shortLabel(need.getItems()), where, null));
			}
		}
	}

	private static Missed perKill(Need need, Stock stock, int kills, String where, List<String> have)
	{
		final ItemGroup alternative = need.getAlternative();
		final Held kept = alternative == null ? null : find(stock.held, alternative);
		if (kept != null)
		{
			have.add(kept.name);
			return null;
		}
		final int count = count(stock.held, need.getItems());
		if (count > 0 && (kills < 0 || count >= kills))
		{
			have.add(count + " " + need.noun(count) + (kills > 0 ? " (need " + kills + ")" : ""));
			return null;
		}
		final Missed fromBank = perKillFromBank(need, stock, kills, where, count);
		if (fromBank != null) return fromBank;
		if (count > 0)
		{
			return new Missed(more(need, count, kills, where) + (alternative == null ? "" : ", or " + alternative.getLabel()),
				moreItem("Missing: ", need, count, kills, where));
		}
		final String counted = kills > 0 ? kills + " " + need.noun(kills) : need.plural();
		final String wanted = counted + place(where);
		if (alternative == null) return new Missed(wanted, missingItem(counted, where, null));
		// The compact item names the first of the two, as the line does
		return need.isAlternativeFirst()
			? new Missed(alternative.getLabel() + ", or " + wanted, missingItem(shortLabel(alternative), null, null))
			: new Missed(wanted + ", or " + alternative.getLabel(), missingItem(counted, where, null));
	}

	/**
	 * What the bank brings for a used-up need: the kept item, or the rest of the count when what is carried and what the
	 * bank holds cover the kills left. The kept item comes first where the line names it first. Null when the bank cannot
	 * bring either.
	 */
	private static Missed perKillFromBank(Need need, Stock stock, int kills, String where, int count)
	{
		final ItemGroup alternative = need.getAlternative();
		final int keptId = alternative == null ? -1 : stock.bankItem(alternative);
		final Missed kept = keptId < 0 ? null : keptItem(alternative, keptId, where);
		if (kept != null && need.isAlternativeFirst()) return kept;
		final int stored = stock.bankCount(need.getItems());
		if (stored <= 0 || (kills > 0 && (long) count + stored < kills)) return kept;
		// With the kills left unknown any count carried would do, so none is carried here
		if (kills < 0) return Missed.banked(need.plural() + place(where), fit(IN_BANK, need.plural(), where, null), -1);
		if (count == 0)
		{
			final String counted = kills + " " + need.noun(kills);
			return Missed.banked(counted + place(where), fit(IN_BANK, counted, where, null), -1);
		}
		return Missed.banked(more(need, count, kills, where), moreItem(IN_BANK, need, count, kills, where), -1);
	}

	private static Missed charges(Need need, Stock stock, int kills, String where, List<String> have)
	{
		boolean holder = false;
		int charges = 0;
		for (Held item : stock.held)
		{
			if (need.getItems().matches(item.id, item.name))
			{
				holder = true;
				charges += chargesInName(item.name) * Math.max(1, item.quantity);
			}
		}
		if (!holder)
		{
			// The spray comes first, the fullest the bank holds, since the group lists them from 10 charges down. Its
			// charges count once it is carried.
			final int spray = stock.bankItem(need.getItems());
			if (spray >= 0) return keptItem(need.getItems(), spray, where);
			return new Missed(need.getItems().getLabel() + place(where), missingItem(shortLabel(need.getItems()), where, null));
		}
		// Refills only help when there is a spray to put them in.
		charges += need.getRefillCharges() * count(stock.held, need.getRefills());
		if (charges > 0 && (kills < 0 || charges >= kills))
		{
			have.add(charges + " " + need.noun(charges) + (kills > 0 ? " (need " + kills + ")" : ""));
			return null;
		}
		final int stored = stock.bankCharges(need);
		if (stored > 0 && kills < 0) return Missed.banked(need.plural() + place(where), fit(IN_BANK, need.plural(), where, null), -1);
		if (stored > 0 && (long) charges + stored >= kills)
		{
			return Missed.banked(more(need, charges, kills, where), moreItem(IN_BANK, need, charges, kills, where), -1);
		}
		if (kills < 0) return new Missed(need.plural() + place(where), missingItem(need.plural(), where, null));
		return new Missed(more(need, charges, kills, where), moreItem("Missing: ", need, charges, kills, where));
	}

	/** "14 more ice coolers for desert lizards (have 26, need 40)" */
	private static String more(Need need, int count, int kills, String where)
	{
		final int more = kills - count;
		return more + " more " + need.noun(more) + place(where) + " (have " + count + ", need " + kills + ")";
	}

	/** The compact item of {@link #more}, such as "Missing: 14 ice coolers (26 of 40)". */
	private static String moreItem(String start, Need need, int count, int kills, String where)
	{
		final int more = kills - count;
		return fit(start, more + " " + need.noun(more), where, count + " of " + kills);
	}

	private static Held find(List<Held> held, ItemGroup group)
	{
		for (Held item : held)
		{
			if (group.matches(item.id, item.name)) return item;
		}
		return null;
	}

	private static int count(List<Held> held, ItemGroup group)
	{
		int count = 0;
		for (Held item : held)
		{
			if (group.matches(item.id, item.name)) count += Math.max(0, item.quantity);
		}
		return count;
	}

	private static boolean hasGroup(List<Need> needs, ItemGroup group)
	{
		for (Need need : needs)
		{
			if (need.getItems() == group) return true;
		}
		return false;
	}

	private static String place(String where)
	{
		return where == null ? "" : " " + where;
	}

	/** "a", "a and b", "a, b and c". Missing items take a serial comma, since their labels hold "or". */
	static String list(List<String> parts, boolean serialComma)
	{
		final StringBuilder sb = new StringBuilder();
		for (int i = 0; i < parts.size(); i++)
		{
			if (i > 0)
			{
				final boolean last = i == parts.size() - 1;
				sb.append(!last ? ", " : serialComma ? ", and " : " and ");
			}
			sb.append(parts.get(i));
		}
		return sb.toString();
	}

	private static String sentences(String first, List<String> more)
	{
		final List<String> all = new ArrayList<>();
		if (first != null) all.add(first);
		all.addAll(more);
		return String.join(". ", all);
	}
}

package com.slayercompanion;

import lombok.AllArgsConstructor;

/**
 * What the player wants from Slayer. The points plan is built for it, and the Slayer points goal adds the
 * next-task routine. Stored in config by constant name, so the names must not change.
 */
@AllArgsConstructor
public enum SlayerGoal
{
	XP("XP"),
	PROFIT("Profit"),
	POINTS("Slayer points");

	private final String displayName;

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.slayercompanion;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.function.ToDoubleFunction;
import lombok.Value;

/**
 * Turns a master's pool into one number per goal, so masters and block lists can be compared. Pure.
 * <p>
 * The XP and profit ratings are per hour, so a pool is judged by where the time goes. Each task counts by
 * its chance of coming up times how long it takes, and the minutes between tasks (getting the task, travel,
 * banking) earn nothing. A short poor task costs little, which is why the wiki puts the common long tasks on
 * block lists before the rare quick ones ("between the choice of spiritual creatures (7) or zygomites (2)
 * from Duradel, blocking the former would be more beneficial", wiki Slayer training). How long a task takes
 * comes from its speed rating, scaled by how many the master assigns against the amount the rating was
 * judged at. Turael's and Spria's small filler tasks have their own estimate instead
 * ({@link com.slayercompanion.data.TaskRating.Filler}), as their time is in the trip, not the kills. For Slayer
 * points the rate is tasks finished per hour, which is what decides points per hour at one master. On the points
 * routine it is points per hour over a cycle of filler tasks and one milestone task ({@link #cycleRate}), so the
 * filler master's list counts as much as the time spent there.
 * <p>
 * The minutes per speed rating are judgments that match the scale in {@link com.slayercompanion.data.TaskRating}.
 * The rates only ever compare masters or tasks with each other. They are never shown.
 */
final class SlayerGoalModel
{
	/** Minutes per assignment for speed ratings 1 to 5, everything included. */
	private static final double[] TASK_MINUTES = {0, 100, 65, 40, 22, 12};
	/** Of those, the minutes per assignment that earn nothing: getting the task, travel and banking. */
	static final double OVERHEAD_MINUTES = 6;
	/** A skip costs one trip to a master. */
	static final double SKIP_MINUTES = 3;
	/** The lowest rating: a task this poor is worth a skip however short it is. */
	private static final int VERY_POOR = 1;
	private static final double EPSILON = 1e-9;

	/** One task the player may be given, with its chance of coming up. */
	@Value
	static class Offer
	{
		SlayerPool.Entry entry;
		double chance;
	}

	/** What the skip model skips: the worst offers first, while a skip still raises the rate. */
	@Value
	static class Skips
	{
		/** Share of all offers skipped. */
		double share;
		/** The goal's rate with these skips. */
		double rate;
		/** The tasks skipped, worst first. The last may be skipped only part of the time. */
		List<SlayerPool.Entry> tasks;
	}

	private SlayerGoalModel()
	{
	}

	/**
	 * Minutes spent killing on one assignment of the task at its master. A task with its own estimate at the master,
	 * as Turael's and Spria's filler tasks have, takes that, less the minutes between tasks.
	 */
	static double killMinutes(SlayerPool.Entry e)
	{
		if (e.getMinutes() > 0) return Math.max(0, e.getMinutes() - OVERHEAD_MINUTES);
		final double minutes = TASK_MINUTES[e.getRating().getSpeed()] - OVERHEAD_MINUTES;
		final double amount = e.averageAmount();
		if (amount <= 0 || e.getTypicalAmount() <= 0) return minutes;
		return minutes * amount / e.getTypicalAmount();
	}

	/** The rated tasks the master can give now, each with its chance among them. */
	static List<Offer> offers(SlayerPool pool)
	{
		int weight = 0;
		for (SlayerPool.Entry e : pool.getEntries())
		{
			if (e.isOpen() && e.isRated()) weight += e.getWeight();
		}
		final List<Offer> out = new ArrayList<>();
		if (weight == 0) return out;
		for (SlayerPool.Entry e : pool.getEntries())
		{
			if (e.isOpen() && e.isRated()) out.add(new Offer(e, e.getWeight() / (double) weight));
		}
		return out;
	}

	/** The goal's rate when every task the master gives is done. Higher is better. */
	static double rate(SlayerPool pool, SlayerGoal goal)
	{
		return rate(offers(pool), goal, 0, 0);
	}

	/**
	 * @param bonus added to every task's rating for XP and profit: a master-level effect, see {@link SlayerMasterRanker}
	 * @param skipped share of all offers skipped, at {@link #SKIP_MINUTES} each. The chances must already leave them out.
	 */
	static double rate(List<Offer> offers, SlayerGoal goal, double bonus, double skipped)
	{
		double gain = 0;
		double minutes = skipped * SKIP_MINUTES;
		double done = 0;
		for (Offer o : offers)
		{
			final double kill = killMinutes(o.getEntry());
			gain += o.getChance() * kill * (o.getEntry().rating(goal) + bonus);
			minutes += o.getChance() * (kill + OVERHEAD_MINUTES);
			done += o.getChance();
		}
		if (minutes <= 0) return 0;
		return goal == SlayerGoal.POINTS ? 60 * done / minutes : gain / minutes;
	}

	/**
	 * A what-if rate for rewards that change how a task goes rather than which tasks come up. {@code time} scales a
	 * task's killing minutes, so a faster kill earns the same in less time. {@code yield} scales what it earns for XP
	 * or profit. {@code overhead} is the task's minutes between tasks, {@link #OVERHEAD_MINUTES} unless a reward
	 * shortens the trip.
	 */
	static double rate(List<Offer> offers, SlayerGoal goal, ToDoubleFunction<SlayerPool.Entry> time,
			ToDoubleFunction<SlayerPool.Entry> yield, ToDoubleFunction<SlayerPool.Entry> overhead)
	{
		double gain = 0;
		double minutes = 0;
		double done = 0;
		for (Offer o : offers)
		{
			final SlayerPool.Entry e = o.getEntry();
			final double kill = killMinutes(e);
			gain += o.getChance() * kill * e.rating(goal) * yield.applyAsDouble(e);
			minutes += o.getChance() * (kill * time.applyAsDouble(e) + overhead.applyAsDouble(e));
			done += o.getChance();
		}
		if (minutes <= 0) return 0;
		return goal == SlayerGoal.POINTS ? 60 * done / minutes : gain / minutes;
	}

	/** Minutes per assignment over the offers on average, killing and the minutes between tasks. 0 without offers. */
	static double minutesPerTask(List<Offer> offers)
	{
		return minutesPerTask(offers, e -> 1, e -> OVERHEAD_MINUTES);
	}

	/** {@link #minutesPerTask(List)} when a reward changes how tasks go: {@code time} and {@code overhead} as in {@link #rate}. */
	static double minutesPerTask(List<Offer> offers, ToDoubleFunction<SlayerPool.Entry> time, ToDoubleFunction<SlayerPool.Entry> overhead)
	{
		double minutes = 0;
		double done = 0;
		for (Offer o : offers)
		{
			final SlayerPool.Entry e = o.getEntry();
			minutes += o.getChance() * (killMinutes(e) * time.applyAsDouble(e) + overhead.applyAsDouble(e));
			done += o.getChance();
		}
		return done > 0 ? minutes / done : 0;
	}

	/**
	 * Slayer points an hour on the points routine. One cycle is {@code fillers} tasks at the filler master, 9 for
	 * every 10th task or 49 for every 50th, and one milestone task, which pays {@code points}. Each task takes its
	 * own master's average minutes. Only the time depends on the lists, so blocks at either master compare on it.
	 */
	static double cycleRate(double fillerMinutes, double milestoneMinutes, int fillers, double points)
	{
		final double minutes = fillers * fillerMinutes + milestoneMinutes;
		return minutes <= 0 ? 0 : 60 * points / minutes;
	}

	/** {@link #cycleRate(double, double, int, double)} over the filler master's and the milestone master's lists. */
	static double cycleRate(SlayerPool fillerList, SlayerPool milestoneList, int fillers, double points)
	{
		return cycleRate(minutesPerTask(offers(fillerList)), minutesPerTask(offers(milestoneList)), fillers, points);
	}

	/**
	 * The tasks worth blocking for the goal, best first, at most {@code slots}. Each pick is the block that
	 * raises the rate most, and picking stops once no block raises it. The pool's current blocks are lifted
	 * first, so this is the list to aim for, not the change from today's.
	 */
	static List<SlayerPool.Entry> bestBlocks(SlayerPool pool, SlayerGoal goal, int slots)
	{
		return bestBlocks(pool, goal, Collections.<Integer>emptyList(), slots);
	}

	/** {@link #bestBlocks(SlayerPool, SlayerGoal, int)} on top of {@code fixed} blocks, which stay. */
	static List<SlayerPool.Entry> bestBlocks(SlayerPool pool, SlayerGoal goal, Collection<Integer> fixed, int slots)
	{
		final List<Integer> blocked = new ArrayList<>(fixed);
		final List<SlayerPool.Entry> out = new ArrayList<>();
		SlayerPool current = pool.withBlocks(blocked);
		for (int n = 0; n < slots; n++)
		{
			SlayerPool.Entry best = null;
			double bestRate = rate(current, goal) + EPSILON;
			for (SlayerPool.Entry e : current.open())
			{
				// "The only way to block a boss is by toggling the ability off" (wiki Boss Slayer). A task the wiki says to
				// do for the goal is never blocked.
				if (!e.isRated() || e.isBoss() || e.wikiSaysDo(goal)) continue;
				blocked.add(e.getTaskRow());
				final double r = rate(pool.withBlocks(blocked), goal);
				blocked.remove(blocked.size() - 1);
				// Equal gains go to the heavier task, then by name, so the advice never flips between rebuilds
				if (r > bestRate + EPSILON || (best != null && Math.abs(r - bestRate) <= EPSILON && before(e, best)))
				{
					best = e;
					bestRate = r;
				}
			}
			if (best == null) break;
			blocked.add(best.getTaskRow());
			out.add(best);
			current = pool.withBlocks(blocked);
		}
		return out;
	}

	private static boolean before(SlayerPool.Entry a, SlayerPool.Entry b)
	{
		if (a.getWeight() != b.getWeight()) return a.getWeight() > b.getWeight();
		return a.getName().compareTo(b.getName()) < 0;
	}

	/**
	 * The rate when the worst offers are skipped, up to {@code budget} as a share of all offers, and only while
	 * a skip raises the rate. Worst means lowest rated for the goal, then longest. A skip costs 30 points, about a
	 * task's worth, so a task shorter than half the average one is only skipped when it is very poor: it is over
	 * almost as soon as a skip would be. The wiki does the same with black dragons, which Duradel gives in tens:
	 * "a very fast task when unextended" (Slayer training, task summary).
	 */
	static double rateWithSkips(List<Offer> offers, SlayerGoal goal, double bonus, double budget)
	{
		return skips(offers, goal, bonus, budget).getRate();
	}

	/** Which offers {@link #rateWithSkips} skips, how often and the rate it reaches. */
	static Skips skips(List<Offer> offers, SlayerGoal goal, double bonus, double budget)
	{
		final List<Offer> worstFirst = new ArrayList<>(offers);
		worstFirst.sort(Comparator.comparingInt((Offer o) -> o.getEntry().rating(goal))
				.thenComparing(Comparator.comparingDouble((Offer o) -> killMinutes(o.getEntry())).reversed()));
		final List<Offer> kept = new ArrayList<>(worstFirst);
		final List<SlayerPool.Entry> tasks = new ArrayList<>();
		final double shortTask = minutesPerTask(offers) / 2;
		double skipped = 0;
		double best = rate(kept, goal, bonus, 0);
		for (int i = 0; i < kept.size() && skipped < budget - EPSILON; i++)
		{
			final Offer o = kept.get(i);
			// A task the wiki says to do for the goal is never skipped
			if (o.getEntry().wikiSaysDo(goal)) continue;
			if (o.getEntry().rating(goal) > VERY_POOR && killMinutes(o.getEntry()) + OVERHEAD_MINUTES < shortTask) continue;
			final double take = Math.min(o.getChance(), budget - skipped);
			final List<Offer> trial = new ArrayList<>(kept);
			trial.set(i, new Offer(o.getEntry(), o.getChance() - take));
			final double r = rate(trial, goal, bonus, skipped + take);
			if (r <= best + EPSILON) break;
			kept.set(i, trial.get(i));
			skipped += take;
			best = r;
			tasks.add(o.getEntry());
		}
		return new Skips(skipped, best, Collections.unmodifiableList(tasks));
	}

	/**
	 * The rate when every assignment offers {@code choices} different tasks and the player takes the best one
	 * for the goal, as Mortimer offers them. Exact over every ordered draw without replacement.
	 */
	static double rateBestOf(List<Offer> offers, SlayerGoal goal, double bonus, int choices)
	{
		return rate(bestOf(offers, goal, choices), goal, bonus, 0);
	}

	/** The chance of doing each task when every assignment offers {@code choices} tasks and the player takes the best. */
	static List<Offer> bestOf(List<Offer> offers, SlayerGoal goal, int choices)
	{
		final List<Offer> chosen = new ArrayList<>();
		if (offers.isEmpty()) return chosen;
		final double[] picked = new double[offers.size()];
		draw(offers, goal, Math.max(1, Math.min(choices, offers.size())), new boolean[offers.size()], 1, 1, -1, picked);
		for (int i = 0; i < picked.length; i++)
		{
			if (picked[i] > 0) chosen.add(new Offer(offers.get(i).getEntry(), picked[i]));
		}
		return chosen;
	}

	/** Chance a task from these offers is rated at least {@code min} for the goal. */
	static double share(List<Offer> offers, SlayerGoal goal, int min)
	{
		double good = 0;
		double all = 0;
		for (Offer o : offers)
		{
			all += o.getChance();
			if (o.getEntry().rating(goal) >= min) good += o.getChance();
		}
		return all > 0 ? good / all : 0;
	}

	private static void draw(List<Offer> offers, SlayerGoal goal, int left, boolean[] used, double probability,
			double remaining, int best, double[] picked)
	{
		if (left == 0)
		{
			picked[best] += probability;
			return;
		}
		for (int i = 0; i < offers.size(); i++)
		{
			if (used[i] || remaining <= EPSILON) continue;
			final double chance = offers.get(i).getChance();
			used[i] = true;
			draw(offers, goal, left - 1, used, probability * chance / remaining, remaining - chance,
					best < 0 || better(offers.get(i), offers.get(best), goal) ? i : best, picked);
			used[i] = false;
		}
	}

	/** Which of two offered tasks the player takes for the goal: the higher rated, then the quicker. */
	static boolean better(Offer a, Offer b, SlayerGoal goal)
	{
		final int ra = a.getEntry().rating(goal);
		final int rb = b.getEntry().rating(goal);
		if (ra != rb) return ra > rb;
		return killMinutes(a.getEntry()) < killMinutes(b.getEntry());
	}
}

package com.slayercompanion;

import com.google.gson.Gson;
import com.slayercompanion.data.Access;
import com.slayercompanion.data.SlayerLocation;
import com.slayercompanion.data.TaskLocations;
import com.slayercompanion.data.WildernessPlaces;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads /slayer_areas.json: the places where Slayer tasks can be done and, per task, the ordered list
 * of those places, plus Krystilia's lists of Wilderness places. A malformed point or fact is dropped with
 * a warning instead of failing the plugin. {@link #problems} lists every such issue so a test can keep the
 * bundled file clean.
 */
@Singleton
@Slf4j
public class SlayerLocations
{
	static final String RESOURCE = "/slayer_areas.json";

	private final Map<String, SlayerLocation> byKey = new LinkedHashMap<>();
	private final Map<Integer, SlayerLocation> byAreaId = new HashMap<>();
	private final Map<Integer, TaskLocations> byTask = new HashMap<>();
	private final Map<Integer, WildernessPlaces> byWildernessTask = new HashMap<>();

	@Inject
	SlayerLocations(Gson gson)
	{
		try (InputStream in = SlayerLocations.class.getResourceAsStream(RESOURCE))
		{
			if (in != null)
			{
				load(gson, new InputStreamReader(in, StandardCharsets.UTF_8));
			}
		}
		catch (Exception e)
		{
			log.warn("slayer-sensei: failed to load {}", RESOURCE, e);
		}
		log.debug("slayer-sensei: loaded {} slayer locations, {} task lists", byKey.size(), byTask.size());
	}

	/** For tests: loads the given JSON instead of the bundled resource. */
	SlayerLocations(Gson gson, Reader reader)
	{
		load(gson, reader);
	}

	SlayerLocation byKey(String key)
	{
		return key == null ? null : byKey.get(key);
	}

	SlayerLocation byAreaId(int areaId)
	{
		return areaId <= 0 ? null : byAreaId.get(areaId);
	}

	TaskLocations forTask(int taskId)
	{
		return byTask.get(taskId);
	}

	/** Where Krystilia's task can be done in the Wilderness, or null when no place is verified. */
	WildernessPlaces forWildernessTask(int taskId)
	{
		return byWildernessTask.get(taskId);
	}

	Collection<WildernessPlaces> wildernessLists()
	{
		return Collections.unmodifiableCollection(byWildernessTask.values());
	}

	Collection<SlayerLocation> all()
	{
		return Collections.unmodifiableCollection(byKey.values());
	}

	Collection<TaskLocations> taskLists()
	{
		return Collections.unmodifiableCollection(byTask.values());
	}

	private void load(Gson gson, Reader reader)
	{
		final LocationFile file = gson.fromJson(reader, LocationFile.class);
		if (file == null) return;
		if (file.locations != null)
		{
			for (SlayerLocation location : file.locations)
			{
				addLocation(location);
			}
		}
		if (file.taskLocations != null)
		{
			for (TaskLocations list : file.taskLocations)
			{
				addTaskList(list);
			}
		}
		if (file.wildernessTaskLocations != null)
		{
			for (WildernessPlaces list : file.wildernessTaskLocations)
			{
				addWildernessList(list);
			}
		}
	}

	private void addLocation(SlayerLocation location)
	{
		if (location == null || blank(location.getKey()))
		{
			log.warn("slayer-sensei: skipping a slayer location without a key");
			return;
		}
		if (byKey.containsKey(location.getKey()))
		{
			log.warn("slayer-sensei: duplicate slayer location {}, keeping the first", location.getKey());
			return;
		}
		for (String problem : problems(location))
		{
			log.warn("slayer-sensei: slayer location {}: {}", location.getKey(), problem);
		}
		sanitize(location);
		if (location.getAreaId() > 0 && byAreaId.containsKey(location.getAreaId()))
		{
			log.warn("slayer-sensei: area {} is claimed by two locations, keeping {}", location.getAreaId(),
					byAreaId.get(location.getAreaId()).getKey());
			location.setAreaId(0);
		}
		byKey.put(location.getKey(), location);
		if (location.getAreaId() > 0) byAreaId.put(location.getAreaId(), location);
	}

	private void addTaskList(TaskLocations list)
	{
		if (list == null || list.getTaskId() <= 0 || byTask.containsKey(list.getTaskId())) return;
		final List<String> keys = new ArrayList<>();
		if (list.getLocations() != null)
		{
			for (String key : list.getLocations())
			{
				if (byKey.containsKey(key) && !keys.contains(key)) keys.add(key);
				else log.warn("slayer-sensei: task {} lists unknown or repeated location {}", list.getTaskId(), key);
			}
		}
		list.setLocations(Collections.unmodifiableList(keys));
		if (list.getRecommended() != null && !keys.contains(list.getRecommended()))
		{
			log.warn("slayer-sensei: task {} recommends {}, which is not in its list", list.getTaskId(), list.getRecommended());
			list.setRecommended(null);
		}
		byTask.put(list.getTaskId(), list);
	}

	private void addWildernessList(WildernessPlaces list)
	{
		if (list == null || list.getTaskId() <= 0 || byWildernessTask.containsKey(list.getTaskId())) return;
		for (String problem : problems(list))
		{
			log.warn("slayer-sensei: Wilderness list for task {}: {}", list.getTaskId(), problem);
		}
		final List<WildernessPlaces.Place> places = new ArrayList<>();
		if (list.getPlaces() != null)
		{
			for (WildernessPlaces.Place place : list.getPlaces())
			{
				if (place == null || !byKey.containsKey(place.getKey()) || places.stream().anyMatch(p -> p.getKey().equals(place.getKey())))
				{
					log.warn("slayer-sensei: Krystilia task {} lists an unknown or repeated place", list.getTaskId());
					continue;
				}
				if (place.getEntrance() != null && !validPoint(place.getEntrance())) place.setEntrance(null);
				final List<int[]> spots = new ArrayList<>();
				if (place.getSpots() != null)
				{
					for (int[] spot : place.getSpots())
					{
						if (validPoint(spot)) spots.add(spot);
					}
				}
				place.setSpots(spots.toArray(new int[0][]));
				places.add(place);
			}
		}
		list.setPlaces(Collections.unmodifiableList(places));
		if (list.getRecommended() != null && places.stream().noneMatch(p -> p.getKey().equals(list.getRecommended())))
		{
			list.setRecommended(null);
		}
		byWildernessTask.put(list.getTaskId(), list);
	}

	/** Every point in a Wilderness list that would be ignored or has no source. */
	static List<String> problems(WildernessPlaces list)
	{
		final List<String> problems = new ArrayList<>();
		if (blank(list.getSource())) problems.add("no source");
		if (list.getPlaces() == null) return problems;
		for (WildernessPlaces.Place place : list.getPlaces())
		{
			final String name = place == null ? "?" : place.getKey();
			if (place == null || blank(place.getKey()))
			{
				problems.add(name + ": no key");
				continue;
			}
			if (place.getEntrance() != null)
			{
				if (!validPoint(place.getEntrance())) problems.add(name + ": invalid entrance point");
				if (blank(place.getEntranceSource())) problems.add(name + ": entrance without a source");
			}
			if (place.getEntranceRoutable() != null && blank(place.getEntranceRoutableSource()))
			{
				problems.add(name + ": entranceRoutable without a source");
			}
			if (place.getSpots() != null)
			{
				for (int[] spot : place.getSpots())
				{
					if (!validPoint(spot)) problems.add(name + ": invalid spot");
				}
				if (place.getSpots().length > 0 && blank(place.getSpotsSource())) problems.add(name + ": spots without a source");
			}
		}
		return problems;
	}

	/** Every reason a value in this location would be ignored, plus facts and points without a source. */
	static List<String> problems(SlayerLocation location)
	{
		final List<String> problems = new ArrayList<>();
		if (blank(location.getLabel())) problems.add("no label");
		if (location.getEntrance() != null)
		{
			if (!validPoint(location.getEntrance())) problems.add("invalid entrance point");
			if (blank(location.getEntranceSource())) problems.add("entrance without a source");
		}
		if (location.getEntranceRoutable() != null && blank(location.getEntranceRoutableSource()))
		{
			problems.add("entranceRoutable without a source");
		}
		checkFacts(problems, "location", location.getCannon(), location.getCannonSource(), location.getCombat(),
				location.getCombatSource(), location.getNote(), location.getNoteSource());
		checkAccess(problems, "location", location.getAccess());
		if (location.getTasks() != null)
		{
			for (SlayerLocation.TaskEntry task : location.getTasks())
			{
				final String name = "task " + (task == null ? "?" : task.getTaskId());
				if (task == null || task.getTaskId() <= 0)
				{
					problems.add(name + ": no task id");
					continue;
				}
				if (task.getSpots() != null)
				{
					for (int[] spot : task.getSpots())
					{
						if (!validPoint(spot)) problems.add(name + ": invalid spot");
					}
					if (task.getSpots().length > 0 && blank(task.getSpotsSource())) problems.add(name + ": spots without a source");
				}
				checkFacts(problems, name, task.getCannon(), task.getCannonSource(), task.getCombat(),
						task.getCombatSource(), task.getNote(), task.getNoteSource());
				checkAccess(problems, name, task.getAccess());
			}
		}
		return problems;
	}

	/** An access entry must need something or carry a note, name its source and ask for real levels only. */
	private static void checkAccess(List<String> problems, String scope, Access access)
	{
		if (access == null) return;
		final boolean locks = access.getQuestsFinished() != null && !access.getQuestsFinished().isEmpty()
				|| access.getQuestsStarted() != null && !access.getQuestsStarted().isEmpty()
				|| access.getSkills() != null && !access.getSkills().isEmpty();
		if (!locks && blank(access.getNote())) problems.add(scope + ": access that needs nothing");
		if (blank(access.getSource())) problems.add(scope + ": access without a source");
		if (access.getSkills() != null)
		{
			for (Map.Entry<String, Integer> skill : access.getSkills().entrySet())
			{
				if (skill.getValue() == null || skill.getValue() < 1 || skill.getValue() > 99)
				{
					problems.add(scope + ": " + skill.getKey() + " level must be 1 to 99");
				}
			}
		}
	}

	private static void checkFacts(List<String> problems, String scope, String cannon, String cannonSource,
			String combat, String combatSource, String note, String noteSource)
	{
		if (cannon != null && cannonValue(cannon) == null) problems.add(scope + ": cannon must be yes or no");
		if (cannon != null && blank(cannonSource)) problems.add(scope + ": cannon without a source");
		if (combat != null && combatValue(combat) == null) problems.add(scope + ": combat must be multi, single or mixed");
		if (combat != null && blank(combatSource)) problems.add(scope + ": combat without a source");
		if (!blank(note) && blank(noteSource)) problems.add(scope + ": note without a source");
	}

	/** Drops values the plugin would otherwise have to second-guess at render time. */
	private static void sanitize(SlayerLocation location)
	{
		if (location.getEntrance() != null && !validPoint(location.getEntrance())) location.setEntrance(null);
		location.setCannon(cannonValue(location.getCannon()));
		location.setCombat(combatValue(location.getCombat()));
		final List<SlayerLocation.TaskEntry> tasks = new ArrayList<>();
		if (location.getTasks() != null)
		{
			for (SlayerLocation.TaskEntry task : location.getTasks())
			{
				if (task == null || task.getTaskId() <= 0) continue;
				final List<int[]> spots = new ArrayList<>();
				if (task.getSpots() != null)
				{
					for (int[] spot : task.getSpots())
					{
						if (validPoint(spot)) spots.add(spot);
					}
				}
				task.setSpots(spots.toArray(new int[0][]));
				task.setCannon(cannonValue(task.getCannon()));
				task.setCombat(combatValue(task.getCombat()));
				tasks.add(task);
			}
		}
		location.setTasks(Collections.unmodifiableList(tasks));
	}

	static boolean validPoint(int[] point)
	{
		return point != null && point.length == 3 && point[0] > 0 && point[1] > 0 && point[2] >= 0 && point[2] <= 3;
	}

	static String cannonValue(String value)
	{
		if (value == null) return null;
		final String v = value.trim().toLowerCase();
		return "yes".equals(v) || "no".equals(v) ? v : null;
	}

	static String combatValue(String value)
	{
		if (value == null) return null;
		final String v = value.trim().toLowerCase();
		return "multi".equals(v) || "single".equals(v) || "mixed".equals(v) ? v : null;
	}

	private static boolean blank(String value)
	{
		return value == null || value.trim().isEmpty();
	}

	private static final class LocationFile
	{
		private List<SlayerLocation> locations;
		private List<TaskLocations> taskLocations;
		private List<WildernessPlaces> wildernessTaskLocations;
	}
}

package com.slayercompanion;

import lombok.AllArgsConstructor;
import lombok.Getter;
import net.runelite.api.gameval.VarbitID;

/**
 * Masters with their own block list. The id is the game's master id: SlayerMasterTask.COL_MASTER_ID,
 * the SLAYER_MASTER varbit and the reward shop's SLAYER_MASTER_IN_FOCUS all use it (checked against a
 * cache dump and the block list client scripts, see tools/cache-dump). Spria (9) shares Turael's block
 * list but has her own pool, so she is not listed here.
 * {@link SlayerAssigner} covers every master spot, with requirements, costs and stand-ins.
 * Block slots 1 to 6 open at 50, 100 ... 300 quest points. On the seven slot lists the last varbit is the
 * slot opened by the elite Lumbridge & Draynor diary. Mortimer has two slots only (wiki Slayer Rewards:
 * "In Mortimer's case, there are two block slots available"), taken here to open at 50 and 100 quest
 * points like everyone's first two.
 */
@Getter
@AllArgsConstructor
public enum SlayerMaster
{
	TURAEL("Turael", 1, true, new int[]{
			VarbitID.SLAYER_BLOCKED_TURAEL_1, VarbitID.SLAYER_BLOCKED_TURAEL_2, VarbitID.SLAYER_BLOCKED_TURAEL_3,
			VarbitID.SLAYER_BLOCKED_TURAEL_4, VarbitID.SLAYER_BLOCKED_TURAEL_5, VarbitID.SLAYER_BLOCKED_TURAEL_6,
			VarbitID.SLAYER_BLOCKED_TURAEL_DIARY}),
	MAZCHNA("Mazchna", 2, true, new int[]{
			VarbitID.SLAYER_BLOCKED_MAZCHNA_1, VarbitID.SLAYER_BLOCKED_MAZCHNA_2, VarbitID.SLAYER_BLOCKED_MAZCHNA_3,
			VarbitID.SLAYER_BLOCKED_MAZCHNA_4, VarbitID.SLAYER_BLOCKED_MAZCHNA_5, VarbitID.SLAYER_BLOCKED_MAZCHNA_6,
			VarbitID.SLAYER_BLOCKED_MAZCHNA_DIARY}),
	VANNAKA("Vannaka", 3, true, new int[]{
			VarbitID.SLAYER_BLOCKED_VANNAKA_1, VarbitID.SLAYER_BLOCKED_VANNAKA_2, VarbitID.SLAYER_BLOCKED_VANNAKA_3,
			VarbitID.SLAYER_BLOCKED_VANNAKA_4, VarbitID.SLAYER_BLOCKED_VANNAKA_5, VarbitID.SLAYER_BLOCKED_VANNAKA_6,
			VarbitID.SLAYER_BLOCKED_VANNAKA_DIARY}),
	CHAELDAR("Chaeldar", 4, true, new int[]{
			VarbitID.SLAYER_BLOCKED_CHAELDAR_1, VarbitID.SLAYER_BLOCKED_CHAELDAR_2, VarbitID.SLAYER_BLOCKED_CHAELDAR_3,
			VarbitID.SLAYER_BLOCKED_CHAELDAR_4, VarbitID.SLAYER_BLOCKED_CHAELDAR_5, VarbitID.SLAYER_BLOCKED_CHAELDAR_6,
			VarbitID.SLAYER_BLOCKED_CHAELDAR_DIARY}),
	KONAR("Konar", 8, true, new int[]{
			VarbitID.SLAYER_BLOCKED_KONAR_1, VarbitID.SLAYER_BLOCKED_KONAR_2, VarbitID.SLAYER_BLOCKED_KONAR_3,
			VarbitID.SLAYER_BLOCKED_KONAR_4, VarbitID.SLAYER_BLOCKED_KONAR_5, VarbitID.SLAYER_BLOCKED_KONAR_6,
			VarbitID.SLAYER_BLOCKED_KONAR_DIARY}),
	NIEVE("Nieve", 6, true, new int[]{
			VarbitID.SLAYER_BLOCKED_NIEVE_1, VarbitID.SLAYER_BLOCKED_NIEVE_2, VarbitID.SLAYER_BLOCKED_NIEVE_3,
			VarbitID.SLAYER_BLOCKED_NIEVE_4, VarbitID.SLAYER_BLOCKED_NIEVE_5, VarbitID.SLAYER_BLOCKED_NIEVE_6,
			VarbitID.SLAYER_BLOCKED_NIEVE_DIARY}),
	DURADEL("Duradel", 5, true, new int[]{
			VarbitID.SLAYER_BLOCKED_DURADEL_1, VarbitID.SLAYER_BLOCKED_DURADEL_2, VarbitID.SLAYER_BLOCKED_DURADEL_3,
			VarbitID.SLAYER_BLOCKED_DURADEL_4, VarbitID.SLAYER_BLOCKED_DURADEL_5, VarbitID.SLAYER_BLOCKED_DURADEL_6,
			VarbitID.SLAYER_BLOCKED_DURADEL_DIARY}),
	KRYSTILIA("Krystilia", 7, true, new int[]{
			VarbitID.SLAYER_BLOCKED_KRYSTILIA_1, VarbitID.SLAYER_BLOCKED_KRYSTILIA_2, VarbitID.SLAYER_BLOCKED_KRYSTILIA_3,
			VarbitID.SLAYER_BLOCKED_KRYSTILIA_4, VarbitID.SLAYER_BLOCKED_KRYSTILIA_5, VarbitID.SLAYER_BLOCKED_KRYSTILIA_6,
			VarbitID.SLAYER_BLOCKED_KRYSTILIA_DIARY}),
	MORTIMER("Mortimer", 10, false, new int[]{
			VarbitID.SLAYER_BLOCKED_MORTIMER_1, VarbitID.SLAYER_BLOCKED_MORTIMER_2});

	/** Quest points per regular block slot. Slot n (1 to 6) needs n times this. */
	static final int QUEST_POINTS_PER_BLOCK_SLOT = 50;

	private final String displayName;
	/** The game's master id, as stored in SlayerMasterTask.COL_MASTER_ID and the SLAYER_MASTER varbit. */
	private final int id;
	/** Whether the last block varbit is the slot the elite Lumbridge & Draynor diary opens. */
	private final boolean diarySlot;
	private final int[] blockVarbits;

	/** The master for a game master id, or null for Spria, the leagues pool and unknown ids. */
	static SlayerMaster forId(int id)
	{
		for (SlayerMaster master : values())
		{
			if (master.id == id) return master;
		}
		return null;
	}

	/** The block list a master spot uses: Spria shares Turael's. Null for an unknown master. */
	static SlayerMaster forAssigner(SlayerAssigner assigner)
	{
		if (assigner == null) return null;
		return assigner == SlayerAssigner.SPRIA ? TURAEL : forId(assigner.getId());
	}

	/** The master spot whose pool this block list goes with. */
	SlayerAssigner assigner()
	{
		return SlayerAssigner.forId(id);
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.slayercompanion;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarbitID;

/**
 * Which masters this player can get a task from, and which NPC stands at each spot. {@link #options} is
 * the pure core. {@link #read} is the thin reader of client state.
 * <p>
 * Who stands where follows the game's own varbits, checked against the cache (tools/cache-dump, section
 * masterNpcs). The masters at Burthorpe, Canifis and Shilo Village are one multi-NPC each, switched by
 * WGS_HERO_PART_1_VIS, and the Tree Gnome Stronghold one by MM2_SLAYER_MASTER. The NPC Contact spell names
 * them from the same varbits (client script 2615).
 * <ul>
 * <li>While Guthix Sleeps: 0 until Turael, Mazchna and Duradel leave to fight Lucien, 1 while they are
 * away, 2 after the quest. Aya replaces Turael and Kuradal replaces Duradel from 1 on, as both die in the
 * quest. Achtryn stands in for Mazchna at 1 only.</li>
 * <li>Monkey Madness II: Steve replaces Nieve once MM2_SLAYER_MASTER is 1.</li>
 * <li>Spria gives tasks once A Porcine of Interest is complete: PORCINE 40, the quest's end state.</li>
 * <li>Mortimer stands in Wyrmscraig Cavern from Fallen From Grace stage 12 to its end state, 20. His
 * Assignment op stays hidden until MORTIMER_INTRODUCTION is set.</li>
 * </ul>
 */
@Slf4j
final class SlayerMasterAccess
{
	/** A Porcine of Interest's end state in the quest table. The master version of Spria shows only then. */
	static final int PORCINE_DONE = 40;
	/** The first Fallen From Grace stage at which Mortimer stands at his spot. */
	static final int MORTIMER_STAGE = 12;
	/** WGS_HERO_PART_1_VIS while the masters are away fighting Lucien. */
	static final int GUTHIX_SLEEPS_AWAY = 1;
	/** At 99 Slayer the Slayer cape stands in for any combat requirement. */
	static final int CAPE_LEVEL = 99;

	/** Everything master access and payouts depend on. */
	@Value
	static class State
	{
		int combatLevel;
		int slayerLevel;
		boolean priestInPeril;
		boolean lostCity;
		boolean shiloVillage;
		/** WGS_HERO_PART_1_VIS. */
		int guthixSleeps;
		/** MM2_SLAYER_MASTER is 1. */
		boolean steve;
		/** PORCINE, the quest's progress. */
		int porcine;
		/** FFG, the quest's progress. */
		int fallenFromGrace;
		/** MORTIMER_INTRODUCTION is set. Until then his Assignment, Trade and Rewards ops are hidden. */
		boolean mortimerIntroduced;
		SlayerPayout.Diaries diaries;
	}

	/** One master spot as this player finds it. */
	@Value
	static class Option
	{
		SlayerAssigner master;
		/** The NPC at the spot, e.g. Aya once she has replaced Turael. */
		String npc;
		/** The first requirement the player lacks, e.g. "combat level 100", or null when usable. */
		String missing;

		boolean isUsable()
		{
			return missing == null;
		}
	}

	/** Quest completions behind master requirements. Each read runs a client script, so callers cache it. */
	@Value
	static class Quests
	{
		static final Quests NONE = new Quests(false, false, false);

		boolean priestInPeril;
		boolean lostCity;
		boolean shiloVillage;

		/** Client thread only. A failed read counts the quests as not done until the next read. */
		static Quests read(Client client)
		{
			try
			{
				return new Quests(finished(client, Quest.PRIEST_IN_PERIL), finished(client, Quest.LOST_CITY),
						finished(client, Quest.SHILO_VILLAGE));
			}
			catch (RuntimeException ex)
			{
				log.debug("Slayer Sensei could not read quest states", ex);
				return NONE;
			}
		}

		private static boolean finished(Client client, Quest quest)
		{
			return quest.getState(client) == QuestState.FINISHED;
		}
	}

	private SlayerMasterAccess()
	{
	}

	/** Levels and varbits are read on every call. Quest completions come from the caller's cache. Client thread. */
	static State read(Client client, Quests quests)
	{
		final Player player = client.getLocalPlayer();
		return new State(player == null ? 0 : player.getCombatLevel(),
				client.getRealSkillLevel(Skill.SLAYER),
				quests.isPriestInPeril(), quests.isLostCity(), quests.isShiloVillage(),
				client.getVarbitValue(VarbitID.WGS_HERO_PART_1_VIS),
				client.getVarbitValue(VarbitID.MM2_SLAYER_MASTER) == 1,
				client.getVarbitValue(VarbitID.PORCINE),
				client.getVarbitValue(VarbitID.FFG),
				client.getVarbitValue(VarbitID.MORTIMER_INTRODUCTION) != 0,
				new SlayerPayout.Diaries(client.getVarbitValue(VarbitID.WESTERN_ELITE_REWARD) != 0,
						client.getVarbitValue(VarbitID.KOUREND_ELITE_REWARD) != 0));
	}

	/** Every master spot in {@link SlayerAssigner} order. */
	static List<Option> options(State state)
	{
		final List<Option> out = new ArrayList<>();
		for (SlayerAssigner master : SlayerAssigner.values())
		{
			out.add(new Option(master, npcName(master, state), missing(master, state)));
		}
		return Collections.unmodifiableList(out);
	}

	/** The option for one master. Never null for a list made by {@link #options}. */
	static Option find(List<Option> options, SlayerAssigner master)
	{
		for (Option o : options)
		{
			if (o.getMaster() == master) return o;
		}
		return null;
	}

	/** The NPC the player finds at the master's spot. */
	static String npcName(SlayerAssigner master, State state)
	{
		switch (master)
		{
			case TURAEL:
				return state.getGuthixSleeps() != 0 ? "Aya" : "Turael";
			case MAZCHNA:
				return state.getGuthixSleeps() == GUTHIX_SLEEPS_AWAY ? "Achtryn" : "Mazchna";
			case DURADEL:
				return state.getGuthixSleeps() != 0 ? "Kuradal" : "Duradel";
			case NIEVE:
				return state.isSteve() ? "Steve" : "Nieve";
			default:
				return master.getDisplayName();
		}
	}

	/** The first requirement the player lacks for the master, or null when the master gives them tasks. */
	static String missing(SlayerAssigner master, State state)
	{
		if (state.getCombatLevel() < master.getCombatLevel() && state.getSlayerLevel() < CAPE_LEVEL)
		{
			return "combat level " + master.getCombatLevel();
		}
		if (state.getSlayerLevel() < master.getSlayerLevel())
		{
			return "Slayer level " + master.getSlayerLevel();
		}
		switch (master.getQuestNeed())
		{
			case PRIEST_IN_PERIL:
				return state.isPriestInPeril() ? null : "Priest in Peril";
			case LOST_CITY:
				return state.isLostCity() ? null : "Lost City";
			case SHILO_VILLAGE:
				return state.isShiloVillage() ? null : "Shilo Village";
			case PORCINE_OF_INTEREST:
				return state.getPorcine() >= PORCINE_DONE ? null : "A Porcine of Interest";
			case FALLEN_FROM_GRACE_PART:
				if (state.getFallenFromGrace() < MORTIMER_STAGE) return "progress in Fallen From Grace";
				return state.isMortimerIntroduced() ? null : "an introduction";
			default:
				return null;
		}
	}
}

package com.slayercompanion;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.function.Function;
import java.util.function.ToIntFunction;
import lombok.Value;

/**
 * Ranks the masters a player can use for the XP and profit goals. Pure.
 * <p>
 * A master is judged by his pool as the player gets it ({@link SlayerPool}), with the player's block slots
 * filled by the blocks that help the goal most ({@link SlayerGoalModel#bestBlocks}), so a block list not
 * built yet does not count against him. On top of the pool come these master-level effects, each from the
 * OSRS Wiki, read 4 October 2026:
 * <ul>
 * <li>Skips. "Use Slayer reward points or Turael to skip undesirable tasks as often as possible", and "use
 * the cancel option as often as it can be used while maintaining a stable level of Slayer reward points"
 * (Slayer training). A master's points per task, milestones averaged in, pay for skipping that share of the
 * worst offers at his cancel cost. This is what Duradel's 15 points a task are worth.</li>
 * <li>Mortimer offers a choice of two tasks, three once 50 of his tasks are done, and his tasks pay no
 * points unless a points modifier comes up (Mortimer), so he gets the best of each offer and no skips.</li>
 * <li>Konar picks the location of every task, each eligible area equally likely, and "some places may be
 * less desirable than others" (Konar quo Maten/Strategies, which skips e.g. abyssal demons outside the
 * Catacombs, 2 chances in 3). Her XP ratings lose {@link #KONAR_LOCATION_XP}, a judgment.</li>
 * <li>Brimstone keys drop on Konar's tasks, about 1 in 100 kills of level 100 monsters, more from Slayer
 * monsters and always from superiors, and the chest averages about 87k (Brimstone key). At 100 to 300 kills
 * an hour that is roughly 100k to 300k, so her profit ratings gain {@link #BRIMSTONE_KEYS_GP}.</li>
 * <li>Larran's keys drop on Krystilia's tasks at about the same rate and the big chest averages about 118k
 * (Larran's key, Larran's big chest). Her profit ratings gain {@link #LARRANS_KEYS_GP}. Her tasks use the
 * ratings' Wilderness version, see {@link SlayerPool}.</li>
 * </ul>
 * With the cache and ratings of 4 October 2026 a maxed account gets Kuradal first for XP, as the Slayer
 * training guide has it ("Duradel is the best Slayer master to use for the fastest experience, but some
 * players may find that Nieve's (or Steve's) task weighting better suit their preferences"), then Steve.
 * Mortimer passes Steve once he offers three tasks, in line with his strategy page ("Players may find more
 * success training at Mortimer if they don't have a lot of slayer points for skipping or a block list fully
 * built out"). For profit Mortimer's choice comes first, then Konar with her keys, then Kuradal.
 * SlayerMasterRankerTest keeps all of this.
 */
final class SlayerMasterRanker
{
	static final double KONAR_LOCATION_XP = -0.4;
	static final double BRIMSTONE_KEYS_GP = 0.3;
	static final double LARRANS_KEYS_GP = 0.3;
	/** Mortimer offers a third task once this many of his tasks are done (wiki Mortimer). */
	static final int MORTIMER_THIRD_CHOICE = 50;
	/** A task rated this or better counts as good for the goal in the reasons. */
	static final int GOOD = 4;
	/** Average milestone multiplier over a long streak, from {@link SlayerPayout#multiplier}. */
	static final double AVERAGE_MULTIPLIER = averageMultiplier();

	@Value
	static class Ranked
	{
		SlayerAssigner master;
		/** The NPC the player finds at the master's spot. */
		String npc;
		/** What the masters are ordered by. Internal, never shown. */
		double score;
		/**
		 * Chance a task is good for the goal (rated {@link #GOOD} or better) once the assumed blocks are in. For
		 * Mortimer, among the tasks the player picks.
		 */
		double goodShare;
		/** The blocks the ranking assumed at this master, best first. */
		List<String> blocks;
		/** Short reason for the sidebar. */
		String reason;
		/** What the player still needs to use the master, e.g. "combat level 100", or null when usable. */
		String missing;
	}

	private SlayerMasterRanker()
	{
	}

	/**
	 * Usable masters for the goal, best first. Empty for the Slayer points goal, which has its routine.
	 *
	 * @param pools a master's pool as the player gets it, null when unknown
	 * @param slots block slots the player can use at a master
	 * @param mortimerTasks SLAYER_MORTIMER_TASKS_COMPLETED
	 */
	static List<Ranked> rank(SlayerGoal goal, List<SlayerMasterAccess.Option> options, Function<SlayerAssigner, SlayerPool> pools,
			ToIntFunction<SlayerAssigner> slots, SlayerPayout.Diaries diaries, int mortimerTasks)
	{
		return judgeAll(goal, options, true, pools, slots, diaries, mortimerTasks);
	}

	/**
	 * The best master the player cannot use yet, when he beats every master in {@code ranking}, or null. He is
	 * judged on the tasks the player could be given today, so the hint errs on the side of silence.
	 */
	static Ranked later(SlayerGoal goal, List<SlayerMasterAccess.Option> options, Function<SlayerAssigner, SlayerPool> pools,
			ToIntFunction<SlayerAssigner> slots, SlayerPayout.Diaries diaries, int mortimerTasks, List<Ranked> ranking)
	{
		final List<Ranked> locked = judgeAll(goal, options, false, pools, slots, diaries, mortimerTasks);
		if (locked.isEmpty()) return null;
		final Ranked best = locked.get(0);
		return ranking.isEmpty() || best.getScore() > ranking.get(0).getScore() ? best : null;
	}

	private static List<Ranked> judgeAll(SlayerGoal goal, List<SlayerMasterAccess.Option> options, boolean usable,
			Function<SlayerAssigner, SlayerPool> pools, ToIntFunction<SlayerAssigner> slots, SlayerPayout.Diaries diaries,
			int mortimerTasks)
	{
		if (goal == SlayerGoal.POINTS) return Collections.emptyList();
		final List<Ranked> out = new ArrayList<>();
		for (SlayerMasterAccess.Option o : options)
		{
			if (o.isUsable() != usable) continue;
			final SlayerPool pool = pools.apply(o.getMaster());
			if (pool == null || SlayerGoalModel.offers(pool).isEmpty()) continue;
			out.add(judge(goal, o, pool, slots.applyAsInt(o.getMaster()), diaries, mortimerTasks));
		}
		out.sort(Comparator.comparingDouble(Ranked::getScore).reversed()
				.thenComparingInt(r -> r.getMaster().ordinal()));
		return Collections.unmodifiableList(out);
	}

	private static Ranked judge(SlayerGoal goal, SlayerMasterAccess.Option option, SlayerPool pool, int slots,
			SlayerPayout.Diaries diaries, int mortimerTasks)
	{
		final SlayerAssigner master = option.getMaster();
		final List<SlayerPool.Entry> blocks = SlayerGoalModel.bestBlocks(pool, goal, slots);
		final List<Integer> rows = new ArrayList<>();
		final List<String> names = new ArrayList<>();
		for (SlayerPool.Entry e : blocks)
		{
			rows.add(e.getTaskRow());
			names.add(e.getName());
		}
		final SlayerPool blocked = pool.withBlocks(rows);
		final List<SlayerGoalModel.Offer> offers = SlayerGoalModel.offers(blocked);
		final double bonus = bonus(master, goal);
		final int choices = choices(master, mortimerTasks);
		final double score;
		final double good;
		if (choices > 1)
		{
			// What counts is the task the player picks from each offer
			final List<SlayerGoalModel.Offer> picked = SlayerGoalModel.bestOf(offers, goal, choices);
			score = SlayerGoalModel.rate(picked, goal, bonus, 0);
			good = SlayerGoalModel.share(picked, goal, GOOD);
		}
		else
		{
			score = SlayerGoalModel.rateWithSkips(offers, goal, bonus, skipBudget(master, diaries));
			good = SlayerGoalModel.share(offers, goal, GOOD);
		}
		return new Ranked(master, option.getNpc(), score, good, Collections.unmodifiableList(names),
				reason(master, option.getNpc(), goal, good, !blocks.isEmpty(), choices), option.getMissing());
	}

	/** What the master adds to every task's rating for the goal. */
	static double bonus(SlayerAssigner master, SlayerGoal goal)
	{
		if (master == SlayerAssigner.KONAR) return goal == SlayerGoal.XP ? KONAR_LOCATION_XP : BRIMSTONE_KEYS_GP;
		if (master == SlayerAssigner.KRYSTILIA && goal == SlayerGoal.PROFIT) return LARRANS_KEYS_GP;
		return 0;
	}

	/** How many tasks each assignment offers: 1, or Mortimer's 2 or 3. */
	static int choices(SlayerAssigner master, int mortimerTasks)
	{
		if (master != SlayerAssigner.MORTIMER) return 1;
		return mortimerTasks >= MORTIMER_THIRD_CHOICE ? 3 : 2;
	}

	/** Share of offers the master's own points pay to skip, at his cancel cost. 0 for masters who pay no points. */
	static double skipBudget(SlayerAssigner master, SlayerPayout.Diaries diaries)
	{
		final double points = SlayerPayout.basePoints(master, diaries) * AVERAGE_MULTIPLIER;
		return points <= 0 ? 0 : points / (master.getCancelCost() + points);
	}

	private static double averageMultiplier()
	{
		// Every milestone interval divides 1,000, so one run of 1,000 tasks is the long-run average
		int sum = 0;
		for (int task = 1; task <= 1000; task++)
		{
			sum += SlayerPayout.multiplier(task);
		}
		return sum / 1000.0;
	}

	/** "About 2 in 5 tasks are good XP tasks once you block the worst." plus the master's own effect. */
	static String reason(SlayerAssigner master, String npc, SlayerGoal goal, double goodShare, boolean blocks, int choices)
	{
		final StringBuilder sb = new StringBuilder();
		if (choices > 1) sb.append("You choose from ").append(choices).append(" tasks each time. ");
		if (master == SlayerAssigner.KONAR && goal == SlayerGoal.PROFIT) sb.append("Brimstone keys add to every task. ");
		if (master == SlayerAssigner.KRYSTILIA && goal == SlayerGoal.PROFIT) sb.append("Larran's keys add to every task. ");
		sb.append(share(goodShare)).append(choices > 1 ? " of the tasks you pick are good " : " tasks are good ")
				.append(goal == SlayerGoal.XP ? "XP" : "money").append(" tasks")
				.append(blocks ? " once you block the worst." : ".");
		if (master == SlayerAssigner.MORTIMER) sb.append(' ').append(npc).append("'s tasks pay no Slayer points.");
		if (master == SlayerAssigner.KRYSTILIA) sb.append(" All of it is in the Wilderness.");
		return sb.toString();
	}

	/** A share as words, so a rough rating never reads as a precise number. */
	static String share(double share)
	{
		final int tenths = (int) Math.round(share * 10);
		if (tenths <= 0) return "Hardly any";
		if (tenths >= 10) return "Nearly all";
		if (tenths == 5) return "About half";
		return "About " + (tenths % 2 == 0 ? tenths / 2 + " in 5" : tenths + " in 10");
	}
}

package com.slayercompanion;

import lombok.Value;

/**
 * Slayer reward points a completed task pays. Pure. Points per task are not in any cache table, so every
 * number here is from the OSRS Wiki, read as raw wikitext on 4 October 2026: the "Slayer reward point"
 * page (its table of points per master, the milestone list and the first four tasks), checked against
 * the points table on each master's own page.
 */
final class SlayerPayout
{
	/** "Slayer points are not awarded for the first four tasks" of a streak (Slayer reward point). */
	static final int UNPAID_TASKS = 4;

	/**
	 * {interval, multiplier} from the Slayer reward point page: 5x every 10th task, 15x every 50th, 25x
	 * every 100th, 35x every 250th and 50x every 1,000th. A task on several intervals takes the largest,
	 * so the largest interval comes first.
	 */
	private static final int[][] MILESTONES = {{1000, 50}, {250, 35}, {100, 25}, {50, 15}, {10, 5}};

	/** The two elite diaries that raise a master's points. */
	@Value
	static class Diaries
	{
		static final Diaries NONE = new Diaries(false, false);

		/** Elite Western Provinces: Nieve and Steve pay 15 instead of 12. */
		boolean westernElite;
		/** Elite Kourend & Kebos: Konar pays 20 instead of 18. */
		boolean kourendElite;
	}

	private SlayerPayout()
	{
	}

	/**
	 * Points for an ordinary task, before milestones. Wiki pages: "Slayer reward point" for all of them,
	 * and Turael, Aya, Spria, Mazchna, Achtryn, Vannaka, Chaeldar, Nieve, Steve, Duradel, Kuradal,
	 * Konar quo Maten, Krystilia and Mortimer. A replacement pays what the master it replaces pays.
	 */
	static int basePoints(SlayerAssigner master, Diaries diaries)
	{
		switch (master)
		{
			case MAZCHNA:
				return 6;
			case VANNAKA:
				return 8;
			case CHAELDAR:
				return 10;
			case NIEVE:
				return diaries.isWesternElite() ? 15 : 12;
			case DURADEL:
				return 15;
			case KONAR:
				return diaries.isKourendElite() ? 20 : 18;
			case KRYSTILIA:
				return 25;
			case TURAEL:
			case SPRIA:
				return 0;
			case MORTIMER:
			default:
				// Mortimer pays 5 to 40 only through his points modifier, never times a milestone
				return 0;
		}
	}

	/** The milestone multiplier for a task number in its streak, 1 for an ordinary task. */
	static int multiplier(int taskNumber)
	{
		for (int[] m : MILESTONES)
		{
			if (taskNumber > 0 && taskNumber % m[0] == 0) return m[1];
		}
		return 1;
	}

	/**
	 * The milestone multiplier averaged over the tasks a routine takes to its paying master, every
	 * {@code every}th task of a long streak: 8.75 for every 10th and 23.75 for every 50th. The pattern repeats
	 * every 1,000 tasks. Over all 1,000 tasks of a streak the same table averages 1.775 times the base points,
	 * the figure the Slayer reward point page gives.
	 */
	static double averageMultiplier(int every)
	{
		final int cycle = MILESTONES[0][0];
		int sum = 0;
		int count = 0;
		for (int task = every; every > 0 && task <= cycle; task += every)
		{
			sum += multiplier(task);
			count++;
		}
		return count == 0 ? 1 : sum / (double) count;
	}

	/** Whether a task number pays a milestone bonus. Every milestone is a multiple of 10. */
	static boolean isMilestone(int taskNumber)
	{
		return multiplier(taskNumber) > 1;
	}

	/**
	 * Points for completing task {@code taskNumber} of the master's own streak (1 for the first task after
	 * a reset). Tasks 1 to 4 pay nothing anywhere.
	 */
	static int payout(SlayerAssigner master, int taskNumber, Diaries diaries)
	{
		if (taskNumber <= UNPAID_TASKS) return 0;
		return basePoints(master, diaries) * multiplier(taskNumber);
	}
}

package com.slayercompanion;

import com.slayercompanion.SlayerPointsPlanner.Candidate;
import com.slayercompanion.SlayerPointsPlanner.Plan;
import com.slayercompanion.SlayerPointsPlanner.Reserve;
import com.slayercompanion.data.SlayerTask;
import com.slayercompanion.data.TaskRating;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Function;
import java.util.function.IntUnaryOperator;
import java.util.function.ToIntFunction;
import lombok.AllArgsConstructor;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * Reads purchases, block lists, levels, streaks and the task in progress from the client and feeds the spend plan,
 * the points routine and the task advice.
 */
final class SlayerPlanBuilder
{
	/** Skips in a row the reserve is ever sized for. */
	static final int MAX_SKIPS_IN_A_ROW = 5;

	/** Everything the plan reads from the client, behind an interface so a plan can be built from test data. */
	interface Account
	{
		int varp(int varp);

		int varbit(int varbit);

		/**
		 * Real levels by stat id, read as the game's whole array. Its order is that of {@link Skill} and of the cache's
		 * stat ids, and slots past the last stat stay 0.
		 */
		int[] levels();

		static Account of(Client client)
		{
			return new Account()
			{
				@Override
				public int varp(int varp)
				{
					return client.getVarpValue(varp);
				}

				@Override
				public int varbit(int varbit)
				{
					return client.getVarbitValue(varbit);
				}

				@Override
				public int[] levels()
				{
					final int[] levels = client.getRealSkillLevels();
					return levels == null ? new int[0] : levels.clone();
				}
			};
		}
	}

	/** The player's planner choices from config. */
	@Value
	@AllArgsConstructor
	static class Settings
	{
		/** Whose task pool and block list the plan reads when it does not follow the goal. */
		SlayerMaster master;
		/** The fewest points the plan keeps for skips, from config. It keeps more when the skip model needs more. */
		int reserve;
		SlayerGoal goal;
		BoostInterval boost;
		/**
		 * The plan uses the goal's master: the best master for XP or profit, the master who pays most for
		 * milestones for Slayer points. False pins it to {@link #master}.
		 */
		boolean followGoal;

		/** A plan pinned to {@code master}. */
		Settings(SlayerMaster master, int reserve, SlayerGoal goal, BoostInterval boost)
		{
			this(master, reserve, goal, boost, false);
		}
	}

	@Value
	static class View
	{
		Plan plan;
		/** Whose pool and block list the plan reads: the goal's master, or the pinned one. */
		SlayerMaster master;
		List<String> blocked;
		/** Open block slots with nothing in them. Slots still locked behind quest points or the diary do not count. */
		int emptySlots;
		/** How the locked block slots open, or null when every slot is open. */
		String lockedSlots;
		int blockedWeightPercent;
		/**
		 * The plan master's pool as the player gets it, with the current blocks: every task's weight, whether
		 * it can be assigned and its ratings. Null without the cache tables.
		 */
		SlayerPool pool;
		/** Which tasks to block at the plan's master for the goal, or null without the cache tables. */
		SlayerBlockAdvisor.Advice blockAdvice;
		List<String> notes;
		/** The notes in a few words for the compact sidebar, one per note in the same order. */
		List<String> noteItems;
		boolean fromCache;
		SlayerGoal goal;
		/** Every master spot with the NPC there and whether the player can use it. Empty without master state. */
		List<SlayerMasterAccess.Option> masters;
		/** The Slayer points routine, or null for the other goals. */
		SlayerPointsRoutine.Advice routine;
		/** The masters the player can use, best first for XP or profit. Empty for Slayer points. */
		List<SlayerMasterRanker.Ranked> ranking;
		/** A master the player cannot use yet who would beat all of them, or null. */
		SlayerMasterRanker.Ranked later;
		/**
		 * The master the goal points to: the best for XP or profit, the best milestone payer for Slayer points.
		 * Null when nothing is known yet. The plan uses it unless Pin planner master is on.
		 */
		SlayerMaster goalMaster;
		/** The task in progress at its master, or null without a task or without the cache tables. */
		SlayerUnlockAdvisor.Situation task;
		/** The "Assigned by" line for the task in progress from the cache, or null to keep the dossier's text. */
		String assignedBy;
		/**
		 * On the Slayer points routine, the filler tasks' block list at Turael's spot, valued in the same plan. Null for
		 * the other goals, and when the plan's master is not where the routine's milestone tasks go.
		 */
		Fillers fillers;

		/** The NPC at the plan master's spot, e.g. Kuradal once she has replaced Duradel. */
		String getMasterName()
		{
			return npc(master);
		}

		/** The NPC at the goal master's spot, or null without one. */
		String getGoalMasterName()
		{
			return goalMaster == null ? null : npc(goalMaster);
		}

		/** Whether the plan reads the goal's master, rather than a pinned one that differs. */
		boolean isFollowingGoal()
		{
			return goalMaster != null && goalMaster == master;
		}

		/** The "Advisor" line for the task in progress, or null. */
		String getTaskAdvice()
		{
			return SlayerUnlockAdvisor.advise(task);
		}

		/** The same advice as the compact sidebar's items. Empty without a line. */
		List<String> getTaskAdviceItems()
		{
			return SlayerUnlockAdvisor.compact(task);
		}

		private String npc(SlayerMaster m)
		{
			final SlayerMasterAccess.Option option = SlayerMasterAccess.find(masters, m.assigner());
			return option == null ? m.toString() : option.getNpc();
		}
	}

	/** The routine's filler list at Turael's spot, which Aya and Spria share, as the sidebar shows it. */
	@Value
	static class Fillers
	{
		/** The NPC at Turael's spot, e.g. Aya. */
		String npc;
		List<String> blocked;
		/** Open block slots with nothing in them. */
		int emptySlots;
		/** How the locked block slots open, or null when every slot is open. */
		String lockedSlots;
		int blockedWeightPercent;
		/** Which filler tasks to block for Slayer points. */
		SlayerBlockAdvisor.Advice blockAdvice;
	}

	/** A master's block list as the player has it. */
	private static final class BlockList
	{
		final Set<Integer> rows = new HashSet<>();
		final List<Integer> inOrder = new ArrayList<>();
		final List<String> names = new ArrayList<>();
		int emptySlots;
	}

	private SlayerPlanBuilder()
	{
	}

	/** Cheap per-tick fingerprint of every input, so the plan is only rebuilt when something changed. */
	static int signature(Client client, Settings settings, SlayerMasterAccess.State access, SlayerShopItem.Sightings items)
	{
		return 31 * signature(Account.of(client), settings, access) + items.hashCode();
	}

	static int signature(Account account, Settings settings, SlayerMasterAccess.State access)
	{
		final SlayerMaster master = settings.getMaster();
		int h = 31 * master.ordinal() + settings.getReserve();
		h = 31 * h + settings.getGoal().ordinal();
		h = 31 * h + settings.getBoost().ordinal();
		h = 31 * h + (settings.isFollowGoal() ? 1 : 0);
		h = 31 * h + (access == null ? 0 : access.hashCode());
		h = 31 * h + account.varbit(VarbitID.SLAYER_TASKS_COMPLETED);
		h = 31 * h + account.varbit(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED);
		h = 31 * h + account.varp(VarPlayerID.SLAYER_MORTIMER_TASKS_COMPLETED);
		h = 31 * h + account.varbit(VarbitID.SLAYER_MASTER);
		// Only whether a task is in progress and which task, not the kill count, so kills do not rebuild the plan
		h = 31 * h + (account.varp(VarPlayerID.SLAYER_COUNT) > 0 ? 1 : 0);
		h = 31 * h + account.varp(VarPlayerID.SLAYER_TARGET);
		h = 31 * h + account.varbit(VarbitID.SLAYER_POINTS);
		// Task requirements reach past Slayer, e.g. Magic for cave kraken and Sailing for frost dragons
		h = 31 * h + Arrays.hashCode(account.levels());
		h = 31 * h + account.varbit(VarbitID.COMBAT_LEVEL_REQS_DISABLED);
		h = 31 * h + account.varbit(VarbitID.SLAYER_TOGGLEOFF_SUPERIORMOBS);
		h = 31 * h + account.varbit(VarbitID.SLAYER_TOGGLEOFF_FOSSILWYVERNBLOCK);
		// Every reward's ownership bit, cached or fallback, lives in these three varps
		for (int varp : SlayerGameData.UNLOCK_VARPS)
		{
			h = 31 * h + account.varp(varp);
		}
		h = 31 * h + account.varp(VarPlayerID.QP);
		h = 31 * h + account.varbit(VarbitID.LUMBRIDGE_ELITE_REWARD);
		// The goal can move the plan to any master, so every block list counts
		for (SlayerMaster m : SlayerMaster.values())
		{
			for (int varbit : m.getBlockVarbits())
			{
				h = 31 * h + account.varbit(varbit);
			}
		}
		return h;
	}

	static View build(Client client, SlayerGameData data, SlayerDataset dataset, Settings settings, SlayerMasterAccess.State access,
			SlayerShopItem.Sightings items)
	{
		return build(Account.of(client), data, dataset, settings, access, items);
	}

	/** A plan that has seen none of the Buy tab's items. */
	static View build(Account account, SlayerGameData data, SlayerDataset dataset, Settings settings, SlayerMasterAccess.State access)
	{
		return build(account, data, dataset, settings, access, SlayerShopItem.Sightings.NONE);
	}

	/**
	 * {@code access} is what {@link SlayerMasterAccess#read} returns. Without it there is no routine, no
	 * master list or ranking, and the forecast assumes every task is done at the plan's master.
	 *
	 * @param items which Buy tab items have been seen on this character
	 */
	static View build(Account account, SlayerGameData data, SlayerDataset dataset, Settings settings, SlayerMasterAccess.State access,
			SlayerShopItem.Sightings items)
	{
		final SlayerGoal goal = settings.getGoal();
		final int points = account.varbit(VarbitID.SLAYER_POINTS);
		final int questPoints = account.varp(VarPlayerID.QP);
		final boolean diaryDone = account.varbit(VarbitID.LUMBRIDGE_ELITE_REWARD) != 0;

		final Set<Integer> owned = ownedRewards(account, data);
		final List<SlayerMasterAccess.Option> masters = access == null
				? Collections.<SlayerMasterAccess.Option>emptyList() : SlayerMasterAccess.options(access);
		final SlayerPayout.Diaries diaries = access == null ? SlayerPayout.Diaries.NONE : access.getDiaries();
		final SlayerPool.Player player = player(account, data, owned, access);
		final Function<String, TaskRating> ratings = ratings(dataset);
		final Function<String, SlayerTask> dossier = dossier(dataset);

		// Masters are ranked by what their pool could be, so each gets the best blocks for its open slots
		final Function<SlayerAssigner, SlayerPool> rankPools = a -> SlayerPool.of(a, data, player, Collections.<Integer>emptySet(), ratings);
		final ToIntFunction<SlayerAssigner> rankSlots = a -> openSlots(SlayerMaster.forAssigner(a), questPoints, diaryDone);
		final int mortimerTasks = account.varp(VarPlayerID.SLAYER_MORTIMER_TASKS_COMPLETED);
		final List<SlayerMasterRanker.Ranked> ranking = data == null || access == null
				? Collections.<SlayerMasterRanker.Ranked>emptyList()
				: SlayerMasterRanker.rank(goal, masters, rankPools, rankSlots, diaries, mortimerTasks);
		final SlayerMasterRanker.Ranked later = data == null || access == null ? null
				: SlayerMasterRanker.later(goal, masters, rankPools, rankSlots, diaries, mortimerTasks, ranking);
		final SlayerMaster goalMaster = goalMaster(goal, ranking, masters, diaries, settings.getBoost());
		final SlayerMaster master = settings.isFollowGoal() && goalMaster != null ? goalMaster : settings.getMaster();
		final SlayerAssigner planMaster = master.assigner();
		final BlockList blocks = blockList(account, data, master, questPoints, diaryDone);

		int blockedWeightPercent = -1;
		SlayerPool planPool = null;
		SlayerBlockAdvisor.Advice blockAdvice = null;
		if (data != null)
		{
			planPool = SlayerPool.of(planMaster, data, player, blocks.rows, ratings);
			blockedWeightPercent = blockedWeightPercent(planPool);
			blockAdvice = SlayerBlockAdvisor.advise(master, planPool, goal, openSlots(master, questPoints, diaryDone), blocks.inOrder);
		}

		final SlayerPointsRoutine.Streaks streaks = streaks(account);
		final boolean routine = goal == SlayerGoal.POINTS && access != null;
		// On the routine every task but the milestone goes to Turael's spot, so that block list is valued in the same plan
		SlayerSpend.Routine cycle = null;
		Fillers fillers = null;
		if (routine && planPool != null && takesMilestones(planMaster))
		{
			final SlayerMaster list = SlayerMaster.TURAEL;
			final BlockList fillerBlocks = blockList(account, data, list, questPoints, diaryDone);
			final SlayerPool fillerPool = SlayerPool.of(SlayerAssigner.TURAEL, data, player, fillerBlocks.rows, ratings);
			final SlayerBlockAdvisor.Advice fillerAdvice = SlayerBlockAdvisor.advise(list, fillerPool, goal,
					openSlots(list, questPoints, diaryDone), fillerBlocks.inOrder);
			final String fillerNpc = npc(masters, SlayerAssigner.TURAEL);
			final double milestonePoints = SlayerPayout.basePoints(planMaster, diaries)
					* SlayerPayout.averageMultiplier(settings.getBoost().getEvery());
			cycle = new SlayerSpend.Routine(settings.getBoost().getEvery() - 1, Math.max(1, milestonePoints), fillerNpc, fillerPool,
					fillerBlocks.emptySlots, fillerAdvice);
			fillers = new Fillers(fillerNpc, fillerBlocks.names, fillerBlocks.emptySlots, lockedSlots(list, questPoints, diaryDone),
					blockedWeightPercent(fillerPool), fillerAdvice);
		}

		final SlayerSpend.Context context = new SlayerSpend.Context(goal, planMaster, npc(masters, planMaster), planPool, data, player,
				Collections.unmodifiableSet(blocks.rows), blocks.emptySlots, blockAdvice, owned, dossier, items, cycle,
				skipBudget(goal, planMaster, diaries, mortimerTasks));
		final List<Candidate> candidates = SlayerSpend.candidates(context, r -> rewardName(data, r), r -> rewardCost(data, r),
				i -> itemCost(data, i));
		final Reserve reserve = reserve(goal, planMaster, planPool, diaries, mortimerTasks, settings.getReserve());
		// Save-for lines say roughly how many tasks the missing points take: with the routine for the
		// points goal, otherwise every task at the plan's master
		final IntUnaryOperator tasksFor = routine
				? need -> SlayerPointsForecast.withRoutine(need, streaks, masters, diaries, settings.getBoost())
				: need -> SlayerPointsForecast.atMaster(need, planMaster, streaks, diaries);
		final Plan plan = SlayerPointsPlanner.plan(candidates, points, reserve, tasksFor, goal);

		final SlayerUnlockAdvisor.Situation task = situation(account, data, goal, player, ratings, dossier, owned, masters, diaries,
				questPoints, diaryDone, mortimerTasks, points, cycle, planPool, ranking.isEmpty() ? null : ranking.get(0).getNpc());
		final int taskRow = data == null || !streaks.isTaskInProgress() ? -1 : data.taskRowForId(account.varp(VarPlayerID.SLAYER_TARGET));
		final List<String> notes = new ArrayList<>();
		final List<String> noteItems = new ArrayList<>();
		notes(account, data, owned, planPool, goal, notes, noteItems);

		return new View(plan, master, blocks.names, blocks.emptySlots, lockedSlots(master, questPoints, diaryDone),
				blockedWeightPercent,
				planPool,
				blockAdvice,
				notes,
				noteItems,
				data != null,
				goal,
				masters,
				routine ? SlayerPointsRoutine.advise(streaks, masters, diaries, settings.getBoost()) : null,
				ranking,
				later,
				goalMaster,
				task,
				SlayerTaskText.assignedBy(data, taskRow, a -> npc(masters, a)),
				fillers);
	}

	/**
	 * Whether a plan master takes the routine's milestone tasks while Turael's spot takes the rest: a master on the
	 * main streak with a list of its own. Turael, Aya and Spria share Turael's list.
	 */
	static boolean takesMilestones(SlayerAssigner master)
	{
		return master.getStreak() == SlayerAssigner.Streak.MAIN && SlayerMaster.forAssigner(master) != SlayerMaster.TURAEL;
	}

	/** Share of the weight of the tasks the player can get that blocks remove, in percent, or -1 when there is none. */
	private static int blockedWeightPercent(SlayerPool pool)
	{
		final int assignable = pool.assignableWeight();
		return assignable > 0 ? Math.round(pool.blockedWeight() * 100f / assignable) : -1;
	}

	/**
	 * Points kept for skips at the plan's master. The master ranking assumes the worst offers are skipped with
	 * the master's own points ({@link SlayerMasterRanker#skipBudget}). The skip model says which and how often, and
	 * the plan keeps enough for the skips that come in a row nine times in ten, never less than {@code floor}.
	 * The Slayer points routine never skips (see {@link SlayerUnlockAdvisor}), and Mortimer offers a choice instead.
	 */
	static Reserve reserve(SlayerGoal goal, SlayerAssigner master, SlayerPool pool, SlayerPayout.Diaries diaries, int mortimerTasks,
			int floor)
	{
		final int cancel = master.getCancelCost();
		final double budget = skipBudget(goal, master, diaries, mortimerTasks);
		if (pool == null || budget <= 0)
		{
			return new Reserve(floor, 0, cancel, 0, Collections.<String>emptyList(), floor);
		}
		final SlayerGoalModel.Skips skips = SlayerGoalModel.skips(SlayerGoalModel.offers(pool), goal,
				SlayerMasterRanker.bonus(master, goal), budget);
		final int run = skipsInARow(skips.getShare());
		final List<String> worst = new ArrayList<>();
		for (SlayerPool.Entry e : skips.getTasks())
		{
			if (worst.size() < 2) worst.add(e.getName());
		}
		return new Reserve(Math.max(floor, run * cancel), run, cancel, skips.getShare(), Collections.unmodifiableList(worst), floor);
	}

	/**
	 * The most of a master's offers the skip model skips for the goal, as a share: the master ranking's budget, or 0
	 * when the goal skips nothing. The Slayer points routine never skips, and Mortimer offers a choice instead.
	 */
	static double skipBudget(SlayerGoal goal, SlayerAssigner master, SlayerPayout.Diaries diaries, int mortimerTasks)
	{
		if (goal == SlayerGoal.POINTS || SlayerMasterRanker.choices(master, mortimerTasks) > 1) return 0;
		return SlayerMasterRanker.skipBudget(master, diaries);
	}

	/** Skips in a row that cover nine runs in ten: the fewest k with {@code share} to the power k at most one in ten. */
	static int skipsInARow(double share)
	{
		if (share <= 0) return 0;
		int k = 1;
		double chance = share;
		while (chance > 0.1 && k < MAX_SKIPS_IN_A_ROW)
		{
			chance *= share;
			k++;
		}
		return k;
	}

	/**
	 * The task in progress at the master who gave it, or null without a task or without the cache tables.
	 *
	 * @param cycle the routine's filler side, null off the routine
	 * @param milestone the plan master's list, which takes the routine's milestone tasks
	 * @param bestMaster the NPC at the best master for XP or profit, or null
	 */
	static SlayerUnlockAdvisor.Situation situation(Account account, SlayerGameData data, SlayerGoal goal, SlayerPool.Player player,
			Function<String, TaskRating> ratings, Function<String, SlayerTask> dossier, Set<Integer> owned,
			List<SlayerMasterAccess.Option> masters, SlayerPayout.Diaries diaries, int questPoints, boolean diaryDone, int mortimerTasks,
			int points, SlayerSpend.Routine cycle, SlayerPool milestone, String bestMaster)
	{
		final SlayerPointsRoutine.Streaks streaks = streaks(account);
		final SlayerAssigner master = streaks.currentMaster();
		if (master == null) return null;
		final int number = master.getStreak() == SlayerAssigner.Streak.MAIN ? streaks.getMain() + 1
				: master.getStreak() == SlayerAssigner.Streak.WILDERNESS ? streaks.getWilderness() + 1 : 0;
		final String npc = npc(masters, master);
		final int payout = SlayerPointsRoutine.currentPayout(streaks, diaries);
		if (data == null)
		{
			return new SlayerUnlockAdvisor.Situation(goal, null, master, npc, points, false, false, false, null, null, number, payout, false, 0,
					bestMaster);
		}
		final int row = data.taskRowForId(account.varp(VarPlayerID.SLAYER_TARGET));
		final SlayerMaster list = SlayerMaster.forAssigner(master);
		final BlockList blocks = list == null ? new BlockList() : blockList(account, data, list, questPoints, diaryDone);
		final SlayerPool pool = SlayerPool.of(master, data, player, blocks.rows, ratings);
		final SlayerPool.Entry entry = row < 0 ? null : pool.find(row);

		final SlayerBlockAdvisor.Advice advice = list == null ? null
				: SlayerBlockAdvisor.advise(list, pool, goal, openSlots(list, questPoints, diaryDone), blocks.inOrder);
		boolean worthBlocking = advice != null && advice.getAddRows().contains(row);
		if (worthBlocking && goal == SlayerGoal.POINTS && list == SlayerMaster.TURAEL)
		{
			// A filler task's block pays only when it raises the routine's rate enough to notice
			worthBlocking = SlayerSpend.fillerBlockGain(cycle, milestone, advice.getKeepRows(), row) > SlayerPointsPlanner.NOTICEABLE;
		}
		final String unblock = advice == null || advice.getMisfits().isEmpty() ? null : advice.getMisfits().get(0).getName();
		boolean worthSkipping = false;
		final double skipBudget = skipBudget(goal, master, diaries, mortimerTasks);
		if (entry != null && skipBudget > 0)
		{
			final SlayerGoalModel.Skips skips = SlayerGoalModel.skips(SlayerGoalModel.offers(pool), goal,
					SlayerMasterRanker.bonus(master, goal), skipBudget);
			for (SlayerPool.Entry e : skips.getTasks())
			{
				worthSkipping |= e.getTaskRow() == row;
			}
			// The wiki's Slayer guide says to skip it, or not to have it at all, for XP
			final TaskRating.XpAdvice wiki = entry.wikiAdvice(goal);
			worthSkipping |= wiki == TaskRating.XpAdvice.SKIP || wiki == TaskRating.XpAdvice.DONT_UNLOCK;
		}

		SlayerUnlockAdvisor.Extension extension = null;
		final SlayerGameData.Extension x = row < 0 ? null : data.extensionOf(row);
		final SlayerGameData.Unlock unlock = x == null ? null : data.unlock(x.getUnlockRow());
		if (unlock != null && unlock.isListed())
		{
			extension = new SlayerUnlockAdvisor.Extension(unlock.getName(), unlock.getCost(), owned.contains(unlock.getRow()),
					SlayerSpend.extensionGain(pool, data, row, goal, skipBudget));
		}
		final SlayerTask dossierTask = entry == null ? null : dossier.apply(entry.getName());
		final SlayerGameData.Unlock superiors = data.unlock(SlayerReward.BIGGER_AND_BADDER.getRow());
		final boolean superiorMissing = dossierTask != null && dossierTask.isHasSuperior()
				&& !owned.contains(SlayerReward.BIGGER_AND_BADDER.getRow());
		final int superiorCost = superiors == null || superiors.getCost() < 0 ? SlayerReward.BIGGER_AND_BADDER.getFallbackCost() : superiors.getCost();
		return new SlayerUnlockAdvisor.Situation(goal, entry, master, npc, points, worthSkipping, worthBlocking, blocks.emptySlots > 0,
				unblock, extension, number, payout, superiorMissing, superiorCost, bestMaster);
	}

	/**
	 * The master a goal points to: the best ranked master with a block list for XP and profit, the master who
	 * pays most for milestone tasks for Slayer points (the one the routine sends milestones to). Null when
	 * nothing is known, so the plan keeps the configured master.
	 */
	static SlayerMaster goalMaster(SlayerGoal goal, List<SlayerMasterRanker.Ranked> ranking, List<SlayerMasterAccess.Option> masters,
			SlayerPayout.Diaries diaries, BoostInterval boost)
	{
		if (goal == SlayerGoal.POINTS)
		{
			// Every milestone multiplies all masters' points alike, so any milestone gives the same order
			final List<SlayerPointsRoutine.Ranked> payers = SlayerPointsRoutine.rank(boost.getEvery(), masters, diaries);
			return payers.isEmpty() ? null : SlayerMaster.forAssigner(payers.get(0).getMaster());
		}
		for (SlayerMasterRanker.Ranked r : ranking)
		{
			final SlayerMaster m = SlayerMaster.forAssigner(r.getMaster());
			if (m != null) return m;
		}
		return null;
	}

	/** The streak counters and whether a task is in progress. */
	static SlayerPointsRoutine.Streaks streaks(Account account)
	{
		return new SlayerPointsRoutine.Streaks(account.varbit(VarbitID.SLAYER_TASKS_COMPLETED),
				account.varbit(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED), account.varbit(VarbitID.SLAYER_MASTER),
				account.varp(VarPlayerID.SLAYER_COUNT) > 0);
	}

	/** What the master pools depend on. Without master state the combat level is not known, so it is not checked. */
	static SlayerPool.Player player(Account account, SlayerGameData data, Set<Integer> owned, SlayerMasterAccess.State access)
	{
		final int[] levels = account.levels();
		// Tasks a bought blocker keeps out of every pool. Stop the Wyvern works until it is toggled off.
		final Set<Integer> removed = new HashSet<>();
		final SlayerGameData.Unlock wyvernBlock = data == null ? null : data.unlock(SlayerReward.STOP_THE_WYVERN.getRow());
		if (wyvernBlock != null && owned.contains(wyvernBlock.getRow())
				&& account.varbit(VarbitID.SLAYER_TOGGLEOFF_FOSSILWYVERNBLOCK) == 0)
		{
			removed.addAll(wyvernBlock.getRelatedTaskRows());
		}
		return new SlayerPool.Player(levels, access == null ? Integer.MAX_VALUE : access.getCombatLevel(),
				account.varbit(VarbitID.COMBAT_LEVEL_REQS_DISABLED) != 0,
				Collections.unmodifiableSet(owned), Collections.unmodifiableSet(removed));
	}

	/** A task's ratings by its cache name, through the dossier's lookup. */
	static Function<String, TaskRating> ratings(SlayerDataset dataset)
	{
		return name ->
		{
			final SlayerTask task = dataset == null ? null : dataset.lookup(name);
			return task == null ? null : task.getRating();
		};
	}

	/** A task's dossier entry by its cache name, or null. */
	static Function<String, SlayerTask> dossier(SlayerDataset dataset)
	{
		return name -> dataset == null ? null : dataset.lookup(name);
	}

	/** The NPC at a master's spot, or the master's own name without master state. */
	private static String npc(List<SlayerMasterAccess.Option> masters, SlayerAssigner master)
	{
		final SlayerMasterAccess.Option option = SlayerMasterAccess.find(masters, master);
		return option == null ? master.getDisplayName() : option.getNpc();
	}

	/** A master's block list: rows, names and the open slots with nothing in them. */
	private static BlockList blockList(Account account, SlayerGameData data, SlayerMaster master, int questPoints, boolean diaryDone)
	{
		final BlockList list = new BlockList();
		final int[] slots = master.getBlockVarbits();
		for (int i = 0; i < slots.length; i++)
		{
			final int taskId = account.varbit(slots[i]);
			if (taskId <= 0)
			{
				if (blockSlotOpen(master, i, questPoints, diaryDone)) list.emptySlots++;
				continue;
			}
			final int row = data == null ? -1 : data.taskRowForId(taskId);
			final String name = row < 0 ? null : data.taskName(row);
			if (row >= 0 && list.rows.add(row)) list.inOrder.add(row);
			list.names.add(name == null ? "Task #" + taskId : name);
		}
		return list;
	}

	/** The cache's name, the fallback without one, or null for a reward taken out of the shop. */
	private static String rewardName(SlayerGameData data, SlayerReward r)
	{
		final SlayerGameData.Unlock unlock = data == null ? null : data.unlock(r.getRow());
		// A reward taken out of the shop keeps its cache row but can no longer be bought
		if (unlock != null && !unlock.isListed()) return null;
		return unlock != null && unlock.getName() != null ? unlock.getName() : r.getFallbackName();
	}

	/** The cache's cost, or null to use the fallback. */
	private static Integer rewardCost(SlayerGameData data, SlayerReward r)
	{
		final SlayerGameData.Unlock unlock = data == null ? null : data.unlock(r.getRow());
		return unlock != null && unlock.getCost() >= 0 ? unlock.getCost() : null;
	}

	/** The Buy tab's cost, null to use the fallback, or -1 when the tab no longer sells the item. */
	private static Integer itemCost(SlayerGameData data, SlayerShopItem item)
	{
		if (data == null || data.shopItems().isEmpty()) return null;
		final Integer cost = data.shopItems().get(item.getItemId());
		return cost == null ? -1 : cost;
	}

	/**
	 * Rows of every owned reward. With the cache this reads each row's bit, which also covers rewards
	 * this plugin does not know yet. Without it, the advice layer's varbits.
	 */
	private static Set<Integer> ownedRewards(Account account, SlayerGameData data)
	{
		final Set<Integer> owned = new HashSet<>();
		if (data != null)
		{
			for (SlayerGameData.Unlock u : data.unlocks())
			{
				if (SlayerGameData.ownsBit(account::varp, u.getBit())) owned.add(u.getRow());
			}
		}
		for (SlayerReward r : SlayerReward.values())
		{
			final SlayerGameData.Unlock u = data == null ? null : data.unlock(r.getRow());
			if ((u == null || u.getBit() < 0) && account.varbit(r.getFallbackVarbit()) != 0) owned.add(r.getRow());
		}
		return owned;
	}

	static String lockedBy(SlayerReward r, int slayer, int crafting, int fletching)
	{
		if (slayer < r.getSlayerLevel()) return r.getSlayerLevel() + " Slayer";
		if (crafting < r.getCraftingLevel()) return r.getCraftingLevel() + " Crafting";
		if (fletching < r.getFletchingLevel()) return r.getFletchingLevel() + " Fletching";
		return null;
	}

	/** {@link #lockedBy(SlayerReward, int, int, int)} with the player's levels. */
	static String lockedBy(SlayerReward r, SlayerPool.Player player)
	{
		return lockedBy(r, player.level(Skill.SLAYER.ordinal()), player.level(Skill.CRAFTING.ordinal()),
				player.level(Skill.FLETCHING.ordinal()));
	}

	/**
	 * Whether block slot {@code slot} (0-based) of a seven slot list can be used. Every slot but the last
	 * needs 50 more quest points than the one before, the last needs the elite Lumbridge & Draynor diary.
	 * Matches the game's block list script (9738).
	 */
	static boolean blockSlotOpen(int slot, int slots, int questPoints, boolean diaryDone)
	{
		if (slot == slots - 1) return diaryDone;
		return questPoints >= (slot + 1) * SlayerMaster.QUEST_POINTS_PER_BLOCK_SLOT;
	}

	/** {@link #blockSlotOpen(int, int, int, boolean)} for a master's list. Mortimer's two slots both take quest points. */
	static boolean blockSlotOpen(SlayerMaster master, int slot, int questPoints, boolean diaryDone)
	{
		if (master.isDiarySlot()) return blockSlotOpen(slot, master.getBlockVarbits().length, questPoints, diaryDone);
		return questPoints >= (slot + 1) * SlayerMaster.QUEST_POINTS_PER_BLOCK_SLOT;
	}

	/** Block slots the player can use at a master, used or not. 0 for an unknown master. */
	static int openSlots(SlayerMaster master, int questPoints, boolean diaryDone)
	{
		if (master == null) return 0;
		int open = 0;
		for (int i = 0; i < master.getBlockVarbits().length; i++)
		{
			if (blockSlotOpen(master, i, questPoints, diaryDone)) open++;
		}
		return open;
	}

	/** How the locked block slots of a master's list open, or null when every slot is open. */
	static String lockedSlots(SlayerMaster master, int questPoints, boolean diaryDone)
	{
		final int slots = master.getBlockVarbits().length;
		return lockedSlots(master.isDiarySlot() ? slots - 1 : slots, master.isDiarySlot(), questPoints, diaryDone);
	}

	private static String lockedSlots(int questSlots, boolean diarySlot, int questPoints, boolean diaryDone)
	{
		int locked = 0;
		int next = 0;
		for (int i = 0; i < questSlots; i++)
		{
			if (questPoints >= (i + 1) * SlayerMaster.QUEST_POINTS_PER_BLOCK_SLOT) continue;
			if (locked++ == 0) next = (i + 1) * SlayerMaster.QUEST_POINTS_PER_BLOCK_SLOT;
		}
		final List<String> parts = new ArrayList<>();
		if (locked > 0)
		{
			parts.add((locked == 1 ? "1 more slot needs" : locked + " more slots need") + " quest points. The next opens at " + next + " QP");
		}
		if (diarySlot && !diaryDone)
		{
			parts.add("1 slot needs the elite Lumbridge & Draynor diary");
		}
		return parts.isEmpty() ? null : String.join(". ", parts);
	}

	/** The plan's notes, each with a few words for the compact sidebar in {@code items}. */
	private static void notes(Account account, SlayerGameData data, Set<Integer> owned, SlayerPool pool, SlayerGoal goal, List<String> notes,
			List<String> items)
	{
		if (owned.contains(SlayerReward.BIGGER_AND_BADDER.getRow()) && account.varbit(VarbitID.SLAYER_TOGGLEOFF_SUPERIORMOBS) != 0
				&& goal != SlayerGoal.POINTS)
		{
			notes.add("Bigger and Badder is bought but toggled off. Turn it back on at a slayer master.");
			items.add("Bigger and Badder is off");
		}
		if (owned.contains(SlayerReward.STOP_THE_WYVERN.getRow()) && account.varbit(VarbitID.SLAYER_TOGGLEOFF_FOSSILWYVERNBLOCK) != 0)
		{
			notes.add("Stop the Wyvern is bought but toggled off, so fossil wyverns can still be assigned.");
			items.add("Stop the Wyvern is off");
		}
		// A task unlock that hurts the goal is better turned off than blocked: "For toggled tasks like lizardmen, the
		// player should simply cancel the toggle" (wiki Slayer training). Boss tasks cannot be blocked at all.
		if (pool == null || data == null) return;
		for (SlayerReward r : SlayerReward.values())
		{
			if (r.getKind() != SlayerReward.Kind.TASK_UNLOCK || !owned.contains(r.getRow())) continue;
			final Set<Integer> rows = new HashSet<>();
			for (SlayerGameData.PoolEntry e : data.pool(pool.getMaster().getId()))
			{
				if (e.getUnlockRow() == r.getRow()) rows.add(e.getTaskRow());
			}
			final SlayerPool without = pool.map(e -> rows.contains(e.getTaskRow()) && e.isOpen() ? e.withStatus(SlayerPool.Status.NEEDS_UNLOCK) : e);
			if (rows.isEmpty() || SlayerSpend.change(pool, without, goal) <= SlayerPointsPlanner.NOTICEABLE) continue;
			final SlayerGameData.Unlock unlock = data.unlock(r.getRow());
			final String name = unlock == null || unlock.getName() == null ? r.getFallbackName() : unlock.getName();
			final int cost = unlock == null || unlock.getCost() < 0 ? r.getFallbackCost() : unlock.getCost();
			notes.add(name + " is on, but the tasks it adds lower your " + goalWord(goal) + " rate here."
					+ (r == SlayerReward.LIKE_A_BOSS ? " Boss tasks cannot be blocked." : "")
					+ " Turning it off at a master stops them" + (cost > 0 ? ", but turning it back on costs " + cost + " points again." : "."));
			items.add("Turn off " + name);
		}
	}

	private static String goalWord(SlayerGoal goal)
	{
		switch (goal)
		{
			case XP:
				return "XP";
			case PROFIT:
				return "profit";
			default:
				return "Slayer points";
		}
	}
}

package com.slayercompanion;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import lombok.Value;

/**
 * The goal advice as short sidebar sentences, and as items for the compact sidebar. Pure, so the wording is tested
 * without Swing.
 */
final class SlayerPlanText
{
	/** The heading over {@link #fillerBlockAdvice}. */
	static final String FILLER_BLOCK_HEADING = "Blocks for filler tasks";

	private SlayerPlanText()
	{
	}

	/** "Best master for XP" or "Best master for profit". Null for the Slayer points goal, which has its routine. */
	static String masterHeading(SlayerGoal goal)
	{
		switch (goal)
		{
			case XP:
				return "Best master for XP";
			case PROFIT:
				return "Best master for profit";
			default:
				return null;
		}
	}

	/**
	 * The best master by the NPC the player will find, one reason and the runner-up, e.g. "Kuradal. About 2 in
	 * 5 tasks are good XP tasks once you block the worst. Next best: Steve." Null without a ranking.
	 */
	static String masterAdvice(SlayerPlanBuilder.View view)
	{
		final List<SlayerMasterRanker.Ranked> ranking = view.getRanking();
		if (ranking.isEmpty()) return null;
		final SlayerMasterRanker.Ranked best = ranking.get(0);
		final StringBuilder sb = new StringBuilder(best.getNpc()).append(". ").append(best.getReason());
		if (ranking.size() > 1) sb.append(" Next best: ").append(ranking.get(1).getNpc()).append('.');
		final SlayerMasterRanker.Ranked later = view.getLater();
		if (later != null) sb.append(" Later: ").append(later.getNpc()).append(", who needs ").append(later.getMissing()).append('.');
		if (!view.isFollowingGoal())
		{
			sb.append(" The plan below uses ").append(view.getMasterName()).append(" because Pin planner master is on.");
		}
		return sb.toString();
	}

	/** {@link #blockAdvice(SlayerBlockAdvisor.Advice, String, String)} for the plan, with where milestone tasks go. */
	static String blockAdvice(SlayerPlanBuilder.View view)
	{
		String note = null;
		if (view.getGoal() == SlayerGoal.POINTS && view.getGoalMaster() != null)
		{
			note = view.isFollowingGoal()
					? "Milestone tasks go to " + view.getMasterName() + ", so block the slow ones there."
					: "Milestone tasks go to " + view.getGoalMasterName() + ". Pin planner master keeps this list on "
							+ view.getMasterName() + ".";
		}
		return blockAdvice(view.getBlockAdvice(), view.getMasterName(), note);
	}

	/**
	 * The filler tasks' block advice on the Slayer points routine, e.g. "Filler tasks go to Aya, so block the longest
	 * ones there.\nBlock next: Cave Bugs. 40 points each at Aya." Null off the routine.
	 */
	static String fillerBlockAdvice(SlayerPlanBuilder.View view)
	{
		final SlayerPlanBuilder.Fillers fillers = view.getFillers();
		if (fillers == null) return null;
		final SlayerMasterAccess.Option spria = SlayerMasterAccess.find(view.getMasters(), SlayerAssigner.SPRIA);
		final String shared = spria != null && spria.isUsable() ? " " + spria.getNpc() + " shares this list." : "";
		return blockAdvice(fillers.getBlockAdvice(), fillers.getNpc(),
				"Filler tasks go to " + fillers.getNpc() + ", so block the longest ones there." + shared);
	}

	/** "Blocks for XP", "Blocks for profit" or "Blocks for Slayer points". */
	static String blockHeading(SlayerGoal goal)
	{
		return "Blocks for " + goalWord(goal);
	}

	/** {@link #blockHeading(SlayerGoal)}, or "Blocks for milestone tasks" when the routine's filler tasks have their own. */
	static String blockHeading(SlayerPlanBuilder.View view)
	{
		return view.getFillers() != null ? "Blocks for milestone tasks" : blockHeading(view.getGoal());
	}

	/** "Skip these for XP": the purchases that would lower the goal's rate. */
	static String skipHeading(SlayerGoal goal)
	{
		return "Skip these for " + goalWord(goal);
	}

	/**
	 * The points line: the points, what the reserve is for and what is left to spend, e.g. "521 points. 90 are kept
	 * to skip up to 3 bad tasks in a row at Kuradal. About 2 in 5 of Kuradal's tasks are worth skipping for XP,
	 * such as Spiritual Creatures and Waterfiends. 431 to spend."
	 */
	static String points(SlayerPointsPlanner.Plan plan, SlayerAssigner master, String npc, SlayerGoal goal)
	{
		final SlayerPointsPlanner.Reserve reserve = plan.getReserve();
		final int spendable = Math.max(0, plan.getPoints() - reserve.getPoints());
		final StringBuilder sb = new StringBuilder().append(plan.getPoints()).append(" points. ");
		if (reserve.getPoints() > 0 && reserve.isFloor())
		{
			sb.append(reserve.getPoints()).append(" are kept for skips, as Points to keep for skips says. ");
		}
		else if (reserve.getSkips() > 0)
		{
			sb.append(reserve.getPoints()).append(" are kept to skip ")
					.append(reserve.getSkips() == 1 ? "a bad task" : "up to " + reserve.getSkips() + " bad tasks in a row")
					.append(" at ").append(npc).append(". ").append(SlayerMasterRanker.share(reserve.getShare())).append(" of ")
					.append(SlayerSpend.possessive(npc)).append(" tasks are worth skipping for ").append(goalWord(goal));
			if (!reserve.getTasks().isEmpty()) sb.append(", such as ").append(SlayerSpend.join(reserve.getTasks()));
			sb.append(". ");
		}
		else if (goal == SlayerGoal.POINTS)
		{
			sb.append("None are kept for skips, since the routine does every task. ");
		}
		else if (master == SlayerAssigner.MORTIMER)
		{
			sb.append("None are kept for skips, since you choose from ").append(SlayerSpend.possessive(npc)).append(" tasks instead. ");
		}
		else if (SlayerPayout.basePoints(master, SlayerPayout.Diaries.NONE) == 0)
		{
			sb.append("None are kept for skips, since ").append(npc).append(" pays no points. ");
		}
		else
		{
			sb.append("None are kept for skips, since no task at ").append(npc).append(" is worth one. ");
		}
		return sb.append(spendable).append(" to spend.").toString();
	}

	/**
	 * Which tasks to block next with the cost, which blocks to keep and which do not fit the goal. Null without
	 * advice.
	 *
	 * @param note a first line, or null
	 */
	static String blockAdvice(SlayerBlockAdvisor.Advice advice, String npc, String note)
	{
		if (advice == null) return null;
		final List<String> lines = new ArrayList<>();
		if (note != null) lines.add(note);
		if (advice.getSlots() == 0)
		{
			lines.add("Block slots open at " + SlayerMaster.QUEST_POINTS_PER_BLOCK_SLOT + " quest points.");
			return String.join("\n", lines);
		}
		if (!advice.getAdd().isEmpty())
		{
			lines.add("Block next: " + String.join(", ", advice.getAdd()) + ". " + advice.getCost() + " points each at " + npc + ".");
		}
		else if (advice.getKeep().size() >= advice.getSlots())
		{
			lines.add("Every open slot holds a useful block.");
		}
		else
		{
			lines.add("No other task is worth a block for " + goalWord(advice.getGoal()) + ".");
		}
		if (!advice.getKeep().isEmpty())
		{
			lines.add("Already blocked and right: " + String.join(", ", advice.getKeep()) + ".");
		}
		if (!advice.getMisfits().isEmpty())
		{
			final List<String> misfits = new ArrayList<>();
			for (SlayerBlockAdvisor.Misfit m : advice.getMisfits())
			{
				misfits.add(m.getName() + " (" + m.getWhy() + ")");
			}
			lines.add("Not right for " + goalWord(advice.getGoal()) + ": " + String.join(", ", misfits)
					+ ". Unblock " + (misfits.size() == 1 ? "it" : "them") + " to free the slot.");
		}
		return String.join("\n", lines);
	}

	// ---- the compact sidebar ----

	/** The compact plan's heading over {@link #masterItems}. */
	static final String BEST_MASTER_HEADING = "BEST MASTER";

	/** "521, 401 to spend": the points and what is left above the reserve. */
	static String pointsItem(SlayerPointsPlanner.Plan plan)
	{
		final int spendable = Math.max(0, plan.getPoints() - plan.getReserve().getPoints());
		final String spend = spendable == 0 ? "none" : spendable == plan.getPoints() ? "all" : String.valueOf(spendable);
		return plan.getPoints() + ", " + spend + " to spend";
	}

	/**
	 * The best masters for XP or profit as compact items: the best, "then" the runner-up, a better one for later and
	 * the master a pinned plan uses. Empty without a ranking. {@link #masterAdvice} says why.
	 */
	static List<String> masterItems(SlayerPlanBuilder.View view)
	{
		final List<SlayerMasterRanker.Ranked> ranking = view.getRanking();
		if (ranking.isEmpty()) return Collections.emptyList();
		final List<String> items = new ArrayList<>();
		items.add(ranking.get(0).getNpc());
		if (ranking.size() > 1) items.add("then " + ranking.get(1).getNpc());
		final SlayerMasterRanker.Ranked later = view.getLater();
		if (later != null) items.add("Later: " + later.getNpc() + " (" + later.getMissing() + ")");
		if (!view.isFollowingGoal()) items.add("Plan uses " + view.getMasterName() + " (pinned)");
		return items;
	}

	/** "KONAR BLOCKLIST" */
	static String blockListHeading(String npc)
	{
		return npc.toUpperCase(Locale.ROOT) + " BLOCKLIST";
	}

	/** One item of a master's compact block list, with the reason or the cost in its tooltip. */
	@Value
	static class BlockItem
	{
		/** What an item is, which its colour shows. */
		enum Kind
		{
			/** A current block that fits the goal, marked "(set)". */
			SET,
			/** A block the advice would add. */
			ADD,
			/** A current block that does not fit the goal, marked "(unblock)". */
			UNBLOCK,
			/** "(none)", or when the first slot opens. */
			NOTE
		}

		String text;
		Kind kind;
		String tooltip;
	}

	/**
	 * A master's block list as one list of compact items: the current blocks that fit the goal marked "(set)", the blocks
	 * the advice would add next in its order, then the current blocks that do not fit marked "(unblock)". "(none)" when
	 * there is nothing to list, and while no slot is open, when the first one opens. Without advice the current blocks
	 * are listed as they are.
	 */
	static List<BlockItem> blockListItems(String npc, List<String> blocked, SlayerBlockAdvisor.Advice advice)
	{
		final List<BlockItem> items = new ArrayList<>();
		if (advice == null)
		{
			for (String task : blocked)
			{
				items.add(new BlockItem(task + " (set)", BlockItem.Kind.SET, null));
			}
		}
		else
		{
			for (String task : advice.getKeep())
			{
				items.add(new BlockItem(task + " (set)", BlockItem.Kind.SET, "Already blocked and right for " + goalWord(advice.getGoal()) + "."));
			}
			for (String task : advice.getAdd())
			{
				items.add(new BlockItem(task, BlockItem.Kind.ADD, "Block it next for " + advice.getCost() + " points at " + npc + "."));
			}
			for (SlayerBlockAdvisor.Misfit misfit : advice.getMisfits())
			{
				items.add(new BlockItem(misfit.getName() + " (unblock)", BlockItem.Kind.UNBLOCK, capitalize(misfit.getWhy())
						+ ". Unblock it to free the slot."));
			}
		}
		if (items.isEmpty()) items.add(new BlockItem("(none)", BlockItem.Kind.NOTE, null));
		if (advice != null && advice.getSlots() == 0)
		{
			items.add(new BlockItem("Slots open at " + SlayerMaster.QUEST_POINTS_PER_BLOCK_SLOT + " QP", BlockItem.Kind.NOTE,
					"Block slots open at " + SlayerMaster.QUEST_POINTS_PER_BLOCK_SLOT + " quest points."));
		}
		return items;
	}

	private static String capitalize(String text)
	{
		return text.isEmpty() ? text : Character.toUpperCase(text.charAt(0)) + text.substring(1);
	}

	private static String goalWord(SlayerGoal goal)
	{
		switch (goal)
		{
			case XP:
				return "XP";
			case PROFIT:
				return "profit";
			default:
				return "Slayer points";
		}
	}
}

package com.slayercompanion;

import java.util.List;
import java.util.function.IntUnaryOperator;

/**
 * Roughly how many tasks it takes to earn a number of Slayer points, by walking the upcoming task numbers
 * so milestones and the unpaid start of a streak are counted. Pure.
 */
final class SlayerPointsForecast
{
	/** The walk stops here. A goal further away than this counts as out of reach. */
	static final int MAX_TASKS = 2000;

	private SlayerPointsForecast()
	{
	}

	/**
	 * Tasks until {@code needed} points are earned: the task in progress first when there is one, then task
	 * {@code nextTask}, {@code nextTask + 1} and so on. 0 when nothing is needed, -1 when the payouts never
	 * get there.
	 *
	 * @param current points the task in progress pays, or -1 without one
	 * @param payoutAt points a task pays, by its number in the streak
	 */
	static int tasksToEarn(int needed, int current, int nextTask, IntUnaryOperator payoutAt)
	{
		if (needed <= 0) return 0;
		int earned = Math.max(0, current);
		int tasks = current >= 0 ? 1 : 0;
		for (int task = nextTask; earned < needed; task++)
		{
			if (tasks >= MAX_TASKS) return -1;
			earned += payoutAt.applyAsInt(task);
			tasks++;
		}
		return tasks;
	}

	/** Tasks to earn {@code needed} points with the Slayer points routine. */
	static int withRoutine(int needed, SlayerPointsRoutine.Streaks streaks, List<SlayerMasterAccess.Option> options,
			SlayerPayout.Diaries diaries, BoostInterval boost)
	{
		return tasksToEarn(needed, SlayerPointsRoutine.currentPayout(streaks, diaries), SlayerPointsRoutine.nextTask(streaks),
				task -> SlayerPointsRoutine.routinePayout(task, boost, options, diaries));
	}

	/** Tasks to earn {@code needed} points doing every task at one master, milestones included. */
	static int atMaster(int needed, SlayerAssigner master, SlayerPointsRoutine.Streaks streaks, SlayerPayout.Diaries diaries)
	{
		return tasksToEarn(needed, SlayerPointsRoutine.currentPayout(streaks, diaries), SlayerPointsRoutine.nextTask(streaks, master),
				task -> SlayerPayout.payout(master, task, diaries));
	}
}

package com.slayercompanion;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import lombok.AllArgsConstructor;
import lombok.Value;

/**
 * Turns valued purchases ({@link SlayerSpend}) into an ordered spend plan. Pure: no client access.
 * <p>
 * Purchases are ranked by what they do for the goal per point: the share by which they raise the goal's rate
 * at the plan's master, divided by their cost. On the Slayer points routine that rate covers the filler master
 * too, so blocks at both masters share the one list. Points above the reserve go down that list. Whatever does not fit
 * is saved for, the ones waiting for a level are listed apart, and the ones that lower the rate are named so they
 * are not bought by mistake.
 * <p>
 * For XP the wiki gives "generally an optimal order" (Slayer training, Using Slayer reward points): blocks, the
 * Fossil Island Wyvern block among them, then superior monsters, the Slayer helmet, extensions and extra unlocks such
 * as Slayer rings. The XP plan follows that order in tiers ({@link #xpTier}), ranks by the goal model within each, and saves
 * for the next purchase rather than buying past it, so the save-for list carries on in the same order.
 */
final class SlayerPointsPlanner
{
	static final int MAX_SAVE_FOR = 5;
	static final int MAX_LATER = 5;
	static final int MAX_AVOID = 5;
	/** A change in the goal's rate smaller than this share neither helps nor hurts enough to list. */
	static final double NOTICEABLE = 0.002;
	/** The longest compact label. The compact sidebar fits about this many characters on a line. */
	static final int MAX_LABEL = 34;

	enum Type
	{
		/** A reward from the shop's Unlock, Extend or Cosmetics tab. */
		REWARD,
		/** A block at the plan's master, or at the filler master on the Slayer points routine. */
		BLOCK,
		/** An item from the shop's Buy tab. */
		ITEM,
		/** One line that stands for several rewards. Not counted in the shop totals. */
		SUMMARY
	}

	@Value
	@AllArgsConstructor
	static class Candidate
	{
		Type type;
		/** The shop reward, or null for a block, item or summary. */
		SlayerReward reward;
		String name;
		/** Points, or -1 when there is no single cost. */
		int cost;
		boolean owned;
		boolean cosmetic;
		/** Share by which the goal's rate rises, below 0 when it falls. NaN when unknown. On the points routine, the cycle's rate. */
		double gain;
		/** A few words on why it helps or hurts the goal, or null. */
		String why;
		/** Unmet requirement, e.g. "85 Slayer", or null when usable now. */
		String lockedBy;
		/** Said after the reason, e.g. whether an item has been seen, or null. */
		String note;
		/** The block list a block goes on, null for everything else. */
		SlayerMaster list;
		/**
		 * The wiki's Slayer guide says not to buy it for the goal, so it is listed under Skip these whatever its gain, and
		 * never recommended.
		 */
		boolean avoid;

		/** Anything but a block. */
		Candidate(Type type, SlayerReward reward, String name, int cost, boolean owned, boolean cosmetic, double gain, String why,
				String lockedBy, String note)
		{
			this(type, reward, name, cost, owned, cosmetic, gain, why, lockedBy, note, null, false);
		}

		/** A block on {@code list}. */
		Candidate(Type type, SlayerReward reward, String name, int cost, boolean owned, boolean cosmetic, double gain, String why,
				String lockedBy, String note, SlayerMaster list)
		{
			this(type, reward, name, cost, owned, cosmetic, gain, why, lockedBy, note, list, false);
		}

		Candidate withGain(double gain)
		{
			return new Candidate(type, reward, name, cost, owned, cosmetic, gain, why, lockedBy, note, list, avoid);
		}
	}

	@Value
	static class Line
	{
		String name;
		int cost;
		String detail;
		/**
		 * Points still short of buying it, 0 when it is affordable now, -1 when the cost is unknown. In the XP order the
		 * purchases saved for before it count too.
		 */
		int need;
		/** Rough tasks to earn {@link #need}, -1 when there is no estimate. */
		int tasks;
		/** The compact sidebar's item: the name and cost, and for some lines what it waits for. */
		String label;

		static Line of(String name, int cost, String detail)
		{
			return new Line(name, cost, detail, 0, -1, label(name, cost));
		}
	}

	/** "Bigger and Badder (50)", or the name alone when there is no single cost. */
	static String label(String name, int cost)
	{
		return label(name, cost, "");
	}

	/** "Block Waterfiends (100), 8 tasks", or "Helmet (400), 19 to go" with the points when there is no estimate of the tasks. */
	static String saveLabel(String name, int cost, int need, int tasks)
	{
		return label(name, cost, tasks > 0 ? ", " + tasks + (tasks == 1 ? " task" : " tasks") : need > 0 ? ", " + need + " to go" : "");
	}

	/** "Gargoyle Smasher (120), 75 Slayer": the purchase and the level it waits for. */
	static String laterLabel(String name, int cost, String lockedBy)
	{
		return label(name, cost, ", " + lockedBy);
	}

	/**
	 * The compact label: the name, the cost and {@code wait}. When that is too long for a compact line it leaves out a
	 * block's master first, as in "Block Kurask" for "Block Kurask at Konar", then the cost, then the wait.
	 */
	static String label(String name, int cost, String wait)
	{
		final String brief = name.replaceFirst("^(Block .+) at \\S+$", "$1");
		final String price = cost >= 0 ? " (" + cost + ")" : "";
		for (String label : new String[]{name + price + wait, brief + price + wait, brief + wait, brief + price})
		{
			if (label.length() <= MAX_LABEL) return label;
		}
		return brief;
	}

	/**
	 * Points the plan keeps for skips, and why. The master ranking assumes the worst offers are skipped at the
	 * master's cancel cost ({@link SlayerMasterRanker#skipBudget}), so the plan keeps enough for the skips that
	 * come in a row nine times in ten.
	 */
	@Value
	static class Reserve
	{
		static final Reserve NONE = new Reserve(0, 0, 0, 0, Collections.<String>emptyList(), 0);

		/** Points kept. */
		int points;
		/** Skips in a row they pay for at the plan's master. */
		int skips;
		/** Points per skip there. */
		int cancelCost;
		/** Share of the master's tasks worth skipping for the goal. */
		double share;
		/** The tasks worth skipping, worst first, at most two. */
		List<String> tasks;
		/** The least the player keeps, from config. */
		int floor;

		/** Whether the configured floor, not the skips, set the amount. */
		boolean isFloor()
		{
			return floor > skips * cancelCost;
		}
	}

	@Value
	static class Plan
	{
		int points;
		Reserve reserve;
		List<Line> buyNow;
		List<Line> saveFor;
		List<Line> later;
		List<Line> avoid;
		/** Shop rewards bought, of {@link #total}. Blocks and items are not counted. */
		int owned;
		int total;
		int cosmeticLeft;
	}

	private SlayerPointsPlanner()
	{
	}

	static Plan plan(List<Candidate> candidates, int points, Reserve reserve)
	{
		return plan(candidates, points, reserve, null);
	}

	/**
	 * @param tasksFor rough tasks to earn a number of points, -1 when unknown (see {@link SlayerPointsForecast}).
	 * Null leaves the estimate out of the save-for lines.
	 */
	static Plan plan(List<Candidate> candidates, int points, Reserve reserve, IntUnaryOperator tasksFor)
	{
		return plan(candidates, points, reserve, tasksFor, null);
	}

	/**
	 * @param goal XP follows the wiki's tiers ({@link #xpTier}) and buys in order only. Other goals, or null, keep
	 * the goal model's order and buy whatever the points reach.
	 */
	static Plan plan(List<Candidate> candidates, int points, Reserve reserve, IntUnaryOperator tasksFor, SlayerGoal goal)
	{
		final List<Candidate> wanted = new ArrayList<>();
		final List<Candidate> later = new ArrayList<>();
		final List<Candidate> avoid = new ArrayList<>();
		int owned = 0;
		int total = 0;
		int cosmeticLeft = 0;

		for (Candidate c : candidates)
		{
			if (c.getType() == Type.REWARD)
			{
				total++;
				if (c.isOwned()) owned++;
			}
			if (c.isOwned()) continue;
			if (c.isCosmetic())
			{
				cosmeticLeft++;
				continue;
			}
			if (c.isAvoid())
			{
				// What the wiki says not to buy is never recommended, and is named once it can be bought
				if (c.getLockedBy() == null) avoid.add(c);
				continue;
			}
			final double gain = c.getGain();
			if (Double.isNaN(gain)) continue;
			if (gain < -NOTICEABLE)
			{
				// It can only hurt once it can be used
				if (c.getLockedBy() == null) avoid.add(c);
				continue;
			}
			if (gain <= NOTICEABLE) continue;
			(c.getLockedBy() != null ? later : wanted).add(c);
		}

		final boolean inOrder = goal == SlayerGoal.XP;
		wanted.sort(inOrder ? XP_ORDER : BEST_FIRST);
		keepBlockOrder(wanted, candidates);
		later.sort(BEST_FIRST);
		// The wiki's own advice against a purchase comes first, then the goal model's, worst first
		avoid.sort(Comparator.comparing((Candidate c) -> !c.isAvoid()).thenComparingDouble(Candidate::getGain).thenComparing(Candidate::getName));

		final List<Line> buyNow = new ArrayList<>();
		final List<Line> saveFor = new ArrayList<>();
		int budget = Math.max(0, points - reserve.getPoints());
		boolean saving = false;
		// In the XP order a purchase waits for the ones before it, so its shortfall counts them too
		int ahead = 0;
		for (Candidate c : wanted)
		{
			final String detail = detail(c);
			if (!saving && c.getCost() >= 0 && c.getCost() <= budget)
			{
				buyNow.add(Line.of(c.getName(), c.getCost(), detail));
				budget -= c.getCost();
				continue;
			}
			// In the XP order nothing is bought past a purchase the points do not reach yet
			saving = inOrder;
			if (saveFor.size() < MAX_SAVE_FOR)
			{
				final int need = c.getCost() < 0 ? -1 : ahead + c.getCost() - budget;
				final int tasks = need > 0 && tasksFor != null ? tasksFor.applyAsInt(need) : -1;
				saveFor.add(new Line(c.getName(), c.getCost(), shortfall(need, tasks) + detail, need, tasks,
						saveLabel(c.getName(), c.getCost(), need, tasks)));
			}
			if (inOrder && c.getCost() > 0) ahead += c.getCost();
		}

		final List<Line> laterLines = new ArrayList<>();
		for (Candidate c : later)
		{
			if (laterLines.size() >= MAX_LATER) break;
			laterLines.add(new Line(c.getName(), c.getCost(), "Needs " + c.getLockedBy() + ". " + detail(c), 0, -1,
					laterLabel(c.getName(), c.getCost(), c.getLockedBy())));
		}
		final List<Line> avoidLines = new ArrayList<>();
		for (Candidate c : avoid)
		{
			// Every purchase the wiki says not to make is named, the goal model's only up to the limit
			if (!c.isAvoid() && avoidLines.size() >= MAX_AVOID) break;
			// What not to buy needs no price
			avoidLines.add(new Line(c.getName(), c.getCost(), detail(c), 0, -1, c.getName()));
		}
		return new Plan(points, reserve, buyNow, saveFor, laterLines, avoidLines, owned, total, cosmeticLeft);
	}

	/**
	 * Blocks help each other: every block raises the master's average, so the next poor task is worth more to block.
	 * Their values depend on the order they are bought in, and each list's block advice gives that order. The blocks
	 * keep the places the sort gave them among the other purchases, but each list fills its places in its advice's
	 * order, so the plan and the block lists agree on which block comes first.
	 */
	private static void keepBlockOrder(List<Candidate> sorted, List<Candidate> given)
	{
		final Map<SlayerMaster, Deque<Candidate>> blocks = new HashMap<>();
		for (Candidate c : given)
		{
			if (c.getType() == Type.BLOCK && sorted.contains(c)) blocks.computeIfAbsent(c.getList(), k -> new ArrayDeque<>()).add(c);
		}
		for (int i = 0; i < sorted.size(); i++)
		{
			final Candidate c = sorted.get(i);
			if (c.getType() == Type.BLOCK) sorted.set(i, blocks.get(c.getList()).poll());
		}
	}

	/** Most gain per point first. A free purchase counts as costing one point. Ties go to the bigger gain, then the name. */
	static final Comparator<Candidate> BEST_FIRST = Comparator
			.comparingDouble((Candidate c) -> c.getGain() / Math.max(1, c.getCost())).reversed()
			.thenComparing(Comparator.comparingDouble(Candidate::getGain).reversed())
			.thenComparing(Candidate::getName);

	/** The wiki's tiers for XP first, the goal model's order within each. */
	static final Comparator<Candidate> XP_ORDER = Comparator.comparingInt(SlayerPointsPlanner::xpTier).thenComparing(BEST_FIRST);

	/**
	 * A purchase's place in the XP order: 1 regular blocks and Bigger and Badder, 2 Stop the Wyvern and Malevolent
	 * Masquerade for the Slayer helmet, 3 extensions, 4 everything else. This departs from the wiki's literal list,
	 * which puts the Fossil Island Wyvern block with the blocks and superior monsters after them. Bigger and Badder costs
	 * 50 points and the wiki itself recommends turning it on ("optional, but recommended since you can toggle it off
	 * without penalty"), while Stop the Wyvern costs 500, five blocks' worth, to free one block slot. Taken literally, the
	 * order would hold a 50 point purchase behind a 500 point one.
	 */
	static int xpTier(Candidate c)
	{
		final SlayerReward r = c.getReward();
		if (c.getType() == Type.BLOCK || r == SlayerReward.BIGGER_AND_BADDER) return 1;
		if (r == SlayerReward.STOP_THE_WYVERN || r == SlayerReward.MALEVOLENT_MASQUERADE) return 2;
		if (r != null && r.getKind() == SlayerReward.Kind.EXTENSION) return 3;
		return 4;
	}

	/** "119 more points, about 12 tasks. " or "" when the cost is unknown. */
	static String shortfall(int need, int tasks)
	{
		if (need < 0) return "";
		final StringBuilder sb = new StringBuilder().append(need).append(" more points");
		if (tasks > 0) sb.append(", about ").append(tasks).append(tasks == 1 ? " task" : " tasks");
		return sb.append(". ").toString();
	}

	private static String detail(Candidate c)
	{
		final String why = c.getWhy() == null ? "" : c.getWhy();
		if (c.getNote() == null) return why;
		return why.isEmpty() ? c.getNote() : why + " " + c.getNote();
	}
}

package com.slayercompanion;

import com.slayercompanion.SlayerMasterAccess.Option;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import lombok.Value;

/**
 * The Slayer points routine: every task at Turael or Aya, who pay nothing but move the streak, and each
 * boost task (every 10th or every 50th) at the master who pays most. Turael, Aya and Spria all count
 * toward the four unpaid tasks at the start of a streak, which is why the routine reaches milestones
 * fastest (OSRS Wiki, Slayer reward point, "Point boosting").
 * <p>
 * Pure. Only masters on the main streak are ranked. Krystilia keeps her own streak (her milestones follow
 * her own count, not this one), and Mortimer's tasks never count toward it and pay through his modifier
 * only, so neither can turn this streak's milestone into points.
 */
final class SlayerPointsRoutine
{
	/** The streak counters and the task in progress, as the client holds them. */
	@Value
	static class Streaks
	{
		/** SLAYER_TASKS_COMPLETED: tasks done in a row for every master except Krystilia and Mortimer. */
		int main;
		/** SLAYER_WILDERNESS_TASKS_COMPLETED: Krystilia's own streak. */
		int wilderness;
		/** SLAYER_MASTER: the master of the current assignment. Only meaningful while a task is in progress. */
		int taskMaster;
		boolean taskInProgress;

		/** Who gave the task in progress, or null without a task or for an unknown master id. */
		SlayerAssigner currentMaster()
		{
			return taskInProgress ? SlayerAssigner.forId(taskMaster) : null;
		}
	}

	/** One master's pay for a milestone task. */
	@Value
	static class Ranked
	{
		SlayerAssigner master;
		String npc;
		int points;
	}

	/** The routine's advice, as short sentences for the sidebar plus the numbers behind them. */
	@Value
	static class Advice
	{
		/** Who gave the task in progress and what it pays, or null without a task. */
		String current;
		/** Where to get the next task. */
		String next;
		/** The wiki's warning about Konar on 10th tasks, or null. */
		String caveat;
		/** The next milestone and what it pays at the best master. */
		String milestone;
		/** Changing a task at Turael or Aya resets the streak. */
		String warning;
		/** The next task to get, numbered in the main streak. */
		int nextTask;
		/** Masters ranked for the next task when it is a boost task, highest first, else empty. */
		List<Ranked> ranking;
		/** The compact sidebar's heading, "NEXT TASK", or "NEXT TASK #50" when the next task is a milestone. */
		String heading;
		/**
		 * The compact sidebar's items: the next task and the next milestone, as "#48 Aya, 0 pts" and "#50 Konar, 270 pts".
		 * Before a milestone the paying masters instead, as "Konar 270".
		 */
		List<String> items;
	}

	/** Masters the compact sidebar names for a milestone task. {@link Advice#getNext} keeps the whole list. */
	static final int COMPACT_MASTERS = 3;

	private SlayerPointsRoutine()
	{
	}

	/** The next main-streak task to get. A task in progress from a master on that streak comes first. */
	static int nextTask(Streaks streaks)
	{
		final SlayerAssigner current = streaks.currentMaster();
		// An unknown master id is most likely a main streak master, so its task is counted
		final boolean currentCounts = streaks.isTaskInProgress()
				&& (current == null || current.getStreak() == SlayerAssigner.Streak.MAIN);
		return streaks.getMain() + (currentCounts ? 2 : 1);
	}

	/** The next task of a master's own streak, after any task in progress that counts toward it. */
	static int nextTask(Streaks streaks, SlayerAssigner master)
	{
		if (master.getStreak() == SlayerAssigner.Streak.WILDERNESS)
		{
			final boolean currentCounts = streaks.currentMaster() == SlayerAssigner.KRYSTILIA;
			return streaks.getWilderness() + (currentCounts ? 2 : 1);
		}
		return nextTask(streaks);
	}

	/** Points the task in progress pays on completion, or -1 without a task or when its master is unknown. */
	static int currentPayout(Streaks streaks, SlayerPayout.Diaries diaries)
	{
		final SlayerAssigner master = streaks.currentMaster();
		if (master == null) return -1;
		switch (master.getStreak())
		{
			case WILDERNESS:
				return SlayerPayout.payout(master, streaks.getWilderness() + 1, diaries);
			case MORTIMER:
				return 0;
			default:
				return SlayerPayout.payout(master, streaks.getMain() + 1, diaries);
		}
	}

	/**
	 * Usable main-streak masters that pay for task {@code task}, highest first. On a tie the master with
	 * the lower combat requirement comes first, as its tasks are usually quicker.
	 */
	static List<Ranked> rank(int task, List<Option> options, SlayerPayout.Diaries diaries)
	{
		final List<Ranked> out = new ArrayList<>();
		for (Option o : options)
		{
			if (!o.isUsable() || o.getMaster().getStreak() != SlayerAssigner.Streak.MAIN) continue;
			final int points = SlayerPayout.payout(o.getMaster(), task, diaries);
			if (points > 0) out.add(new Ranked(o.getMaster(), o.getNpc(), points));
		}
		out.sort(Comparator.comparingInt(Ranked::getPoints).reversed()
				.thenComparingInt(r -> r.getMaster().getCombatLevel()));
		return out;
	}

	/** What task {@code task} pays when the routine is followed: the best master on a boost task, else 0. */
	static int routinePayout(int task, BoostInterval boost, List<Option> options, SlayerPayout.Diaries diaries)
	{
		if (!boost.isBoostTask(task)) return 0;
		final List<Ranked> ranking = rank(task, options, diaries);
		return ranking.isEmpty() ? 0 : ranking.get(0).getPoints();
	}

	static Advice advise(Streaks streaks, List<Option> options, SlayerPayout.Diaries diaries, BoostInterval boost)
	{
		final Option low = SlayerMasterAccess.find(options, SlayerAssigner.TURAEL);
		final Option spria = SlayerMasterAccess.find(options, SlayerAssigner.SPRIA);
		final int next = nextTask(streaks);
		final boolean boostNext = boost.isBoostTask(next);
		final List<Ranked> ranking = boostNext ? rank(next, options, diaries) : Collections.<Ranked>emptyList();
		final String caveat = caveat(next, ranking);

		final List<String> items = new ArrayList<>();
		final String heading;
		if (boostNext && !ranking.isEmpty())
		{
			heading = "NEXT TASK #" + next;
			for (Ranked r : ranking.subList(0, Math.min(COMPACT_MASTERS, ranking.size())))
			{
				items.add(r.getNpc() + " " + r.getPoints());
			}
			if (caveat != null) items.add("Wiki: avoid Konar for 10ths");
		}
		else
		{
			heading = "NEXT TASK";
			items.add("#" + next + " " + low.getNpc() + (spria != null && spria.isUsable() ? " or " + spria.getNpc() : "") + ", 0 pts");
			items.add(milestoneItem(boostNext ? next + boost.getEvery() : boost.nextBoostTask(next), options, diaries));
		}

		return new Advice(
				current(streaks, options, diaries),
				nextText(next, boostNext, ranking, low, spria),
				caveat,
				milestone(next, boostNext, streaks.isTaskInProgress(), boost, options, diaries),
				"Changing a task with " + low.getNpc() + " resets your streak to 0.",
				next,
				ranking,
				heading,
				Collections.unmodifiableList(items));
	}

	/** "#50 Konar, 270 pts": the master who pays most for milestone {@code target}, or "No master pays yet". */
	private static String milestoneItem(int target, List<Option> options, SlayerPayout.Diaries diaries)
	{
		final List<Ranked> ranking = rank(target, options, diaries);
		if (ranking.isEmpty()) return "No master pays yet";
		return "#" + target + " " + ranking.get(0).getNpc() + ", " + ranking.get(0).getPoints() + " pts";
	}

	private static String current(Streaks streaks, List<Option> options, SlayerPayout.Diaries diaries)
	{
		if (!streaks.isTaskInProgress()) return null;
		final SlayerAssigner master = streaks.currentMaster();
		final int task = streaks.getMain() + 1;
		if (master == null)
		{
			return "This is task " + task + " of your streak. What it pays depends on the master who gave it.";
		}
		final Option option = SlayerMasterAccess.find(options, master);
		final String npc = option == null ? master.getDisplayName() : option.getNpc();
		switch (master.getStreak())
		{
			case WILDERNESS:
				final int wild = streaks.getWilderness() + 1;
				return pays(npc, SlayerPayout.payout(master, wild, diaries)) + " for task " + wild
						+ " of her Wilderness streak. That streak is counted apart from this one.";
			case MORTIMER:
				return "Mortimer pays points only through his points modifier. His tasks do not count toward your streak.";
			default:
				final int points = SlayerPayout.payout(master, task, diaries);
				if (points == 0 && task <= SlayerPayout.UNPAID_TASKS)
				{
					return "Task " + task + " of your streak pays nothing. The first " + SlayerPayout.UNPAID_TASKS
							+ " tasks of a streak never pay.";
				}
				return pays(npc, points) + " for task " + task + " of your streak."
						+ (points == 0 ? " It still counts toward the streak." : "");
		}
	}

	private static String pays(String npc, int points)
	{
		return points == 0 ? npc + " pays no points" : npc + " pays " + points;
	}

	private static String nextText(int next, boolean boostNext, List<Ranked> ranking, Option low, Option spria)
	{
		final String lowAt = low.getNpc() + " in " + low.getMaster().getLocation()
				+ (spria != null && spria.isUsable() ? " or " + spria.getNpc() + " in " + spria.getMaster().getLocation() : "");
		if (boostNext && !ranking.isEmpty())
		{
			return "Task " + next + " is a milestone. Get it from the master who pays most: " + list(ranking) + ".";
		}
		if (boostNext)
		{
			return "Task " + next + " is a milestone, but no master you can use pays points yet. Get it from " + lowAt + ".";
		}
		if (next <= SlayerPayout.UNPAID_TASKS)
		{
			return "Get task " + next + " from " + lowAt + ". The first " + SlayerPayout.UNPAID_TASKS
					+ " tasks of a streak pay no points anywhere.";
		}
		return "Get task " + next + " from " + lowAt + ". It pays no points but still counts toward your streak.";
	}

	private static String list(List<Ranked> ranking)
	{
		final StringBuilder sb = new StringBuilder();
		for (Ranked r : ranking)
		{
			if (sb.length() > 0) sb.append(", ");
			sb.append(r.getNpc()).append(' ').append(r.getPoints());
		}
		return sb.toString();
	}

	/**
	 * The Turael and Aya wiki pages advise against boosting every 10th task with Konar, as she gives many
	 * unfavourable tasks, unless another master takes the 10th. Her 50th and later milestones are fine.
	 */
	private static String caveat(int next, List<Ranked> ranking)
	{
		if (ranking.isEmpty() || ranking.get(0).getMaster() != SlayerAssigner.KONAR || next % 50 == 0) return null;
		final String runnerUp = ranking.size() > 1
				? " " + ranking.get(1).getNpc() + " at " + ranking.get(1).getPoints() + " is the next best." : "";
		return "Konar gives many unfavourable tasks, so the wiki suggests another master for 10th tasks." + runnerUp;
	}

	private static String milestone(int next, boolean boostNext, boolean taskInProgress, BoostInterval boost,
			List<Option> options, SlayerPayout.Diaries diaries)
	{
		final int target = boostNext ? next + boost.getEvery() : boost.nextBoostTask(next);
		final List<Ranked> ranking = rank(target, options, diaries);
		if (ranking.isEmpty())
		{
			return "No master you can use pays points yet." + firstPayingLock(options);
		}
		final Ranked best = ranking.get(0);
		final String pays = " " + best.getNpc() + " pays " + best.getPoints() + " for it.";
		if (boostNext)
		{
			return "After task " + next + ", the next is task " + target + "." + pays;
		}
		final int away = target - next + 1;
		return "Task " + target + ", " + away + (taskInProgress ? " tasks after this one." : " tasks from now.") + pays;
	}

	/** What keeps the lowest paying master out of reach, so a new account knows what to work toward. */
	private static String firstPayingLock(List<Option> options)
	{
		for (Option o : options)
		{
			if (o.getMaster().getStreak() == SlayerAssigner.Streak.MAIN && !o.isUsable()
					&& SlayerPayout.basePoints(o.getMaster(), SlayerPayout.Diaries.NONE) > 0)
			{
				return " " + o.getNpc() + " needs " + o.getMissing() + ".";
			}
		}
		return "";
	}
}

package com.slayercompanion;

import com.slayercompanion.data.TaskRating;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Function;
import java.util.function.UnaryOperator;
import lombok.AllArgsConstructor;
import lombok.Getter;
import lombok.Value;

/**
 * One master's task pool as this player gets it: every pool row with its weight, whether the master can
 * assign it to the player, and the task's ratings. Pure. {@link SlayerGoalModel} turns a pool into a rate
 * per goal, {@link SlayerMasterRanker} ranks masters with it and {@link SlayerBlockAdvisor} picks blocks.
 * <p>
 * Eligibility follows the cache tables, checked against a dump of the live cache (tools/cache-dump): every
 * stat level in COL_MIN_STAT_REQUIREMENT_ALL (Slayer, and e.g. 50 Magic for cave kraken or 87 Sailing for
 * frost dragons), one of COL_MIN_STAT_REQUIREMENT_ANY (60 Strength or 60 Agility for the God Wars Dungeon),
 * COL_MIN_COMLEVEL, the reward a pool row needs (COL_TASK_UNLOCK) and the tasks a bought blocker takes out
 * of every pool (Stop the Wyvern). The combat level is skipped when the player switched combat checks off
 * at a master (wiki Slayer training, "Combat levels") and by Krystilia, who "will assign any monster
 * regardless of your combat level" (wiki Krystilia). Quest requirements are not in the tables, so a few
 * tasks can still be out of reach.
 */
final class SlayerPool
{
	enum Status
	{
		/** The master can assign it. */
		OPEN,
		/** On the block list. The master could assign it otherwise. */
		BLOCKED,
		/** Needs a reward the player does not own, e.g. Like a Boss. */
		NEEDS_UNLOCK,
		/** Needs a Slayer, other stat or combat level the player lacks. */
		NEEDS_LEVEL,
		/** Taken out of every pool by a bought blocker, e.g. Stop the Wyvern. */
		REMOVED
	}

	/** Everything about the player a pool depends on, apart from the master's block list. */
	@Value
	static class Player
	{
		/** Real levels by {@link net.runelite.api.Skill} ordinal, the order the cache's stat ids use. */
		int[] levels;
		int combatLevel;
		/** COMBAT_LEVEL_REQS_DISABLED: the player told the masters to ignore their combat level. */
		boolean combatChecksOff;
		Set<Integer> ownedUnlocks;
		/** Task rows a bought blocker keeps out of every pool. */
		Set<Integer> removedTasks;

		int level(int stat)
		{
			return stat >= 0 && stat < levels.length ? levels[stat] : 0;
		}
	}

	@Value
	@AllArgsConstructor
	static class Entry
	{
		/** The wiki's advice bounds an XP rating at these: a task to do is fair at least, one to skip poor at best. */
		static final int FAIR = 3;
		static final int POOR = 2;

		int taskRow;
		String name;
		int weight;
		/** Fewest and most kills the master assigns, -1 for boss tasks where the player picks. */
		int minAmount;
		int maxAmount;
		/** The amount the rating's speed was judged at, see {@link SlayerGameData#typicalAmount}. */
		double typicalAmount;
		Status status;
		/** The ratings that apply at this master: Krystilia's Wilderness version where there is one. Null when unrated. */
		TaskRating rating;
		/**
		 * Minutes per assignment from the task's own estimate at this master, the minutes between tasks included, or 0
		 * when the speed rating and the amounts decide. Turael's and Spria's filler tasks have one.
		 */
		double minutes;
		/** The wiki's advice on the task for XP at this master, or null. Krystilia's Wilderness tasks have none. */
		TaskRating.XpAdvice xpAdvice;

		/** A task timed by its speed rating and amounts. */
		Entry(int taskRow, String name, int weight, int minAmount, int maxAmount, double typicalAmount, Status status, TaskRating rating)
		{
			this(taskRow, name, weight, minAmount, maxAmount, typicalAmount, status, rating, 0, null);
		}

		/** A task with its own time estimate. */
		Entry(int taskRow, String name, int weight, int minAmount, int maxAmount, double typicalAmount, Status status, TaskRating rating,
				double minutes)
		{
			this(taskRow, name, weight, minAmount, maxAmount, typicalAmount, status, rating, minutes, null);
		}

		boolean isOpen()
		{
			return status == Status.OPEN;
		}

		/** Whether the master can assign it to this player once it is off the block list. */
		boolean isAssignable()
		{
			return status == Status.OPEN || status == Status.BLOCKED;
		}

		boolean isRated()
		{
			return rating != null && rating.isComplete();
		}

		/**
		 * The task's rating for a goal, 0 when unrated. For XP the wiki's advice bounds it: a task it says to do counts
		 * as fair at least, one it says to skip or not to unlock as poor at best. Every XP decision reads this.
		 */
		int rating(SlayerGoal goal)
		{
			if (!isRated()) return 0;
			final int r = rating.forGoal(goal);
			final TaskRating.XpAdvice advice = wikiAdvice(goal);
			if (advice == null) return r;
			return advice == TaskRating.XpAdvice.DO ? Math.max(r, FAIR) : Math.min(r, POOR);
		}

		/** The wiki's advice on the task for the goal, or null. Only XP has one. */
		TaskRating.XpAdvice wikiAdvice(SlayerGoal goal)
		{
			return goal == SlayerGoal.XP ? xpAdvice : null;
		}

		/** Whether the wiki says to do the task for the goal, so no skip or block may touch it. */
		boolean wikiSaysDo(SlayerGoal goal)
		{
			return wikiAdvice(goal) == TaskRating.XpAdvice.DO;
		}

		/** Average kills per assignment, or -1 for boss tasks. */
		double averageAmount()
		{
			return minAmount > 0 ? (minAmount + maxAmount) / 2.0 : -1;
		}

		/** A boss task, where the player picks the amount. It cannot be blocked, only toggled off with Like a Boss. */
		boolean isBoss()
		{
			return minAmount < 0;
		}

		Entry withStatus(Status status)
		{
			return new Entry(taskRow, name, weight, minAmount, maxAmount, typicalAmount, status, rating, minutes, xpAdvice);
		}

		/** The same task with another amount, e.g. once an extension is bought. */
		Entry withAmounts(int min, int max)
		{
			return new Entry(taskRow, name, weight, min, max, typicalAmount, status, rating, minutes, xpAdvice);
		}

		/** The same task with another weight, e.g. Chance of Heavy Frost. */
		Entry withWeight(int weight)
		{
			return new Entry(taskRow, name, weight, minAmount, maxAmount, typicalAmount, status, rating, minutes, xpAdvice);
		}
	}

	@Getter
	private final SlayerAssigner master;
	@Getter
	private final List<Entry> entries;

	private SlayerPool(SlayerAssigner master, List<Entry> entries)
	{
		this.master = master;
		this.entries = Collections.unmodifiableList(entries);
	}

	/**
	 * @param blockedRows task rows on the master's block list
	 * @param ratings a task's ratings by its cache name, null when unknown. The dataset's lookup.
	 */
	static SlayerPool of(SlayerAssigner master, SlayerGameData data, Player player, Set<Integer> blockedRows,
			Function<String, TaskRating> ratings)
	{
		final List<Entry> entries = new ArrayList<>();
		for (SlayerGameData.PoolEntry e : data.pool(master.getId()))
		{
			final String name = data.taskName(e.getTaskRow());
			TaskRating rating = name == null ? null : ratings.apply(name);
			if (rating != null && master == SlayerAssigner.KRYSTILIA && rating.getWilderness() != null)
			{
				rating = rating.getWilderness();
			}
			// Turael and Spria give small amounts, so their tasks are timed by the trip, not by other masters' amounts
			final boolean filler = master == SlayerAssigner.TURAEL || master == SlayerAssigner.SPRIA;
			final double minutes = filler && rating != null && rating.getFiller() != null ? rating.getFiller().getMinutes() : 0;
			// The wiki's XP advice is for the regular masters, not Krystilia's Wilderness tasks
			final TaskRating.XpAdvice advice = rating == null || master == SlayerAssigner.KRYSTILIA ? null : rating.getXpAdvice();
			entries.add(new Entry(e.getTaskRow(), name == null ? "Task row " + e.getTaskRow() : name, e.getWeight(),
					e.getMinAmount(), e.getMaxAmount(), data.typicalAmount(e.getTaskRow()),
					status(master, data, player, blockedRows, e), rating, minutes, advice));
		}
		return new SlayerPool(master, entries);
	}

	/** A pool of ready-made entries, for tests and what-if pools. */
	static SlayerPool of(SlayerAssigner master, List<Entry> entries)
	{
		return new SlayerPool(master, new ArrayList<>(entries));
	}

	/** The same pool with some entries changed, e.g. a task opened by an unlock or lengthened by an extension. */
	SlayerPool map(UnaryOperator<Entry> change)
	{
		final List<Entry> out = new ArrayList<>();
		for (Entry e : entries)
		{
			out.add(change.apply(e));
		}
		return new SlayerPool(master, out);
	}

	private static Status status(SlayerAssigner master, SlayerGameData data, Player player, Set<Integer> blockedRows,
			SlayerGameData.PoolEntry e)
	{
		final int row = e.getTaskRow();
		if (player.getRemovedTasks().contains(row)) return Status.REMOVED;
		if (e.getUnlockRow() >= 0 && !player.getOwnedUnlocks().contains(e.getUnlockRow())) return Status.NEEDS_UNLOCK;
		if (!meetsLevels(master, data, player, row)) return Status.NEEDS_LEVEL;
		return blockedRows.contains(row) ? Status.BLOCKED : Status.OPEN;
	}

	static boolean meetsLevels(SlayerAssigner master, SlayerGameData data, Player player, int row)
	{
		for (SlayerGameData.StatLevel s : data.statsAll(row))
		{
			if (player.level(s.getStat()) < s.getLevel()) return false;
		}
		final List<SlayerGameData.StatLevel> any = data.statsAny(row);
		boolean anyMet = any.isEmpty();
		for (SlayerGameData.StatLevel s : any)
		{
			anyMet |= player.level(s.getStat()) >= s.getLevel();
		}
		if (!anyMet) return false;
		final boolean combatChecked = !player.isCombatChecksOff() && master != SlayerAssigner.KRYSTILIA;
		return !combatChecked || player.getCombatLevel() >= data.combatLevel(row);
	}

	/** The same pool with these rows blocked and every other block lifted. */
	SlayerPool withBlocks(Collection<Integer> rows)
	{
		final Set<Integer> blocked = new HashSet<>(rows);
		final List<Entry> out = new ArrayList<>();
		for (Entry e : entries)
		{
			if (!e.isAssignable()) out.add(e);
			else out.add(e.withStatus(blocked.contains(e.getTaskRow()) ? Status.BLOCKED : Status.OPEN));
		}
		return new SlayerPool(master, out);
	}

	/** The tasks the master can give right now. */
	List<Entry> open()
	{
		final List<Entry> out = new ArrayList<>();
		for (Entry e : entries)
		{
			if (e.isOpen()) out.add(e);
		}
		return out;
	}

	Entry find(int taskRow)
	{
		for (Entry e : entries)
		{
			if (e.getTaskRow() == taskRow) return e;
		}
		return null;
	}

	/** Weight of the tasks the master can give right now. */
	int openWeight()
	{
		int w = 0;
		for (Entry e : entries)
		{
			if (e.isOpen()) w += e.getWeight();
		}
		return w;
	}

	/** Weight of the tasks the player has the requirements for, blocked or not. */
	int assignableWeight()
	{
		int w = 0;
		for (Entry e : entries)
		{
			if (e.isAssignable()) w += e.getWeight();
		}
		return w;
	}

	int blockedWeight()
	{
		int w = 0;
		for (Entry e : entries)
		{
			if (e.getStatus() == Status.BLOCKED) w += e.getWeight();
		}
		return w;
	}

	/** Chance the next task from this master is this one, 0 when the master cannot give it now. */
	double chance(Entry entry)
	{
		final int open = openWeight();
		return entry.isOpen() && open > 0 ? entry.getWeight() / (double) open : 0;
	}

	/**
	 * The goal's rating averaged over the tasks the master can give now, by their chance of coming up:
	 * the "expected rating" of the pool, 1 to 5. Unrated tasks are left out. -1 when nothing is rated.
	 */
	double expected(SlayerGoal goal)
	{
		double sum = 0;
		int weight = 0;
		for (Entry e : entries)
		{
			if (!e.isOpen() || !e.isRated()) continue;
			sum += e.getWeight() * (double) e.rating(goal);
			weight += e.getWeight();
		}
		return weight > 0 ? sum / weight : -1;
	}

	/** Chance the next task is rated at least {@code min} for the goal, among the rated tasks the master can give now. */
	double share(SlayerGoal goal, int min)
	{
		int good = 0;
		int weight = 0;
		for (Entry e : entries)
		{
			if (!e.isOpen() || !e.isRated()) continue;
			weight += e.getWeight();
			if (e.rating(goal) >= min) good += e.getWeight();
		}
		return weight > 0 ? good / (double) weight : 0;
	}
}

