		recommend(DRAGONFIRE_PROTECTION, "Black dragons", "Blue dragons", "Green dragons", "Red dragons", "Metal dragons", "Lava Dragons",
			"Frost dragons", "The King Black Dragon", "Vorkath");
		// Wiki: Draconic (attribute), whose list covers dragons, drakes, hydras, wyrms and wyverns.
		recommend(DRAGONBANE, "Black dragons", "Blue dragons", "Green dragons", "Red dragons", "Metal dragons", "Lava Dragons",
			"Frost dragons", "The King Black Dragon", "Vorkath", "Drakes", "Hydras", "The Alchemical Hydra", "Wyrms", "Skeletal wyverns",
			"Fossil island wyverns");
		// Wiki: Demon (attribute). Every monster of these tasks is a demon. Duke Sucellus takes 70% of the bonus.
		recommend(DEMONBANE, "Abyssal demons", "Black demons", "Greater demons", "Lesser demons", "Bloodveld", "Hellhounds", "Nechryael",
			"Pyrefiends", "Icefiends", "Waterfiends", "The Abyssal Sire", "Cerberus", "K'ril Tsutsaroth", "Duke Sucellus");
		// Wiki: Kalphite (attribute). Scabarites count too.
		recommend(KERIS, "Kalphites", "The Kalphite Queen", "Scabarites");
		recommend(INSULATED_BOOTS, "Killerwatts");
		// Wiki: Lumbridge Swamp Caves, Light sources (Gas explosions). An open flame still lights the cave, so the darkness
		// check takes it, but in parts of the caves it sets off the gas, which hurts and puts it out. The Fire of Eternal
		// Light stops the explosions. Asked for only while a flame is the light, so a player with no light gets the red line.
		recommend(Recommendation.onlyWith(COVERED_LIGHT, OPEN_FLAMES, VarbitID.MY2ARM_FIRE_LUMB, SWAMP_GAS_REASON),
			"Cave bugs", "Cave slimes", "Wall beasts");
		Collections.addAll(UNDEAD, normalize("Aberrant spectres"), normalize("Ankou"), normalize("Banshees"), normalize("Crawling hands"),
			normalize("Ghosts"), normalize("Revenants"), normalize("Shades"), normalize("Skeletons"), normalize("Zombies"),
			normalize("Vorkath"), normalize("Vet'ion"));
	}

	private SlayerRequirements()
	{
	}

	static Requirement forTask(String taskName)
	{
		return REQUIREMENTS.get(normalize(taskName));
	}

	/** Needs that any task assigned to this SLAYER_AREA id brings with it. */
	static List<Need> forArea(int areaId)
	{
		final List<Need> needs = AREA_NEEDS.get(areaId);
		return needs == null ? Collections.emptyList() : needs;
	}

	/** Normalised task names with a requirement, for the tests that keep them equal to the game's names. */
	static Set<String> taskKeys()
	{
		return Collections.unmodifiableSet(REQUIREMENTS.keySet());
	}

	/** The recommended tier for a task, without the helmet. Empty when there is none. */
	static List<Recommendation> recommendedFor(String taskName)
	{
		final List<Recommendation> recommendations = RECOMMENDED.get(normalize(taskName));
		return recommendations == null ? Collections.emptyList() : Collections.unmodifiableList(recommendations);
	}

	/** Normalised task names with recommended items, for the tests that keep them equal to the game's names. */
	static Set<String> recommendedKeys()
	{
		return Collections.unmodifiableSet(RECOMMENDED.keySet());
	}

	/** Normalised names of the undead tasks, for the same test. */
	static Set<String> undeadKeys()
	{
		return Collections.unmodifiableSet(UNDEAD);
	}

	/** Every item id the item groups list, the only items the bank memory keeps. */
	static Set<Integer> gearIds()
	{
		return GEAR_IDS_VIEW;
	}

	/** Whether a mandatory item of the task is one a Slayer helmet stands in for. Each of those goes on the head. */
	static boolean helmetStandsIn(String taskName)
	{
		final Requirement requirement = forTask(taskName);
		if (requirement == null) return false;
		for (Need need : requirement.getNeeds())
		{
			if (need.getItems().ids().contains(ItemID.SLAYER_HELM)) return true;
		}
		return false;
	}

	/**
	 * What gives the task's on-task bonus: a Slayer helmet or black mask, a salve amulet as well against the undead, and
	 * only the helmet where a mandatory item takes the head slot.
	 */
	static ItemGroup slayerHeadgear(String taskName)
	{
		final boolean undead = UNDEAD.contains(normalize(taskName));
		if (helmetStandsIn(taskName)) return undead ? HELMET_OR_SALVE : SLAYER_HELMET;
		return undead ? HELMET_MASK_OR_SALVE : HELMET_OR_MASK;
	}

	static String normalize(String value)
	{
		if (value == null) return "";
		return value.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", " ").trim();
	}

	/** Names a recolour of the helmet would get, such as "Hydra slayer helmet (i)". */
	static boolean isSlayerHelmetName(String name)
	{
		if (name == null) return false;
		final String n = name.trim().toLowerCase(Locale.ROOT);
		return n.endsWith("slayer helmet") || n.endsWith("slayer helmet (i)");
	}

	private static void put(String task, Unlock unlock, Need... needs)
	{
		final String key = normalize(task);
		if (REQUIREMENTS.containsKey(key)) throw new IllegalStateException("Two requirements for " + task);
		final List<Need> list = new ArrayList<>();
		Collections.addAll(list, needs);
		REQUIREMENTS.put(key, new Requirement(Collections.unmodifiableList(list), unlock));
	}

	private static void recommend(ItemGroup items, String... tasks)
	{
		recommend(Recommendation.of(items), tasks);
	}

	private static void recommend(Recommendation recommendation, String... tasks)
	{
		for (String task : tasks)
		{
			final List<Recommendation> recommendations = RECOMMENDED.computeIfAbsent(normalize(task), k -> new ArrayList<>());
			for (Recommendation other : recommendations)
			{
				if (other.getItems() == recommendation.getItems())
				{
					throw new IllegalStateException("Two recommendations of " + recommendation.getItems().getLabel() + " for " + task);
				}
			}
			recommendations.add(recommendation);
		}
	}

	/** The items of {@code from} that are not in {@code minus}. */
	private static ItemGroup without(String label, ItemGroup from, ItemGroup minus)
	{
		final Map<Integer, String> map = new LinkedHashMap<>(from.items);
		map.keySet().removeAll(minus.ids());
		return new ItemGroup(label, map, false);
	}

	/** Ids that share one name, such as the recolours of the helmet. */
	private static Map<Integer, String> named(int[] ids, String name)
	{
		final Map<Integer, String> map = new LinkedHashMap<>();
		for (int id : ids)
		{
			map.put(id, name);
		}
		return map;
	}

	private static Item item(int id, String name)
	{
		return new Item(id, name);
	}

	private static ItemGroup items(String label, Item... items)
	{
		final Map<Integer, String> map = new LinkedHashMap<>();
		for (Item item : items)
		{
			if (map.put(item.id, item.name) != null) throw new IllegalStateException("Item " + item.id + " listed twice");
		}
		return new ItemGroup(label, map, false);
	}

	private static ItemGroup group(String label, ItemGroup... parts)
	{
		final Map<Integer, String> map = new LinkedHashMap<>();
		boolean helmetNames = false;
		for (ItemGroup part : parts)
		{
			map.putAll(part.items);
			helmetNames |= part.anySlayerHelmetName;
		}
		return new ItemGroup(label, map, helmetNames);
	}

	/** One item id with its in-game name. */
	static final class Item
	{
		final int id;
		final String name;

		private Item(int id, String name)
		{
			this.id = id;
			this.name = name;
		}
	}

	/** Items that do the same job. Any one of them is enough. */
	static final class ItemGroup
	{
		private final String label;
		private final Map<Integer, String> items;
		private final boolean anySlayerHelmetName;

		private ItemGroup(String label, Map<Integer, String> items, boolean anySlayerHelmetName)
		{
			this.label = label;
			this.items = Collections.unmodifiableMap(items);
			this.anySlayerHelmetName = anySlayerHelmetName;
			GEAR_IDS.addAll(items.keySet());
		}

		/** What the line asks for when none of the items is there, such as "a nose peg or Slayer helmet". */
		String getLabel()
		{
			return label;
		}

		Set<Integer> ids()
		{
			return items.keySet();
		}

		/** The in-game name the group gives an item, which names an item the bank holds. Null when it does not list the id. */
		String name(int id)
		{
			return items.get(id);
		}

		boolean matches(int id, String name)
		{
			return items.containsKey(id) || anySlayerHelmetName && isSlayerHelmetName(name);
		}
	}

	/**
	 * One item class of the recommended tier. Most are asked for whenever none is held. A conditional one is asked for
	 * only while one of another group is held, such as a covered lantern while an open flame is the light, unless its
	 * varbit is set, and its reason follows the request in the line.
	 */
	static final class Recommendation
	{
		private final ItemGroup items;
		private final ItemGroup onlyWith;
		private final int exemptVarbit;
		private final String reason;

		private Recommendation(ItemGroup items, ItemGroup onlyWith, int exemptVarbit, String reason)
		{
			this.items = items;
			this.onlyWith = onlyWith;
			this.exemptVarbit = exemptVarbit;
			this.reason = reason;
		}

		static Recommendation of(ItemGroup items)
		{
			return new Recommendation(items, null, -1, null);
		}

		static Recommendation onlyWith(ItemGroup items, ItemGroup onlyWith, int exemptVarbit, String reason)
		{
			return new Recommendation(items, onlyWith, exemptVarbit, reason);
		}

		ItemGroup getItems()
		{
			return items;
		}

		/** The group that must be held for the request, or null when it always applies. */
		ItemGroup getOnlyWith()
		{
			return onlyWith;
		}

		/** A varbit that drops the request when set, or -1. */
		int getExemptVarbit()
		{
			return exemptVarbit;
		}

		/** Said after the request, or null. */
		String getReason()
		{
			return reason;
		}
	}

	/** A Slayer reward that uses the item for you at low health. The item is still needed in the inventory. */
	static final class Unlock
	{
		private final String name;
		private final int varbit;
		private final ItemGroup uses;

		private Unlock(String name, int varbit, ItemGroup uses)
		{
			this.name = name;
			this.varbit = varbit;
			this.uses = uses;
		}

		String getName()
		{
			return name;
		}

		int getVarbit()
		{
			return varbit;
		}

		ItemGroup getUses()
		{
			return uses;
		}
	}

	/**
	 * One thing a task needs. By default it applies wherever the task is done. A need tied to a place applies
	 * when Konar assigned that place, and otherwise carries the place in its text so the line stays true.
	 */
	static final class Need
	{
		enum Kind
		{
			/** Any one of the items. */
			HAVE,
			/** Used up once per kill, so the count is compared with the kills left. A kept item may replace it. */
			PER_KILL,
			/** Charges read from the item names plus refills, one charge per kill. */
			CHARGES,
			/** Not mandatory. A note replaces it when it is missing. */
			ADVICE
		}

		private final Kind kind;
		private final ItemGroup items;
		private final ItemGroup alternative;
		private final boolean alternativeFirst;
		private final ItemGroup refills;
		private final int refillCharges;
		private final String one;
		private final String many;
		private final String advice;
		private final String where;
		private final int[] areas;
		private final boolean assignedOnly;
		private final int exemptVarbit;
		private final String exemptNote;
		private final String exemptWhere;

		private Need(Kind kind, ItemGroup items, ItemGroup alternative, boolean alternativeFirst, ItemGroup refills,
			int refillCharges, String one, String many, String advice, String where, int[] areas, boolean assignedOnly,
			int exemptVarbit, String exemptNote, String exemptWhere)
		{
			this.kind = kind;
			this.items = items;
			this.alternative = alternative;
			this.alternativeFirst = alternativeFirst;
			this.refills = refills;
			this.refillCharges = refillCharges;
			this.one = one;
			this.many = many;
			this.advice = advice;
			this.where = where;
			this.areas = areas;
			this.assignedOnly = assignedOnly;
			this.exemptVarbit = exemptVarbit;
			this.exemptNote = exemptNote;
			this.exemptWhere = exemptWhere;
		}

		static Need have(ItemGroup items)
		{
			return new Need(Kind.HAVE, items, null, false, null, 0, null, null, null, null, null, false, -1, null, null);
		}

		static Need perKill(ItemGroup items, String one, String many)
		{
			return new Need(Kind.PER_KILL, items, null, false, null, 0, one, many, null, null, null, false, -1, null, null);
		}

		static Need charges(ItemGroup items, ItemGroup refills, int refillCharges, String one, String many)
		{
			return new Need(Kind.CHARGES, items, null, false, refills, refillCharges, one, many, null, null, null, false,
				-1, null, null);
		}

		static Need advice(ItemGroup items, String advice)
		{
			return new Need(Kind.ADVICE, items, null, false, null, 0, null, null, advice, null, null, false, -1, null, null);
		}

		/** A kept item that does the job of the used-up one, such as a rock hammer instead of thrownhammers. */
		Need or(ItemGroup alternative, boolean nameItFirst)
		{
			return new Need(kind, items, alternative, nameItFirst, refills, refillCharges, one, many, advice, where, areas,
				assignedOnly, exemptVarbit, exemptNote, exemptWhere);
		}

		/** Needed only at one place. It applies when Konar assigned one of the areas, or names the place otherwise. */
		Need onlyAt(String where, int... areas)
		{
			return new Need(kind, items, alternative, alternativeFirst, refills, refillCharges, one, many, advice, where,
				areas, false, exemptVarbit, exemptNote, exemptWhere);
		}

		/** Needed only when Konar assigned one of these areas. Without an assigned area it is left out. */
		Need onlyIfAssigned(int... areas)
		{
			return new Need(kind, items, alternative, alternativeFirst, refills, refillCharges, one, many, advice, where,
				areas, true, exemptVarbit, exemptNote, exemptWhere);
		}

		/** Not needed once the varbit is set, such as boots after the elite Kourend & Kebos diary. */
		Need unless(int varbit, String note)
		{
			return unless(varbit, note, null);
		}

		/** The varbit removes the need at one place, and {@code stillWhere} names where it is still needed. */
		Need unless(int varbit, String note, String stillWhere)
		{
			return new Need(kind, items, alternative, alternativeFirst, refills, refillCharges, one, many, advice, where,
				areas, assignedOnly, varbit, note, stillWhere);
		}

		boolean appliesIn(int assignedAreaId)
		{
			if (assignedAreaId <= 0) return !assignedOnly;
			if (areas == null) return true;
			for (int area : areas)
			{
				if (area == assignedAreaId) return true;
			}
			return false;
		}

		Kind getKind()
		{
			return kind;
		}

		ItemGroup getItems()
		{
			return items;
		}

		ItemGroup getAlternative()
		{
			return alternative;
		}

		boolean isAlternativeFirst()
		{
			return alternativeFirst;
		}

		ItemGroup getRefills()
		{
			return refills;
		}

		int getRefillCharges()
		{
			return refillCharges;
		}

		/** Singular or plural name of the used-up item or charge. */
		String noun(int count)
		{
			return count == 1 ? one : many;
		}

		String plural()
		{
			return many;
		}

		String getAdvice()
		{
			return advice;
		}

		/** The place in the text, such as "for desert lizards", or null when the need applies everywhere. */
		String getWhere()
		{
			return where;
		}

		int getExemptVarbit()
		{
			return exemptVarbit;
		}

		String getExemptNote()
		{
			return exemptNote;
		}

		String getExemptWhere()
		{
			return exemptWhere;
		}
	}

	static final class Requirement
	{
		private final List<Need> needs;
		private final Unlock unlock;

		private Requirement(List<Need> needs, Unlock unlock)
		{
			this.needs = needs;
			this.unlock = unlock;
		}

		List<Need> getNeeds()
		{
			return needs;
		}

		/** The reward that finishes the monster for you, or null. */
		Unlock getUnlock()
		{
			return unlock;
		}
	}
}

package com.slayercompanion;

import java.util.Collections;
import java.util.EnumSet;
import java.util.Set;
import java.util.function.IntPredicate;
import lombok.AllArgsConstructor;
import lombok.Getter;
import lombok.Value;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;

/**
 * Items on the reward shop's Buy tab that can be worth points for a goal. The costs come from the cache at
 * runtime ({@link SlayerGameData#shopItems}). The names and costs here are fallbacks, and SlayerShopItemTest
 * keeps them equal to the cache dump. The tab also sells Slayer rings, broad bolts and broad arrows. Those are
 * used up, so the plan never recommends them. What each item is worth for a goal is in {@link SlayerSpend}.
 * <p>
 * Whether the player has one cannot be read from the game unless the bank is open, so it is sighted: an item
 * counts as owned once one of {@link #getOwnedIds} has been seen in the inventory, worn or in the bank.
 */
@Getter
@AllArgsConstructor
enum SlayerShopItem
{
	/** Wiki Herb sack: "Buying one requires level 58 in Herblore". The silklined sack is an upgrade of it. */
	HERB_SACK(ItemID.SLAYER_HERB_SACK, "Herb sack", 750, Skill.HERBLORE, 58, new int[]{
			ItemID.SLAYER_HERB_SACK, ItemID.SLAYER_HERB_SACK_OPEN, ItemID.SLAYER_HERB_SACK_SILK, ItemID.SLAYER_HERB_SACK_SILK_OPEN},
			"Tithe Farm sells it for 250 of its points"),
	/** The locked, divine and noted pouches all count. Wiki Rune pouch: "Players cannot own more than one rune pouch". */
	RUNE_POUCH(ItemID.BH_RUNE_POUCH, "Rune pouch", 750, null, 0, new int[]{
			ItemID.BH_RUNE_POUCH, ItemID.BH_RUNE_POUCH_TROUVER, ItemID.DIVINE_RUNE_POUCH, ItemID.DIVINE_RUNE_POUCH_TROUVER,
			ItemID.PROMISSORY_NOTE_RUNEPOUCH},
			"A rune pouch note from the Grand Exchange or 75 Last Man Standing points also gets you one"),
	/** Wiki Looting bag: it drops from "any monster in the Wilderness" except a few. */
	LOOTING_BAG(ItemID.LOOTING_BAG, "Looting bag", 10, null, 0, new int[]{
			ItemID.LOOTING_BAG, ItemID.LOOTING_BAG_OPEN, ItemID.PROMISSORY_NOTE_LOOTINGBAG},
			"Wilderness monsters drop it too");

	/** The item the Buy tab sells, the key of its cost in the cache. */
	private final int itemId;
	private final String fallbackName;
	private final int fallbackCost;
	/** The skill buying or using it needs, or null. */
	private final Skill skill;
	private final int level;
	/** Every item that means the player already has one. */
	private final int[] ownedIds;
	/** A cheaper way to get one, or another fact every line should carry. */
	private final String fact;

	/** Whether a container holds one, e.g. {@code container::contains}. */
	boolean seenIn(IntPredicate contains)
	{
		for (int id : ownedIds)
		{
			if (contains.test(id)) return true;
		}
		return false;
	}

	/** What has been seen of one character's items, kept per character. */
	@Value
	static class Sightings
	{
		static final Sightings NONE = new Sightings(Collections.<SlayerShopItem>emptySet(), false);

		/** Items seen in the inventory, worn or in the bank at least once. */
		Set<SlayerShopItem> seen;
		/** Whether the bank has been seen open at least once, so an item not in it is likely not owned. */
		boolean bankSeen;

		boolean owns(SlayerShopItem item)
		{
			return seen.contains(item);
		}

		Sightings with(Set<SlayerShopItem> more, boolean bank)
		{
			final Set<SlayerShopItem> all = seen.isEmpty() ? EnumSet.noneOf(SlayerShopItem.class) : EnumSet.copyOf(seen);
			all.addAll(more);
			return new Sightings(Collections.unmodifiableSet(all), bankSeen || bank);
		}

		/** The stored form: item names separated by commas, then "bank" when the bank has been seen. */
		String encode()
		{
			final StringBuilder sb = new StringBuilder();
			for (SlayerShopItem item : SlayerShopItem.values())
			{
				if (!seen.contains(item)) continue;
				if (sb.length() > 0) sb.append(',');
				sb.append(item.name());
			}
			if (bankSeen) sb.append(sb.length() > 0 ? "," : "").append(BANK);
			return sb.toString();
		}

		/** Reads {@link #encode}. Unknown names are skipped, so a removed item does not lose the rest. */
		static Sightings decode(String stored)
		{
			if (stored == null || stored.trim().isEmpty()) return NONE;
			final Set<SlayerShopItem> seen = EnumSet.noneOf(SlayerShopItem.class);
			boolean bank = false;
			for (String part : stored.split(","))
			{
				final String name = part.trim();
				if (BANK.equals(name))
				{
					bank = true;
					continue;
				}
				for (SlayerShopItem item : SlayerShopItem.values())
				{
					if (item.name().equals(name)) seen.add(item);
				}
			}
			return new Sightings(Collections.unmodifiableSet(seen), bank);
		}

		private static final String BANK = "bank";
	}
}

package com.slayercompanion;

import com.slayercompanion.SlayerPointsPlanner.Candidate;
import com.slayercompanion.SlayerPointsPlanner.Type;
import com.slayercompanion.data.SlayerTask;
import com.slayercompanion.data.TaskRating;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.function.ToDoubleFunction;
import lombok.Value;
import net.runelite.api.Skill;

/**
 * What each way of spending Slayer points does for the goal at the plan's master: a shop reward, a block or an
 * item from the Buy tab. Pure. The rate is the one the block advice uses, {@link SlayerGoalModel#rate(SlayerPool,
 * SlayerGoal)} over the master's list. A purchase's gain is how much it raises that rate, divided by the rate
 * today, so every purchase is on one scale: 0.02 adds 2% of today's rate, and below zero it costs. Skips are left
 * out of it. The reserve pays for them.
 * <p>
 * On the Slayer points routine the rate is points per hour over a whole cycle ({@link SlayerGoalModel#cycleRate}):
 * the filler tasks from Turael's list, which Aya and Spria share, and one milestone task from the plan master's
 * list. Blocks at both masters are valued on it, each at its own master's cost and within that list's open slots,
 * and the documented effects below apply to the tasks of both lists.
 * <ul>
 * <li>Blocks: each block a list's block advice puts forward, in its order, on top of the blocks it keeps and the
 * ones before it. The other list stays as it is today.</li>
 * <li>Everything else is valued with those blocks in place, so the plan never lengthens a task it also blocks.</li>
 * <li>Extensions: the list with the task at its extended amount from the cache (SlayerTask COL_EXTENSION_MIN_MAX
 * and COL_EXTENSION_ADDITIVE). That is more time on the task, which helps when the task is better than the
 * master's average for the goal. The average is the one the skip model leaves, as the master ranking and the
 * reserve assume the worst offers are skipped. Only a task rated good or better for the goal is ever worth it ("Only
 * extend tasks that have good value to them", wiki Slayer training, Task extension), and never one that section
 * advises against. For Slayer points the rate is tasks finished an hour, which a longer task always lowers.</li>
 * <li>Task unlocks and Chance of Heavy Frost: the list with the task added, or heavier. For XP an unlock whose task the
 * wiki's Slayer guide says not to unlock is never recommended and always named under Skip these.</li>
 * <li>Stop the Wyvern: fossil wyverns gone from the list, and a slot they took or would take used for the next
 * best block.</li>
 * <li>The rest: the documented effects below, each applied to the tasks it touches in the master's list, so the
 * value follows the list. They are judgments from the wiki pages named, read 4 October 2026. A speed-up raises
 * every goal's rate alike, since the same task in less time leaves more time for the rest.</li>
 * </ul>
 * Rewards that only matter for a task the player cannot be given yet are valued as if they could, and carry the
 * missing level, so the plan can list them under the unlocks that wait for a level.
 */
final class SlayerSpend
{
	/**
	 * A superior spawns once in 200 kills on task and gives "about ten times the hitpoints of the superior" in
	 * Slayer XP (wiki Superior slayer monster). The wiki's table puts that at 26 to 32 kills of the regular monster
	 * for most of them, so about 14% more Slayer XP on a task that has one.
	 */
	static final double SUPERIOR_XP = 1.14;
	/**
	 * Superiors roll the monster's drop table three times, have the imbued heart and eternal gem tables and drop
	 * clue scrolls ten times as often (wiki). Judgment: about 3% more loot on a task that has one.
	 */
	static final double SUPERIOR_LOOT = 1.03;
	/** A superior takes about as long as five regular kills. Judgment. */
	static final double SUPERIOR_TIME = 1.025;
	/**
	 * The helmet keeps the black mask's 16.67% accuracy and damage (15% for ranged and magic once imbued) on tasks
	 * that need a nose peg, earmuffs, facemask, spiny helmet or goggles (wiki Slayer helmet, Slayer training).
	 * Accuracy and damage together make kills about a quarter faster. Judgment.
	 */
	static final double HELMET_TIME = 0.8;
	/** Gargoyle Smasher and the like: "players will save a large amount of time" (wiki Slayer training). Judgment: 15%. */
	static final double FINISHER_TIME = 0.85;
	/** Slayer rings teleport to six task areas (cache, item params). Judgment: a minute less travel on tasks there. */
	static final double RING_MINUTES_SAVED = 1;
	/** Herb sack: room for herb drops on tasks that drop them (wiki Herb sack). Judgment: 10% more loot there. */
	static final double HERB_SACK_LOOT = 1.1;
	/** Rune pouch: three rune types in one slot, so fewer bank trips on barrage and burst tasks. Judgment: 5% faster. */
	static final double RUNE_POUCH_TIME = 0.95;
	/** Looting bag: more loot carried per trip on Krystilia's Wilderness tasks. Judgment: 5% more loot. */
	static final double LOOTING_BAG_LOOT = 1.05;

	/** Where a Slayer ring teleports to, as the dossier names the places (cache, Slayer ring (8) params). */
	private static final String[] RING_PLACES = {"stronghold slayer cave", "slayer tower", "fremennik slayer dungeon",
		"tarn", "mourner tunnels", "wyrmscraig"};

	/** Everything a valuation reads. */
	@Value
	static class Context
	{
		SlayerGoal goal;
		/** The plan's master spot, and the NPC the player finds there. */
		SlayerAssigner master;
		String npc;
		/** The master's list as the player gets it, with the current blocks. Null without the cache tables. */
		SlayerPool pool;
		/** Null without the cache tables. */
		SlayerGameData data;
		SlayerPool.Player player;
		/** Task rows on the master's block list. */
		Set<Integer> blockedRows;
		/** Open block slots with nothing in them. */
		int emptySlots;
		/** The block advice at the master. Null without the cache tables. */
		SlayerBlockAdvisor.Advice blocks;
		/** Rows of the rewards the player owns. */
		Set<Integer> owned;
		/** The dossier entry for a task's cache name, or null. */
		Function<String, SlayerTask> dossier;
		SlayerShopItem.Sightings items;
		/** The routine's filler tasks when the plan's master takes the milestone tasks of the points routine, else null. */
		Routine routine;
		/**
		 * The most of the plan master's offers the skip model skips, as a share, 0 when the goal skips nothing (Slayer
		 * points, Mortimer's choice). See {@link SlayerMasterRanker#skipBudget}.
		 */
		double skipBudget;
	}

	/**
	 * The Slayer points routine's filler tasks: every task but the milestone goes to Turael's spot. Turael, Aya and
	 * Spria share one block list.
	 */
	@Value
	static class Routine
	{
		/** Filler tasks per milestone task: 9 for every 10th task, 49 for every 50th. */
		int fillers;
		/** Points the milestone task pays on average. It sets the size of the rate, never a comparison. */
		double points;
		/** The NPC at Turael's spot, e.g. Aya. */
		String npc;
		/** Turael's list as the player gets it, with the current blocks. */
		SlayerPool pool;
		/** Open block slots with nothing in them on that list. */
		int emptySlots;
		/** The block advice for that list. */
		SlayerBlockAdvisor.Advice blocks;
	}

	/** A context with the lists everything but the blocks is valued against, and the rate gains are divided by. */
	private static final class Model
	{
		final Context c;
		/** The plan master's list with the advised blocks in place. */
		final SlayerPool pool;
		/** On the routine, the filler list with its advised blocks in place, else null. */
		final SlayerPool fillers;
		/** The goal's rate today. */
		final double base;

		Model(Context c)
		{
			this.c = c;
			this.pool = c.getPool() == null ? null : planned(c.getPool(), c.getBlocks());
			final Routine r = c.getRoutine();
			this.fillers = r == null || r.getPool() == null ? null : planned(r.getPool(), r.getBlocks());
			this.base = c.getPool() == null ? 0 : rate(c.getPool(), r == null ? null : r.getPool());
		}

		SlayerGoal goal()
		{
			return c.getGoal();
		}

		/** The goal's rate with this list at the plan's master and, on the routine, this filler list. */
		double rate(SlayerPool list, SlayerPool fillerList)
		{
			final Routine r = c.getRoutine();
			if (r == null || fillerList == null) return SlayerGoalModel.rate(list, goal());
			return SlayerGoalModel.cycleRate(fillerList, list, r.getFillers(), r.getPoints());
		}

		/** The gain from {@code before} to {@code after} at the plan's master, as a share of today's rate. */
		double gain(SlayerPool before, SlayerPool after)
		{
			return base <= 0 ? 0 : (rate(after, fillers) - rate(before, fillers)) / base;
		}

		/** {@link #gain} with the skip model's skips on both sides, as the master ranking and the reserve assume. */
		double skipGain(SlayerPool before, SlayerPool after)
		{
			if (base <= 0 || c.getSkipBudget() <= 0 || c.getRoutine() != null) return gain(before, after);
			return (withSkips(after, goal(), c.getMaster(), c.getSkipBudget()) - withSkips(before, goal(), c.getMaster(), c.getSkipBudget()))
					/ base;
		}

		/** The gain from a change in how tasks go, over {@code list} and, on the routine, the filler tasks too. */
		double effect(SlayerPool list, ToDoubleFunction<SlayerPool.Entry> time, ToDoubleFunction<SlayerPool.Entry> yield,
				ToDoubleFunction<SlayerPool.Entry> overhead)
		{
			if (base <= 0) return 0;
			final List<SlayerGoalModel.Offer> offers = SlayerGoalModel.offers(list);
			final Routine r = c.getRoutine();
			if (r == null || fillers == null)
			{
				return (SlayerGoalModel.rate(offers, goal(), time, yield, overhead) - SlayerGoalModel.rate(offers, goal(), 0, 0)) / base;
			}
			// Slayer points: what a task earns is its points, which no reward changes, so only the time counts
			final List<SlayerGoalModel.Offer> filler = SlayerGoalModel.offers(fillers);
			final double after = SlayerGoalModel.cycleRate(SlayerGoalModel.minutesPerTask(filler, time, overhead),
					SlayerGoalModel.minutesPerTask(offers, time, overhead), r.getFillers(), r.getPoints());
			final double before = SlayerGoalModel.cycleRate(SlayerGoalModel.minutesPerTask(filler),
					SlayerGoalModel.minutesPerTask(offers), r.getFillers(), r.getPoints());
			return (after - before) / base;
		}
	}

	/** A list with its advised blocks in place. */
	private static SlayerPool planned(SlayerPool list, SlayerBlockAdvisor.Advice blocks)
	{
		if (blocks == null) return list;
		final List<Integer> rows = new ArrayList<>(blocks.getKeepRows());
		rows.addAll(blocks.getAddRows());
		return list.withBlocks(rows);
	}

	private SlayerSpend()
	{
	}

	/**
	 * Every reward, block and item, valued. {@code names} gives a reward's name, null for one taken out of the
	 * shop. {@code costs} and {@code itemCosts} give the cache's costs, null when unknown, and an item cost below
	 * zero means the Buy tab no longer sells it.
	 */
	static List<Candidate> candidates(Context c, Function<SlayerReward, String> names, Function<SlayerReward, Integer> costs,
			Function<SlayerShopItem, Integer> itemCosts)
	{
		final Model m = new Model(c);
		final List<Candidate> out = new ArrayList<>();
		boolean extensionHurts = false;
		for (SlayerReward r : SlayerReward.values())
		{
			final String name = names.apply(r);
			// A reward taken out of the shop keeps its cache row but can no longer be bought
			if (name == null) continue;
			final Candidate candidate = reward(m, r, name, costs.apply(r));
			if (r.getKind() == SlayerReward.Kind.EXTENSION && c.getGoal() == SlayerGoal.POINTS && !candidate.isOwned())
			{
				// For points every extension hurts the same way, so one line says it for all of them
				extensionHurts |= candidate.getGain() < -SlayerPointsPlanner.NOTICEABLE && candidate.getLockedBy() == null;
				out.add(candidate.withGain(Double.NaN));
				continue;
			}
			out.add(candidate);
		}
		if (extensionHurts)
		{
			out.add(new Candidate(Type.SUMMARY, null, "Task extensions", -1, false, false, -1,
					"Longer tasks mean fewer tasks finished an hour, and points are paid per task.", null, null));
		}
		out.addAll(blocks(m));
		for (SlayerShopItem item : SlayerShopItem.values())
		{
			final Integer cost = itemCosts.apply(item);
			// A negative cost: the Buy tab no longer sells it
			if (cost == null || cost >= 0) out.add(item(m, item, cost));
		}
		return out;
	}

	// ---- shop rewards ----

	private static Candidate reward(Model m, SlayerReward r, String name, Integer cost)
	{
		final Context c = m.c;
		final boolean owned = c.getOwned().contains(r.getRow());
		final int price = cost == null ? r.getFallbackCost() : cost;
		if (r.getKind() == SlayerReward.Kind.COSMETIC)
		{
			return new Candidate(Type.REWARD, r, name, price, owned, true, 0, null, null, null);
		}
		final Valued v = owned ? NONE : value(m, r);
		final String lockedBy = v.lockedBy != null ? v.lockedBy : SlayerPlanBuilder.lockedBy(r, c.getPlayer());
		return new Candidate(Type.REWARD, r, name, price, owned, false, v.gain, sentence(v.why, r.getFact()), lockedBy, null, null, v.avoid);
	}

	/** A value with its reason and, for a task the player cannot be given yet, the level it waits for. */
	private static final class Valued
	{
		final double gain;
		final String why;
		final String lockedBy;
		/** The wiki's Slayer guide says not to buy it for the goal. */
		final boolean avoid;

		Valued(double gain, String why, String lockedBy)
		{
			this(gain, why, lockedBy, false);
		}

		Valued(double gain, String why, String lockedBy, boolean avoid)
		{
			this.gain = gain;
			this.why = why;
			this.lockedBy = lockedBy;
			this.avoid = avoid;
		}
	}

	private static final Valued NONE = new Valued(0, null, null);

	private static Valued value(Model m, SlayerReward r)
	{
		if (m.pool == null || m.c.getData() == null)
		{
			// Without the cache tables there is no list to judge against
			return new Valued(Double.NaN, null, null);
		}
		switch (r.getKind())
		{
			case EXTENSION:
				return extension(m, r);
			case TASK_UNLOCK:
				return taskUnlock(m, r);
			case WEIGHTING:
				return weighting(m, r);
			case BLOCKER:
				return blocker(m, r);
			case TASK_HELPER:
				return helper(m, r);
			default:
				return general(m, r);
		}
	}

	private static Valued extension(Model m, SlayerReward r)
	{
		final Map<Integer, SlayerGameData.Extension> extensions = new HashMap<>();
		for (SlayerGameData.Extension e : m.c.getData().extensions(r.getRow())) extensions.put(e.getTaskRow(), e);
		final Waiting w = waiting(m, extensions.keySet());
		if (w == null) return NONE;
		final SlayerPool after = w.pool.map(e ->
		{
			final SlayerGameData.Extension x = e.isOpen() && !e.isBoss() ? extensions.get(e.getTaskRow()) : null;
			return x == null ? e : e.withAmounts(x.extendedMin(e.getMinAmount()), x.extendedMax(e.getMaxAmount()));
		});
		final double gain = m.skipGain(w.pool, after);
		return new Valued(extendable(w.entry, m.goal()) ? gain : Math.min(0, gain),
				"More time on " + w.entry.getName() + ", " + judge(w.entry, m.goal()) + ".", w.lockedBy);
	}

	/** Ratings from this one up count as good for a goal. */
	static final int GOOD = 4;

	/**
	 * Whether more time on a task can be worth points at all: rated good or better for the goal, and not a task the
	 * wiki advises against extending.
	 */
	static boolean extendable(SlayerPool.Entry e, SlayerGoal goal)
	{
		return e.isRated() && e.rating(goal) >= GOOD && !e.getRating().isExtensionDiscouraged();
	}

	/** The goal's rate over a list when the skip model skips the worst offers, at most {@code budget} of them. */
	private static double withSkips(SlayerPool list, SlayerGoal goal, SlayerAssigner master, double budget)
	{
		return SlayerGoalModel.rateWithSkips(SlayerGoalModel.offers(list), goal, SlayerMasterRanker.bonus(master, goal), budget);
	}

	private static Valued taskUnlock(Model m, SlayerReward r)
	{
		final Context c = m.c;
		// The pool rows this reward gates at the master. Its related tasks can be in the list without it mattering.
		final Set<Integer> rows = new HashSet<>();
		for (SlayerGameData.PoolEntry e : c.getData().pool(c.getMaster().getId()))
		{
			if (e.getUnlockRow() == r.getRow()) rows.add(e.getTaskRow());
		}
		final List<SlayerPool.Entry> added = new ArrayList<>();
		String lockedBy = null;
		boolean anyOpen = false;
		for (SlayerPool.Entry e : m.pool.getEntries())
		{
			if (!rows.contains(e.getTaskRow()) || e.getStatus() != SlayerPool.Status.NEEDS_UNLOCK) continue;
			added.add(e);
			if (SlayerPool.meetsLevels(c.getMaster(), c.getData(), c.getPlayer(), e.getTaskRow())) anyOpen = true;
			else if (lockedBy == null) lockedBy = missingLevel(c, e.getTaskRow());
		}
		if (added.isEmpty()) return NONE;
		final boolean later = !anyOpen;
		// A task waiting for a level is judged as if the level were there, so the line can say what it would do
		final SlayerPool after = m.pool.map(e -> !rows.contains(e.getTaskRow()) || e.getStatus() != SlayerPool.Status.NEEDS_UNLOCK ? e
				: e.withStatus(c.getBlockedRows().contains(e.getTaskRow()) ? SlayerPool.Status.BLOCKED
				: later || SlayerPool.meetsLevels(c.getMaster(), c.getData(), c.getPlayer(), e.getTaskRow())
				? SlayerPool.Status.OPEN : SlayerPool.Status.NEEDS_LEVEL));
		final String list = possessive(c.getNpc()) + " list";
		// For XP the wiki's Slayer guide says not to unlock some tasks at all, the boss tasks unless for the helmet's bonus
		boolean dontUnlock = false;
		for (SlayerPool.Entry e : added) dontUnlock |= e.wikiAdvice(m.goal()) == TaskRating.XpAdvice.DONT_UNLOCK;
		if (dontUnlock)
		{
			final boolean bosses = added.get(0).isBoss();
			return new Valued(Math.min(0, m.gain(m.pool, after)), "The wiki's Slayer guide says not to unlock " + (bosses ? "boss tasks" : names(added))
					+ " for XP" + (bosses ? " unless you want the Slayer helmet's bonus on bosses." : "."), later ? lockedBy : null, true);
		}
		final String why;
		if (added.size() > 1) why = "Adds " + names(added) + " to " + list + ".";
		else if (added.get(0).isBoss()) why = "Adds boss tasks to " + list + ". Each is " + judge(added.get(0), m.goal()) + ".";
		else why = "Adds " + added.get(0).getName() + ", " + judge(added.get(0), m.goal()) + ", to " + list + ".";
		return new Valued(m.gain(m.pool, after), why, later ? lockedBy : null);
	}

	private static Valued weighting(Model m, SlayerReward r)
	{
		final Map<Integer, Integer> weights = new HashMap<>();
		for (SlayerGameData.Weighting x : m.c.getData().weightings(r.getRow())) weights.put(x.getTaskRow(), x.getWeight());
		final Waiting w = waiting(m, weights.keySet());
		if (w == null) return NONE;
		final SlayerPool after = w.pool.map(e -> e.isOpen() && weights.containsKey(e.getTaskRow()) ? e.withWeight(weights.get(e.getTaskRow())) : e);
		return new Valued(m.gain(w.pool, after), "Makes " + w.entry.getName() + ", " + judge(w.entry, m.goal())
				+ ", come up more often at " + m.c.getNpc() + ".", w.lockedBy);
	}

	/**
	 * Stop the Wyvern takes the task out of every list. Valued against the advised block list with and without it:
	 * a slot fossil wyverns take, or would take, then holds the next best block.
	 */
	private static Valued blocker(Model m, SlayerReward r)
	{
		final Context c = m.c;
		final Set<Integer> rows = new HashSet<>(c.getData().blockedBy(r.getRow()));
		if (rows.isEmpty()) rows.addAll(taskRows(c, r));
		boolean present = false;
		String lockedBy = null;
		for (SlayerPool.Entry e : c.getPool().getEntries())
		{
			if (!rows.contains(e.getTaskRow())) continue;
			if (e.isAssignable()) present = true;
			else if (e.getStatus() == SlayerPool.Status.NEEDS_LEVEL && lockedBy == null) lockedBy = missingLevel(c, e.getTaskRow());
		}
		final boolean later = !present && lockedBy != null;
		if (!present && !later) return NONE;
		final SlayerPool pool = later ? open(c.getPool(), rows) : c.getPool();
		final List<Integer> before = new ArrayList<>();
		if (c.getBlocks() != null)
		{
			before.addAll(c.getBlocks().getKeepRows());
			before.addAll(c.getBlocks().getAddRows());
		}
		final SlayerPool gone = pool.map(e -> rows.contains(e.getTaskRow()) && e.isAssignable() ? e.withStatus(SlayerPool.Status.REMOVED) : e);
		final List<Integer> fixed = new ArrayList<>(before);
		fixed.removeAll(rows);
		final int slots = c.getBlocks() == null ? 0 : c.getBlocks().getSlots();
		final List<SlayerPool.Entry> extra = SlayerGoalModel.bestBlocks(gone, m.goal(), fixed, Math.max(0, slots - fixed.size()));
		final List<Integer> after = new ArrayList<>(fixed);
		for (SlayerPool.Entry e : extra) after.add(e.getTaskRow());
		final StringBuilder why = new StringBuilder("Keeps ").append(name(c, rows)).append(" out of every master's list without a block slot.");
		boolean usesSlot = false;
		for (int row : rows) usesSlot |= before.contains(row);
		if (usesSlot && !extra.isEmpty())
		{
			why.append(" The slot its block takes can then hold ").append(extra.get(extra.size() - 1).getName()).append('.');
		}
		return new Valued(m.gain(pool.withBlocks(before), gone.withBlocks(after)), why.toString(), later ? lockedBy : null);
	}

	private static Valued helper(Model m, SlayerReward r)
	{
		final Set<Integer> rows = taskRows(m.c, r);
		final Waiting w = waiting(m, rows);
		// On the routine a filler task counts too, e.g. lizards at Turael's spot
		final SlayerPool.Entry filler = m.fillers == null ? null : firstOpen(m.fillers, rows);
		if (w == null && filler == null) return NONE;
		final boolean now = filler != null || w.lockedBy == null;
		final SlayerPool.Entry entry = w != null && w.lockedBy == null ? w.entry : filler != null ? filler : w.entry;
		final double gain = m.effect(now ? m.pool : w.pool, e -> rows.contains(e.getTaskRow()) ? FINISHER_TIME : 1, e -> 1,
				e -> SlayerGoalModel.OVERHEAD_MINUTES);
		return new Valued(gain, "Finishes " + entry.getName() + " for you at low health, so those tasks go faster.", now ? null : w.lockedBy);
	}

	/** The first rated task of these rows the list gives now, or null. */
	private static SlayerPool.Entry firstOpen(SlayerPool list, Set<Integer> rows)
	{
		for (SlayerPool.Entry e : list.getEntries())
		{
			if (rows.contains(e.getTaskRow()) && e.isOpen() && e.isRated()) return e;
		}
		return null;
	}

	private static Valued general(Model m, SlayerReward r)
	{
		final Context c = m.c;
		final SlayerGoal goal = m.goal();
		switch (r)
		{
			case BIGGER_AND_BADDER:
			{
				if (goal == SlayerGoal.POINTS)
				{
					return new Valued(0, "Superiors add time to a task without making it count for more.", null);
				}
				final double yield = goal == SlayerGoal.XP ? SUPERIOR_XP : SUPERIOR_LOOT;
				return new Valued(m.effect(m.pool, e -> superior(c, e) ? SUPERIOR_TIME : 1, e -> superior(c, e) ? yield : 1,
						e -> SlayerGoalModel.OVERHEAD_MINUTES),
						goal == SlayerGoal.XP ? "Superior monsters spawn on task and give a lot of Slayer XP."
								: "Superior monsters spawn on task, roll the drop table three times and can drop the imbued heart.", null);
			}
			case MALEVOLENT_MASQUERADE:
				return new Valued(m.effect(m.pool, e -> helmetTask(e) ? HELMET_TIME : 1, e -> 1, e -> SlayerGoalModel.OVERHEAD_MINUTES),
						"The Slayer helmet keeps the black mask's boost on tasks that need a nose peg, earmuffs, facemask or spiny helmet.", null);
			case RING_BLING:
				return new Valued(m.effect(m.pool, e -> 1, e -> 1,
						e -> ringTask(c, e) ? SlayerGoalModel.OVERHEAD_MINUTES - RING_MINUTES_SAVED : SlayerGoalModel.OVERHEAD_MINUTES),
						"Make Slayer rings, which teleport to the Slayer Tower, the Stronghold Slayer Cave and other task areas.", null);
			case TASK_STORAGE:
				// Wiki Slayer training: "Purchasing Task Storage is up to the player's preference"
				return new Valued(0, "It splits up long tasks, which the wiki leaves to preference.", null);
			case DOUBLE_TROUBLE:
				return new Valued(0, "It only helps if you kill the Grotesque Guardians on gargoyle tasks.", null);
			case BROADER_FLETCHING:
				return new Valued(0, "It is for Fletching. Broad bolts are sold for points and leaf-bladed weapons work too.", null);
			case DULY_NOTED:
				return new Valued(0, "Noted mithril bars only save space for ironmen.", null);
			default:
				return NONE;
		}
	}

	// ---- blocks ----

	/** The block advice's blocks at the plan's master and, on the routine, at the filler master. */
	private static List<Candidate> blocks(Model m)
	{
		final List<Candidate> out = new ArrayList<>();
		final Context c = m.c;
		if (c.getPool() == null) return out;
		final Routine r = c.getRoutine();
		final SlayerPool fillersToday = r == null ? null : r.getPool();
		out.addAll(blocks(m, SlayerMaster.forAssigner(c.getMaster()), c.getBlocks(), c.getPool(), c.getEmptySlots(), c.getNpc(),
				fillersToday == null ? null : "Milestone tasks get quicker on average.", list -> m.rate(list, fillersToday)));
		if (fillersToday != null)
		{
			out.addAll(blocks(m, SlayerMaster.TURAEL, r.getBlocks(), fillersToday, r.getEmptySlots(), r.getNpc(),
					"Filler tasks get quicker on average.", list -> m.rate(c.getPool(), list)));
		}
		return out;
	}

	/**
	 * One list's blocks in its advice's order, each valued on top of the blocks it keeps and the ones before it.
	 *
	 * @param effect what the blocks do on the routine, or null
	 * @param rate the goal's rate with this list as given and the other list as it is today
	 */
	private static List<Candidate> blocks(Model m, SlayerMaster list, SlayerBlockAdvisor.Advice advice, SlayerPool pool, int emptySlots,
			String npc, String effect, ToDoubleFunction<SlayerPool> rate)
	{
		final List<Candidate> out = new ArrayList<>();
		if (advice == null) return out;
		final List<Integer> blocked = new ArrayList<>(advice.getKeepRows());
		double previous = rate.applyAsDouble(pool.withBlocks(blocked));
		for (int i = 0; i < advice.getAddRows().size(); i++)
		{
			final SlayerPool.Entry e = pool.find(advice.getAddRows().get(i));
			blocked.add(e.getTaskRow());
			final double next = rate.applyAsDouble(pool.withBlocks(blocked));
			final int misfit = i - Math.max(0, emptySlots);
			final String note = misfit >= 0 && misfit < advice.getMisfits().size()
					? "Unblock " + advice.getMisfits().get(misfit).getName() + " first to free its slot." : null;
			out.add(new Candidate(Type.BLOCK, null, blockName(e, npc, m.goal()), advice.getCost(), false, false,
					m.base <= 0 ? 0 : (next - previous) / m.base, blockWhy(e, npc, m.goal(), effect), null, note, list));
			previous = next;
		}
		return out;
	}

	/** "Block Kurask", or for Slayer points, whose plan can hold blocks at two masters, "Block Kurask at Konar". */
	static String blockName(SlayerPool.Entry e, String npc, SlayerGoal goal)
	{
		return "Block " + e.getName() + (goal == SlayerGoal.POINTS ? " at " + npc : "");
	}

	/**
	 * Why a block helps. For Slayer points a block pays in time, and the block advice only blocks a task that takes
	 * longer than the average task left on the list, however quick its rating.
	 */
	static String blockWhy(SlayerPool.Entry e, String npc, SlayerGoal goal, String effect)
	{
		if (goal != SlayerGoal.POINTS) return "Stops " + npc + " giving " + e.getName() + ", " + judge(e, goal) + ".";
		final String why = e.getName() + " take longer than the average task at " + npc + ".";
		return effect == null ? why : why + " " + effect;
	}

	/**
	 * What blocking {@code row} on the filler list does for the routine's rate, as a share of today's: on top of the
	 * blocks {@code kept} there, with the milestone master's list as it is.
	 */
	static double fillerBlockGain(Routine r, SlayerPool milestone, List<Integer> kept, int row)
	{
		if (r == null || r.getPool() == null || milestone == null) return 0;
		final double base = SlayerGoalModel.cycleRate(r.getPool(), milestone, r.getFillers(), r.getPoints());
		if (base <= 0) return 0;
		final List<Integer> with = new ArrayList<>(kept);
		with.add(row);
		return (SlayerGoalModel.cycleRate(r.getPool().withBlocks(with), milestone, r.getFillers(), r.getPoints())
				- SlayerGoalModel.cycleRate(r.getPool().withBlocks(kept), milestone, r.getFillers(), r.getPoints())) / base;
	}

	// ---- the Buy tab ----

	private static Candidate item(Model m, SlayerShopItem item, Integer cost)
	{
		final Context c = m.c;
		final boolean owned = c.getItems().owns(item);
		final int price = cost == null ? item.getFallbackCost() : cost;
		final String lockedBy = item.getSkill() != null && c.getPlayer().level(item.getSkill().ordinal()) < item.getLevel()
				? item.getLevel() + " " + item.getSkill().getName() : null;
		final String seen = owned ? null : c.getItems().isBankSeen()
				? "Could not tell if you have one. None has been seen in your bank, inventory or worn items."
				: "Could not tell if you have one. Open your bank once so the plan can look.";
		final SlayerGoal goal = m.goal();
		double gain = 0;
		String why = null;
		if (m.pool != null)
		{
			switch (item)
			{
				case HERB_SACK:
					if (goal == SlayerGoal.PROFIT)
					{
						gain = m.effect(m.pool, e -> 1, e -> herbTask(c, e) ? HERB_SACK_LOOT : 1, e -> SlayerGoalModel.OVERHEAD_MINUTES);
						why = "Holds the herbs that " + example(m, e -> herbTask(c, e)) + " drop.";
					}
					break;
				case RUNE_POUCH:
					gain = m.effect(m.pool, e -> barrageTask(c, e) ? RUNE_POUCH_TIME : 1, e -> 1, e -> SlayerGoalModel.OVERHEAD_MINUTES);
					why = "Frees inventory space when you barrage " + example(m, e -> barrageTask(c, e)) + ".";
					break;
				case LOOTING_BAG:
					if (goal == SlayerGoal.PROFIT && c.getMaster() == SlayerAssigner.KRYSTILIA)
					{
						gain = m.effect(m.pool, e -> 1, e -> LOOTING_BAG_LOOT, e -> SlayerGoalModel.OVERHEAD_MINUTES);
						why = "Carries more loot on " + possessive(c.getNpc()) + " Wilderness tasks.";
					}
					break;
				default:
					break;
			}
		}
		return new Candidate(Type.ITEM, null, item.getFallbackName(), price, owned, false, m.pool == null ? Double.NaN : gain,
				sentence(why, item.getFact()), lockedBy, seen);
	}

	// ---- the goal model ----

	/**
	 * The extension of the task in progress at its master, as a share of the goal's rate there, valued as the plan
	 * values extensions: against the rate the skip model leaves, and never above 0 for a task an extension cannot
	 * be worth. 0 when it has none.
	 *
	 * @param skipBudget the most of the master's offers the skip model skips, 0 when the goal skips nothing
	 */
	static double extensionGain(SlayerPool pool, SlayerGameData data, int taskRow, SlayerGoal goal, double skipBudget)
	{
		final SlayerGameData.Extension x = data == null ? null : data.extensionOf(taskRow);
		final SlayerPool.Entry entry = pool == null ? null : pool.find(taskRow);
		if (x == null || entry == null || !entry.isOpen() || entry.isBoss()) return 0;
		final SlayerPool after = pool.map(e -> e.getTaskRow() == taskRow
				? e.withAmounts(x.extendedMin(e.getMinAmount()), x.extendedMax(e.getMaxAmount())) : e);
		double gain = change(pool, after, goal);
		if (skipBudget > 0)
		{
			final double before = withSkips(pool, goal, pool.getMaster(), skipBudget);
			gain = before <= 0 ? 0 : (withSkips(after, goal, pool.getMaster(), skipBudget) - before) / before;
		}
		return extendable(entry, goal) ? gain : Math.min(0, gain);
	}

	/** The share by which the goal's rate rises from {@code before} to {@code after}. */
	static double change(SlayerPool before, SlayerPool after, SlayerGoal goal)
	{
		final double base = SlayerGoalModel.rate(before, goal);
		return base <= 0 ? 0 : (SlayerGoalModel.rate(after, goal) - base) / base;
	}

	/** A list to judge a task reward against: as it is, or with the task opened when it only waits for a level. */
	private static final class Waiting
	{
		final SlayerPool pool;
		final SlayerPool.Entry entry;
		final String lockedBy;

		Waiting(SlayerPool pool, SlayerPool.Entry entry, String lockedBy)
		{
			this.pool = pool;
			this.entry = entry;
			this.lockedBy = lockedBy;
		}
	}

	/**
	 * The list to value a reward for these tasks against, or null when the master never gives them, they are
	 * blocked or advised for a block, or they need an unlock or are removed. A task waiting for a level is opened,
	 * with the level named.
	 */
	private static Waiting waiting(Model m, Set<Integer> rows)
	{
		SlayerPool.Entry open = null;
		SlayerPool.Entry level = null;
		for (SlayerPool.Entry e : m.pool.getEntries())
		{
			if (!rows.contains(e.getTaskRow()) || !e.isRated()) continue;
			if (e.isOpen() && open == null) open = e;
			if (e.getStatus() == SlayerPool.Status.NEEDS_LEVEL && level == null) level = e;
		}
		if (open != null) return new Waiting(m.pool, open, null);
		if (level == null) return null;
		final SlayerPool opened = open(m.pool, rows);
		return new Waiting(opened, opened.find(level.getTaskRow()), missingLevel(m.c, level.getTaskRow()));
	}

	private static SlayerPool open(SlayerPool pool, Set<Integer> rows)
	{
		return pool.map(e -> rows.contains(e.getTaskRow()) && e.getStatus() == SlayerPool.Status.NEEDS_LEVEL
				? e.withStatus(SlayerPool.Status.OPEN) : e);
	}

	/** The cache rows of a reward's task, by its related tasks and its name. */
	private static Set<Integer> taskRows(Context c, SlayerReward r)
	{
		final Set<Integer> rows = new HashSet<>();
		final SlayerGameData.Unlock unlock = c.getData().unlock(r.getRow());
		if (unlock != null) rows.addAll(unlock.getRelatedTaskRows());
		if (r.getTask() != null) rows.addAll(c.getData().taskRowsNamed(r.getTask()));
		return rows;
	}

	/** The first level the player lacks for a task, e.g. "87 Slayer" or "combat level 80", or null. */
	static String missingLevel(Context c, int row)
	{
		return missingLevel(c.getData(), c.getPlayer(), c.getMaster(), row);
	}

	static String missingLevel(SlayerGameData data, SlayerPool.Player player, SlayerAssigner master, int row)
	{
		for (SlayerGameData.StatLevel s : data.statsAll(row))
		{
			if (player.level(s.getStat()) < s.getLevel()) return s.getLevel() + " " + skill(s.getStat());
		}
		final List<SlayerGameData.StatLevel> any = data.statsAny(row);
		boolean met = any.isEmpty();
		for (SlayerGameData.StatLevel s : any) met |= player.level(s.getStat()) >= s.getLevel();
		if (!met)
		{
			final List<String> options = new ArrayList<>();
			for (SlayerGameData.StatLevel s : any) options.add(s.getLevel() + " " + skill(s.getStat()));
			return String.join(" or ", options);
		}
		final boolean combatChecked = !player.isCombatChecksOff() && master != SlayerAssigner.KRYSTILIA;
		if (combatChecked && player.getCombatLevel() < data.combatLevel(row)) return "combat level " + data.combatLevel(row);
		return null;
	}

	private static String skill(int stat)
	{
		return stat >= 0 && stat < Skill.values().length ? Skill.values()[stat].getName() : "stat " + stat;
	}

	// ---- which tasks an effect touches ----

	private static boolean superior(Context c, SlayerPool.Entry e)
	{
		final SlayerTask task = c.getDossier().apply(e.getName());
		return task != null && task.isHasSuperior();
	}

	/** Tasks whose gear needs a Slayer helmet can stand in for, from the gear check's own table. */
	static boolean helmetTask(SlayerPool.Entry e)
	{
		return SlayerRequirements.helmetStandsIn(e.getName());
	}

	private static boolean ringTask(Context c, SlayerPool.Entry e)
	{
		final SlayerTask task = c.getDossier().apply(e.getName());
		final String where = task == null || task.getBestLocation() == null ? "" : task.getBestLocation().toLowerCase(Locale.ROOT);
		for (String place : RING_PLACES)
		{
			if (where.contains(place)) return true;
		}
		return false;
	}

	private static boolean herbTask(Context c, SlayerPool.Entry e)
	{
		final SlayerTask task = c.getDossier().apply(e.getName());
		return task != null && task.getNotableDrops() != null && task.getNotableDrops().toLowerCase(Locale.ROOT).contains("herb");
	}

	private static boolean barrageTask(Context c, SlayerPool.Entry e)
	{
		final SlayerTask task = c.getDossier().apply(e.getName());
		final String style = task == null || task.getKillStyle() == null ? "" : task.getKillStyle().toLowerCase(Locale.ROOT);
		return style.contains("barrage") || style.contains("burst");
	}

	/** "Aberrant Spectres and Nechryael", the two commonest open tasks that match, or "some tasks". */
	private static String example(Model m, Predicate<SlayerPool.Entry> match)
	{
		final List<SlayerPool.Entry> found = new ArrayList<>();
		for (SlayerPool.Entry e : m.pool.open())
		{
			if (e.isRated() && match.test(e)) found.add(e);
		}
		found.sort((a, b) -> a.getWeight() != b.getWeight() ? b.getWeight() - a.getWeight() : a.getName().compareTo(b.getName()));
		if (found.isEmpty()) return "some tasks";
		return found.size() == 1 ? found.get(0).getName() : found.get(0).getName() + " and " + found.get(1).getName();
	}

	// ---- words ----

	/**
	 * "a good XP task", "a poor money task", or for Slayer points how long it takes, "a slow task". For XP a task the
	 * wiki's Slayer guide gives advice on is described by that advice: its rating only says how fast the XP comes.
	 */
	static String judge(SlayerPool.Entry e, SlayerGoal goal)
	{
		if (!e.isRated()) return "a task not rated yet";
		final TaskRating.XpAdvice advice = e.wikiAdvice(goal);
		if (advice != null) return "a task " + wikiClause(advice);
		final int rating = e.rating(goal);
		switch (goal)
		{
			case XP:
				return article(quality(rating)) + " XP task";
			case PROFIT:
				return article(quality(rating)) + " money task";
			default:
				return speed(rating);
		}
	}

	/** "the wiki's Slayer guide says to skip or block for XP", to follow "a task". */
	private static String wikiClause(TaskRating.XpAdvice advice)
	{
		switch (advice)
		{
			case DO:
				return "the wiki's Slayer guide says to do for XP";
			case SKIP:
				return "the wiki's Slayer guide says to skip or block for XP";
			default:
				return "the wiki's Slayer guide says not to unlock for XP";
		}
	}

	/** The wiki's advice on a task for XP as a sentence, e.g. "The wiki's Slayer guide says to skip or block it for XP." */
	static String wikiSays(TaskRating.XpAdvice advice)
	{
		switch (advice)
		{
			case DO:
				return "The wiki's Slayer guide says to do it for XP.";
			case SKIP:
				return "The wiki's Slayer guide says to skip or block it for XP.";
			default:
				return "The wiki's Slayer guide says not to unlock it for XP.";
		}
	}

	/** Ratings as words, never as numbers. */
	static String quality(int rating)
	{
		switch (rating)
		{
			case 5:
				return "excellent";
			case 4:
				return "good";
			case 3:
				return "fair";
			case 2:
				return "poor";
			default:
				return "very poor";
		}
	}

	/** A speed rating as words. */
	static String speed(int rating)
	{
		switch (rating)
		{
			case 5:
				return "a very quick task";
			case 4:
				return "a quick task";
			case 3:
				return "a task of average length";
			case 2:
				return "a slow task";
			default:
				return "a very slow task";
		}
	}

	private static String article(String word)
	{
		return ("aeiou".indexOf(word.charAt(0)) >= 0 ? "an " : "a ") + word;
	}

	static String possessive(String npc)
	{
		return npc.endsWith("s") ? npc + "'" : npc + "'s";
	}

	private static String name(Context c, Set<Integer> rows)
	{
		final List<String> names = new ArrayList<>();
		for (SlayerPool.Entry e : c.getPool().getEntries())
		{
			if (rows.contains(e.getTaskRow()) && !names.contains(e.getName())) names.add(e.getName());
		}
		if (names.isEmpty())
		{
			for (int row : rows)
			{
				final String n = c.getData().taskName(row);
				if (n != null && !names.contains(n)) names.add(n);
			}
		}
		return names.isEmpty() ? "the task" : join(names);
	}

	private static String names(Collection<SlayerPool.Entry> entries)
	{
		final List<String> names = new ArrayList<>();
		for (SlayerPool.Entry e : entries) names.add(e.getName());
		return join(names);
	}

	/** "A", "A and B", "A, B and C". */
	static String join(List<String> parts)
	{
		if (parts.size() <= 1) return parts.isEmpty() ? "" : parts.get(0);
		return String.join(", ", parts.subList(0, parts.size() - 1)) + " and " + parts.get(parts.size() - 1);
	}

	/** The reason and the reward's own fact as sentences, or null when there is neither. */
	private static String sentence(String why, String fact)
	{
		if (why == null) return fact == null ? null : fact + ".";
		return fact == null ? why : why + " " + fact + ".";
	}
}

package com.slayercompanion;

import java.util.List;
import java.util.function.IntUnaryOperator;
import lombok.Value;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * The task in progress, read from the game the same way RuneLite's own Slayer plugin reads it (SlayerPlugin.updateTask
 * in client 1.13.1), so the name comes out exactly as that plugin would store it. The dossier, the gear tables and the
 * places are keyed by those names. Slayer Sensei needs no other plugin for its task. That plugin reads the tables
 * only when one of its varps changes. This reader is asked every tick, so it keeps the last name it found and reads
 * the tables again only when SLAYER_TARGET or the boss id changes. Pure apart from the reads it is given, which belong
 * on the client thread.
 */
final class SlayerTaskReader
{
	/** The SLAYER_TARGET value of a boss task. Which boss it is, SLAYER_TARGET_BOSSID says. */
	static final int BOSS_TASK = 98;
	/** SLAYER_MODIFIER_ID of "Slayer Quantity Change" (SlayerModifiers table), which moves the amount assigned. */
	static final int QUANTITY_MODIFIER = 2;

	/** The task as the game holds it. */
	@Value
	static class Task
	{
		/** The name RuneLite's Slayer plugin stores, such as "Abyssal Demons" or "The Alchemical Hydra". */
		String name;
		/** Kills left (SLAYER_COUNT). */
		int amount;
		/** Kills assigned (SLAYER_COUNT_ORIGINAL), with a quantity modifier counted in, as that plugin counts it. */
		int initialAmount;
	}

	/** The SLAYER_TARGET and boss id of {@link #lastName}. */
	private int lastTarget;
	private int lastBossId;
	/** The name the last lookup found, or null when none is kept. */
	private String lastName;

	/**
	 * The task, or null without one. Null too while the tables have no row for the target, so nothing shows until the
	 * game's values can be read. A table read that throws goes to the caller and keeps nothing.
	 */
	Task read(IntUnaryOperator varps, IntUnaryOperator varbits, SlayerGameData.Db db)
	{
		final int amount = varps.applyAsInt(VarPlayerID.SLAYER_COUNT);
		if (amount <= 0) return null;
		final String name = name(db, varps.applyAsInt(VarPlayerID.SLAYER_TARGET), varbits.applyAsInt(VarbitID.SLAYER_TARGET_BOSSID));
		return name == null ? null : new Task(name, amount, initialAmount(varps, varbits));
	}

	/**
	 * {@link #taskName}, kept for the last SLAYER_TARGET and boss id it found a name for, so the tables are read only when
	 * one of them changes. A lookup that finds no name, or throws, is never kept, so the next call looks again.
	 */
	String name(SlayerGameData.Db db, int target, int bossId)
	{
		if (lastName != null && target == lastTarget && bossId == lastBossId) return lastName;
		final String name = taskName(db, target, bossId);
		if (name == null || name.isEmpty()) return null;
		lastTarget = target;
		lastBossId = bossId;
		lastName = name;
		return name;
	}

	/** Forgets the name kept. The session ended. */
	void clear()
	{
		lastName = null;
	}

	/**
	 * The stored name for a SLAYER_TARGET value. A boss task leads from SLAYER_TARGET_BOSSID through the boss list
	 * (SlayerTaskSublist) to its SlayerTask row, any other task goes straight to the SlayerTask row with that id. The
	 * name is the row's COL_NAME_UPPERCASE, unchanged. Null when the tables have no such row.
	 */
	static String taskName(SlayerGameData.Db db, int target, int bossId)
	{
		final int row;
		if (target == BOSS_TASK)
		{
			final List<Integer> bosses = db.rowsByValue(DBTableID.SlayerTaskSublist.ID, DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID,
				0, bossId);
			if (bosses.isEmpty()) return null;
			final Object[] task = db.field(bosses.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0);
			if (task.length == 0 || !(task[0] instanceof Integer)) return null;
			row = (Integer) task[0];
		}
		else
		{
			final List<Integer> tasks = db.rowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, target);
			if (tasks.isEmpty()) return null;
			row = tasks.get(0);
		}
		final Object[] name = db.field(row, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0);
		return name.length == 0 || !(name[0] instanceof String) ? null : (String) name[0];
	}

	/** SLAYER_COUNT_ORIGINAL, moved up or down by a quantity modifier the way RuneLite's Slayer plugin moves it. */
	static int initialAmount(IntUnaryOperator varps, IntUnaryOperator varbits)
	{
		int initial = varps.applyAsInt(VarPlayerID.SLAYER_COUNT_ORIGINAL);
		if (varbits.applyAsInt(VarbitID.SLAYER_MODIFIER_ID) == QUANTITY_MODIFIER)
		{
			final int change = varbits.applyAsInt(VarbitID.SLAYER_MODIFIER_VALUE);
			initial += varbits.applyAsInt(VarbitID.SLAYER_MODIFIER_NEGATIVE) == 1 ? -change : change;
		}
		return initial;
	}
}

package com.slayercompanion;

import com.slayercompanion.data.SlayerTask;
import com.slayercompanion.data.TaskRating;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Skill;

/**
 * The dossier's "Verdict" and "Assigned by" lines, and the dossier's fields in a few words for the compact sidebar.
 * Pure, so the wording is tested without Swing.
 */
final class SlayerTaskText
{
	/** The longest compact item, about what fits on a line of the compact sidebar. A longer field is left to the tooltip. */
	static final int MAX_ITEM = 34;
	/** The longest start of the dossier's place the compact sidebar shows. */
	static final int SHORT_PLACE = 34;
	static final String SUPERIOR_ITEM = "Superior possible";
	private static final Pattern PRAYER = Pattern.compile("\\b(Melee|Missiles|Magic)\\b");
	private static final Pattern SPELLS = Pattern.compile("\\b(air|water|earth|fire) spells\\b");
	private static final Pattern ATTACK = Pattern.compile("\\b(?:weak(?:est)? to|low) (crush|slash|stab)\\b|\\b(crush|slash|stab) attacks\\b");
	/** Where the name of a place ends in the dossier's text. */
	private static final Pattern PLACE_END = Pattern.compile("[(,;.]| or | for ");

	private SlayerTaskText()
	{
	}

	/**
	 * The Verdict line: the task judged for the goal in words from its ratings, then the dossier's note. Krystilia's
	 * Wilderness version is judged by its own ratings. Ratings are never shown as numbers. Where the wiki's Slayer guide
	 * gives advice on the task for XP, the XP part cites it, except on Krystilia's Wilderness tasks, which it does not
	 * cover.
	 */
	static String verdict(SlayerTask task, SlayerGoal goal, boolean wilderness)
	{
		return verdict(task, goal, wilderness, false);
	}

	/**
	 * The Verdict line for the task in progress, given by {@code master}, or null for an unknown one. Under Slayer
	 * points a filler task from Turael's spot or Spria is judged by its filler time, as the routine's block advice is,
	 * rather than by its general speed.
	 */
	static String verdict(SlayerTask task, SlayerGoal goal, SlayerAssigner master)
	{
		final boolean wilderness = master != null && master.getStreak() == SlayerAssigner.Streak.WILDERNESS;
		return verdict(task, goal, wilderness, master == SlayerAssigner.TURAEL || master == SlayerAssigner.SPRIA);
	}

	private static String verdict(SlayerTask task, SlayerGoal goal, boolean wilderness, boolean fillerMaster)
	{
		if (task == null) return null;
		TaskRating rating = task.getRating();
		final boolean wild = wilderness && rating != null && rating.getWilderness() != null;
		if (wild) rating = rating.getWilderness();
		final String first = fillerMaster && goal == SlayerGoal.POINTS && rating != null && rating.getFiller() != null
				? filler(rating.getFiller()) : null;
		final String judged = judge(rating, goal, !wilderness, first);
		final String line = judged == null ? "Not rated yet." : (wild ? "In the Wilderness: " + lower(judged) : judged);
		final String note = task.getNote();
		return note == null || note.trim().isEmpty() ? line : line + "\n" + note.trim();
	}

	/**
	 * A filler task in words from its filler time, never the minutes: "A quick filler task.", "A filler task of average
	 * length." or "One of the slower filler tasks.", by the cut points next to the scale in {@link TaskRating.Filler}.
	 */
	static String filler(TaskRating.Filler filler)
	{
		if (filler.getMinutes() <= TaskRating.Filler.QUICK) return "A quick filler task.";
		if (filler.getMinutes() >= TaskRating.Filler.SLOW) return "One of the slower filler tasks.";
		return "A filler task of average length.";
	}

	/**
	 * "Good for XP. Fair for profit. Slow to finish." with the goal first. For Slayer points the speed leads, since
	 * points come per task. Null when the rating is missing or incomplete.
	 *
	 * @param wikiAdvice whether the XP part may cite the wiki's advice on the task instead of the rating
	 * @param pointsFirst for Slayer points, the first sentence in place of the speed, or null
	 */
	private static String judge(TaskRating rating, SlayerGoal goal, boolean wikiAdvice, String pointsFirst)
	{
		if (rating == null || !rating.isComplete()) return null;
		final String xp = wikiAdvice && rating.getXpAdvice() != null ? SlayerSpend.wikiSays(rating.getXpAdvice())
				: capitalize(SlayerSpend.quality(rating.getXp())) + " for XP.";
		final String gp = capitalize(SlayerSpend.quality(rating.getGp())) + " for profit.";
		final String speed = speed(rating.getSpeed());
		switch (goal)
		{
			case XP:
				return xp + " " + gp + " " + speed + ".";
			case PROFIT:
				return gp + " " + xp + " " + speed + ".";
			default:
				final String first = pointsFirst != null ? pointsFirst
						: speed + ", so " + SlayerSpend.quality(rating.getSpeed()) + " for Slayer points.";
				return first + " " + xp + " " + gp;
		}
	}

	private static String speed(int rating)
	{
		switch (rating)
		{
			case 5:
				return "Very quick to finish";
			case 4:
				return "Quick to finish";
			case 3:
				return "Takes an average time";
			case 2:
				return "Slow to finish";
			default:
				return "Very slow to finish";
		}
	}

	/**
	 * The Assigned by line from the cache: each master that gives the task with its weight, the unlocks some of
	 * them need, and the levels the task needs. Null when the cache has no master giving it, so the dossier's own
	 * text stays.
	 *
	 * @param npc the NPC the player finds at a master's spot, e.g. Kuradal
	 */
	static String assignedBy(SlayerGameData data, int taskRow, Function<SlayerAssigner, String> npc)
	{
		if (data == null || taskRow < 0) return null;
		final List<String> weights = new ArrayList<>();
		final Map<Integer, List<String>> byUnlock = new LinkedHashMap<>();
		boolean wilderness = false;
		for (SlayerAssigner master : SlayerAssigner.values())
		{
			for (SlayerGameData.PoolEntry e : data.pool(master.getId()))
			{
				if (e.getTaskRow() != taskRow) continue;
				weights.add(npc.apply(master) + " " + e.getWeight());
				if (e.getUnlockRow() >= 0) byUnlock.computeIfAbsent(e.getUnlockRow(), k -> new ArrayList<>()).add(npc.apply(master));
				wilderness |= master == SlayerAssigner.KRYSTILIA;
			}
		}
		if (weights.isEmpty()) return null;
		final StringBuilder sb = new StringBuilder("Weight at each master: ").append(SlayerSpend.join(weights)).append('.');
		for (Map.Entry<Integer, List<String>> u : byUnlock.entrySet())
		{
			final SlayerGameData.Unlock unlock = data.unlock(u.getKey());
			final String name = unlock == null || unlock.getName() == null ? "an unlock" : unlock.getName();
			sb.append(' ').append(SlayerSpend.join(u.getValue())).append(u.getValue().size() == 1 ? " needs " : " need ")
					.append(name).append(" first.");
		}
		final String needs = needs(data, taskRow);
		if (needs != null) sb.append(" Needs ").append(needs).append('.');
		if (wilderness) sb.append(" Krystilia's version is in the Wilderness.");
		return sb.toString();
	}

	/**
	 * "87 Slayer, 50 Magic and combat level 80", with a choice of stats last, as in "63 Slayer and combat level 60,
	 * and 60 Strength or 60 Agility". Null when the task needs nothing.
	 */
	private static String needs(SlayerGameData data, int taskRow)
	{
		final List<String> parts = new ArrayList<>();
		for (SlayerGameData.StatLevel s : data.statsAll(taskRow))
		{
			parts.add(s.getLevel() + " " + skill(s.getStat()));
		}
		if (data.combatLevel(taskRow) > 0) parts.add("combat level " + data.combatLevel(taskRow));
		final List<String> any = new ArrayList<>();
		for (SlayerGameData.StatLevel s : data.statsAny(taskRow))
		{
			any.add(s.getLevel() + " " + skill(s.getStat()));
		}
		final String either = String.join(" or ", any);
		if (parts.isEmpty()) return either.isEmpty() ? null : either;
		return SlayerSpend.join(parts) + (either.isEmpty() ? "" : ", and " + either);
	}

	private static String skill(int stat)
	{
		return stat >= 0 && stat < Skill.values().length ? Skill.values()[stat].getName() : "stat " + stat;
	}

	// ---- the compact sidebar ----

	/**
	 * The Verdict's part for the goal in a few words: "Good for XP", "Wiki: skip or block for XP", "Quick to finish" or for
	 * a filler task under Slayer points "Slow filler". The other goals and the note stay in {@link #verdict}.
	 */
	static String compactVerdict(SlayerTask task, SlayerGoal goal, SlayerAssigner master)
	{
		if (task == null) return null;
		final boolean wilderness = master != null && master.getStreak() == SlayerAssigner.Streak.WILDERNESS;
		TaskRating rating = task.getRating();
		final boolean wild = wilderness && rating != null && rating.getWilderness() != null;
		if (wild) rating = rating.getWilderness();
		if (rating == null || !rating.isComplete()) return "Not rated yet";
		final String judged;
		if (goal == SlayerGoal.POINTS && (master == SlayerAssigner.TURAEL || master == SlayerAssigner.SPRIA) && rating.getFiller() != null)
		{
			final int minutes = rating.getFiller().getMinutes();
			judged = minutes <= TaskRating.Filler.QUICK ? "Quick filler" : minutes >= TaskRating.Filler.SLOW ? "Slow filler" : "Average filler";
		}
		else if (goal == SlayerGoal.XP)
		{
			judged = !wilderness && rating.getXpAdvice() != null ? wikiWords(rating.getXpAdvice())
					: capitalize(SlayerSpend.quality(rating.getXp())) + " for XP";
		}
		else if (goal == SlayerGoal.PROFIT)
		{
			judged = capitalize(SlayerSpend.quality(rating.getGp())) + " for profit";
		}
		else
		{
			judged = speed(rating.getSpeed());
		}
		return wild ? "Wilderness: " + lower(judged) : judged;
	}

	private static String wikiWords(TaskRating.XpAdvice advice)
	{
		switch (advice)
		{
			case DO:
				return "Wiki: do it for XP";
			case SKIP:
				return "Wiki: skip or block for XP";
			default:
				return "Wiki: do not unlock for XP";
		}
	}

	/** A dossier field as it is, without its full stop, when it is a few plain words. Null when it takes sentences. */
	static String shortField(String text)
	{
		if (text == null) return null;
		String t = text.trim();
		if (t.endsWith(".")) t = t.substring(0, t.length() - 1).trim();
		if (t.isEmpty() || t.contains(";") || t.contains(":") || t.contains(". ") || t.contains(" - ") || t.contains("\u2013")
				|| t.contains("\u2014"))
		{
			return null;
		}
		return t;
	}

	/** {@code label} and a short field, when together they fit on a compact line. Null otherwise. */
	private static String item(String label, String field)
	{
		return field == null || label.length() + field.length() > MAX_ITEM ? null : label + field;
	}

	/**
	 * "Pray melee", "Pray missiles" or "Pray magic" when the dossier's prayer starts with that protection prayer and names
	 * no other, "No prayer needed" when it starts with none. Null when it takes a sentence.
	 */
	static String prayerItem(String text)
	{
		if (text == null) return null;
		final String t = text.trim();
		if (t.toLowerCase(Locale.ROOT).startsWith("none")) return "No prayer needed";
		final Set<String> named = new HashSet<>();
		final Matcher m = PRAYER.matcher(t);
		while (m.find()) named.add(m.group(1));
		if (named.size() != 1) return null;
		final String prayer = named.iterator().next();
		return t.startsWith("Protect from " + prayer) ? "Pray " + prayer.toLowerCase(Locale.ROOT) : null;
	}

	/**
	 * "Weak: demonbane" or "Weak: water spells, demonbane": up to two of the spells, slayer weapons and melee styles the
	 * dossier's weakness names as working. Null when it names none of them.
	 */
	static String weaknessItem(String text)
	{
		if (text == null) return null;
		final String t = text.toLowerCase(Locale.ROOT);
		final List<String> found = new ArrayList<>();
		final Matcher spells = SPELLS.matcher(t);
		if (spells.find()) found.add(spells.group(1) + " spells");
		if (t.contains("demonbane")) found.add("demonbane");
		if (t.contains("dragonbane")) found.add("dragonbane");
		final Matcher attack = ATTACK.matcher(t);
		if (attack.find()) found.add(attack.group(1) != null ? attack.group(1) : attack.group(2));
		return found.isEmpty() ? null : "Weak: " + String.join(", ", found.subList(0, Math.min(2, found.size())));
	}

	/** "Style: melee or ranged" when the dossier's kill style takes a few words, else null. */
	static String styleItem(String text)
	{
		final String style = shortField(text);
		return style == null ? null : item("Style: ", lower(style));
	}

	/** "Attacks: melee" when the dossier's enemy attacks take a few words, else null. */
	static String attacksItem(String text)
	{
		final String attacks = shortField(text);
		return attacks == null ? null : item("Attacks: ", lower(attacks));
	}

	/**
	 * The Cannon and Combat area lines in a few words: "No cannon, multi", "Cannon", "Single combat". A line may be a
	 * place's fact ("Not allowed.", "Multicombat") or one of the dossier's plain words ("banned", "single"). Null when
	 * neither line is one of those.
	 */
	static String cannonItem(String cannonLine, String combatLine)
	{
		final String cannon = cannonWord(cannonLine);
		final String combat = combatWord(combatLine);
		if (cannon == null && combat == null) return null;
		if (cannon == null)
		{
			return "multi".equals(combat) ? "Multicombat" : "single".equals(combat) ? "Single combat" : "Partly multicombat";
		}
		return combat == null ? cannon : cannon + ", " + combat;
	}

	/**
	 * "Cannon" for a place that allows one or a dossier line that only praises it, "No cannon" for one that rules it out.
	 * A line that does both, such as "great in Stronghold Slayer Cave; banned in Catacombs of Kourend", is left to the tooltip.
	 */
	private static String cannonWord(String line)
	{
		if (line == null) return null;
		final String t = line.trim().toLowerCase(Locale.ROOT);
		if (t.startsWith("not allowed") || t.startsWith("not usable") || t.startsWith("banned") || t.equals("single-no")
				|| t.equals("immune to cannons"))
		{
			return "No cannon";
		}
		final boolean mixed = t.contains(";") || t.contains("banned") || t.contains("not usable") || t.contains("not allowed");
		if (t.startsWith("allowed") || !mixed && (t.startsWith("great") || t.startsWith("good") || t.equals("ok"))) return "Cannon";
		return null;
	}

	private static String combatWord(String line)
	{
		if (line == null) return null;
		final String t = line.trim().toLowerCase(Locale.ROOT);
		if (t.equals("multicombat") || t.equals("multi")) return "multi";
		if (t.equals("single combat") || t.equals("single")) return "single";
		return t.startsWith("mixed") ? "partly multi" : null;
	}

	/** The name the dossier's place starts with, e.g. "Catacombs of Kourend" from "Catacombs of Kourend (multi) for XP". */
	static String placeItem(String text)
	{
		if (text == null) return null;
		final Matcher end = PLACE_END.matcher(text);
		final String place = (end.find() ? text.substring(0, end.start()) : text).trim();
		return place.isEmpty() || place.length() > SHORT_PLACE ? null : place;
	}

	private static String capitalize(String text)
	{
		return text.isEmpty() ? text : Character.toUpperCase(text.charAt(0)) + text.substring(1);
	}

	private static String lower(String text)
	{
		return text.isEmpty() ? text : Character.toLowerCase(text.charAt(0)) + text.substring(1);
	}
}

package com.slayercompanion;

import com.slayercompanion.data.TaskRating;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import lombok.Value;

/**
 * The "Advisor" line for the task in progress: do it, extend it, skip it or block it, for the goal. Pure.
 * <p>
 * It follows the same model as the plan. A task is worth skipping when the skip model at its master skips it
 * ({@link SlayerGoalModel#skips}, the assumption behind the master ranking and the plan's reserve), and worth
 * blocking when the block advice at its master would block it. Costs are that master's ({@link SlayerAssigner}).
 * Which reward lengthens the task, and whether it is owned, come from the cache.
 * <p>
 * For Slayer points the streak comes first: the line never suggests changing a task from Turael or Aya, whose
 * task change resets the streak, and never suggests skipping a milestone task. A skip costs 30 points, more than
 * an ordinary task pays anywhere, so it never suggests skipping for points at all. A block can still pay: on the
 * routine a filler task from Turael's spot or Spria that the block advice there would block, when the block
 * raises the routine's points per hour enough to notice. A block skips the task in progress "without penalties"
 * (wiki Slayer Rewards), so a milestone task never gets one.
 * <p>
 * For XP or profit a task from Turael's spot or Spria is simply done: every task they give is poor for both, so a
 * block or skip there buys nothing, and the line names the goal's best master instead.
 * <p>
 * For XP the Recommendation column of the wiki's task summary decides where it has advice
 * ({@link TaskRating#getXpAdvice}): a task it says to do is done, and one it says to skip or not to unlock is skipped or
 * blocked at a master that takes skips. The line cites the guide rather than calling a fast task poor.
 * <p>
 * Each decision also gives the compact sidebar's items ({@link #compact}), which say the same in a few words.
 */
final class SlayerUnlockAdvisor
{
	/** Everything the line depends on, gathered by {@link SlayerPlanBuilder}. */
	@Value
	static class Situation
	{
		SlayerGoal goal;
		/** The task in its master's list, with the ratings that apply there. Null when unknown. */
		SlayerPool.Entry entry;
		SlayerAssigner master;
		/** The NPC who gave it. */
		String npc;
		int points;
		/** The skip model at the master skips it for the goal. */
		boolean worthSkipping;
		/**
		 * The block advice at the master would block it. For a filler task on the Slayer points routine, only when
		 * the block also raises the routine's rate enough to notice.
		 */
		boolean worthBlocking;
		/** An open block slot is empty at the master. */
		boolean freeSlot;
		/** A current block that does not fit the goal and can be lifted to make room, or null. */
		String unblock;
		/** The reward that lengthens the task, or null when it has none. */
		Extension extension;
		/** The task's number in its streak, 0 when it counts toward none. */
		int taskNumber;
		/** Points the task pays when done, -1 when unknown. */
		int payout;
		/** The task has a superior and Bigger and Badder is not owned. */
		boolean superiorMissing;
		int superiorCost;
		/** The NPC at the best master for XP or profit, or null when unknown. */
		String bestMaster;
	}

	/** The reward that lengthens the task. */
	@Value
	static class Extension
	{
		String name;
		int cost;
		boolean owned;
		/** What it does for the goal at the master, as in {@link SlayerSpend}. */
		double gain;
	}

	/** The line and the compact sidebar's items that say the same in a few words, e.g. "Skip (30)". */
	private static final class Said
	{
		final String line;
		final List<String> items;

		Said(String line, String... items)
		{
			this.line = line;
			this.items = Collections.unmodifiableList(Arrays.asList(items));
		}
	}

	private SlayerUnlockAdvisor()
	{
	}

	/** The line, or null when there is no task or nothing to judge it by. */
	static String advise(Situation s)
	{
		final Said said = decide(s);
		return said == null ? null : said.line;
	}

	/** The same advice as the compact sidebar's items, e.g. "Skip (30)". Empty when there is no line. */
	static List<String> compact(Situation s)
	{
		final Said said = decide(s);
		return said == null ? Collections.<String>emptyList() : said.items;
	}

	private static Said decide(Situation s)
	{
		if (s == null || s.getMaster() == null) return null;
		if (s.getGoal() == SlayerGoal.POINTS) return forPoints(s);
		if (s.getMaster() == SlayerAssigner.TURAEL || s.getMaster() == SlayerAssigner.SPRIA) return forFillerMaster(s);
		final SlayerPool.Entry e = s.getEntry();
		if (e == null || !e.isRated()) return null;
		final int block = s.getMaster().getBlockCost();
		final int skip = s.getMaster().getCancelCost();
		// For XP the wiki's Slayer guide is the advice where it has some, cited instead of the rating
		final TaskRating.XpAdvice wiki = e.wikiAdvice(s.getGoal());
		final String judged = wiki != null ? SlayerSpend.wikiSays(wiki) : capitalize(SlayerSpend.judge(e, s.getGoal())) + " at " + s.getNpc() + ".";
		final String have = " You have " + s.getPoints() + " points.";
		final String blockLater = "Later: block (" + block + ")";
		if (wiki == TaskRating.XpAdvice.DO) return doIt(s, judged);
		if (s.isWorthBlocking() && s.getPoints() >= block)
		{
			if (s.isFreeSlot())
			{
				return new Said("Block it for " + block + " points. " + judged + " A block slot is free and you have " + s.getPoints() + " points.",
						"Block (" + block + ")");
			}
			if (s.getUnblock() != null)
			{
				return new Said("Block it for " + block + " points once you unblock " + s.getUnblock() + ", which does not fit your goal. " + judged
						+ have, "Unblock " + s.getUnblock(), "Then block (" + block + ")");
			}
		}
		if (s.isWorthSkipping())
		{
			if (s.getPoints() >= skip)
			{
				final String later = s.isWorthBlocking() ? " It is worth a block once you have " + block + " points and a free slot." : "";
				final String line = "Skip it for " + skip + " points. " + judged + have + later;
				return s.isWorthBlocking() ? new Said(line, "Skip (" + skip + ")", blockLater) : new Said(line, "Skip (" + skip + ")");
			}
			return new Said("Do it. Skipping costs " + skip + " points and you have " + s.getPoints() + ". " + judged,
					"Do it", "Skip costs " + skip + ", you have " + s.getPoints());
		}
		if (s.isWorthBlocking())
		{
			return new Said("Do it. " + judged + " It is worth a block once you have " + block + " points and a free slot." + have,
					"Do it", blockLater);
		}
		if (wiki != null && s.getMaster().getStreak() == SlayerAssigner.Streak.MORTIMER)
		{
			// Mortimer takes no skips here: he offers a choice of tasks instead
			return new Said("Do it. " + judged + " " + s.getNpc() + " offers a choice, so pick another next time.",
					"Do it", "Pick another next time");
		}
		return doIt(s, judged);
	}

	/** "Do it." with the judgement and the one purchase that would make the task better: its extension or its superior. */
	private static Said doIt(Situation s, String judged)
	{
		final String line = "Do it. " + judged;
		final Extension x = s.getExtension();
		if (x != null && !x.isOwned() && x.getGain() > SlayerPointsPlanner.NOTICEABLE)
		{
			return new Said(line + " Buy " + x.getName() + " for " + x.getCost() + " points to make the next ones longer.",
					"Do it", "Buy " + x.getName() + " (" + x.getCost() + ")");
		}
		if (s.isSuperiorMissing())
		{
			return new Said(line + " Bigger and Badder, " + s.getSuperiorCost() + " points, adds its superior.",
					"Do it", "Buy Bigger and Badder (" + s.getSuperiorCost() + ")");
		}
		return new Said(line, "Do it");
	}

	/** Slayer points: protect the streak, and spend points only on a block that speeds up the routine. */
	private static Said forPoints(Situation s)
	{
		final SlayerAssigner master = s.getMaster();
		final String npc = s.getNpc();
		final int n = s.getTaskNumber();
		if (master.getStreak() == SlayerAssigner.Streak.MORTIMER)
		{
			return new Said("Do it. " + SlayerSpend.possessive(npc) + " tasks do not count toward your streak.", "Do it, not on your streak");
		}
		final boolean milestone = n > 0 && SlayerPayout.isMilestone(n);
		final int cost = master.getBlockCost();
		final SlayerPool.Entry e = s.getEntry();
		// A block skips the task in progress, so a milestone task is never blocked
		final boolean block = !milestone && s.isWorthBlocking() && s.isFreeSlot() && s.getPoints() >= cost && e != null && e.isRated();
		final String longer = e == null ? "" : e.getName() + " take longer than the average task at " + npc;
		final String have = " A block slot is free and you have " + s.getPoints() + " points.";
		final String blockIt = "Block (" + cost + ")";
		if (SlayerPayout.basePoints(master, SlayerPayout.Diaries.NONE) == 0)
		{
			// Turael, Aya and Spria pay nothing but move the streak. Changing the task with Turael or Aya resets it.
			final boolean changes = master == SlayerAssigner.TURAEL;
			if (block)
			{
				return new Said("Block it for " + cost + " points. " + longer + ", and a block keeps your filler tasks quick." + have
						+ (changes ? " A block skips it without penalty, but changing it with " + npc + " would reset your streak." : ""), blockIt);
			}
			final String change = changes ? " Changing it with " + npc + " would reset your streak." : "";
			return new Said("Do it. Task " + n + " of your streak pays no points but counts toward the next milestone." + change,
					"Do it, #" + n + " pays 0");
		}
		if (milestone)
		{
			final String pays = s.getPayout() > 0 ? npc + " pays " + s.getPayout() + " for it." : "It pays a milestone bonus.";
			return new Said("Do it. Task " + n + " is a milestone. " + pays,
					s.getPayout() > 0 ? "Do it, #" + n + " pays " + s.getPayout() : "Do it, #" + n + " is a milestone");
		}
		if (block)
		{
			return new Said("Block it for " + cost + " points. " + longer + ", and a block keeps your milestone tasks quick." + have, blockIt);
		}
		final String pays = s.getPayout() >= 0 ? " " + npc + " pays " + s.getPayout() + " for task " + n + "." : "";
		return new Said("Do it." + pays, s.getPayout() >= 0 ? "Do it, #" + n + " pays " + s.getPayout() : "Do it");
	}

	/** XP or profit from Turael's spot or Spria, whose tasks are fillers for the points streak. */
	private static Said forFillerMaster(Situation s)
	{
		final String best = s.getBestMaster();
		final String goal = s.getGoal() == SlayerGoal.XP ? "XP" : "profit";
		final String where = best == null || best.equals(s.getNpc()) ? "" : " " + best + " is the best master for " + goal + ".";
		return new Said("Do it. " + SlayerSpend.possessive(s.getNpc()) + " tasks are quick fillers for a Slayer points streak." + where, "Do it");
	}

	private static String capitalize(String text)
	{
		return text.isEmpty() ? text : Character.toUpperCase(text.charAt(0)) + text.substring(1);
	}
}

package com.slayercompanion;

import com.slayercompanion.data.SlayerTask;
import lombok.Getter;
import net.runelite.api.coords.WorldPoint;

/**
 * Maps the dossier's free-text best location to a place, for tasks without an assigned area. Points
 * are RuneLite's own world-map dungeon icons (net.runelite.client.plugins.worldmap.DungeonLocation),
 * re-checked against RuneLite 1.13.1. TzHaar City uses the Karamja volcano icon, the surface way in to
 * Mor Ul Rek. {@code key} names the same place in /slayer_areas.json, where a test keeps the two points
 * identical.
 */
@Getter
public final class TaskDestination
{
	private final String key;
	private final String label;
	private final WorldPoint point;

	private TaskDestination(String key, String label, int x, int y)
	{
		this.key = key;
		this.label = label;
		this.point = new WorldPoint(x, y, 0);
	}

	public static TaskDestination forTask(SlayerTask task)
	{
		if (task == null || task.getBestLocation() == null)
		{
			return null;
		}
		final String location = task.getBestLocation().toLowerCase();
		if (location.startsWith("catacombs of kourend")) return at("catacombs_of_kourend", "Catacombs of Kourend", 1636, 3673);
		if (location.startsWith("god wars dungeon")) return at("god_wars_dungeon", "God Wars Dungeon", 2917, 3747);
		if (location.startsWith("jormungand")) return at("jormungands_prison", "Jormungand's Prison", 2464, 4012);
		if (location.startsWith("taverley dungeon")) return at("taverley_dungeon", "Taverley Dungeon", 2883, 3397);
		if (location.startsWith("mos le")) return at("mos_leharmless_cave", "Mos Le'Harmless Cave", 3747, 2973);
		if (location.startsWith("kraken cove")) return at("kraken_cove", "Kraken Cove", 2277, 3611);
		if (location.startsWith("lighthouse")) return at("lighthouse", "Lighthouse basement", 2508, 3644);
		if (location.startsWith("iorwerth")) return at("iorwerth_dungeon", "Iorwerth Dungeon", 3224, 6044);
		if (location.startsWith("karuulm")) return at("karuulm_slayer_dungeon", "Karuulm Slayer Dungeon", 1308, 3807);
		if (location.startsWith("fremennik slayer")) return at("fremennik_slayer_dungeon", "Fremennik Slayer Dungeon", 2796, 3615);
		if (location.startsWith("kalphite cave")) return at("kalphite_cave", "Kalphite Cave", 3319, 3122);
		if (location.startsWith("ancient cavern")) return at("ancient_cavern", "Ancient Cavern", 2511, 3508);
		if (location.startsWith("smoke devil")) return at("smoke_devil_dungeon", "Smoke Devil Dungeon", 2411, 3061);
		if (location.startsWith("brimhaven dungeon")) return at("brimhaven_dungeon", "Brimhaven Dungeon", 2743, 3154);
		if (location.startsWith("asgarnian ice")) return at("asgarnian_ice_dungeon", "Asgarnian Ice Dungeon", 3007, 3150);
		if (location.startsWith("slayer tower")) return at("slayer_tower", "Slayer Tower", 3416, 3535);
		if (location.startsWith("stronghold slayer")) return at("stronghold_slayer_dungeon", "Stronghold Slayer Cave", 2427, 3424);
		if (location.startsWith("chasm of fire")) return at("chasm_of_fire", "Chasm of Fire", 1432, 3670);
		if (location.startsWith("mor ul rek")) return at("tzhaar_city", "TzHaar City", 2855, 3168);
		if (location.startsWith("wyvern cave")) return at("wyvern_cave", "Wyvern Cave", 3745, 3779);
		return null;
	}

	private static TaskDestination at(String key, String label, int x, int y)
	{
		return new TaskDestination(key, label, x, y);
	}
}

package com.slayercompanion;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;

/**
 * World map marker for the task destination. On screen it is a pin whose tip sits on the point. When the
 * point is off screen RuneLite snaps the marker to the edge of the map view and calls
 * {@link #onEdgeSnap}, and the pin becomes an orange arrow aimed at the destination. Clicking either form
 * focuses the map on the destination through RuneLite's own jumpOnClick handling.
 */
class TaskMapPoint extends WorldMapPoint
{
	/** RuneLite's own accent, the plugin's colour in the sidebar, on the panel and on its toolbar icon. */
	static final Color ORANGE = ColorScheme.BRAND_ORANGE;
	private static final Color DARK = new Color(45, 45, 45, 240);
	static final String NAME = "Slayer task";

	static final BufferedImage PIN = drawPin();
	/** Tip of the pin, relative to the image's top left corner. */
	static final Point PIN_TIP = new Point(PIN.getWidth() / 2, PIN.getHeight() - 1);
	/** One arrow per compass direction, clockwise from north. */
	static final BufferedImage[] ARROWS = drawArrows();

	private int direction;

	TaskMapPoint(WorldPoint point, String tooltip)
	{
		super(point, PIN);
		setTarget(point);
		setName(NAME);
		setTooltip(tooltip);
		setSnapToEdge(true);
		setJumpOnClick(true);
		setImagePoint(PIN_TIP);
	}

	@Override
	public void onEdgeSnap()
	{
		setImage(ARROWS[direction]);
		setImagePoint(null);
	}

	@Override
	public void onEdgeUnsnap()
	{
		setImage(PIN);
		setImagePoint(PIN_TIP);
	}

	/** Aims the edge arrow from the centre of the map view. Cheap enough to call every frame. */
	void aimFrom(int mapCenterX, int mapCenterY)
	{
		final int d = direction(mapCenterX, mapCenterY, getWorldPoint().getX(), getWorldPoint().getY());
		if (d == direction)
		{
			return;
		}
		direction = d;
		if (isCurrentlyEdgeSnapped())
		{
			setImage(ARROWS[d]);
		}
	}

	int getDirection()
	{
		return direction;
	}

	/**
	 * Compass direction from one world position to another, as 0 to 7 clockwise from north. World y grows
	 * northwards, which is up on the map.
	 */
	static int direction(int fromX, int fromY, int toX, int toY)
	{
		if (fromX == toX && fromY == toY)
		{
			return 0;
		}
		final double degrees = Math.toDegrees(Math.atan2(toX - fromX, toY - fromY));
		return (int) Math.round((degrees + 360.0) % 360.0 / 45.0) % 8;
	}

	private static BufferedImage drawPin()
	{
		final int width = 20;
		final int height = 28;
		final BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		final Polygon point = new Polygon(new int[]{4, 16, width / 2}, new int[]{13, 13, height - 1}, 3);
		g.setColor(DARK);
		g.fillPolygon(point);
		g.setColor(ORANGE);
		g.setStroke(new BasicStroke(1.5f));
		g.drawPolygon(point);
		g.setColor(DARK);
		g.fillOval(0, 0, 19, 19);
		g.setColor(ORANGE);
		g.drawOval(1, 1, 17, 17);
		g.setFont(new Font("SansSerif", Font.BOLD, 12));
		g.drawString("S", 6, 14);
		g.dispose();
		return image;
	}

	private static BufferedImage[] drawArrows()
	{
		final BufferedImage[] arrows = new BufferedImage[8];
		for (int i = 0; i < arrows.length; i++)
		{
			arrows[i] = drawArrow(i * 45);
		}
		return arrows;
	}

	/** An orange arrow pointing up, turned clockwise by the given angle. */
	private static BufferedImage drawArrow(int degrees)
	{
		final int size = 26;
		final BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setTransform(AffineTransform.getRotateInstance(Math.toRadians(degrees), size / 2.0, size / 2.0));
		final Polygon arrow = new Polygon(
				new int[]{13, 23, 17, 17, 9, 9, 3},
				new int[]{2, 13, 13, 23, 23, 13, 13}, 7);
		g.setColor(ORANGE);
		g.fillPolygon(arrow);
		g.setColor(DARK);
		g.setStroke(new BasicStroke(1.5f));
		g.drawPolygon(arrow);
		g.dispose();
		return image;
	}
}

package com.slayercompanion;

import com.slayercompanion.data.SlayerLocation;
import com.slayercompanion.data.SlayerTask;
import com.slayercompanion.data.TaskLocations;
import com.slayercompanion.data.WildernessPlaces;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import lombok.Value;

/**
 * The places the sidebar offers for the current task and the one in use. Masters other than Konar leave
 * the place to the player, so the task's list from /slayer_areas.json becomes a picker and the pick is
 * remembered per task in the plugin config. Krystilia's tasks only count in the Wilderness, so they offer
 * only her Wilderness list and remember their pick apart. Every place says whether the account can enter it
 * ({@link PlaceAccess}), and the first one it can enter is recommended. The decisions here are pure and unit
 * tested. {@link Destination#resolve} turns the chosen key into the destination.
 */
@Value
class TaskPlaces
{
	/** Config keys "place_" plus the task id, in the plugin's config group, hold the remembered pick. */
	static final String CONFIG_KEY_PREFIX = "place_";
	/** The same for a pick among Krystilia's Wilderness places. */
	static final String WILDERNESS_CONFIG_KEY_PREFIX = "wildernessPlace_";

	enum Show
	{
		/** Two or more places: a picker. */
		PICKER,
		/** Exactly one place: its name as text. */
		ONE_PLACE,
		/** No known place: the dossier's own text. */
		DOSSIER
	}

	@Value
	static class Place
	{
		String key;
		String label;
		boolean recommended;
		/** Short facts that help choose, such as "Cannon not allowed. Multicombat.", or null when none are known. */
		String facts;
		/** Whether the account can enter the place, and what it lacks when not. */
		PlaceAccess.Verdict access;

		Place(String key, String label, boolean recommended, String facts, PlaceAccess.Verdict access)
		{
			this.key = key;
			this.label = label;
			this.recommended = recommended;
			this.facts = facts;
			this.access = access == null ? PlaceAccess.Verdict.OPEN : access;
		}

		/** A place nothing is known to lock. */
		Place(String key, String label, boolean recommended, String facts)
		{
			this(key, label, recommended, facts, PlaceAccess.Verdict.OPEN);
		}

		boolean isLocked()
		{
			return access.isLocked();
		}
	}

	int taskId;
	/** The recommended place first, then the data file's order. */
	List<Place> places;
	/** Key of the place in use, or null when there are no places. */
	String chosenKey;
	/** Krystilia's task: the places are her Wilderness list, and kills elsewhere do not count. */
	boolean wilderness;

	TaskPlaces(int taskId, List<Place> places, String chosenKey, boolean wilderness)
	{
		this.taskId = taskId;
		this.places = places;
		this.chosenKey = chosenKey;
		this.wilderness = wilderness;
	}

	TaskPlaces(int taskId, List<Place> places, String chosenKey)
	{
		this(taskId, places, chosenKey, false);
	}

	/**
	 * Whether the player may pick the place for this assignment. Konar names the area herself, so her
	 * tasks keep it, even one without an area. Krystilia's tasks get a pick among her Wilderness places.
	 *
	 * @param assignedAreaId value of the SLAYER_AREA varp
	 * @param masterId value of the SLAYER_MASTER varbit, 0 when unknown
	 */
	static boolean pickable(int assignedAreaId, int masterId)
	{
		return assignedAreaId <= 0 && masterId != SlayerAssigner.KONAR.getId();
	}

	/** Whether the assignment only counts in the Wilderness: Krystilia's tasks. */
	static boolean wildernessOnly(int masterId)
	{
		return masterId == SlayerAssigner.KRYSTILIA.getId();
	}

	/**
	 * The places for one of Krystilia's tasks, the recommended one first, each with its facts for this task.
	 * Only her Wilderness list counts. A task without one offers nothing, so nothing is marked or routed.
	 */
	static List<Place> offeredInWilderness(int taskId, SlayerLocations data)
	{
		return offeredInWilderness(taskId, data, PlaceAccess.Account.UNKNOWN);
	}

	/** As above, with whether the account can enter each place. The first place it can enter is recommended. */
	static List<Place> offeredInWilderness(int taskId, SlayerLocations data, PlaceAccess.Account account)
	{
		final WildernessPlaces list = data.forWildernessTask(taskId);
		if (list == null || list.getPlaces().isEmpty())
		{
			return Collections.emptyList();
		}
		final String recommended = Destination.recommendedWildernessKey(list);
		final List<Place> places = new ArrayList<>();
		for (WildernessPlaces.Place wild : list.getPlaces())
		{
			final SlayerLocation location = data.byKey(wild.getKey());
			if (location == null) continue;
			final String label = wild.getLabel() != null && !wild.getLabel().trim().isEmpty()
					? wild.getLabel().trim() : Destination.label(location);
			final Place place = new Place(wild.getKey(), label, wild.getKey().equals(recommended), facts(location, taskId),
					PlaceAccess.check(PlaceAccess.of(location, taskId), account));
			if (place.isRecommended()) places.add(0, place);
			else places.add(place);
		}
		return Collections.unmodifiableList(firstOpenRecommended(places));
	}

	/** Every place the data lists for the task, the recommended one first, each with its facts for this task. */
	static List<Place> offered(int taskId, SlayerTask dossier, SlayerLocations data)
	{
		return offered(taskId, dossier, data, PlaceAccess.Account.UNKNOWN);
	}

	/** As above, with whether the account can enter each place. The first place it can enter is recommended. */
	static List<Place> offered(int taskId, SlayerTask dossier, SlayerLocations data, PlaceAccess.Account account)
	{
		final TaskLocations list = data.forTask(taskId);
		if (list == null || list.getLocations() == null || list.getLocations().isEmpty())
		{
			return Collections.emptyList();
		}
		final String recommended = Destination.recommendedKey(taskId, dossier, data);
		final List<Place> places = new ArrayList<>();
		for (String key : list.getLocations())
		{
			final SlayerLocation location = data.byKey(key);
			if (location == null) continue;
			final Place place = new Place(key, Destination.label(location), key.equals(recommended), facts(location, taskId),
					PlaceAccess.check(PlaceAccess.of(location, taskId), account));
			if (place.isRecommended()) places.add(0, place);
			else places.add(place);
		}
		return Collections.unmodifiableList(firstOpenRecommended(places));
	}

	/**
	 * The recommended place is the first place in display order the account can enter. It moves to the front and the
	 * place before it loses the recommendation. When every place is locked the order stays as it is.
	 */
	static List<Place> firstOpenRecommended(List<Place> places)
	{
		if (places.isEmpty() || !places.get(0).isLocked()) return places;
		int open = -1;
		for (int i = 1; i < places.size() && open < 0; i++)
		{
			if (!places.get(i).isLocked()) open = i;
		}
		if (open < 0) return places;
		final Place first = places.get(open);
		final List<Place> out = new ArrayList<>();
		out.add(new Place(first.getKey(), first.getLabel(), true, first.getFacts(), first.getAccess()));
		for (int i = 0; i < places.size(); i++)
		{
			final Place place = places.get(i);
			if (i == open) continue;
			out.add(place.isRecommended() ? new Place(place.getKey(), place.getLabel(), false, place.getFacts(), place.getAccess()) : place);
		}
		return out;
	}

	/**
	 * The quests the places of a task name, Krystilia's Wilderness list for hers. Reading a quest state runs a client
	 * script, so the plugin reads only these.
	 */
	static Set<String> quests(int taskId, boolean wilderness, SlayerLocations data)
	{
		final List<SlayerLocation> locations = new ArrayList<>();
		if (wilderness)
		{
			final WildernessPlaces list = data.forWildernessTask(taskId);
			if (list != null)
			{
				for (WildernessPlaces.Place place : list.getPlaces())
				{
					if (data.byKey(place.getKey()) != null) locations.add(data.byKey(place.getKey()));
				}
			}
		}
		else
		{
			final TaskLocations list = data.forTask(taskId);
			if (list != null && list.getLocations() != null)
			{
				for (String key : list.getLocations())
				{
					if (data.byKey(key) != null) locations.add(data.byKey(key));
				}
			}
		}
		return PlaceAccess.quests(locations, taskId);
	}

	/** A place's facts for one task. The task's own facts win over the place-wide ones. */
	private static String facts(SlayerLocation location, int taskId)
	{
		final SlayerLocation.TaskEntry task = Destination.taskEntry(location, taskId);
		final String cannon = task != null && task.getCannon() != null ? task.getCannon() : location.getCannon();
		final String combat = task != null && task.getCombat() != null ? task.getCombat() : location.getCombat();
		return facts(cannon, combat);
	}

	/** The remembered pick while the task still offers it, else the recommended place. */
	static String chosen(List<Place> places, String storedKey)
	{
		if (places.isEmpty()) return null;
		for (Place place : places)
		{
			if (place.getKey().equals(storedKey)) return storedKey;
		}
		return places.get(0).getKey();
	}

	static Show show(TaskPlaces places)
	{
		if (places == null || places.getPlaces().isEmpty()) return Show.DOSSIER;
		return places.getPlaces().size() == 1 ? Show.ONE_PLACE : Show.PICKER;
	}

	boolean offers(String key)
	{
		return place(key) != null;
	}

	/** The place in use, or null without places. */
	Place chosen()
	{
		return place(chosenKey);
	}

	private Place place(String key)
	{
		for (Place place : places)
		{
			if (place.getKey().equals(key)) return place;
		}
		return null;
	}

	/** The line under the picker: whether the place in use is the recommended one, and its facts. */
	String summary()
	{
		final Place chosen = chosen();
		if (chosen == null) return null;
		if (chosen.isRecommended())
		{
			return chosen.getFacts() == null ? "Recommended." : "Recommended. " + chosen.getFacts();
		}
		final String recommended = places.get(0).isRecommended() ? "Recommended: " + places.get(0).getLabel() + "." : null;
		if (chosen.getFacts() == null) return recommended;
		return recommended == null ? chosen.getFacts() : chosen.getFacts() + " " + recommended;
	}

	/**
	 * The compact sidebar's item under the picker: "Recommended", or "Recommended: " and the recommended place while
	 * another is in use. Null without a recommended place. {@link #summary} adds the facts.
	 */
	String compactSummary()
	{
		final Place chosen = chosen();
		if (chosen == null) return null;
		if (chosen.isRecommended()) return "Recommended";
		return places.get(0).isRecommended() ? "Recommended: " + places.get(0).getLabel() : null;
	}

	/** The second line of a place in the picker's list, or null when there is nothing to add. */
	static String rowNote(Place place)
	{
		if (!place.isRecommended()) return place.getFacts();
		return place.getFacts() == null ? "Recommended." : "Recommended. " + place.getFacts();
	}

	/**
	 * What the place in use needs and its access note, as the sidebar's line under the place, such as
	 * "Needs Priest in Peril." Null when the account can enter it and no note applies.
	 */
	String accessLine()
	{
		final Place chosen = chosen();
		return chosen == null ? null : chosen.getAccess().sentence();
	}

	static String facts(String cannon, String combat)
	{
		final StringBuilder sb = new StringBuilder();
		final String c = SlayerLocations.cannonValue(cannon);
		if (c != null) sb.append("yes".equals(c) ? "Cannon allowed." : "Cannon not allowed.");
		final String m = SlayerLocations.combatValue(combat);
		if (m != null)
		{
			if (sb.length() > 0) sb.append(' ');
			sb.append("multi".equals(m) ? "Multicombat." : "single".equals(m) ? "Single combat." : "Partly multicombat.");
		}
		return sb.length() == 0 ? null : sb.toString();
	}

	/**
	 * The sidebar's Cannon or Combat area line. Konar's area shows only its own fact. With a place list, the
	 * chosen place's fact shows when known. The dossier's line describes the recommended place, so it stands
	 * in for that place only, and a place the player picked shows no line rather than borrowed advice.
	 * Krystilia's Wilderness places never borrow it either, since the dossier may describe a place outside
	 * the Wilderness. Without a place list, the dossier's line stays as before.
	 */
	static String factLine(Destination destination, TaskPlaces places, String placeFact, String dossierLine)
	{
		if (destination != null && destination.getOrigin() == Destination.Origin.ASSIGNED) return placeFact;
		if (show(places) == Show.DOSSIER || destination == null) return dossierLine;
		if (placeFact != null || places.isWilderness()) return placeFact;
		return destination.getOrigin() == Destination.Origin.RECOMMENDED ? dossierLine : null;
	}

	static String configKey(int taskId)
	{
		return configKey(taskId, false);
	}

	static String configKey(int taskId, boolean wilderness)
	{
		return (wilderness ? WILDERNESS_CONFIG_KEY_PREFIX : CONFIG_KEY_PREFIX) + taskId;
	}

	/** The task id of a remembered-place config key, either kind, or -1 for any other key. */
	static int taskIdOfConfigKey(String key)
	{
		if (key == null) return -1;
		final String prefix = key.startsWith(CONFIG_KEY_PREFIX) ? CONFIG_KEY_PREFIX
				: key.startsWith(WILDERNESS_CONFIG_KEY_PREFIX) ? WILDERNESS_CONFIG_KEY_PREFIX : null;
		if (prefix == null) return -1;
		try
		{
			final int taskId = Integer.parseInt(key.substring(prefix.length()));
			return taskId > 0 ? taskId : -1;
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}
}

package com.slayercompanion;

import java.util.Objects;
import lombok.Value;

/**
 * Decides when Slayer Sensei asks Shortest Path to draw or clear a route. It is a pure state
 * machine fed once per game tick, so the rules are unit tested without a client.
 * <ul>
 * <li>After a login, hop, profile switch or plugin start, the assignment once the game's values have
 * settled is only a baseline. A task that was already in progress never draws a route on its own.</li>
 * <li>Every field of an assignment, its task name included, is read from the game on the same tick
 * ({@link SlayerTaskReader}), so a new assignment counts on the tick it appears, once.</li>
 * <li>Only a route this plugin requested is ever cleared, and ownership is dropped as soon as the
 * player or another plugin changes the Shortest Path target.</li>
 * <li>A route to the next Slayer master is ours too. Finishing the task in progress keeps it, since that is when
 * it is needed. The next assignment replaces it: in NEW_TASK mode with the route to the new task, otherwise it is
 * cleared once the new task is assigned. It is also cleared when another character logs in, or when a login finds
 * a task other than the one in progress when it was drawn.</li>
 * </ul>
 */
final class TaskRouteTracker
{
	/** Ticks after a session starts, while the game's values load, before an assignment change can count as a new task. */
	static final int SETTLE_TICKS = 5;

	enum Action
	{
		NONE,
		/** Request a route to the new assignment. This replaces any route already shown. */
		PATH,
		/** Clear the route this plugin requested earlier. */
		CLEAR
	}

	/** Identity of one task assignment. A changed field means a new assignment. */
	@Value
	static class Assignment
	{
		String profile;
		String taskName;
		int taskId;
		int bossId;
		int areaId;
		int initialAmount;
	}

	private boolean primed;
	private int sessionTicks;
	private Assignment baseline;
	/** The assignment our task route leads to, or null. */
	private Assignment owned;
	/** Our route leads to a Slayer master. */
	private boolean master;
	/** The assignment in progress when the master route was drawn, null between tasks. */
	private Assignment masterFrom;
	/** The character the master route was drawn for, null when unknown. */
	private String masterProfile;
	/** The character of this session, null when unknown. */
	private String profile;

	/** A login, hop, profile switch or plugin start, character unknown. The route this plugin drew is kept. */
	void sessionStarted()
	{
		sessionStarted(null);
	}

	/** {@link #sessionStarted()} for {@code profile}'s character, null when unknown. */
	void sessionStarted(String profile)
	{
		this.profile = profile;
		primed = false;
		sessionTicks = 0;
		baseline = null;
	}

	/**
	 * Feeds one game tick while logged in.
	 *
	 * @param current the assignment now, or null when there is no task
	 * @param autoPath whether a new assignment should get a route now: path mode is NEW_TASK, Shortest
	 *        Path is running and the destination has a verified point
	 */
	Action observe(Assignment current, boolean autoPath)
	{
		sessionTicks++;
		if (!primed)
		{
			if (sessionTicks < SETTLE_TICKS)
			{
				return Action.NONE;
			}
			primed = true;
			baseline = current;
			if (master)
			{
				// A login between tasks, or on the same task, keeps the way to the master
				final boolean sameCharacter = profile == null || masterProfile == null || profile.equals(masterProfile);
				return sameCharacter && (baseline == null || baseline.equals(masterFrom)) ? Action.NONE : clear();
			}
			return dropStaleRoute(baseline);
		}
		if (Objects.equals(current, baseline))
		{
			return Action.NONE;
		}
		baseline = current;
		if (current != null && autoPath)
		{
			master = false;
			owned = current;
			return Action.PATH;
		}
		if (master)
		{
			// Finishing the task in progress keeps the way to the master. The next task replaces it.
			return current == null ? Action.NONE : clear();
		}
		return dropStaleRoute(current);
	}

	private Action dropStaleRoute(Assignment now)
	{
		if (owned != null && !owned.equals(now))
		{
			owned = null;
			return Action.CLEAR;
		}
		return Action.NONE;
	}

	private Action clear()
	{
		owned = null;
		master = false;
		return Action.CLEAR;
	}

	/** The player pressed "Path to task" and the request was posted. */
	void routeRequested(Assignment assignment)
	{
		master = false;
		owned = assignment;
	}

	/**
	 * The player pressed the plan's path to a master and the request was posted.
	 *
	 * @param profile the character it is for, null when unknown
	 * @param current the assignment in progress, null between tasks
	 */
	void masterRouteRequested(String profile, Assignment current)
	{
		owned = null;
		master = true;
		masterFrom = current;
		masterProfile = profile;
	}

	/**
	 * The player picked another place for the current task. A route this plugin drew moves to the new
	 * place, or is cleared when Shortest Path cannot route there, because it would lead to the old place.
	 * Without a route of ours nothing is drawn.
	 *
	 * @param canRoute Shortest Path is running and the new place has a point it can reach
	 */
	Action placeChanged(boolean canRoute)
	{
		if (owned == null)
		{
			return Action.NONE;
		}
		if (canRoute)
		{
			return Action.PATH;
		}
		owned = null;
		return Action.CLEAR;
	}

	/** This plugin cleared its own route. */
	void routeCleared()
	{
		owned = null;
		master = false;
	}

	/** The player or another plugin changed the Shortest Path target, so the route is theirs now. */
	void routeTakenOver()
	{
		owned = null;
		master = false;
	}

	boolean ownsRoute()
	{
		return owned != null || master;
	}

	/** Whether our route leads to a Slayer master. */
	boolean ownsMasterRoute()
	{
		return master;
	}
}

