/** Whether a place is open for an account, decided from its requirements, the quest states and the real levels alone. */
public class PlaceAccessTest
{
	private static Access access(List<String> finished, List<String> started, Map<String, Integer> skills, String note)
	{
		final Access access = new Access();
		access.setQuestsFinished(finished);
		access.setQuestsStarted(started);
		access.setSkills(skills);
		access.setNote(note);
		access.setSource("test");
		return access;
	}

	private static Access finished(String... quests)
	{
		return access(Arrays.asList(quests), null, null, null);
	}

	private static Access started(String... quests)
	{
		return access(null, Arrays.asList(quests), null, null);
	}

	private static Access level(String skill, int level)
	{
		return access(null, null, Collections.singletonMap(skill, level), null);
	}

	private static PlaceAccess.Account quests(Object... nameAndState)
	{
		final Map<String, QuestState> states = new HashMap<>();
		for (int i = 0; i + 1 < nameAndState.length; i += 2)
		{
			states.put((String) nameAndState[i], (QuestState) nameAndState[i + 1]);
		}
		return new PlaceAccess.Account(states, levels());
	}

	/** Every real level 1, then the given ones. */
	private static int[] levels(Object... skillAndLevel)
	{
		final int[] levels = new int[Skill.values().length];
		Arrays.fill(levels, 1);
		for (int i = 0; i + 1 < skillAndLevel.length; i += 2)
		{
			levels[((Skill) skillAndLevel[i]).ordinal()] = (Integer) skillAndLevel[i + 1];
		}
		return levels;
	}

	private static PlaceAccess.Verdict check(Access access, PlaceAccess.Account account)
	{
		return PlaceAccess.check(Collections.singletonList(access), account);
	}

	@Test
	public void aQuestThatMustBeFinishedLocksUntilItIs()
	{
		final Access tower = finished("PRIEST_IN_PERIL");
		for (QuestState state : new QuestState[]{QuestState.NOT_STARTED, QuestState.IN_PROGRESS})
		{
			final PlaceAccess.Verdict verdict = check(tower, quests("PRIEST_IN_PERIL", state));
			assertTrue(state.name(), verdict.isLocked());
			assertEquals("Needs Priest in Peril", verdict.needs());
		}
		final PlaceAccess.Verdict done = check(tower, quests("PRIEST_IN_PERIL", QuestState.FINISHED));
		assertFalse(done.isLocked());
		assertNull(done.needs());
		assertSame("open with nothing to say", PlaceAccess.Verdict.OPEN, done);
	}

	@Test
	public void aQuestThatMustBeStartedLocksOnlyBeforeItIsStarted()
	{
		final Access dungeon = started("WATERFALL_QUEST");
		assertEquals("Needs Waterfall Quest started", check(dungeon, quests("WATERFALL_QUEST", QuestState.NOT_STARTED)).needs());
		assertFalse(check(dungeon, quests("WATERFALL_QUEST", QuestState.IN_PROGRESS)).isLocked());
		assertFalse(check(dungeon, quests("WATERFALL_QUEST", QuestState.FINISHED)).isLocked());
	}

	@Test
	public void aRealLevelBelowTheRequirementLocks()
	{
		final Access island = level("SAILING", 60);
		final PlaceAccess.Verdict low = check(island, new PlaceAccess.Account(Collections.emptyMap(), levels(Skill.SAILING, 59)));
		assertEquals("Needs 60 Sailing", low.needs());
		assertFalse(check(island, new PlaceAccess.Account(Collections.emptyMap(), levels(Skill.SAILING, 60))).isLocked());
		assertFalse(check(island, new PlaceAccess.Account(Collections.emptyMap(), levels(Skill.SAILING, 99))).isLocked());
	}

	@Test
	public void whatIsNotKnownLocksNothing()
	{
		// A quest that was not read, a level that is not loaded yet, and an account read before anything
		assertFalse(check(finished("PRIEST_IN_PERIL"), quests()).isLocked());
		assertFalse(check(level("SAILING", 60), new PlaceAccess.Account(Collections.emptyMap(), levels(Skill.SAILING, 0))).isLocked());
		assertFalse(check(level("SAILING", 60), new PlaceAccess.Account(Collections.emptyMap(), new int[0])).isLocked());
		assertFalse(check(finished("PRIEST_IN_PERIL"), PlaceAccess.Account.UNKNOWN).isLocked());
	}

	@Test
	public void aNameTheClientDoesNotKnowLocksNothingAndDoesNotThrow()
	{
		// Data newer than the client may name a quest or skill this client has no constant for
		final Access future = access(Collections.singletonList("A_QUEST_FROM_THE_FUTURE"), Collections.singletonList("ANOTHER_ONE"),
				Collections.singletonMap("FUTURE_SKILL", 50), null);
		final PlaceAccess.Account account = quests("A_QUEST_FROM_THE_FUTURE", QuestState.NOT_STARTED, "ANOTHER_ONE", QuestState.NOT_STARTED);
		assertFalse(check(future, account).isLocked());
		assertNull(PlaceAccess.quest("A_QUEST_FROM_THE_FUTURE"));
		assertNull(PlaceAccess.skill("FUTURE_SKILL"));
		assertNull(PlaceAccess.quest(null));
		final PlaceAccess.Account read = PlaceAccess.Account.read(Arrays.asList("A_QUEST_FROM_THE_FUTURE", "PRIEST_IN_PERIL"),
				quest -> QuestState.FINISHED, null);
		assertEquals("only the known quest is read", Collections.singleton("PRIEST_IN_PERIL"), read.getQuests().keySet());
	}

	@Test
	public void everyMissingRequirementIsNamedOnce()
	{
		final List<Access> place = Arrays.asList(
				access(Collections.singletonList("PRIEST_IN_PERIL"), Collections.singletonList("SINS_OF_THE_FATHER"),
						Collections.singletonMap("SAILING", 60), null),
				// The task's own requirement there asks again for a quest the place already names
				access(Collections.singletonList("SINS_OF_THE_FATHER"), Collections.singletonList("PRIEST_IN_PERIL"), null, null));
		final PlaceAccess.Account account = new PlaceAccess.Account(quests("PRIEST_IN_PERIL", QuestState.IN_PROGRESS,
				"SINS_OF_THE_FATHER", QuestState.NOT_STARTED).getQuests(), levels(Skill.SAILING, 50));
		final PlaceAccess.Verdict verdict = PlaceAccess.check(place, account);
		assertEquals(Arrays.asList("Priest in Peril", "Sins of the Father", "60 Sailing"), verdict.getMissing());
		assertEquals("Needs Priest in Peril, Sins of the Father and 60 Sailing", verdict.needs());
		assertEquals("Needs Priest in Peril, Sins of the Father and 60 Sailing.", verdict.sentence());
	}

	@Test
	public void aNoteIsShownAndNeverLocks()
	{
		final Access gwd = access(null, null, null, "Needs 60 Strength or 60 Agility, boosts count.");
		final PlaceAccess.Verdict open = check(gwd, PlaceAccess.Account.UNKNOWN);
		assertFalse(open.isLocked());
		assertNull(open.needs());
		assertEquals("Needs 60 Strength or 60 Agility, boosts count.", open.sentence());
		final Access both = access(Collections.singletonList("PRIEST_IN_PERIL"), null, null, "A note.");
		assertEquals("Needs Priest in Peril. A note.", check(both, quests("PRIEST_IN_PERIL", QuestState.NOT_STARTED)).sentence());
	}

	private static final String JSON = "{\"locations\": ["
			+ "{\"key\": \"slayer_tower\", \"label\": \"Slayer Tower\","
			+ " \"access\": {\"questsFinished\": [\"PRIEST_IN_PERIL\"], \"source\": \"test\"},"
			+ " \"tasks\": [{\"taskId\": 48, \"access\": {\"questsStarted\": [\"SINS_OF_THE_FATHER\"], \"source\": \"test\"}},"
			+ "   {\"taskId\": 41}]},"
			+ "{\"key\": \"open_field\", \"label\": \"Open field\", \"tasks\": [{\"taskId\": 41}]},"
			+ "{\"key\": \"other\", \"label\": \"Other\", \"tasks\": [{\"taskId\": 99, \"access\": {\"questsFinished\": [\"DRAGON_SLAYER_II\"], \"source\": \"test\"}}]}"
			+ "]}";

	@Test
	public void aPlaceNeedsItsOwnAccessAndThatOfTheTaskThere()
	{
		final SlayerLocations data = new SlayerLocations(new Gson(), new StringReader(JSON));
		final SlayerLocation tower = data.byKey("slayer_tower");
		assertEquals(2, PlaceAccess.of(tower, 48).size());
		assertEquals("another task there needs only the place's own", 1, PlaceAccess.of(tower, 41).size());
		assertTrue(PlaceAccess.of(data.byKey("open_field"), 41).isEmpty());
		assertTrue(PlaceAccess.of(null, 41).isEmpty());
		final PlaceAccess.Account account = quests("PRIEST_IN_PERIL", QuestState.FINISHED, "SINS_OF_THE_FATHER", QuestState.NOT_STARTED);
		assertEquals("Needs Sins of the Father started", PlaceAccess.check(PlaceAccess.of(tower, 48), account).needs());
		assertFalse(PlaceAccess.check(PlaceAccess.of(tower, 41), account).isLocked());
	}

	@Test
	public void onlyTheQuestsATasksPlacesNameAreRead()
	{
		final SlayerLocations data = new SlayerLocations(new Gson(), new StringReader(JSON));
		final List<SlayerLocation> places = new ArrayList<>(data.all());
		assertEquals(new LinkedHashSet<>(Arrays.asList("PRIEST_IN_PERIL", "SINS_OF_THE_FATHER")), PlaceAccess.quests(places, 48));
		assertEquals(Collections.singleton("PRIEST_IN_PERIL"), PlaceAccess.quests(places, 41));
		final List<Quest> asked = new ArrayList<>();
		final PlaceAccess.Account account = PlaceAccess.Account.read(PlaceAccess.quests(places, 41), quest ->
		{
			asked.add(quest);
			return QuestState.IN_PROGRESS;
		}, levels());
		assertEquals(Collections.singletonList(Quest.PRIEST_IN_PERIL), asked);
		assertEquals(QuestState.IN_PROGRESS, account.getQuests().get("PRIEST_IN_PERIL"));
	}

	@Test
	public void aQuestWhoseStateCannotBeReadStaysUnknown()
	{
		final PlaceAccess.Account account = PlaceAccess.Account.read(Arrays.asList("PRIEST_IN_PERIL", "LOST_CITY"), quest ->
		{
			if (quest == Quest.PRIEST_IN_PERIL) throw new IllegalStateException("script failed");
			return QuestState.NOT_STARTED;
		}, levels());
		assertFalse(account.getQuests().containsKey("PRIEST_IN_PERIL"));
		assertFalse(check(finished("PRIEST_IN_PERIL"), account).isLocked());
		assertTrue(check(finished("LOST_CITY"), account).isLocked());
	}

	@Test
	public void theLevelsAreCopiedSoTheAccountCanBeCompared()
	{
		final int[] live = levels(Skill.AGILITY, 50);
		final PlaceAccess.Account before = PlaceAccess.Account.read(Collections.emptyList(), quest -> null, live);
		live[Skill.AGILITY.ordinal()] = 51;
		final PlaceAccess.Account after = PlaceAccess.Account.read(Collections.emptyList(), quest -> null, live);
		assertFalse("a level gained is a change", before.equals(after));
		assertEquals(after, PlaceAccess.Account.read(Collections.emptyList(), quest -> null, live));
	}
}

package com.slayercompanion;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

/** Which notice the sidebar shows about Shortest Path, its words and its button. */
public class PluginNoticesTest
{
	@Test
	public void shortestPathIsOptionalAndOnlyAButtonTurnsItOn()
	{
		final PluginNotices.Notice off = PluginNotices.shortestPath(ShortestPathBridge.Status.DISABLED, PathMode.NEW_TASK, false);
		assertEquals("Optional, draws the route", off.getItem());
		assertEquals("Shortest Path is optional. It draws the route to your task and to your next master. It is installed but off.",
			off.getText());
		assertEquals("Turn on Shortest Path", off.getButton());
		assertFalse(off.isFailed());
		// Not installed: one line, no install button and no link
		final PluginNotices.Notice missing = PluginNotices.shortestPath(ShortestPathBridge.Status.MISSING, PathMode.NEW_TASK, false);
		assertEquals("Optional: Shortest Path, Plugin Hub", missing.getItem());
		assertEquals("Shortest Path is optional. It draws the route to your task and to your next master. You can install it from"
			+ " the Plugin Hub.", missing.getText());
		assertNull(missing.getButton());
		assertFalse(missing.getText().contains("http"));
	}

	@Test
	public void aFailedPressSaysSoAndKeepsTheButton()
	{
		final PluginNotices.Notice failed = PluginNotices.shortestPath(ShortestPathBridge.Status.DISABLED, PathMode.BUTTON, true);
		assertEquals("Could not turn it on", failed.getItem());
		assertEquals("Shortest Path is optional. It draws the route to your task and to your next master. The button could not turn"
			+ " it on. Turn it on in RuneLite's plugin list instead.", failed.getText());
		assertTrue(failed.isFailed());
		assertEquals("Turn on Shortest Path", failed.getButton());
	}

	@Test
	public void nothingIsSaidAboutShortestPathWhenItRunsOrRoutesAreOff()
	{
		for (ShortestPathBridge.Status status : ShortestPathBridge.Status.values())
		{
			assertNull(status.name(), PluginNotices.shortestPath(status, PathMode.OFF, false));
			assertNull(status.name(), PluginNotices.shortestPath(status, PathMode.OFF, true));
		}
		for (PathMode mode : PathMode.values())
		{
			assertNull(mode.name(), PluginNotices.shortestPath(ShortestPathBridge.Status.ACTIVE, mode, false));
		}
	}

	/** Compact items fit on a line, and no user-facing text uses dashes or semicolons. */
	@Test
	public void theItemsAreShort()
	{
		final List<PluginNotices.Notice> notices = new ArrayList<>();
		for (ShortestPathBridge.Status status : ShortestPathBridge.Status.values())
		{
			for (PathMode mode : PathMode.values())
			{
				notices.add(PluginNotices.shortestPath(status, mode, false));
				notices.add(PluginNotices.shortestPath(status, mode, true));
			}
		}
		for (PluginNotices.Notice notice : notices)
		{
			if (notice == null) continue;
			assertTrue(notice.getItem(), notice.getItem().length() <= 35);
		}
	}
}

package com.slayercompanion;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.List;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginInstantiationException;
import org.junit.Test;

/**
 * The sidebar's turn-on buttons without a client: the steps the plugin manager is asked for, in order, and what a
 * failure at each step leaves behind.
 */
public class PluginSwitchTest
{
	@PluginDescriptor(name = "Stand-in")
	private static final class StandIn extends Plugin
	{
	}

	/** Records the calls, and starts or fails as told. */
	private static class FakePlugins implements PluginSwitch.Plugins
	{
		final List<String> calls = new ArrayList<>();
		final boolean[] enabled = new boolean[1];
		boolean active;
		PluginInstantiationException startFails;
		RuntimeException startBreaks;

		@Override
		public void setEnabled(Plugin plugin, boolean on)
		{
			calls.add("enable " + on);
			enabled[0] = on;
		}

		@Override
		public boolean start(Plugin plugin) throws PluginInstantiationException
		{
			calls.add("start");
			if (startFails != null) throw startFails;
			if (startBreaks != null) throw startBreaks;
			// As the plugin manager does: a disabled plugin is not started
			if (!enabled[0] || active) return false;
			active = true;
			return true;
		}

		@Override
		public boolean isActive(Plugin plugin)
		{
			return active;
		}
	}

	@Test
	public void itIsEnabledFirstAndThenStarted()
	{
		final FakePlugins plugins = new FakePlugins();
		assertTrue(PluginSwitch.turnOn(plugins, new StandIn()));
		// The plugin manager starts only an enabled plugin, as RuneLite's plugin list does it
		assertEquals(java.util.Arrays.asList("enable true", "start"), plugins.calls);
	}

	@Test
	public void aPluginThatFailsToStartIsReportedAndStaysEnabled()
	{
		final FakePlugins plugins = new FakePlugins();
		plugins.startFails = new PluginInstantiationException("startUp threw");
		assertFalse(PluginSwitch.turnOn(plugins, new StandIn()));
		assertTrue("left enabled, as the plugin list leaves it", plugins.enabled[0]);

		final FakePlugins broken = new FakePlugins();
		broken.startBreaks = new IllegalStateException("conflict");
		assertFalse(PluginSwitch.turnOn(broken, new StandIn()));
	}

	@Test
	public void aStartThatDoesNothingCountsOnlyIfThePluginRuns()
	{
		// Already running: starting returns false, but the plugin runs
		final FakePlugins running = new FakePlugins();
		running.active = true;
		assertTrue(PluginSwitch.turnOn(running, new StandIn()));
		// Started without an error but not running afterwards
		final FakePlugins stopped = new FakePlugins()
		{
			@Override
			public boolean start(Plugin plugin)
			{
				calls.add("start");
				return true;
			}
		};
		assertFalse(PluginSwitch.turnOn(stopped, new StandIn()));
	}

	@Test
	public void aPluginThatIsNotThereIsNotTouched()
	{
		final FakePlugins plugins = new FakePlugins();
		assertFalse(PluginSwitch.turnOn(plugins, null));
		assertTrue(plugins.calls.isEmpty());
	}
}

package com.slayercompanion;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class RefreshGateTest
{
	private final RefreshGate gate = new RefreshGate();

	@Test
	public void withNoListOpenTheSidebarRebuildsAtOnce()
	{
		assertTrue(gate.shouldRebuild(false));
		assertFalse("nothing was held back", gate.popupClosed());
	}

	@Test
	public void aRefreshWhileAListIsOpenWaitsAndRunsOnceWhenItCloses()
	{
		assertFalse(gate.shouldRebuild(true));
		assertFalse("a kill on every tick still means one rebuild", gate.shouldRebuild(true));
		assertTrue(gate.popupClosed());
		assertFalse(gate.popupClosed());
	}

	@Test
	public void closingAListWithNothingHeldBackDoesNotRebuild()
	{
		assertFalse(gate.popupClosed());
	}

	@Test
	public void aRebuildAfterTheListClosedClearsTheHold()
	{
		assertFalse(gate.shouldRebuild(true));
		assertTrue(gate.shouldRebuild(false));
		assertFalse(gate.popupClosed());
	}
}

package com.slayercompanion;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import org.junit.Test;

public class ShortestPathBridgeTest
{
	private static final WorldPoint A = new WorldPoint(1650, 10070, 0);
	private static final WorldPoint B = new WorldPoint(1660, 10080, 0);

	@Test
	public void oneTargetIsSentAsAWorldPoint()
	{
		final Map<String, Object> data = ShortestPathBridge.pathData(Collections.singletonList(A));
		assertEquals(Collections.singleton("target"), data.keySet());
		assertEquals(A, data.get("target"));
	}

	@Test
	public void severalTargetsAreSentAsASetSoShortestPathPicksTheClosest()
	{
		final Map<String, Object> data = ShortestPathBridge.pathData(Arrays.asList(A, B, A));
		assertTrue(data.get("target") instanceof Set);
		assertEquals(new LinkedHashSet<>(Arrays.asList(A, B)), data.get("target"));
		assertFalse("no start, so Shortest Path uses the player's location", data.containsKey("start"));
		assertFalse("never override the user's Shortest Path settings", data.containsKey("config"));
	}

	@Test
	public void duplicatesOfOnePointCollapseToAWorldPoint()
	{
		assertEquals(A, ShortestPathBridge.pathData(Arrays.asList(A, A)).get("target"));
	}

	@Test(expected = IllegalArgumentException.class)
	public void aRouteWithoutTargetsIsABug()
	{
		ShortestPathBridge.pathData(Collections.emptyList());
	}

	@Test
	public void routeRequestsFromAnyPluginAreRecognised()
	{
		assertTrue(ShortestPathBridge.isRouteRequest(new PluginMessage("shortestpath", "path")));
		assertTrue(ShortestPathBridge.isRouteRequest(new PluginMessage("shortestpath", "clear")));
		assertFalse("Shortest Path's own transport report is not a target change",
				ShortestPathBridge.isRouteRequest(new PluginMessage("shortestpath", "transports")));
		assertFalse(ShortestPathBridge.isRouteRequest(new PluginMessage("questhelper", "path")));
	}

	@Test
	public void shortestPathMenuEntriesThatChangeTheTargetAreRecognised()
	{
		assertTrue(ShortestPathBridge.changesTarget("Set", "<col=ff9040>Target</col>"));
		assertTrue(ShortestPathBridge.changesTarget("Set", "<col=ff9040>Target</col> <col=ff9040>2</col>"));
		assertTrue(ShortestPathBridge.changesTarget("Clear", "<col=ff9040>Path</col>"));
		assertTrue(ShortestPathBridge.changesTarget("Find closest", "<col=ff9040>Bank</col>"));
		assertFalse("a new start keeps the target", ShortestPathBridge.changesTarget("Set", "<col=ff9040>Start</col>"));
		assertFalse(ShortestPathBridge.changesTarget("Walk here", ""));
		assertFalse(ShortestPathBridge.changesTarget("Clear", "<col=ff9040>Inventory</col>"));
		assertFalse(ShortestPathBridge.changesTarget(null, null));
	}

	@PluginDescriptor(name = "Shortest Path")
	private static final class RenamedShortestPath extends Plugin
	{
	}

	@PluginDescriptor(name = "Shortest Clue")
	private static final class OtherPlugin extends Plugin
	{
	}

	@Test
	public void theShortestPathPluginIsFoundByItsDescriptor()
	{
		assertTrue(ShortestPathBridge.isShortestPath(new RenamedShortestPath()));
		assertFalse(ShortestPathBridge.isShortestPath(new OtherPlugin()));
		assertFalse(ShortestPathBridge.isShortestPath(null));
	}
}

package com.slayercompanion;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.slayercompanion.SlayerBlockAdvisor.Advice;
import com.slayercompanion.SlayerBlockAdvisor.Misfit;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import net.runelite.api.Skill;
import net.runelite.api.gameval.DBTableID.SlayerTask.Row;
import org.junit.Test;

/** Block advice at one master, against the live cache dump and the dossier's ratings. */
public class SlayerBlockAdvisorTest
{
	private static Advice advise(SlayerMaster master, SlayerPool.Player player, SlayerGoal goal, int slots, Integer... blocked)
	{
		final List<Integer> rows = Arrays.asList(blocked);
		final SlayerPool pool = SlayerPool.of(master.assigner(), SlayerMasterRankerTest.DATA, player, new HashSet<>(rows),
				SlayerMasterRankerTest.RATINGS);
		return SlayerBlockAdvisor.advise(master, pool, goal, slots, rows);
	}

	@Test
	public void konarForXpKeepsTheRightBlocksAndFlagsTheRest()
	{
		final Advice advice = advise(SlayerMaster.KONAR, SlayerMasterRankerTest.maxed(), SlayerGoal.XP, 7, Row.SLAYER_TARGET_DAGANNOTH,
				Row.SLAYER_TARGET_CAVEKRAKEN);
		assertEquals(80, advice.getCost());
		assertEquals(7, advice.getSlots());
		assertEquals(Collections.singletonList("Cave Kraken"), advice.getKeep());
		assertEquals(Arrays.asList("Waterfiends", "Metal Dragons", "Fossil Island Wyverns", "Hydras", "Drakes", "Wyrms"), advice.getAdd());
		// Dagannoth is an 85k XP an hour cannon task the wiki's Slayer guide says to do
		assertEquals(Collections.singletonList(new Misfit("Dagannoth", "the wiki's Slayer guide says to do it for XP")), advice.getMisfits());
		// Fire giants are fair and the wiki's advice on them is conditional, so a block that lowers the rate does not call them good
		assertEquals(Collections.singletonList(new Misfit("Fire Giants", "a block on it lowers your XP rate")),
				advise(SlayerMaster.KONAR, SlayerMasterRankerTest.maxed(), SlayerGoal.XP, 7, Row.SLAYER_TARGET_FIREGIANTS).getMisfits());
		// Drakes, which the wiki says to skip or block for XP, stay blocked
		assertEquals(Collections.singletonList("Drakes"),
				advise(SlayerMaster.KONAR, SlayerMasterRankerTest.maxed(), SlayerGoal.XP, 7, Row.SLAYER_TARGET_DRAKES).getKeep());
	}

	@Test
	public void theGoalDecidesTheBlocks()
	{
		final SlayerPool.Player maxed = SlayerMasterRankerTest.maxed();
		// Profit blocks the money losers, Slayer points the slow tasks
		final List<String> profit = advise(SlayerMaster.KONAR, maxed, SlayerGoal.PROFIT, 7).getAdd();
		assertTrue(profit.toString(), profit.containsAll(Arrays.asList("Kalphites", "Dagannoth")));
		assertFalse(profit.toString(), profit.contains("Hydras"));
		final List<String> points = advise(SlayerMaster.KONAR, maxed, SlayerGoal.POINTS, 7).getAdd();
		assertTrue(points.toString(), points.containsAll(Arrays.asList("Hydras", "Drakes")));
		// Tasks the wiki's task summary says to block for XP at Duradel
		final List<String> xp = advise(SlayerMaster.DURADEL, maxed, SlayerGoal.XP, 7).getAdd();
		assertTrue(xp.toString(), xp.containsAll(Arrays.asList("Cave Kraken", "Fossil Island Wyverns", "Metal Dragons")));
		assertFalse(xp.toString(), xp.contains("Smoke Devils"));
	}

	@Test
	public void onlyTheOpenSlotsAreFilled()
	{
		final Advice two = advise(SlayerMaster.KONAR, SlayerMasterRankerTest.maxed(), SlayerGoal.XP, 2);
		assertEquals(Arrays.asList("Cave Kraken", "Waterfiends"), two.getAdd());
		final Advice none = advise(SlayerMaster.KONAR, SlayerMasterRankerTest.maxed(), SlayerGoal.XP, 0);
		assertTrue(none.getAdd().isEmpty());
		// Mortimer charges 120 a block (wiki Slayer Master)
		assertEquals(120, advise(SlayerMaster.MORTIMER, SlayerMasterRankerTest.maxed(), SlayerGoal.XP, 2).getCost());
	}

	@Test
	public void helpfulBlocksStayAndFreeSlotsAreFilled()
	{
		// At Kuradal kurask is a poor XP task but not among the seven best blocks. Blocks cost points and
		// unblocking refunds nothing, so it stays and the other six slots are filled around it.
		final Advice advice = advise(SlayerMaster.DURADEL, SlayerMasterRankerTest.maxed(), SlayerGoal.XP, 7, Row.SLAYER_TARGET_KURASK);
		assertEquals(Collections.singletonList("Kurask"), advice.getKeep());
		assertEquals(6, advice.getAdd().size());
		assertFalse(advice.getAdd().contains("Kurask"));
		assertTrue(advice.getMisfits().isEmpty());
	}

	@Test
	public void aBlockIsJudgedOnTopOfTheOthers()
	{
		// Task 2 is poor but helps only once the very poor, very long task 1 is blocked too. Judged alone it would be
		// lifted and then put straight back. Judged on top of the other block it stays, and nothing is asked twice.
		final SlayerPool pool = SlayerPool.of(SlayerAssigner.KONAR, Arrays.asList(
				SlayerPoolTest.entry(1, 10, SlayerPoolTest.rating(1, 1, 1), SlayerPool.Status.BLOCKED),
				SlayerPoolTest.entry(2, 5, SlayerPoolTest.rating(2, 1, 3), SlayerPool.Status.BLOCKED),
				SlayerPoolTest.entry(3, 10, SlayerPoolTest.rating(3, 1, 4), SlayerPool.Status.OPEN),
				SlayerPoolTest.entry(4, 10, SlayerPoolTest.rating(5, 1, 4), SlayerPool.Status.OPEN)));
		assertTrue(SlayerGoalModel.rate(pool.withBlocks(Collections.singletonList(2)), SlayerGoal.XP)
				< SlayerGoalModel.rate(pool.withBlocks(Collections.<Integer>emptyList()), SlayerGoal.XP));
		final Advice advice = SlayerBlockAdvisor.advise(SlayerMaster.KONAR, pool, SlayerGoal.XP, 2, Arrays.asList(1, 2));
		assertEquals(Arrays.asList("Task 1", "Task 2"), advice.getKeep());
		assertTrue(advice.getAdd().isEmpty());
		assertTrue(advice.getMisfits().isEmpty());
	}

	@Test
	public void aFullListSwapsOnlyForAMuchBetterBlock()
	{
		// Seven mild blocks fill every slot while a common, long, poor task waits
		final List<SlayerPool.Entry> entries = new ArrayList<>();
		entries.add(SlayerPoolTest.entry(1, 8, SlayerPoolTest.rating(1, 1, 1), SlayerPool.Status.OPEN));
		final List<Integer> blocked = new ArrayList<>();
		for (int row = 2; row <= 8; row++)
		{
			entries.add(SlayerPoolTest.entry(row, 1, SlayerPoolTest.rating(2, 1, 4), SlayerPool.Status.BLOCKED));
			blocked.add(row);
		}
		entries.add(SlayerPoolTest.entry(9, 20, SlayerPoolTest.rating(4, 1, 3), SlayerPool.Status.OPEN));
		Advice advice = SlayerBlockAdvisor.advise(SlayerMaster.KONAR, SlayerPool.of(SlayerAssigner.KONAR, entries), SlayerGoal.XP, 7, blocked);
		assertEquals(Collections.singletonList("Task 1"), advice.getAdd());
		assertEquals(6, advice.getKeep().size());
		assertEquals(Collections.singletonList(new Misfit("Task 2", "a weaker block than Task 1")), advice.getMisfits());
		// A waiting task no worse than the blocks already there is not worth the points
		entries.set(0, SlayerPoolTest.entry(1, 1, SlayerPoolTest.rating(2, 1, 4), SlayerPool.Status.OPEN));
		advice = SlayerBlockAdvisor.advise(SlayerMaster.KONAR, SlayerPool.of(SlayerAssigner.KONAR, entries), SlayerGoal.XP, 7, blocked);
		assertTrue(advice.getAdd().isEmpty());
		assertEquals(7, advice.getKeep().size());
		assertEquals("Every open slot holds a useful block.\nAlready blocked and right: Task 2, Task 3, Task 4, Task 5, Task 6, Task 7, Task 8.",
				SlayerPlanText.blockAdvice(advice, "Konar", null));
	}

	@Test
	public void aBlockOnATaskYouCannotGetIsWasted()
	{
		final int[] levels = SlayerMasterRankerTest.levels(99);
		levels[Skill.SLAYER.ordinal()] = 90;
		final SlayerPool.Player slayer90 = new SlayerPool.Player(levels, 126, false, Collections.<Integer>emptySet(),
				Collections.<Integer>emptySet());
		final Advice advice = advise(SlayerMaster.KONAR, slayer90, SlayerGoal.XP, 7, Row.SLAYER_TARGET_HYDRAS);
		assertEquals(Collections.singletonList(new Misfit("Hydras", "you cannot be given it anyway")), advice.getMisfits());
		assertFalse(advice.getAdd().contains("Hydras"));
	}
}

package com.slayercompanion;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.SortedSet;
import java.util.TreeSet;

/**
 * The trimmed dump of the live cache in src/test/resources, read back with the client's
 * getDBTableField rules so SlayerGameData parses it exactly as it parses the game. It also holds the
 * multi-NPCs that put a slayer master or a stand-in at each spot, the quest end states that go with them,
 * and the enums of the reward shop's Buy tab.
 * Regenerate it with tools/cache-dump ({@code -Pfixture}). Columns left out of the fixture throw.
 */
final class SlayerCacheFixture implements SlayerGameData.Db
{
	static final class Table
	{
		final int id;
		final String name;
		final Map<String, Integer> columnIds = new HashMap<>();
		final Map<Integer, Integer> typeCounts = new HashMap<>();
		final Map<Integer, Object[]> defaults = new HashMap<>();
		final List<Integer> rows = new ArrayList<>();

		Table(int id, String name)
		{
			this.id = id;
			this.name = name;
		}
	}

	static final class Varbit
	{
		final int id;
		final String name;
		final int varp;
		final int lsb;
		final int msb;

		Varbit(int id, String name, int varp, int lsb, int msb)
		{
			this.id = id;
			this.name = name;
			this.varp = varp;
			this.lsb = lsb;
			this.msb = msb;
		}
	}

	/** A multi-NPC that turns into a slayer master. The last transform is the default for values past the list. */
	static final class Spot
	{
		final int npc;
		final int varbit;
		final int varp;
		final int[] transforms;

		Spot(int npc, int varbit, int varp, int[] transforms)
		{
			this.npc = npc;
			this.varbit = varbit;
			this.varp = varp;
			this.transforms = transforms;
		}

		/** The NPC the client shows for a varbit value, -1 for none, as the client's transform picks it. */
		int shown(int value)
		{
			return value >= 0 && value < transforms.length - 1 ? transforms[value] : transforms[transforms.length - 1];
		}
	}

	private static SlayerCacheFixture instance;

	private final Map<Integer, Table> tables = new HashMap<>();
	private final Map<Integer, Table> tableOfRow = new HashMap<>();
	private final Map<Integer, String> rowNames = new HashMap<>();
	private final Map<Integer, Map<Integer, Object[]>> values = new HashMap<>();
	private final Map<Integer, Varbit> varbits = new HashMap<>();
	private final List<Spot> masterSpots = new ArrayList<>();
	/** NPC ids of the master versions that give tasks, to their names. */
	private final Map<Integer, String> masterNames = new HashMap<>();
	/** Quest end states by the Quest table's gameval row name. */
	private final Map<String, Integer> questEnds = new HashMap<>();
	/** The reward shop's Buy tab enums, {keys, int values}. */
	private final Map<Integer, int[][]> enums = new HashMap<>();

	private SlayerCacheFixture()
	{
	}

	static synchronized SlayerCacheFixture get()
	{
		if (instance == null)
		{
			instance = load("/slayer_cache_fixture.json");
		}
		return instance;
	}

	private static SlayerCacheFixture load(String resource)
	{
		try (InputStream in = SlayerCacheFixture.class.getResourceAsStream(resource))
		{
			if (in == null) throw new IllegalStateException(resource + " is missing. Run tools/cache-dump with -Pfixture.");
			final JsonObject root = new JsonParser().parse(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
			final SlayerCacheFixture fixture = new SlayerCacheFixture();
			for (JsonElement t : root.getAsJsonArray("tables"))
			{
				fixture.addTable(t.getAsJsonObject());
			}
			for (JsonElement v : root.getAsJsonArray("varbits"))
			{
				final JsonObject o = v.getAsJsonObject();
				final Varbit varbit = new Varbit(o.get("id").getAsInt(),
						o.get("name").isJsonNull() ? null : o.get("name").getAsString(),
						o.get("varp").getAsInt(), o.get("lsb").getAsInt(), o.get("msb").getAsInt());
				fixture.varbits.put(varbit.id, varbit);
			}
			for (JsonElement s : root.getAsJsonArray("masterNpcs"))
			{
				final JsonObject o = s.getAsJsonObject();
				final JsonArray t = o.getAsJsonArray("transforms");
				final int[] transforms = new int[t.size()];
				for (int i = 0; i < transforms.length; i++) transforms[i] = t.get(i).getAsInt();
				fixture.masterSpots.add(new Spot(o.get("npc").getAsInt(), o.get("varbit").getAsInt(), o.get("varp").getAsInt(), transforms));
			}
			for (Map.Entry<String, JsonElement> e : root.getAsJsonObject("masterNames").entrySet())
			{
				fixture.masterNames.put(Integer.parseInt(e.getKey()), e.getValue().getAsString());
			}
			for (JsonElement q : root.getAsJsonArray("quests"))
			{
				final JsonObject o = q.getAsJsonObject();
				fixture.questEnds.put(o.get("name").getAsString(), o.get("endState").getAsInt());
			}
			for (JsonElement e : root.getAsJsonArray("enums"))
			{
				final JsonObject o = e.getAsJsonObject();
				fixture.enums.put(o.get("id").getAsInt(), new int[][]{ints(o.getAsJsonArray("keys")), ints(o.getAsJsonArray("ints"))});
			}
			return fixture;
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}
	}

	private void addTable(JsonObject t)
	{
		final Table table = new Table(t.get("id").getAsInt(), t.get("name").getAsString());
		for (JsonElement c : t.getAsJsonArray("columns"))
		{
			final JsonObject col = c.getAsJsonObject();
			final int id = col.get("id").getAsInt();
			table.columnIds.put(col.get("name").getAsString(), id);
			table.typeCounts.put(id, col.getAsJsonArray("types").size());
			if (!col.get("default").isJsonNull()) table.defaults.put(id, raw(col.getAsJsonArray("default")));
		}
		for (JsonElement r : t.getAsJsonArray("rows"))
		{
			final JsonObject row = r.getAsJsonObject();
			final int id = row.get("row").getAsInt();
			table.rows.add(id);
			tableOfRow.put(id, table);
			if (!row.get("name").isJsonNull()) rowNames.put(id, row.get("name").getAsString());
			final Map<Integer, Object[]> rowValues = new HashMap<>();
			for (Map.Entry<String, JsonElement> e : row.getAsJsonObject("values").entrySet())
			{
				rowValues.put(Integer.parseInt(e.getKey()), raw(e.getValue().getAsJsonArray()));
			}
			values.put(id, rowValues);
		}
		tables.put(table.id, table);
	}

	private static int[] ints(JsonArray array)
	{
		final int[] out = new int[array.size()];
		for (int i = 0; i < out.length; i++) out[i] = array.get(i).getAsInt();
		return out;
	}

	private static Object[] raw(JsonArray array)
	{
		final Object[] out = new Object[array.size()];
		for (int i = 0; i < out.length; i++)
		{
			final JsonElement e = array.get(i);
			if (e.isJsonNull()) out[i] = null;
			else if (e.getAsJsonPrimitive().isString()) out[i] = e.getAsString();
			else out[i] = e.getAsInt();
		}
		return out;
	}

	@Override
	public List<Integer> rows(int table)
	{
		final Table t = tables.get(table);
		if (t == null) throw new IllegalArgumentException("Table " + table + " is not in the fixture");
		return Collections.unmodifiableList(t.rows);
	}

	/** The client's rules: element {@code tupleIndex} of every tuple, the column default for a missing value. */
	@Override
	public Object[] field(int row, int column, int tupleIndex)
	{
		final Table table = tableOfRow.get(row);
		if (table == null) throw new IllegalArgumentException("Row " + row + " is not in the fixture");
		final Integer types = table.typeCounts.get(column);
		if (types == null) throw new IllegalArgumentException(table.name + " column " + column + " is not in the fixture");
		if (tupleIndex >= types) throw new IllegalArgumentException("tuple index too large");
		Object[] flat = values.get(row).get(column);
		if (flat == null) flat = table.defaults.get(column);
		if (flat == null) return new Object[0];
		final Object[] out = new Object[flat.length / types];
		for (int i = 0; i < out.length; i++)
		{
			out[i] = flat[i * types + tupleIndex];
		}
		return out;
	}

	/** Like client.getEnum: the keys and int values, or empty arrays for an enum the fixture does not hold. */
	@Override
	public int[][] enumInts(int enumId)
	{
		final int[][] e = enums.get(enumId);
		return e == null ? new int[][]{new int[0], new int[0]} : new int[][]{e[0].clone(), e[1].clone()};
	}

	Table table(int id)
	{
		return tables.get(id);
	}

	String rowName(int row)
	{
		return rowNames.get(row);
	}

	/** First element of every tuple in a column, by gameval column name. */
	Object[] column(int row, String columnName)
	{
		return field(row, tableOfRow.get(row).columnIds.get(columnName), 0);
	}

	int intValue(int row, String columnName)
	{
		final Object[] v = column(row, columnName);
		return v.length == 0 ? -1 : (Integer) v[0];
	}

	Varbit varbit(int id)
	{
		return varbits.get(id);
	}

	Collection<Varbit> varbits()
	{
		return Collections.unmodifiableCollection(varbits.values());
	}

	List<Spot> masterSpots()
	{
		return Collections.unmodifiableList(masterSpots);
	}

	/** The name of a master version that gives tasks, or null for any other NPC. */
	String masterName(int npc)
	{
		return masterNames.get(npc);
	}

	/** Names of the task-giving masters every spot switched by {@code varbit} shows at {@code value}. */
	Set<String> mastersShown(int varbit, int value)
	{
		final Set<String> out = new TreeSet<>();
		for (Spot spot : masterSpots)
		{
			final String name = spot.varbit == varbit ? masterName(spot.shown(value)) : null;
			if (name != null) out.add(name);
		}
		return out;
	}

	/** The varbit values at which a spot switched by {@code varbit} shows the task-giving {@code master}. */
	SortedSet<Integer> valuesShowing(int varbit, String master)
	{
		final SortedSet<Integer> out = new TreeSet<>();
		for (Spot spot : masterSpots)
		{
			if (spot.varbit != varbit) continue;
			for (int v = 0; v < spot.transforms.length - 1; v++)
			{
				if (master.equals(masterName(spot.shown(v)))) out.add(v);
			}
		}
		return out;
	}

	/** A quest's progress value once complete, by its Quest table row name, e.g. QUEST_PORCINEOFINTEREST. */
	int questEnd(String row)
	{
		final Integer end = questEnds.get(row);
		if (end == null) throw new IllegalArgumentException(row + " is not in the fixture");
		return end;
	}
}

package com.slayercompanion;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.events.ConfigChanged;
import org.junit.Test;

/**
 * The plugin's bank memory on logged-in ticks without a task. The bank is looked at only after it changed, on a tick its
 * interface is open, and read at most once a tick. The gear check counts what the bank of the character logged in held.
 * The client here answers only what such a tick reads, the bank's interface and the bank, and counts the last two.
 */
public class SlayerCompanionBankTest
{
	/** Coins and a rock hammer. Only the hammer is kept. */
	private static final Item[] BANK = {new Item(ItemID.COINS, 1_000_000), new Item(ItemID.SLAYER_ROCK_HAMMER, 1)};

	@Test
	public void nothingLooksAtTheBankUntilItChanges() throws Exception
	{
		final Harness plugin = new Harness();
		plugin.open = true;
		plugin.tick();
		// The inventory and the worn items are the gear check's own, not the bank's
		plugin.changed(InventoryID.INV);
		plugin.changed(InventoryID.WORN);
		plugin.tick();
		assertEquals(0, plugin.widgetLooks);
		assertEquals(0, plugin.bankReads);
		assertTrue(plugin.stored.isEmpty());
	}

	@Test
	public void aChangeIsReadOnTheNextTickOnceHoweverOftenItChanged() throws Exception
	{
		final Harness plugin = new Harness();
		plugin.open = true;
		plugin.changed(InventoryID.BANK);
		plugin.changed(InventoryID.BANK);
		plugin.changed(InventoryID.BANK);
		assertEquals("nothing is read before the tick", 0, plugin.bankReads);
		plugin.tick();
		assertEquals(1, plugin.bankReads);
		assertEquals("4162:1", plugin.stored.get("profile-a"));
		plugin.tick();
		assertEquals("read again only after the next change", 1, plugin.bankReads);
		assertEquals(1, plugin.widgetLooks);
	}

	@Test
	public void aChangeWhileTheBankIsClosedWaitsUntilItIsOpen() throws Exception
	{
		final Harness plugin = new Harness();
		plugin.changed(InventoryID.BANK);
		plugin.tick();
		plugin.tick();
		assertEquals(0, plugin.bankReads);
		assertTrue(plugin.stored.isEmpty());
		plugin.open = true;
		plugin.tick();
		assertEquals(1, plugin.bankReads);
		assertEquals("4162:1", plugin.stored.get("profile-a"));
	}

	@Test
	public void theGearCheckCountsTheBankOfTheCharacterLoggedIn() throws Exception
	{
		final Harness plugin = new Harness();
		SlayerGearCheck.Result gear = plugin.gear("Gargoyles", "40");
		assertFalse(gear.isBankSeen());
		assertEquals(Collections.singletonList("Missing: rock or granite hammer"), gear.getItems());
		plugin.open = true;
		plugin.changed(InventoryID.BANK);
		plugin.tick();
		gear = plugin.gear("Gargoyles", "40");
		assertTrue(gear.isBankSeen());
		assertEquals(Collections.singletonList("In bank: Rock hammer"), gear.getItems());
		// The next character's bank has not been seen yet
		plugin.profile = "profile-b";
		gear = plugin.gear("Gargoyles", "40");
		assertFalse(gear.isBankSeen());
		assertEquals(Collections.singletonList("Missing: rock or granite hammer"), gear.getItems());
		plugin.profile = "profile-a";
		assertEquals(Collections.singletonList("In bank: Rock hammer"), plugin.gear("Gargoyles", "40").getItems());
	}

	/** Writing the memory posts a config change for its group, which must not be taken for a change of a setting. */
	@Test
	public void storingTheBankChangesNoSetting() throws Exception
	{
		final Harness plugin = new Harness();
		plugin.set("lastSidebarSignature", "shown");
		final ConfigChanged event = new ConfigChanged();
		event.setGroup(SlayerCompanionPlugin.BANK_GEAR_GROUP);
		event.setKey(SlayerCompanionPlugin.BANK_GEAR_KEY);
		event.setNewValue("4162:1");
		plugin.plugin.onConfigChanged(event);
		assertEquals("shown", plugin.get("lastSidebarSignature"));
	}

	/** The plugin with a client that counts what it is asked about the bank, settings that are all off, and stored text by character. */
	private static final class Harness
	{
		final SlayerCompanionPlugin plugin = new SlayerCompanionPlugin();
		final Map<String, String> stored = new HashMap<>();
		String profile = "profile-a";
		boolean open;
		int widgetLooks;
		int bankReads;

		Harness() throws Exception
		{
			set("client", Proxy.newProxyInstance(getClass().getClassLoader(), new Class<?>[]{Client.class},
				(proxy, method, args) -> client(method, args)));
			set("config", Proxy.newProxyInstance(getClass().getClassLoader(), new Class<?>[]{SlayerCompanionConfig.class},
				(proxy, method, args) -> method.getReturnType() == boolean.class ? Boolean.FALSE : null));
			set("bankMemory", new BankGear.Memory(() -> profile, () -> stored.get(profile), value -> stored.put(profile, value)));
		}

		void tick()
		{
			plugin.onGameTick(new GameTick());
		}

		void changed(int containerId)
		{
			plugin.onItemContainerChanged(new ItemContainerChanged(containerId, null));
		}

		/** The gear check of a task with nothing carried, as the tick on that task builds it. */
		SlayerGearCheck.Result gear(String task, String killsLeft) throws Exception
		{
			set("taskName", task);
			set("taskAmount", killsLeft);
			set("assignedAreaId", 0);
			set("gearItems", Collections.<SlayerGearCheck.Held>emptyList());
			set("gearCheckDirty", false);
			final Method update = SlayerCompanionPlugin.class.getDeclaredMethod("updateGearCheck");
			update.setAccessible(true);
			update.invoke(plugin);
			return plugin.getGearResult();
		}

		private Object client(Method method, Object[] args)
		{
			switch (method.getName())
			{
				case "getGameState":
					return GameState.LOGGED_IN;
				case "getVarpValue":
				case "getVarbitValue":
					return 0;
				case "getWidget":
					widgetLooks++;
					assertEquals(InterfaceID.Bankmain.ITEMS, args[0]);
					return widget(!open);
				case "getItemContainer":
					bankReads++;
					assertEquals(InventoryID.BANK, args[0]);
					return bank();
				case "hashCode":
					return System.identityHashCode(this);
				case "toString":
					return "client";
				default:
					throw new AssertionError("a tick asked the client for " + method.getName());
			}
		}

		private Widget widget(boolean hidden)
		{
			return (Widget) Proxy.newProxyInstance(getClass().getClassLoader(), new Class<?>[]{Widget.class}, (proxy, method, args) ->
			{
				if ("isHidden".equals(method.getName())) return hidden;
				throw new AssertionError("the bank's interface was asked for " + method.getName());
			});
		}

		private ItemContainer bank()
		{
			return (ItemContainer) Proxy.newProxyInstance(getClass().getClassLoader(), new Class<?>[]{ItemContainer.class},
				(proxy, method, args) ->
				{
					if ("getItems".equals(method.getName())) return BANK.clone();
					throw new AssertionError("the bank was asked for " + method.getName());
				});
		}

		void set(String field, Object value) throws Exception
		{
			final Field f = SlayerCompanionPlugin.class.getDeclaredField(field);
			f.setAccessible(true);
			f.set(plugin, value);
		}

		Object get(String field) throws Exception
		{
			final Field f = SlayerCompanionPlugin.class.getDeclaredField(field);
			f.setAccessible(true);
			return f.get(plugin);
		}
	}
}

