		assertTrue(sidebar.texts().toString(), sidebar.texts().contains("- Missing: 14 ice coolers (26 of 40)"));
		sidebar.kill(39, 1);
		sidebar.refresh();
		assertTrue(sidebar.texts().toString(), sidebar.texts().contains("- Missing: 13 ice coolers (26 of 39)"));
