package com.slayercompanion;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import net.runelite.api.GameState;
import org.junit.Test;

/**
 * Regression coverage for per-character isolation of the task tracker.
 */
public class SlayerCompanionStateTest
{
	@Test
	public void switchingCharacterDropsThePreviousTracking()
	{
		// The progress rate, ETA and cached dossier belong to one character. A change of task name alone
		// does not tell two accounts apart when both are on a task with the same name.
		assertTrue(SlayerCompanionPlugin.shouldResetForProfile("profile-a", "profile-b"));
		assertTrue(SlayerCompanionPlugin.shouldResetForProfile(null, "profile-a"));
		assertTrue(SlayerCompanionPlugin.shouldResetForProfile("profile-a", null));
	}

	@Test
	public void loggingBackIntoTheSameCharacterKeepsTracking()
	{
		assertFalse(SlayerCompanionPlugin.shouldResetForProfile("profile-a", "profile-a"));
		assertFalse(SlayerCompanionPlugin.shouldResetForProfile(null, null));
	}

	@Test
	public void logoutAndHopEndTheTrackedSession()
	{
		assertTrue(SlayerCompanionPlugin.endsSession(GameState.LOGIN_SCREEN));
		assertTrue(SlayerCompanionPlugin.endsSession(GameState.HOPPING));
	}

	@Test
	public void loadingAndPlayingDoNotEndTheTrackedSession()
	{
		// A loading screen between regions is not an account change; resetting there would throw
		// away a legitimate progress-rate sample every time the player crossed a region boundary.
		assertFalse(SlayerCompanionPlugin.endsSession(GameState.LOGGED_IN));
		assertFalse(SlayerCompanionPlugin.endsSession(GameState.LOADING));
		assertFalse(SlayerCompanionPlugin.endsSession(GameState.LOGGING_IN));
	}

	/**
	 * A game tick also arrives during a loading screen, on every teleport, cave entrance and region boundary. Reading it
	 * as no task would reset the rate, restart the new-task window, drop the plan and rebuild the marker and the sidebar.
	 * Such a tick reads nothing and changes nothing, and neither does a read that fails.
	 */
	@Test
	public void aTickWhileNotLoggedInOrWithAFailedReadKeepsTheTask()
	{
		for (GameState state : GameState.values())
		{
			if (state == GameState.LOGGED_IN) continue;
			final SlayerCompanionPlugin.TaskTick tick = SlayerCompanionPlugin.taskTick(state, () ->
			{
				throw new AssertionError("read while " + state);
			});
			assertTrue(state.name(), tick.isSkip());
		}
		assertTrue("a failed read", SlayerCompanionPlugin.taskTick(GameState.LOGGED_IN, () ->
		{
			throw new IllegalStateException("table not readable");
		}).isSkip());
		// Logged in, the read decides, and no kills left is no task at once
		final SlayerTaskReader.Task task = new SlayerTaskReader.Task("Abyssal Demons", 112, 150);
		assertEquals(new SlayerCompanionPlugin.TaskTick(false, task), SlayerCompanionPlugin.taskTick(GameState.LOGGED_IN, () -> task));
		assertEquals(new SlayerCompanionPlugin.TaskTick(false, null), SlayerCompanionPlugin.taskTick(GameState.LOGGED_IN, () -> null));
	}

	@Test
	public void progressIsCountedFromDropsOfTheTaskCounter()
	{
		// These are counter-progress units, not literal NPC deaths: bracelet effects may make one
		// physical kill consume two units or none.
		assertEquals(1, SlayerCompanionPlugin.progressRecorded(10, 9));
		assertEquals(3, SlayerCompanionPlugin.progressRecorded(10, 7));
		assertEquals(30, SlayerCompanionPlugin.progressRecorded(50, 20));
	}

	@Test
	public void nonProgressCounterMovementsAreIgnored()
	{
		// First observation after login or a task change.
		assertEquals(0, SlayerCompanionPlugin.progressRecorded(-1, 50));
		assertEquals(0, SlayerCompanionPlugin.progressRecorded(0, 0));
		// No change, and a new assignment raising the count.
		assertEquals(0, SlayerCompanionPlugin.progressRecorded(10, 10));
		assertEquals(0, SlayerCompanionPlugin.progressRecorded(10, 133));
		// Zero is ambiguous between completion, cancel and block. Suppressing terminal drops makes
		// even a small cancel truthful rather than reporting fake combat progress.
		assertEquals(0, SlayerCompanionPlugin.progressRecorded(5, 0));
		assertEquals(0, SlayerCompanionPlugin.progressRecorded(1, 0));
		assertEquals(0, SlayerCompanionPlugin.progressRecorded(100, 69));
	}

	@Test
	public void aChangedOriginalAmountRebaselinesEvenWhenTaskNameIsTheSame()
	{
		assertTrue(SlayerCompanionPlugin.assignmentChanged(150, 130));
		assertTrue(SlayerCompanionPlugin.assignmentChanged(150, 0));
		assertFalse(SlayerCompanionPlugin.assignmentChanged(150, 150));
		assertFalse(SlayerCompanionPlugin.assignmentChanged(-1, 150));
	}

	@Test
	public void krystiliaAndMortimerTasksShowTheirOwnStreak()
	{
		assertEquals(SlayerAssigner.Streak.WILDERNESS, SlayerCompanionPlugin.streakFor(7));
		assertEquals(SlayerAssigner.Streak.MORTIMER, SlayerCompanionPlugin.streakFor(10));
		assertEquals(SlayerAssigner.Streak.MAIN, SlayerCompanionPlugin.streakFor(6));
		assertEquals(SlayerAssigner.Streak.MAIN, SlayerCompanionPlugin.streakFor(8));
		assertEquals("no task or an unknown master", SlayerAssigner.Streak.MAIN, SlayerCompanionPlugin.streakFor(0));
		assertEquals("Wilderness streak / points", SlayerCompanionPanel.streakHeading(SlayerAssigner.Streak.WILDERNESS));
		assertEquals("Mortimer streak / points", SlayerCompanionPanel.streakHeading(SlayerAssigner.Streak.MORTIMER));
		assertEquals("Streak / points", SlayerCompanionPanel.streakHeading(SlayerAssigner.Streak.MAIN));
	}

	@Test
	public void theTaskRateAsALineAndAsACompactItem()
	{
		assertEquals("Shows once the task count first goes down.", SlayerCompanionPlugin.rateText(0, 0, 150, false));
		assertEquals("After the first kill", SlayerCompanionPlugin.rateText(0, 0, 150, true));
		assertEquals("Learning the rate. 2 done so far.", SlayerCompanionPlugin.rateText(2, 600, 148, false));
		assertEquals("Learning, 2 done", SlayerCompanionPlugin.rateText(2, 600, 148, true));
		assertEquals("Learning, 5 done", SlayerCompanionPlugin.rateText(5, 59, 145, true));
		// 31 in six minutes is 310 an hour, so 62 left take 12 minutes
		assertEquals("310 an hour. About 12m left.", SlayerCompanionPlugin.rateText(31, 360, 62, false));
		assertEquals("310 an hour, 12m left", SlayerCompanionPlugin.rateText(31, 360, 62, true));
		assertEquals("60 an hour, 2h 30m left", SlayerCompanionPlugin.rateText(60, 3600, 150, true));
	}

	@Test
	public void startupSeedsOnlyAnAlreadyLoggedInProfile()
	{
		assertEquals("profile-a", SlayerCompanionPlugin.initialProfileKey(GameState.LOGGED_IN, "profile-a"));
		assertEquals(null, SlayerCompanionPlugin.initialProfileKey(GameState.LOGIN_SCREEN, "profile-a"));
	}

	/**
	 * When the scene panel shows: after a new task, within three minutes of the last kill, or always when the player
	 * asked for that. It needs no other plugin for this.
	 */
	@Test
	public void thePanelShowsAfterANewTaskAndWhileKillingOrAlways()
	{
		assertEquals("three minutes of game ticks", 180.0, SlayerCompanionPlugin.WORKING_TICKS * 0.6, 0.001);
		// The new-task window, before any kill
		assertTrue(SlayerCompanionPlugin.overlayShows(false, 150, 200, -1));
		assertFalse(SlayerCompanionPlugin.overlayShows(false, 201, 200, -1));
		// Working on the task
		final int lastKill = 1000;
		assertTrue(SlayerCompanionPlugin.overlayShows(false, lastKill, 200, lastKill));
		assertTrue(SlayerCompanionPlugin.overlayShows(false, lastKill + SlayerCompanionPlugin.WORKING_TICKS, 200, lastKill));
		assertFalse("gone on a bank trip", SlayerCompanionPlugin.overlayShows(false, lastKill + SlayerCompanionPlugin.WORKING_TICKS + 1,
				200, lastKill));
		// Always show
		assertTrue(SlayerCompanionPlugin.overlayShows(true, 99_999, 200, -1));
	}
}

package com.slayercompanion;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.fail;

import com.google.gson.Gson;
import com.slayercompanion.data.SlayerTask;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.time.Instant;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import org.junit.Test;

/**
 * The plugin's own tick and session handlers on a task in progress. A game tick also arrives during a loading screen, on
 * every teleport, cave entrance and region boundary, and a table read can fail. Such a tick must leave the task, its rate,
 * the new-task window, the marker and the sidebar as they are. The client here answers only what that tick may ask, and
 * the config answers nothing unless a test lets it, so a tick that went on would fail the test.
 */
public class SlayerCompanionTickTest
{
	private static final SlayerDataset DATASET = new SlayerDataset(new Gson());
	private static final WorldPoint CATACOMBS = new WorldPoint(1636, 3673, 0);

	@Test
	public void aTickDuringALoadingScreenChangesNothing() throws Exception
	{
		final Harness plugin = new Harness(GameState.LOADING, null);
		plugin.onTask();
		plugin.tick();
		plugin.assertTaskKept();
	}

	@Test
	public void aTickWhoseReadFailsChangesNothing() throws Exception
	{
		final Map<Integer, Integer> varps = new HashMap<>();
		varps.put(VarPlayerID.SLAYER_COUNT, 112);
		varps.put(VarPlayerID.SLAYER_TARGET, 42);
		final Harness plugin = new Harness(GameState.LOGGED_IN, varps);
		plugin.failTableReads = true;
		plugin.onTask();
		plugin.tick();
		plugin.assertTaskKept();
	}

	/** Logged in, no kills left is no task on that same tick. The streak and points are read again at once. */
	@Test
	public void noKillsLeftEndsTheTaskOnTheSameTick() throws Exception
	{
		final Map<Integer, Integer> varps = new HashMap<>();
		varps.put(VarPlayerID.SLAYER_COUNT, 0);
		varps.put(VarPlayerID.SLAYER_TARGET, 42);
		final Harness plugin = new Harness(GameState.LOGGED_IN, varps);
		plugin.configAnswers = true;
		plugin.varbits.put(VarbitID.SLAYER_MASTER, SlayerAssigner.DURADEL.getId());
		plugin.varbits.put(VarbitID.SLAYER_TASKS_COMPLETED, 48);
		plugin.varbits.put(VarbitID.SLAYER_POINTS, 536);
		plugin.onTask();
		plugin.tick();
		assertNull(plugin.get("taskName"));
		assertNull(plugin.get("currentTask"));
		assertNull(plugin.get("taskAmount"));
		assertEquals(0, plugin.get("taskProgress"));
		assertEquals(-1, plugin.get("lastProgressTick"));
		assertNull(plugin.get("mapPoint"));
		assertEquals("48", plugin.get("taskStreak"));
		assertEquals("536", plugin.get("slayerPoints"));
		assertEquals(SlayerAssigner.DURADEL, plugin.get("taskMaster"));
	}

	/**
	 * Logging out, hopping and switching profiles clear everything at once, the master and the streak kind too, since no
	 * tick clears them while the player is not logged in. The name the reader kept is forgotten as well.
	 */
	@Test
	public void theEndOfASessionClearsEverything() throws Exception
	{
		for (String end : new String[]{"logout", "hop", "profile switch"})
		{
			final Harness plugin = new Harness(GameState.LOGIN_SCREEN, null);
			plugin.configAnswers = true;
			plugin.onTask();
			plugin.set("streakKind", SlayerAssigner.Streak.WILDERNESS);
			plugin.set("activeProfileKey", "profile-a");
			final SlayerTaskReader reader = (SlayerTaskReader) plugin.get("taskReader");
			assertEquals("Abyssal Demons", reader.name(SlayerCacheFixture.get(), 42, 0));

			switch (end)
			{
				case "logout":
					plugin.plugin.onGameStateChanged(gameState(GameState.LOGIN_SCREEN));
					break;
				case "hop":
					plugin.plugin.onGameStateChanged(gameState(GameState.HOPPING));
					break;
				default:
					plugin.plugin.onRuneScapeProfileChanged(new RuneScapeProfileChanged("profile-a", "profile-b"));
					break;
			}
			assertNull(end, plugin.get("taskName"));
			assertNull(end, plugin.get("currentTask"));
			assertNull(end, plugin.get("taskAmount"));
			assertNull(end, plugin.get("taskStreak"));
			assertNull(end, plugin.get("slayerPoints"));
			assertNull(end, plugin.get("taskMaster"));
			assertEquals(end, SlayerAssigner.Streak.MAIN, plugin.get("streakKind"));
			assertEquals(end, 0, plugin.get("taskProgress"));
			assertNull(end, plugin.get("mapPoint"));
			try
			{
				reader.name(UNREADABLE, 42, 0);
				fail(end + " kept the name the reader looked up");
			}
			catch (IllegalStateException expected)
			{
				// Forgotten, so the next login reads the tables again
			}
		}
	}

	/** Tables that cannot be read. */
	private static final SlayerGameData.Db UNREADABLE = new SlayerGameData.Db()
	{
		@Override
		public List<Integer> rows(int table)
		{
			throw new IllegalStateException("table not readable");
		}

		@Override
		public Object[] field(int row, int column, int tupleIndex)
		{
			throw new IllegalStateException("table not readable");
		}
	};

	private static GameStateChanged gameState(GameState state)
	{
		final GameStateChanged event = new GameStateChanged();
		event.setGameState(state);
		return event;
	}

	/**
	 * The plugin with a fake client and config and the world map's markers. Nothing else is injected, so a tick that used
	 * anything else would throw.
	 */
	private static final class Harness
	{
		final SlayerCompanionPlugin plugin = new SlayerCompanionPlugin();
		final GameState state;
		final Map<Integer, Integer> varps;
		final Map<Integer, Integer> varbits = new HashMap<>();
		boolean failTableReads;
		/** Off, any config read fails the test. On, every setting is off. */
		boolean configAnswers;
		final SlayerTask dossier = DATASET.lookupOrFallback("Abyssal demons");
		final TaskMapPoint marker = new TaskMapPoint(CATACOMBS, "Slayer task: Abyssal Demons");
		final Instant started = Instant.now().minusSeconds(600);

		Harness(GameState state, Map<Integer, Integer> varps) throws Exception
		{
			this.state = state;
			this.varps = varps;
			set("client", Proxy.newProxyInstance(getClass().getClassLoader(), new Class<?>[]{Client.class},
				(proxy, method, args) -> client(method, args)));
			set("config", Proxy.newProxyInstance(getClass().getClassLoader(), new Class<?>[]{SlayerCompanionConfig.class},
				(proxy, method, args) -> config(method)));
			set("worldMapPointManager", new WorldMapPointManager());
		}

		/** Abyssal demons, 112 of 150 left, 38 killed so far, the marker up and the new-task window open. */
		void onTask() throws Exception
		{
			set("taskName", "Abyssal Demons");
			set("currentTask", dossier);
			set("taskAmount", "112");
			set("taskInitialAmount", "150");
			set("taskStreak", "47");
			set("slayerPoints", "521");
			set("taskMaster", SlayerAssigner.KONAR);
			set("taskIntroUntilTick", 500);
			set("lastProgressTick", 400);
			set("taskProgress", 38);
			set("lastRemainingAmount", 112);
			set("lastInitialAmount", 150);
			set("trackingStart", started);
			((WorldMapPointManager) get("worldMapPointManager")).add(marker);
			set("mapPoint", marker);
		}

		void tick()
		{
			plugin.onGameTick(new GameTick());
		}

		void assertTaskKept() throws Exception
		{
			assertEquals("Abyssal Demons", get("taskName"));
			assertSame(dossier, get("currentTask"));
			assertEquals("112", get("taskAmount"));
			assertEquals("150", get("taskInitialAmount"));
			assertEquals("47", get("taskStreak"));
			assertEquals("521", get("slayerPoints"));
			assertEquals(SlayerAssigner.KONAR, get("taskMaster"));
			assertEquals("the new-task window", 500, get("taskIntroUntilTick"));
			assertEquals(400, get("lastProgressTick"));
			assertEquals("the rate", 38, get("taskProgress"));
			assertEquals(112, get("lastRemainingAmount"));
			assertEquals(150, get("lastInitialAmount"));
			assertSame(started, get("trackingStart"));
			assertSame("the marker", marker, get("mapPoint"));
		}

		private Object client(Method method, Object[] args)
		{
			switch (method.getName())
			{
				case "getGameState":
					return state;
				case "getVarpValue":
					if (varps != null) return varps.getOrDefault((Integer) args[0], 0);
					break;
				case "getVarbitValue":
					if (varps != null) return varbits.getOrDefault((Integer) args[0], 0);
					break;
				case "getDBRowsByValue":
					if (failTableReads) throw new IllegalStateException("table not readable");
					break;
				case "hashCode":
					return System.identityHashCode(this);
				case "toString":
					return "client " + state;
				default:
					break;
			}
			throw new AssertionError("a tick on " + state + " asked the client for " + method.getName());
		}

		private Object config(Method method)
		{
			if (!configAnswers)
			{
				throw new AssertionError("a tick on " + state + " read the setting " + method.getName());
			}
			return method.getReturnType() == boolean.class ? Boolean.FALSE : null;
		}

		void set(String field, Object value) throws Exception
		{
			final Field f = SlayerCompanionPlugin.class.getDeclaredField(field);
			f.setAccessible(true);
			f.set(plugin, value);
		}

		Object get(String field) throws Exception
		{
			final Field f = SlayerCompanionPlugin.class.getDeclaredField(field);
			f.setAccessible(true);
			return f.get(plugin);
		}
	}
}

package com.slayercompanion;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

import java.lang.reflect.Field;
import net.runelite.client.plugins.PluginDependency;
import org.junit.Test;

/**
 * Guice wiring invariants that unit tests cannot catch by running plugin logic. Slayer Sensei reads the task from
 * the game itself, so it depends on no other plugin. A type from another plugin's package is bound only inside that
 * plugin's own injector: injecting one without a matching {@code @PluginDependency} makes plugin creation throw at load
 * time, and RuneLite then silently leaves the plugin out of the plugin list while every logic test stays green.
 */
public class SlayerCompanionWiringTest
{
	@Test
	public void thePluginDependsOnNoOtherPlugin()
	{
		assertEquals(0, SlayerCompanionPlugin.class.getAnnotationsByType(PluginDependency.class).length);
	}

	@Test
	public void nothingIsInjectedFromAnotherPlugin()
	{
		for (Field field : SlayerCompanionPlugin.class.getDeclaredFields())
		{
			if (!field.isAnnotationPresent(javax.inject.Inject.class))
			{
				continue;
			}
			final Package fieldPackage = field.getType().getPackage();
			// The plugin manager lives in net.runelite.client.plugins itself, which is the client's, not a plugin's
			assertFalse("field '" + field.getName() + "' injects a type from another plugin's package " + fieldPackage,
					fieldPackage != null && fieldPackage.getName().startsWith("net.runelite.client.plugins."));
		}
	}
}

