		int twoOrMore = 0;
		for (String id : OTHER_MASTER_TASKS.split(" "))
		{
			final int taskId = Integer.parseInt(id);
			final TaskLocations list = data.forTask(taskId);
			if (list == null || list.getLocations().isEmpty())
			{
				missing.add(id);
				continue;
			}
			if (list.getLocations().size() >= 2) twoOrMore++;
		}
