package com.slayercompanion;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.DBTableID.SlayerUnlock.Row;
import org.junit.Test;

/**
 * Keeps {@link SlayerReward} in step with the reward shop. A game update that adds a reward fails
 * here once the RuneLite api names its row, or once the fixture is regenerated from the new cache.
 */
public class SlayerRewardCoverageTest
{
	/**
	 * Rows the advice layer leaves out on purpose. On 27 August 2025 the metal dragons became one task
	 * and these four rewards left the shop (OSRS Wiki, Slayer Rewards changes). The rows stay in the
	 * cache with list position (-1, -1), which SlayerGameData reads as unlisted.
	 */
	private static final Map<Integer, String> IGNORED = new HashMap<>();

	static
	{
		IGNORED.put(Row.SLAYER_REWARDS_UNLOCK_MITHRILDRAGONS, "I Hope You Mith Me");
		IGNORED.put(Row.SLAYER_REWARDS_LONGER_MITHRILDRAGONS, "I Really Mith You");
		IGNORED.put(Row.SLAYER_REWARDS_LONGER_ADAMANTDRAGONS, "Ada'mind Some More");
		IGNORED.put(Row.SLAYER_REWARDS_LONGER_RUNEDRAGONS, "RUUUUUNE");
	}

	private static final SlayerCacheFixture FIXTURE = SlayerCacheFixture.get();
	private static final SlayerGameData DATA = SlayerGameData.load(FIXTURE);

	@Test
	public void everyNamedRowIsCoveredOrIgnored()
	{
		final Set<Integer> covered = rewardRows();
		int rows = 0;
		for (Field f : Row.class.getDeclaredFields())
		{
			final int m = f.getModifiers();
			if (!Modifier.isStatic(m) || f.getType() != int.class) continue;
			final int row = rowValue(f);
			rows++;
			assertTrue("SlayerUnlock row " + f.getName() + " is new. Add it to SlayerReward or to IGNORED with a reason.",
					covered.contains(row) || IGNORED.containsKey(row));
			assertFalse(f.getName() + " is both covered and ignored", covered.contains(row) && IGNORED.containsKey(row));
		}
		assertEquals(rows, covered.size() + IGNORED.size());
	}

	@Test
	public void everyCacheRowIsCoveredOrIgnored()
	{
		final Set<Integer> covered = rewardRows();
		for (int row : FIXTURE.table(DBTableID.SlayerUnlock.ID).rows)
		{
			assertTrue("Cache row " + row + " (" + FIXTURE.rowName(row) + ") is not in SlayerReward",
					covered.contains(row) || IGNORED.containsKey(row));
		}
	}

	@Test
	public void ignoredRowsAreOutOfTheShop()
	{
		for (Map.Entry<Integer, String> e : IGNORED.entrySet())
		{
			final SlayerGameData.Unlock unlock = DATA.unlock(e.getKey());
			assertEquals(e.getValue(), unlock.getName());
			assertFalse(e.getValue() + " is back in the shop. Add it to SlayerReward.", unlock.isListed());
		}
		for (SlayerReward r : SlayerReward.values())
		{
			assertTrue(r + " left the shop", DATA.unlock(r.getRow()).isListed());
		}
	}

	@Test
	public void fallbackNamesAndCostsMatchTheCache()
	{
		for (SlayerReward r : SlayerReward.values())
		{
			final SlayerGameData.Unlock unlock = DATA.unlock(r.getRow());
			assertNotNull(r.name(), unlock);
			assertEquals(r.name(), unlock.getName(), r.getFallbackName());
			assertEquals(r.name(), unlock.getCost(), r.getFallbackCost());
		}
	}

	@Test
	public void fallbackVarbitsSitOnTheRowsBit()
	{
		for (SlayerReward r : SlayerReward.values())
		{
			final int bit = DATA.unlock(r.getRow()).getBit();
			final SlayerCacheFixture.Varbit varbit = FIXTURE.varbit(r.getFallbackVarbit());
			assertNotNull(r.name(), varbit);
			assertEquals(r.name(), SlayerGameData.UNLOCK_VARPS[bit / 32], varbit.varp);
			assertEquals(r.name(), bit % 32, varbit.lsb);
			assertEquals(r.name(), bit % 32, varbit.msb);
		}
	}

	@Test
	public void slayerLevelsMatchTheTasksTheRewardNames()
	{
		for (SlayerReward r : SlayerReward.values())
		{
			final SlayerReward.Kind kind = r.getKind();
			// Rewards that only change the pool wait for the level of the task itself, from the cache
			if (kind == SlayerReward.Kind.TASK_UNLOCK || kind == SlayerReward.Kind.WEIGHTING || kind == SlayerReward.Kind.COSMETIC)
			{
				continue;
			}
			int expected = 0;
			for (int task : DATA.unlock(r.getRow()).getRelatedTaskRows())
			{
				expected = Math.max(expected, DATA.slayerLevel(task));
			}
			assertEquals(r.name(), expected, r.getSlayerLevel());
		}
	}

	/** The kinds follow the shop's own tabs and the cache's task columns, so a reward cannot be valued the wrong way. */
	@Test
	public void kindsMatchTheCache()
	{
		for (SlayerReward r : SlayerReward.values())
		{
			final SlayerGameData.Unlock unlock = DATA.unlock(r.getRow());
			final SlayerReward.Kind kind = r.getKind();
			assertEquals(r.name(), kind == SlayerReward.Kind.EXTENSION, unlock.getTab() == SlayerGameData.TAB_EXTEND);
			assertEquals(r.name(), kind == SlayerReward.Kind.COSMETIC, unlock.getTab() == SlayerGameData.TAB_COSMETIC);
			// Every extension lengthens its task in the cache, and nothing else does
			assertEquals(r.name(), kind == SlayerReward.Kind.EXTENSION, !DATA.extensions(r.getRow()).isEmpty());
			assertEquals(r.name(), kind == SlayerReward.Kind.WEIGHTING, !DATA.weightings(r.getRow()).isEmpty());
			assertEquals(r.name(), kind == SlayerReward.Kind.BLOCKER, !DATA.blockedBy(r.getRow()).isEmpty());
			// Task unlocks gate some master's pool, except one that no master needs yet
			if (DATA.gatesPool(r.getRow())) assertEquals(r.name(), SlayerReward.Kind.TASK_UNLOCK, kind);
		}
	}

	@Test
	public void taskNamesExistInTheCache()
	{
		for (SlayerReward r : SlayerReward.values())
		{
			if (r.getTask() == null) continue;
			assertFalse(r.name() + " task '" + r.getTask() + "'", DATA.taskRowsNamed(r.getTask()).isEmpty());
		}
	}

	private static Set<Integer> rewardRows()
	{
		final Set<Integer> rows = new HashSet<>();
		for (SlayerReward r : SlayerReward.values())
		{
			assertTrue(r + " shares a row", rows.add(r.getRow()));
		}
		return rows;
	}

	private static int rowValue(Field f)
	{
		try
		{
			return f.getInt(null);
		}
		catch (IllegalAccessException e)
		{
			throw new AssertionError(e);
		}
	}
}

package com.slayercompanion;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/** The Buy tab items the plan recommends, against the cache dump, and how they are sighted. */
public class SlayerShopItemTest
{
	private static final SlayerGameData DATA = SlayerMasterRankerTest.DATA;

	@Test
	public void fallbackCostsMatchTheCache()
	{
		for (SlayerShopItem item : SlayerShopItem.values())
		{
			assertEquals(item.name(), DATA.shopItems().get(item.getItemId()), Integer.valueOf(item.getFallbackCost()));
		}
	}

	/** The rest of the tab is used up, so it is left out: Slayer rings run out of charges, bolts and arrows are fired. */
	@Test
	public void onlyItemsThatLastAreListed()
	{
		final Set<Integer> listed = new HashSet<>();
		for (SlayerShopItem item : SlayerShopItem.values()) listed.add(item.getItemId());
		final Set<Integer> usedUp = new HashSet<>(Arrays.asList(ItemID.SLAYER_RING_8, ItemID.SLAYER_BROAD_BOLT, ItemID.SLAYER_BROAD_ARROWS));
		for (int sold : DATA.shopItems().keySet())
		{
			assertTrue("Buy tab item " + sold + " is new. List it in SlayerShopItem or say why it is left out.",
					listed.contains(sold) || usedUp.contains(sold));
		}
	}

	@Test
	public void upgradesAndNotesCountAsOwning()
	{
		assertTrue(SlayerShopItem.HERB_SACK.seenIn(id -> id == ItemID.SLAYER_HERB_SACK_SILK_OPEN));
		assertTrue(SlayerShopItem.RUNE_POUCH.seenIn(id -> id == ItemID.DIVINE_RUNE_POUCH));
		assertTrue(SlayerShopItem.RUNE_POUCH.seenIn(id -> id == ItemID.PROMISSORY_NOTE_RUNEPOUCH));
		assertTrue(SlayerShopItem.LOOTING_BAG.seenIn(id -> id == ItemID.LOOTING_BAG_OPEN));
		assertFalse(SlayerShopItem.RUNE_POUCH.seenIn(id -> id == ItemID.SLAYER_HERB_SACK));
	}

	@Test
	public void sightingsAreKeptAsText()
	{
		final SlayerShopItem.Sightings none = SlayerShopItem.Sightings.decode(null);
		assertEquals(SlayerShopItem.Sightings.NONE, none);
		assertEquals("", none.encode());
		final SlayerShopItem.Sightings seen = none.with(EnumSet.of(SlayerShopItem.RUNE_POUCH), true);
		assertEquals("RUNE_POUCH,bank", seen.encode());
		assertEquals(seen, SlayerShopItem.Sightings.decode(seen.encode()));
		assertTrue(seen.owns(SlayerShopItem.RUNE_POUCH));
		assertFalse(seen.owns(SlayerShopItem.HERB_SACK));
		// Once seen, always seen
		assertTrue(seen.with(Collections.<SlayerShopItem>emptySet(), false).isBankSeen());
		// An item a later version drops does not lose the rest
		assertEquals(seen, SlayerShopItem.Sightings.decode("GONE_ITEM, RUNE_POUCH ,bank"));
	}
}

package com.slayercompanion;

import static com.slayercompanion.SlayerPoolTest.entry;
import static com.slayercompanion.SlayerPoolTest.rating;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.slayercompanion.SlayerPointsPlanner.Candidate;
import com.slayercompanion.SlayerPool.Status;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.Skill;
import net.runelite.api.gameval.DBTableID;
import org.junit.Test;

/** How each way of spending points is valued for a goal. */
public class SlayerSpendTest
{
	private static final SlayerGameData DATA = SlayerMasterRankerTest.DATA;
	private static final SlayerDataset DATASET = new SlayerDataset(new Gson());

	/** A long excellent XP task and a short poor one. */
	private static final SlayerPool PAIR = SlayerPool.of(SlayerAssigner.DURADEL, Arrays.asList(
			entry(1, 1, rating(5, 1, 2), Status.OPEN),
			entry(2, 1, rating(1, 5, 5), Status.OPEN)));

	@Test
	public void aLongerTaskHelpsWhenItBeatsTheAverageAndNeverHelpsPoints()
	{
		final SlayerPool longer = PAIR.map(e -> e.getTaskRow() == 1 ? e.withAmounts(200, 200) : e);
		assertTrue(SlayerSpend.change(PAIR, longer, SlayerGoal.XP) > 0);
		assertTrue(SlayerSpend.change(PAIR, longer, SlayerGoal.PROFIT) < 0);
		assertTrue(SlayerSpend.change(PAIR, longer, SlayerGoal.POINTS) < 0);
	}

	@Test
	public void helmetTasksComeFromTheGearCheck()
	{
		for (String task : Arrays.asList("Aberrant Spectres", "Banshees", "Dust Devils", "Smoke Devils", "Wall Beasts", "Sourhogs"))
		{
			assertTrue(task, SlayerSpend.helmetTask(named(task)));
		}
		assertFalse(SlayerSpend.helmetTask(named("Kurask")));
	}

	private static SlayerPool.Entry named(String name)
	{
		return new SlayerPool.Entry(1, name, 1, 100, 100, 100, Status.OPEN, rating(1, 1, 1));
	}

	@Test
	public void ratingsReadAsWords()
	{
		assertEquals("an excellent XP task", SlayerSpend.judge(entry(1, 1, rating(5, 1, 1), Status.OPEN), SlayerGoal.XP));
		assertEquals("a very poor money task", SlayerSpend.judge(entry(1, 1, rating(5, 1, 1), Status.OPEN), SlayerGoal.PROFIT));
		assertEquals("a very slow task", SlayerSpend.judge(entry(1, 1, rating(5, 1, 1), Status.OPEN), SlayerGoal.POINTS));
		assertEquals("a task of average length", SlayerSpend.judge(entry(1, 1, rating(5, 1, 3), Status.OPEN), SlayerGoal.POINTS));
		assertEquals("A and B", SlayerSpend.join(Arrays.asList("A", "B")));
		assertEquals("A, B and C", SlayerSpend.join(Arrays.asList("A", "B", "C")));
		assertEquals("Konar's", SlayerSpend.possessive("Konar"));
		assertEquals("Spria's", SlayerSpend.possessive("Spria"));
	}

	@Test
	public void theMissingLevelIsTheFirstTheTaskNeeds()
	{
		final int kraken = DBTableID.SlayerTask.Row.SLAYER_TARGET_CAVEKRAKEN;
		final int[] levels = SlayerMasterRankerTest.levels(99);
		levels[Skill.SLAYER.ordinal()] = 86;
		assertEquals("87 Slayer", SlayerSpend.missingLevel(DATA, player(levels, 126), SlayerAssigner.KONAR, kraken));
		levels[Skill.SLAYER.ordinal()] = 99;
		levels[Skill.MAGIC.ordinal()] = 49;
		assertEquals("50 Magic", SlayerSpend.missingLevel(DATA, player(levels, 126), SlayerAssigner.KONAR, kraken));
		levels[Skill.MAGIC.ordinal()] = 99;
		assertEquals("combat level 80", SlayerSpend.missingLevel(DATA, player(levels, 79), SlayerAssigner.KONAR, kraken));
		// Krystilia does not check combat level
		assertNull(SlayerSpend.missingLevel(DATA, player(levels, 79), SlayerAssigner.KRYSTILIA, kraken));
		levels[Skill.STRENGTH.ordinal()] = 59;
		levels[Skill.AGILITY.ordinal()] = 59;
		assertEquals("60 Strength or 60 Agility", SlayerSpend.missingLevel(DATA, player(levels, 126), SlayerAssigner.DURADEL,
				DBTableID.SlayerTask.Row.SLAYER_TARGET_SPIRITUALGWD));
	}

	private static SlayerPool.Player player(int[] levels, int combat)
	{
		return new SlayerPool.Player(levels, combat, false, Collections.<Integer>emptySet(), Collections.<Integer>emptySet());
	}

	private static List<Candidate> at(SlayerAssigner master, SlayerGoal goal)
	{
		final SlayerPool pool = SlayerPool.of(master, DATA, SlayerMasterRankerTest.maxed(), Collections.<Integer>emptySet(),
				SlayerMasterRankerTest.RATINGS);
		final SlayerMaster list = SlayerMaster.forAssigner(master);
		final SlayerBlockAdvisor.Advice advice = SlayerBlockAdvisor.advise(list, pool, goal, list.getBlockVarbits().length,
				Collections.<Integer>emptyList());
		return SlayerSpend.candidates(new SlayerSpend.Context(goal, master, master.getDisplayName(), pool, DATA, SlayerMasterRankerTest.maxed(),
				Collections.<Integer>emptySet(), list.getBlockVarbits().length, advice, Collections.<Integer>emptySet(),
				SlayerPlanBuilder.dossier(DATASET), SlayerShopItem.Sightings.NONE, null, SlayerPlanBuilder.skipBudget(goal, master,
				SlayerPayout.Diaries.NONE, 0)), SlayerReward::getFallbackName, r -> null, i -> null);
	}

	private static Candidate find(List<Candidate> candidates, String name)
	{
		for (Candidate c : candidates)
		{
			if (c.getName().equals(name)) return c;
		}
		return null;
	}

	@Test
	public void documentedEffectsFollowTheGoal()
	{
		final List<Candidate> xp = at(SlayerAssigner.DURADEL, SlayerGoal.XP);
		final List<Candidate> profit = at(SlayerAssigner.DURADEL, SlayerGoal.PROFIT);
		final List<Candidate> points = at(SlayerAssigner.DURADEL, SlayerGoal.POINTS);
		// Superiors are worth XP, a little loot, and only time for Slayer points
		assertTrue(find(xp, "Bigger and Badder").getGain() > find(profit, "Bigger and Badder").getGain());
		assertEquals(0, find(points, "Bigger and Badder").getGain(), 0);
		// The herb sack only helps profit
		assertTrue(find(profit, "Herb sack").getGain() > SlayerPointsPlanner.NOTICEABLE);
		assertEquals(0, find(xp, "Herb sack").getGain(), 0);
		// The helmet and the rune pouch speed tasks up, so they help all three
		for (List<Candidate> goal : Arrays.asList(xp, profit, points))
		{
			assertTrue(find(goal, "Malevolent Masquerade").getGain() > SlayerPointsPlanner.NOTICEABLE);
			assertTrue(find(goal, "Rune pouch").getGain() > SlayerPointsPlanner.NOTICEABLE);
			// Neither helps any goal enough to list: preference, Fletching and ironman rewards
			assertEquals(0, find(goal, "Task Storage").getGain(), 0);
			assertEquals(0, find(goal, "Broader Fletching").getGain(), 0);
			assertEquals(0, find(goal, "Duly Noted").getGain(), 0);
			assertEquals(0, find(goal, "Double Trouble").getGain(), 0);
			// The looting bag only on Krystilia's tasks
			assertEquals(0, find(goal, "Looting bag").getGain(), 0);
		}
		assertTrue(find(at(SlayerAssigner.KRYSTILIA, SlayerGoal.PROFIT), "Looting bag").getGain() > SlayerPointsPlanner.NOTICEABLE);
	}

	@Test
	public void theListIsJudgedWithTheAdvisedBlocksInPlace()
	{
		// Metal dragons are a poor XP task the advice blocks at Konar, so lengthening them is not worth anything there
		final List<Candidate> xp = at(SlayerAssigner.KONAR, SlayerGoal.XP);
		assertTrue(find(xp, "Block Metal Dragons") != null);
		assertEquals(0, find(xp, "Pedal to the Metals").getGain(), 0);
		// For profit they are a good money task, but the wiki discourages extending them, so the extension is never worth points
		final List<Candidate> profit = at(SlayerAssigner.KONAR, SlayerGoal.PROFIT);
		assertTrue(find(profit, "Pedal to the Metals").getGain() <= 0);
		// Skeletal wyverns are a good money task the wiki has nothing against, so they are lengthened
		assertTrue(find(profit, "Wyver-nother one").getGain() > SlayerPointsPlanner.NOTICEABLE);
	}

	@Test
	public void onlyTasksRatedGoodAreWorthMoreTime()
	{
		assertTrue(SlayerSpend.extendable(entry(1, 1, rating(4, 1, 3), Status.OPEN), SlayerGoal.XP));
		assertFalse(SlayerSpend.extendable(entry(1, 1, rating(3, 5, 3), Status.OPEN), SlayerGoal.XP));
		assertTrue(SlayerSpend.extendable(entry(1, 1, rating(3, 5, 3), Status.OPEN), SlayerGoal.PROFIT));
		final com.slayercompanion.data.TaskRating discouraged = rating(5, 5, 3);
		discouraged.setExtensionDiscouraged(true);
		assertFalse(SlayerSpend.extendable(entry(1, 1, discouraged, Status.OPEN), SlayerGoal.PROFIT));
		assertFalse(SlayerSpend.extendable(entry(1, 1, null, Status.OPEN), SlayerGoal.XP));
	}

	@Test
	public void pointsHaveOneLineForEveryExtension()
	{
		final List<Candidate> points = at(SlayerAssigner.KONAR, SlayerGoal.POINTS);
		assertTrue(Double.isNaN(find(points, "Augment My Abbies").getGain()));
		final Candidate summary = find(points, "Task extensions");
		assertEquals(SlayerPointsPlanner.Type.SUMMARY, summary.getType());
		assertTrue(summary.getGain() < 0);
		assertNull(find(at(SlayerAssigner.KONAR, SlayerGoal.XP), "Task extensions"));
	}

	@Test
	public void theRoutineValuesBlocksAtBothListsOnItsCycle()
	{
		// Konar takes the milestone tasks, Aya the nine filler tasks between them. Neither list has a block yet.
		final SlayerPool konar = SlayerPool.of(SlayerAssigner.KONAR, DATA, SlayerMasterRankerTest.maxed(), Collections.<Integer>emptySet(),
				SlayerMasterRankerTest.RATINGS);
		final SlayerPool aya = SlayerPool.of(SlayerAssigner.TURAEL, DATA, SlayerMasterRankerTest.maxed(), Collections.<Integer>emptySet(),
				SlayerMasterRankerTest.RATINGS);
		final SlayerBlockAdvisor.Advice konarBlocks = SlayerBlockAdvisor.advise(SlayerMaster.KONAR, konar, SlayerGoal.POINTS, 7,
				Collections.<Integer>emptyList());
		final SlayerBlockAdvisor.Advice ayaBlocks = SlayerBlockAdvisor.advise(SlayerMaster.TURAEL, aya, SlayerGoal.POINTS, 7,
				Collections.<Integer>emptyList());
		final double points = 18 * SlayerPayout.averageMultiplier(10);
		final SlayerSpend.Routine routine = new SlayerSpend.Routine(9, points, "Aya", aya, 7, ayaBlocks);
		final List<Candidate> all = SlayerSpend.candidates(new SlayerSpend.Context(SlayerGoal.POINTS, SlayerAssigner.KONAR, "Konar", konar, DATA,
				SlayerMasterRankerTest.maxed(), Collections.<Integer>emptySet(), 7, konarBlocks, Collections.<Integer>emptySet(),
				SlayerPlanBuilder.dossier(DATASET), SlayerShopItem.Sightings.NONE, routine, 0), SlayerReward::getFallbackName, r -> null, i -> null);

		// Each list's first block, valued on the whole cycle against today's rate, at its own master's cost
		final double base = SlayerGoalModel.cycleRate(aya, konar, 9, points);
		final int bugs = ayaBlocks.getAddRows().get(0);
		final Candidate ayaFirst = find(all, "Block Cave Bugs at Aya");
		assertEquals(bugs, (int) DATA.taskRowForId(63));
		assertEquals(40, ayaFirst.getCost());
		assertEquals(SlayerMaster.TURAEL, ayaFirst.getList());
		assertEquals((SlayerGoalModel.cycleRate(aya.withBlocks(Collections.singletonList(bugs)), konar, 9, points) - base) / base,
				ayaFirst.getGain(), 1e-12);
		final int hydras = konarBlocks.getAddRows().get(0);
		final Candidate konarFirst = find(all, "Block Hydras at Konar");
		assertEquals(80, konarFirst.getCost());
		assertEquals(SlayerMaster.KONAR, konarFirst.getList());
		assertEquals((SlayerGoalModel.cycleRate(aya, konar.withBlocks(Collections.singletonList(hydras)), 9, points) - base) / base,
				konarFirst.getGain(), 1e-12);
		// Every block either list's advice puts forward is there once, one per open slot
		int konarLines = 0;
		int ayaLines = 0;
		for (Candidate c : all)
		{
			if (c.getType() != SlayerPointsPlanner.Type.BLOCK) continue;
			if (c.getList() == SlayerMaster.KONAR) konarLines++;
			if (c.getList() == SlayerMaster.TURAEL) ayaLines++;
			assertTrue(c.getGain() > 0);
		}
		assertEquals(konarBlocks.getAddRows().size(), konarLines);
		assertEquals(7, ayaLines);
		// A reward for a filler task counts on the routine: with no slot on Aya's list her lizards stay, and Konar never
		// gives them. With the slots, lizards are among the blocks, so the reward is worth nothing there.
		final SlayerBlockAdvisor.Advice noSlots = SlayerBlockAdvisor.advise(SlayerMaster.TURAEL, aya, SlayerGoal.POINTS, 0,
				Collections.<Integer>emptyList());
		final List<Candidate> unblocked = SlayerSpend.candidates(new SlayerSpend.Context(SlayerGoal.POINTS, SlayerAssigner.KONAR, "Konar", konar,
				DATA, SlayerMasterRankerTest.maxed(), Collections.<Integer>emptySet(), 7, konarBlocks, Collections.<Integer>emptySet(),
				SlayerPlanBuilder.dossier(DATASET), SlayerShopItem.Sightings.NONE, new SlayerSpend.Routine(9, points, "Aya", aya, 0, noSlots), 0),
				SlayerReward::getFallbackName, r -> null, i -> null);
		assertTrue(find(unblocked, "Reptile Freezer").getGain() > 0);
		assertEquals(0, find(all, "Reptile Freezer").getGain(), 0);
		assertEquals(0, find(at(SlayerAssigner.KONAR, SlayerGoal.POINTS), "Reptile Freezer").getGain(), 0);
	}

	@Test
	public void linesEndWithAFullStopAndUseWholeNumbers()
	{
		for (SlayerAssigner master : SlayerAssigner.values())
		{
			for (SlayerGoal goal : SlayerGoal.values())
			{
				for (Candidate c : at(master, goal))
				{
					for (String text : Arrays.asList(c.getWhy(), c.getNote()))
					{
						if (text == null) continue;
						assertTrue(text, text.endsWith("."));
						assertFalse(text, text.matches(".*[0-9]\\.[0-9].*"));
					}
				}
			}
		}
	}
}

package com.slayercompanion;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

/**
 * The task read from the game, against the dump of the live cache. The dossier, the gear tables and the places are keyed
 * by the names RuneLite's Slayer plugin stores, so every name the reader can produce is checked against the names the
 * guard tests accept, and every key those tables hold must be one the reader can produce.
 */
public class SlayerTaskReaderTest
{
	private static final SlayerCacheFixture CACHE = SlayerCacheFixture.get();

	@Test
	public void everyTaskAndBossNameIsOneTheTablesAreKeyedBy() throws Exception
	{
		final Set<String> runeLite = SlayerRequirementsTest.runeLiteTaskNames();
		final Set<String> cache = SlayerRequirementsTest.cacheTaskNames();
		final Set<String> derived = new HashSet<>();
		// Every task id a master's SLAYER_TARGET can hold. Boss rows have the id -1 and are reached through the boss list.
		final Map<Integer, String> byRow = new HashMap<>();
		int tasks = 0;
		for (int row : CACHE.rows(DBTableID.SlayerTask.ID))
		{
			final int id = CACHE.intValue(row, "COL_ID");
			// The "Boss" row's id is the boss task's target, which names its boss instead, as checked below
			if (id <= 0 || id == SlayerTaskReader.BOSS_TASK) continue;
			final String name = SlayerTaskReader.taskName(CACHE, id, 0);
			assertNotNull("task id " + id, name);
			// The name is the row's own, unchanged, as RuneLite's Slayer plugin stores it
			assertEquals(CACHE.column(row, "COL_NAME_UPPERCASE")[0], name);
			assertTrue(name, cache.contains(SlayerRequirements.normalize(name)));
			derived.add(SlayerRequirements.normalize(name));
			byRow.put(row, name);
			tasks++;
		}
		// Every boss SLAYER_TARGET_BOSSID can name, through the boss list
		int bosses = 0;
		for (int row : CACHE.rows(DBTableID.SlayerTaskSublist.ID))
		{
			final int bossId = CACHE.intValue(row, "COL_TASK_SUBTABLE_ID");
			final String name = SlayerTaskReader.taskName(CACHE, SlayerTaskReader.BOSS_TASK, bossId);
			assertNotNull("boss " + bossId, name);
			assertTrue(name + " is not a task name in RuneLite's Slayer Task enum", runeLite.contains(SlayerRequirements.normalize(name)));
			assertTrue(name, cache.contains(SlayerRequirements.normalize(name)));
			derived.add(SlayerRequirements.normalize(name));
			bosses++;
		}
		assertTrue(tasks > 100);
		assertEquals("every boss the game lists", 33, bosses);
		// Every task a master assigns comes out as a name RuneLite's Slayer plugin knows. The boss task goes by its boss.
		for (int entry : CACHE.rows(DBTableID.SlayerMasterTask.ID))
		{
			final int taskRow = CACHE.intValue(entry, "COL_TASK");
			if (CACHE.intValue(taskRow, "COL_ID") == SlayerTaskReader.BOSS_TASK) continue;
			final String name = byRow.get(taskRow);
			assertNotNull("pool row " + taskRow, name);
			assertTrue(name + " is not a task name in RuneLite's Slayer Task enum", runeLite.contains(SlayerRequirements.normalize(name)));
		}
		// And every key the gear tables hold is a name the reader can produce, so none silently stops matching
		final Set<String> keys = new LinkedHashSet<>(SlayerRequirements.taskKeys());
		keys.addAll(SlayerRequirements.recommendedKeys());
		keys.addAll(SlayerRequirements.undeadKeys());
		for (String key : keys)
		{
			assertTrue("'" + key + "' is no name the game gives a task", derived.contains(key));
		}
	}

	@Test
	public void namesComeOutInTheCachesOwnCasing()
	{
		assertEquals("Abyssal Demons", SlayerTaskReader.taskName(CACHE, 42, 0));
		assertEquals("Mutated Zygomites", SlayerTaskReader.taskName(CACHE, 74, 0));
		assertEquals("Metal Dragons", SlayerTaskReader.taskName(CACHE, 127, 0));
		// Boss tasks: the target says boss, the boss id says which
		assertEquals("Cerberus", SlayerTaskReader.taskName(CACHE, SlayerTaskReader.BOSS_TASK, 20));
		assertEquals("The Alchemical Hydra", SlayerTaskReader.taskName(CACHE, SlayerTaskReader.BOSS_TASK, 24));
		assertEquals("Barrows brothers", SlayerTaskReader.taskName(CACHE, SlayerTaskReader.BOSS_TASK, 17));
		// Ids the tables do not hold give no task
		assertNull(SlayerTaskReader.taskName(CACHE, 9_999, 0));
		assertNull(SlayerTaskReader.taskName(CACHE, SlayerTaskReader.BOSS_TASK, 999));
		assertNull(SlayerTaskReader.taskName(CACHE, 0, 0));
	}

	@Test
	public void theTaskComesWithItsKillsAndTheAmountAssigned()
	{
		final SlayerTaskReader reader = new SlayerTaskReader();
		final SlayerTaskReader.Task task = reader.read(varps(42, 112, 150), varbits(0, 0, 0, 0), CACHE);
		assertEquals(new SlayerTaskReader.Task("Abyssal Demons", 112, 150), task);
		assertEquals("Cerberus", reader.read(varps(SlayerTaskReader.BOSS_TASK, 30, 30), varbits(20, 0, 0, 0), CACHE).getName());
		// No kills left is no task, as RuneLite's Slayer plugin reads it, and nothing shows while the tables have no row
		assertNull(reader.read(varps(42, 0, 150), varbits(0, 0, 0, 0), CACHE));
		assertNull(reader.read(varps(9_999, 40, 40), varbits(0, 0, 0, 0), CACHE));
	}

	/** The SlayerModifiers table: modifier 2 is "Slayer Quantity Change", which moves the amount up or down. */
	@Test
	public void aQuantityModifierMovesTheAmountAssigned()
	{
		final SlayerTaskReader reader = new SlayerTaskReader();
		assertEquals(170, reader.read(varps(42, 112, 150), varbits(0, SlayerTaskReader.QUANTITY_MODIFIER, 20, 0), CACHE)
			.getInitialAmount());
		assertEquals(130, reader.read(varps(42, 112, 150), varbits(0, SlayerTaskReader.QUANTITY_MODIFIER, 20, 1), CACHE)
			.getInitialAmount());
		// Any other modifier leaves it alone
		assertEquals(150, reader.read(varps(42, 112, 150), varbits(0, 1, 20, 0), CACHE).getInitialAmount());
	}

	/**
	 * The reader is asked every tick, and RuneLite's Slayer plugin reads the tables only when one of its varps changes. So
	 * the name is kept for its SLAYER_TARGET and boss id, and the tables are read again only when one of them changes. A
	 * lookup that finds nothing or throws is never kept, and the end of a session forgets the name.
	 */
	@Test
	public void theTablesAreReadOnlyWhenTheTargetOrTheBossChanges()
	{
		final CountingDb db = new CountingDb();
		final SlayerTaskReader reader = new SlayerTaskReader();
		assertEquals("Abyssal Demons", reader.read(varps(42, 112, 150), varbits(0, 0, 0, 0), db).getName());
		assertTrue(db.reads > 0);
		// More ticks on the task, kills going down and a quantity modifier set, read no table
		int reads = db.reads;
		assertEquals("Abyssal Demons", reader.read(varps(42, 111, 150), varbits(0, 0, 0, 0), db).getName());
		assertEquals(new SlayerTaskReader.Task("Abyssal Demons", 110, 170),
			reader.read(varps(42, 110, 150), varbits(0, SlayerTaskReader.QUANTITY_MODIFIER, 20, 0), db));
		assertEquals(reads, db.reads);
		// No kills left reads no table either, and the next task on the same target still finds its name kept
		assertNull(reader.read(varps(42, 0, 150), varbits(0, 0, 0, 0), db));
		assertEquals("Abyssal Demons", reader.read(varps(42, 150, 150), varbits(0, 0, 0, 0), db).getName());
		assertEquals(reads, db.reads);

		// The next task is usually another ordinary one, so the boss id stays 0 and only the target changes
		assertEquals("Mutated Zygomites", reader.read(varps(74, 80, 80), varbits(0, 0, 0, 0), db).getName());
		assertTrue(db.reads > reads);
		reads = db.reads;
		assertEquals("Abyssal Demons", reader.read(varps(42, 150, 150), varbits(0, 0, 0, 0), db).getName());
		assertTrue(db.reads > reads);
		reads = db.reads;

		// A new target reads them again, and so does another boss on the boss target
		assertEquals("Cerberus", reader.read(varps(SlayerTaskReader.BOSS_TASK, 30, 30), varbits(20, 0, 0, 0), db).getName());
		assertTrue(db.reads > reads);
		reads = db.reads;
		assertEquals("The Alchemical Hydra", reader.read(varps(SlayerTaskReader.BOSS_TASK, 30, 30), varbits(24, 0, 0, 0), db).getName());
		assertTrue(db.reads > reads);
		reads = db.reads;
		assertEquals("The Alchemical Hydra", reader.read(varps(SlayerTaskReader.BOSS_TASK, 29, 30), varbits(24, 0, 0, 0), db).getName());
		assertEquals(reads, db.reads);

		// A target the tables do not hold is not kept. It never shows the last name, and every tick looks again
		assertNull(reader.read(varps(9_999, 40, 40), varbits(0, 0, 0, 0), db));
		reads = db.reads;
		assertNull(reader.read(varps(9_999, 40, 40), varbits(0, 0, 0, 0), db));
		assertTrue(db.reads > reads);

		// Nor is a lookup that throws. It goes to the caller, and the next tick looks again and finds the name
		db.failing = true;
		try
		{
			reader.read(varps(42, 112, 150), varbits(0, 0, 0, 0), db);
			fail("a failed table read is the caller's to handle");
		}
		catch (IllegalStateException expected)
		{
			// The plugin keeps what it shows and reads again next tick
		}
		db.failing = false;
		reads = db.reads;
		assertEquals("Abyssal Demons", reader.read(varps(42, 112, 150), varbits(0, 0, 0, 0), db).getName());
		assertTrue(db.reads > reads);
		reads = db.reads;
		assertEquals("Abyssal Demons", reader.read(varps(42, 111, 150), varbits(0, 0, 0, 0), db).getName());
		assertEquals(reads, db.reads);

		// The session ends, so the name kept is forgotten
		reader.clear();
		assertEquals("Abyssal Demons", reader.read(varps(42, 111, 150), varbits(0, 0, 0, 0), db).getName());
		assertTrue(db.reads > reads);
	}

	/** The fixture's tables, counting every read and throwing while {@link #failing}, as a client read might. */
	private static final class CountingDb implements SlayerGameData.Db
	{
		int reads;
		boolean failing;

		@Override
		public List<Integer> rows(int table)
		{
			read();
			return CACHE.rows(table);
		}

		@Override
		public Object[] field(int row, int column, int tupleIndex)
		{
			read();
			return CACHE.field(row, column, tupleIndex);
		}

		@Override
		public List<Integer> rowsByValue(int table, int column, int tupleIndex, Object value)
		{
			read();
			return CACHE.rowsByValue(table, column, tupleIndex, value);
		}

		private void read()
		{
			reads++;
			if (failing) throw new IllegalStateException("table not readable");
		}
	}

	private static IntUnaryOperator varps(int target, int left, int assigned)
	{
		final Map<Integer, Integer> values = new HashMap<>();
		values.put(VarPlayerID.SLAYER_TARGET, target);
		values.put(VarPlayerID.SLAYER_COUNT, left);
		values.put(VarPlayerID.SLAYER_COUNT_ORIGINAL, assigned);
		return varp -> values.getOrDefault(varp, 0);
	}

	private static IntUnaryOperator varbits(int bossId, int modifier, int change, int negative)
	{
		final Map<Integer, Integer> values = new HashMap<>();
		values.put(VarbitID.SLAYER_TARGET_BOSSID, bossId);
		values.put(VarbitID.SLAYER_MODIFIER_ID, modifier);
		values.put(VarbitID.SLAYER_MODIFIER_VALUE, change);
		values.put(VarbitID.SLAYER_MODIFIER_NEGATIVE, negative);
		return varbit -> values.getOrDefault(varbit, 0);
	}
}

package com.slayercompanion;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.slayercompanion.data.SlayerTask;
import com.slayercompanion.data.TaskRating;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

/**
 * The XP advice at Kuradal against the wiki's task summary for Duradel's tasks (Slayer training, Task summary), kept in
 * the test resource wiki_task_summary_duradel.json with the page and the date it was read. The column's advice is in
 * the ratings data ({@link TaskRating#getXpAdvice}) and the XP advice follows it both ways: a task to do is done, a task
 * to skip or block is skipped or blocked, never extended and never called good, and an unlock it says not to make is
 * never recommended. The XP ratings themselves follow the table's XP per hour for the fastest method, with the cut
 * points in {@link TaskRating}.
 */
public class SlayerTaskSummaryGuardTest
{
	private static final SlayerGameData DATA = SlayerPointsPlannerTest.DATA;
	private static final SlayerDataset DATASET = SlayerPointsPlannerTest.DATASET;

	/** One row of the wiki's table. */
	static final class Row
	{
		String wiki;
		/** The cache name the plugin uses. */
		String task;
		String recommendation;
		String xpPerHour;
		/** do, skip, dontUnlock or none. */
		String forXp;
	}

	static final class Summary
	{
		String page;
		String section;
		String url;
		String read;
		List<Row> tasks;
	}

	static Summary summary()
	{
		try (Reader reader = new InputStreamReader(SlayerTaskSummaryGuardTest.class.getResourceAsStream("/wiki_task_summary_duradel.json"),
				StandardCharsets.UTF_8))
		{
			return new Gson().fromJson(reader, Summary.class);
		}
		catch (IOException ex)
		{
			throw new AssertionError(ex);
		}
	}

